-- Nursing Skills and Fundamentals question bank: exactly 1100 hand-written NCLEX-style
-- single-best-answer questions, 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/Fundamentals/tube-care-nursing.html
--   Notes/Fundamentals/family-dynamics-nursing.html
--   Notes/Fundamentals/informed-consent-nursing.html
--   Notes/Fundamentals/fundamentals-nursing-nclex.html
--   Notes/Fundamentals/documentation-informatics-nursing.html
--   Notes/Fundamentals/sbar-communication-nursing.html
--   Notes/Fundamentals/emergency-triage-tag-colors-nursing.html
--   Notes/Fundamentals/amputation-nursing.html
--   Notes/Fundamentals/delegation-nursing-nclex.html
--   Notes/Fundamentals/scope-of-practice-nursing.html
--   Notes/Fundamentals/complementary-alternative-medicine-nursing.html
--   Notes/Fundamentals/bmi-calculation-nursing.html
--   Notes/Fundamentals/nursing-calculations-nclex.html
--   Notes/Fundamentals/precautions-nursing.html
--   Notes/Fundamentals/blood-products-administration-nursing.html
--   Notes/Fundamentals/head-to-toe-assessment-nursing.html
--   Notes/Fundamentals/nursing-diagnosis-nclex.html
--   Notes/Fundamentals/vital-signs-interpretation-nursing.html
--   Notes/Fundamentals/physical-exam-bowel-sounds-nursing.html
--   Notes/Fundamentals/client-positioning-nursing.html
--   Notes/Fundamentals/physical-assessment-nursing.html
--   Notes/Fundamentals/maslows-hierarchy-nursing.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (1100) exist after insert.
BEGIN;

CREATE TEMP TABLE _fund_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

