  ('triage', 'Notes/Fundamentals/emergency-triage-tag-colors-nursing.html', 'Nursing Skills and Fundamentals NCLEX seed v1 - emergency triage tag colors nursing'),
  ('amputation', 'Notes/Fundamentals/amputation-nursing.html', 'Nursing Skills and Fundamentals NCLEX seed v1 - amputation nursing'),
