CREATE TEMP TABLE _fund_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _fund_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'nursing skills and fundamentals'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Nursing Skills and Fundamentals"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'nursing skills and fundamentals'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _fund_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Nursing Skills and Fundamentals subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Nursing Skills and Fundamentals points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _fund_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Fundamentals seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _fund_seed_map) <> 22 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 22 note mappings, found %.',
      (SELECT count(*) FROM _fund_seed_map);
  END IF;

  INSERT INTO _fund_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _fund_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, false, v.display_order, 1, true
  FROM (VALUES
  ('tube', 1, 'Before giving a feeding through a client''s existing nasogastric (NG) tube, the nurse checks the pH of the aspirate. Which result supports correct placement in the stomach?', '[{"id": "a", "text": "pH 7"}, {"id": "b", "text": "pH 10"}, {"id": "c", "text": "pH 8"}, {"id": "d", "text": "pH 3"}]'::jsonb, '["d"]', 'Stomach aspirate should be acidic, with a pH of 1-5, so a pH of 3 supports gastric placement. A pH of 7 or higher is not in the acidic range.'),
  ('tube', 2, 'A nasogastric (NG) tube has just been inserted for a client. Which method is the gold standard for confirming placement before the tube is first used?', '[{"id": "a", "text": "Measuring tube output"}, {"id": "b", "text": "Checking the aspirate pH"}, {"id": "c", "text": "Watching for coughing"}, {"id": "d", "text": "Obtaining an X-ray"}]'::jsonb, '["d"]', 'X-ray is the gold standard for confirming NG tube placement when the tube is first placed. Checking aspirate pH is used to check placement before later uses.'),
  ('tube', 3, 'During a nasogastric (NG) tube feeding, the client begins coughing and has trouble breathing. Which action should the nurse take first?', '[{"id": "a", "text": "Increase the rate of the feeding"}, {"id": "b", "text": "Stop the feeding and check placement"}, {"id": "c", "text": "Flush the tube and continue feeding"}, {"id": "d", "text": "Document and continue the feeding"}]'::jsonb, '["b"]', 'Coughing or breathing problems during an NG feeding suggest wrong placement, so the nurse stops the feeding and checks placement. Continuing the feeding is unsafe.'),
  ('tube', 4, 'Which finding suggests that a client''s nasogastric (NG) tube may be incorrectly placed in the lungs?', '[{"id": "a", "text": "Aspirate pH of 3"}, {"id": "b", "text": "Tube secured at the nose"}, {"id": "c", "text": "Clear oral mucosa after oral care"}, {"id": "d", "text": "Frequent coughing and trouble breathing"}]'::jsonb, '["d"]', 'If the client coughs a lot or has trouble breathing, the nurse should suspect the tube is in the lungs. An aspirate pH of 3 is acidic and supports gastric placement.'),
  ('tube', 5, 'The nurse is administering medication through a client''s nasogastric (NG) tube. Which action is correct?', '[{"id": "a", "text": "Flush with water only after the medication"}, {"id": "b", "text": "Flush with water only if the tube clogs"}, {"id": "c", "text": "Flush with water before and after the medication"}, {"id": "d", "text": "Avoid flushing the tube with any water"}]'::jsonb, '["c"]', 'NG tubes are flushed with water before and after medications and feedings. Flushing only after the medication omits the required flush beforehand.'),
  ('tube', 6, 'A client has a nasogastric (NG) tube connected to suction. How often should the nurse provide oral care?', '[{"id": "a", "text": "Every 8 hours"}, {"id": "b", "text": "Only on request"}, {"id": "c", "text": "Every 2 hours"}, {"id": "d", "text": "Once daily"}]'::jsonb, '["c"]', 'Clients with an NG tube need oral care every 2 hours because the nose and mouth can dry out. Once daily is not frequent enough.'),
  ('tube', 7, 'A client with a nasogastric (NG) tube asks why the nurse provides mouth care so often. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It helps confirm that the tube is in place.\""}, {"id": "b", "text": "\"It keeps the feeding at room temperature.\""}, {"id": "c", "text": "\"It keeps the tube from becoming clogged.\""}, {"id": "d", "text": "\"Your nose and mouth can dry out with the tube.\""}]'::jsonb, '["d"]', 'Frequent oral care is needed because the nose and mouth can dry out with an NG tube. Preventing clogging is the purpose of flushing the tube.'),
  ('tube', 8, 'The nurse is caring for a client with a newly placed nasogastric (NG) tube. Which action helps prevent the tube from being pulled?', '[{"id": "a", "text": "Keep the tube below the chest"}, {"id": "b", "text": "Rotate the tube gently each day"}, {"id": "c", "text": "Secure the tube at the nose"}, {"id": "d", "text": "Clamp the tube between uses"}]'::jsonb, '["c"]', 'An NG tube is secured at the nose to prevent pulling. Gentle rotation (if ordered) applies to a G-tube to prevent skin sticking.'),
  ('tube', 9, 'A client has a nasogastric (NG) tube connected to suction. Which nursing action is specific to this situation?', '[{"id": "a", "text": "Measure the tube output"}, {"id": "b", "text": "Rotate the tube gently"}, {"id": "c", "text": "Keep formula at room temperature"}, {"id": "d", "text": "Compress the drainage bulb"}]'::jsonb, '["a"]', 'When an NG tube is used for suctioning, the nurse measures the output. Compressing the bulb applies to a JP drain.'),
  ('tube', 10, 'A client asks the nurse what a nasogastric (NG) tube is used for. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It goes through your nose to your stomach for feeding or suction.\""}, {"id": "b", "text": "\"It removes air from around your lungs.\""}, {"id": "c", "text": "\"It removes fluid from your surgical site.\""}, {"id": "d", "text": "\"It drains urine from your bladder.\""}]'::jsonb, '["a"]', 'An NG tube goes through the nose into the stomach for feeding or suction. Removing air from around the lungs is the function of a chest tube.'),
  ('tube', 11, 'A client is expected to need tube feedings for a long time. Which tube that enters through the abdomen does the nurse anticipate?', '[{"id": "a", "text": "Chest tube"}, {"id": "b", "text": "Hemovac drain"}, {"id": "c", "text": "Nasogastric (NG) tube"}, {"id": "d", "text": "Gastrostomy (G) tube"}]'::jsonb, '["d"]', 'A G-tube goes through the belly into the stomach for long-term feeding. An NG tube enters through the nose.'),
  ('tube', 12, 'The nurse teaches a family caregiver about site care for a client''s gastrostomy (G) tube. Which statement by the caregiver indicates understanding?', '[{"id": "a", "text": "\"I will clean around the site daily with soap and water.\""}, {"id": "b", "text": "\"I will flush the tube only after feedings.\""}, {"id": "c", "text": "\"I will give the formula cold from the fridge.\""}, {"id": "d", "text": "\"I will clean the site once a week.\""}]'::jsonb, '["a"]', 'G-tube site care includes cleaning around the site daily with soap and water. Formula should be kept at room temperature, and the tube is flushed before and after feedings.'),
  ('tube', 13, 'The nurse teaches a caregiver about gastrostomy (G) tube feedings. Which statement by the caregiver indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll clean around the site daily with soap and water.\""}, {"id": "b", "text": "\"I''ll check for leakage around the tube.\""}, {"id": "c", "text": "\"I''ll give the formula straight from the refrigerator.\""}, {"id": "d", "text": "\"I''ll keep the site around the tube clean and dry.\""}]'::jsonb, '["c"]', 'Feeding formula should be kept at room temperature to avoid cramping, so cold formula from the refrigerator is incorrect. The other statements describe correct G-tube care.'),
  ('tube', 14, 'A client receiving a gastrostomy (G) tube feeding reports abdominal cramping. The nurse notes the formula was given cold. Which explanation is most likely?', '[{"id": "a", "text": "The tube has moved into the lungs"}, {"id": "b", "text": "The tube was flushed before feeding"}, {"id": "c", "text": "The site was cleaned with soap"}, {"id": "d", "text": "Cold formula can cause cramping"}]'::jsonb, '["d"]', 'Formula is kept at room temperature to avoid cramping, so cold formula is the likely cause. Cleaning with soap and flushing before feeding are correct parts of G-tube care.'),
  ('tube', 15, 'The provider orders gentle rotation of a client''s gastrostomy (G) tube. What is the purpose of this action?', '[{"id": "a", "text": "To confirm tube placement"}, {"id": "b", "text": "To increase drainage"}, {"id": "c", "text": "To prevent skin sticking"}, {"id": "d", "text": "To maintain suction"}]'::jsonb, '["c"]', 'A G-tube is gently rotated (if ordered) to prevent skin sticking. Maintaining suction is done by compressing the bulb of a JP drain.'),
  ('tube', 16, 'The nurse notes leaking around a client''s gastrostomy (G) tube. Which action should the nurse take?', '[{"id": "a", "text": "Check the tube and notify the provider"}, {"id": "b", "text": "Increase the feeding rate"}, {"id": "c", "text": "Ignore the small amount of leakage"}, {"id": "d", "text": "Clamp the tube and continue"}]'::jsonb, '["a"]', 'If a G-tube is leaking, the nurse checks the tube and notifies the provider. Ignoring the leak is unsafe.'),
  ('tube', 17, 'The nurse flushes a client''s gastrostomy (G) tube before and after each feeding. What is the purpose of this action?', '[{"id": "a", "text": "To avoid cramping"}, {"id": "b", "text": "To prevent clogging"}, {"id": "c", "text": "To check placement"}, {"id": "d", "text": "To prevent skin sticking"}]'::jsonb, '["b"]', 'G-tubes are flushed before and after feeding to prevent clogging. Preventing skin sticking is the purpose of gentle rotation.'),
  ('tube', 18, 'The nurse is caring for a client with a chest tube. Where should the drainage system be kept?', '[{"id": "a", "text": "On the bed above the chest"}, {"id": "b", "text": "Level with the chest"}, {"id": "c", "text": "On the client''s lap"}, {"id": "d", "text": "Below the chest"}]'::jsonb, '["d"]', 'The chest tube drainage system is kept below the chest so gravity helps drainage. Placing it level with or above the chest works against gravity.'),
  ('tube', 19, 'The nurse observes the water in a client''s chest tube water seal chamber moving up and down with breathing. How should the nurse interpret this finding?', '[{"id": "a", "text": "A normal finding"}, {"id": "b", "text": "An air leak to report"}, {"id": "c", "text": "A blocked chest tube"}, {"id": "d", "text": "A tension pneumothorax"}]'::jsonb, '["a"]', 'Tidaling, water moving up and down with breathing, is normal. Bubbling, not tidaling, indicates an air leak.'),
  ('tube', 20, 'While checking a client''s chest tube, the nurse sees bubbling in the water seal chamber. What does bubbling in this chamber indicate?', '[{"id": "a", "text": "Bloody drainage"}, {"id": "b", "text": "An air leak"}, {"id": "c", "text": "A clamped tube"}, {"id": "d", "text": "Normal tidaling"}]'::jsonb, '["b"]', 'Bubbling in the water seal chamber indicates an air leak. Tidaling is water moving up and down with breathing.'),
  ('tube', 21, 'The nurse is observing a newly hired nurse care for a client with a chest tube. Which action requires correction?', '[{"id": "a", "text": "Checking the water seal for tidaling"}, {"id": "b", "text": "Assessing for a sudden drainage change"}, {"id": "c", "text": "Keeping the drainage below the chest"}, {"id": "d", "text": "Clamping the tube without an order"}]'::jsonb, '["d"]', 'Chest tubes are not clamped unless ordered because of the risk of tension pneumothorax. The other actions are correct chest tube care.'),
  ('tube', 22, 'A UAP asks why a client''s chest tube should not be clamped. Which complication does the nurse explain can result from clamping without an order?', '[{"id": "a", "text": "Abdominal cramping"}, {"id": "b", "text": "Backflow infection"}, {"id": "c", "text": "Tension pneumothorax"}, {"id": "d", "text": "Skin sticking"}]'::jsonb, '["c"]', 'Clamping a chest tube without an order risks tension pneumothorax. Backflow infection is the risk when a urinary drainage bag is not kept below the bladder.'),
  ('tube', 23, 'A client''s chest tube accidentally comes out. Which action should the nurse take?', '[{"id": "a", "text": "Leave the site open to air"}, {"id": "b", "text": "Cover with sterile gauze taped on 3 sides"}, {"id": "c", "text": "Cover with sterile gauze taped on 4 sides"}, {"id": "d", "text": "Reinsert the chest tube"}]'::jsonb, '["b"]', 'If a chest tube comes out, the nurse covers the site with sterile gauze taped on 3 sides so air can escape but not enter. Taping all 4 sides would not let air escape.'),
  ('tube', 24, 'A nursing student asks why the dressing over a dislodged chest tube site is taped on only three sides. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It lets air escape but not enter.\""}, {"id": "b", "text": "\"It lets drainage collect on the gauze.\""}, {"id": "c", "text": "\"It prevents irritation of the skin.\""}, {"id": "d", "text": "\"It makes the dressing easier to remove.\""}]'::jsonb, '["a"]', 'Taping sterile gauze on 3 sides allows air to escape but not enter. The other reasons are not the purpose of this dressing.'),
  ('tube', 25, 'A client asks the nurse what the newly inserted chest tube does. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It removes fluid from your incision site.\""}, {"id": "b", "text": "\"It removes air, blood, or fluid from around your lungs.\""}, {"id": "c", "text": "\"It drains urine from your bladder.\""}, {"id": "d", "text": "\"It goes into your stomach for feeding.\""}]'::jsonb, '["b"]', 'A chest tube removes air, blood, or fluid from the pleural space around the lungs. Draining urine from the bladder is the function of a urinary catheter.'),
  ('tube', 26, 'The nurse notes an unexpected change in the color of a client''s nasogastric (NG) tube suction output. Which action should the nurse take first?', '[{"id": "a", "text": "Notify the provider before seeing the client"}, {"id": "b", "text": "Document and recheck next shift"}, {"id": "c", "text": "Clamp the tube"}, {"id": "d", "text": "Assess the client"}]'::jsonb, '["d"]', 'For an unexpected change in output, the nurse assesses the patient first and then notifies the provider. Calling the provider before assessing reverses the correct order.'),
  ('tube', 27, 'The nurse observes a UAP caring for a client with an indwelling urinary catheter. Which action by the UAP requires correction?', '[{"id": "a", "text": "Performing hand hygiene before care"}, {"id": "b", "text": "Placing the bag on the client''s abdomen"}, {"id": "c", "text": "Keeping the bag below the bladder"}, {"id": "d", "text": "Securing the catheter to the leg"}]'::jsonb, '["b"]', 'The drainage bag must be kept below the bladder to prevent backflow infection, so placing it on the abdomen is incorrect. The other actions are correct catheter care.'),
  ('tube', 28, 'A client with an indwelling urinary catheter asks why the drainage bag must hang below the bladder. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It prevents tugging on the catheter.\""}, {"id": "b", "text": "\"It prevents a collapsed lung.\""}, {"id": "c", "text": "\"It prevents backflow that causes infection.\""}, {"id": "d", "text": "\"It maintains suction in the bag.\""}]'::jsonb, '["c"]', 'Keeping the bag below the bladder prevents backflow infection. Tugging is prevented by securing the catheter to the leg.'),
  ('tube', 29, 'The nurse is caring for a client with an indwelling urinary catheter. Which action prevents tugging on the catheter?', '[{"id": "a", "text": "Rotate the catheter daily"}, {"id": "b", "text": "Secure the catheter to the leg"}, {"id": "c", "text": "Clamp the catheter tubing"}, {"id": "d", "text": "Keep the bag above the bladder"}]'::jsonb, '["b"]', 'Securing the catheter to the leg prevents tugging. The bag must be kept below, not above, the bladder.'),
  ('tube', 30, 'The nurse is assessing a client with an indwelling urinary catheter. Which finding suggests an infection?', '[{"id": "a", "text": "Cloudy, foul-smelling urine and fever"}, {"id": "b", "text": "Pale yellow urine without odor"}, {"id": "c", "text": "Urine draining freely into the bag"}, {"id": "d", "text": "Clear yellow urine"}]'::jsonb, '["a"]', 'Signs of catheter-related infection include cloudy urine, fever, and foul smell. Clear urine draining freely is not a sign of infection.'),
  ('tube', 31, 'The nurse is teaching a UAP about care of a client''s urinary drainage bag. How often should the bag be emptied?', '[{"id": "a", "text": "Only once every 2 to 3 days"}, {"id": "b", "text": "At least every shift or when full"}, {"id": "c", "text": "Only when the client is discharged"}, {"id": "d", "text": "Only once each week"}]'::jsonb, '["b"]', 'The drainage bag should be emptied regularly, at least every shift or when full. Emptying it only every 2 days or weekly is not regular enough.'),
  ('tube', 32, 'The nurse is caring for a client with an indwelling urinary catheter. Which action promotes urine flow into the drainage bag?', '[{"id": "a", "text": "Coil the tubing tightly under the client"}, {"id": "b", "text": "Clamp the tubing between emptyings"}, {"id": "c", "text": "Keep the tubing free of kinks"}, {"id": "d", "text": "Hang the bag above the bladder"}]'::jsonb, '["c"]', 'Catheter tubing should have no kinks, and the bag is kept low so urine can flow. Hanging the bag above the bladder risks backflow infection.'),
  ('tube', 33, 'The nurse is about to empty a client''s urinary drainage bag. Which action should the nurse take first?', '[{"id": "a", "text": "Clamp the catheter"}, {"id": "b", "text": "Rotate the catheter"}, {"id": "c", "text": "Perform hand hygiene"}, {"id": "d", "text": "Raise the bag above the bladder"}]'::jsonb, '["c"]', 'Hand hygiene is performed before and after touching the urinary catheter system. Raising the bag above the bladder risks backflow infection.'),
  ('tube', 34, 'The nurse has just emptied a client''s Jackson-Pratt (JP) drain. Which action should the nurse take next?', '[{"id": "a", "text": "Leave the bulb fully expanded"}, {"id": "b", "text": "Hang the bulb above the site"}, {"id": "c", "text": "Clamp the drain tubing"}, {"id": "d", "text": "Compress the bulb to maintain suction"}]'::jsonb, '["d"]', 'The JP bulb is compressed to maintain suction. Drainage systems are kept below the site, not above it.'),
  ('tube', 35, 'A client has a Hemovac drain after surgery. How does the nurse maintain suction in this drain?', '[{"id": "a", "text": "Keep the spring fully expanded"}, {"id": "b", "text": "Compress the spring"}, {"id": "c", "text": "Clamp the drain tubing"}, {"id": "d", "text": "Flush the drain with water"}]'::jsonb, '["b"]', 'Suction in a Hemovac is maintained by compressing the spring. Leaving the spring expanded would not maintain suction.'),
  ('tube', 36, 'The output from a client''s Jackson-Pratt (JP) drain suddenly stops. Which action should the nurse take first?', '[{"id": "a", "text": "Expand the bulb"}, {"id": "b", "text": "Check for a clot or kink"}, {"id": "c", "text": "Flush the drain with water"}, {"id": "d", "text": "Remove the drain"}]'::jsonb, '["b"]', 'If surgical drain output suddenly stops, the nurse checks for a clot or kink. Expanding the bulb would lose suction rather than restore flow.'),
  ('tube', 37, 'The nurse empties a client''s surgical drain. Which information should the nurse record?', '[{"id": "a", "text": "pH of the drainage"}, {"id": "b", "text": "Color of the drainage"}, {"id": "c", "text": "Bubbling in the chamber"}, {"id": "d", "text": "Presence of tidaling"}]'::jsonb, '["b"]', 'For surgical drains, the nurse records the color of the drainage (bloody, serous, cloudy). Tidaling and bubbling are chest tube water seal findings.'),
  ('tube', 38, 'The nurse receives a client with a newly placed tube. Which is one of the first priorities of care for any tube?', '[{"id": "a", "text": "Check that the tube is in the right place"}, {"id": "b", "text": "Change the tube every day"}, {"id": "c", "text": "Keep the insertion site moist"}, {"id": "d", "text": "Clamp the tube between uses"}]'::jsonb, '["a"]', 'Checking placement, confirming the tube is where it is supposed to be, is a first focus for any tube. The site should be kept clean and dry, not moist.'),
  ('tube', 39, 'The nurse is monitoring the output from a client''s drainage tube. Which characteristics should the nurse assess?', '[{"id": "a", "text": "The amount of output only"}, {"id": "b", "text": "The color of output only"}, {"id": "c", "text": "The smell of output only"}, {"id": "d", "text": "Amount, color, and smell"}]'::jsonb, '["d"]', 'Tube output is monitored for amount, color, and smell. Assessing only one characteristic is incomplete.'),
  ('tube', 40, 'A client''s feeding tube is not allowing the feeding to run as expected. Which complication should the nurse recognize?', '[{"id": "a", "text": "Infection"}, {"id": "b", "text": "Tension pneumothorax"}, {"id": "c", "text": "Blockage"}, {"id": "d", "text": "Dislodgement"}]'::jsonb, '["c"]', 'A blockage is present when a tube is not draining or feeding right. Dislodgement is when the tube moves or falls out.'),
  ('tube', 41, 'The nurse finds that a client''s tube has moved and is partially out of the insertion site. Which complication does this represent?', '[{"id": "a", "text": "Dislodgement"}, {"id": "b", "text": "Air leak"}, {"id": "c", "text": "Infection"}, {"id": "d", "text": "Blockage"}]'::jsonb, '["a"]', 'Dislodgement is when the tube moves or falls out. Blockage is when the tube is not draining or feeding right.'),
  ('tube', 42, 'The nurse is assessing a client''s gastrostomy (G) tube site. Which finding suggests an infection?', '[{"id": "a", "text": "No leakage around the tube"}, {"id": "b", "text": "A tube that rotates freely"}, {"id": "c", "text": "Redness, swelling, and pus"}, {"id": "d", "text": "Clean, dry skin"}]'::jsonb, '["c"]', 'Signs of infection include redness, swelling, fever, and pus. Clean, dry skin is the goal of site care.'),
  ('tube', 43, 'A UAP asks why the nurse keeps a client''s tube insertion site clean and dry. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It helps prevent infection.\""}, {"id": "b", "text": "\"It prevents a collapsed lung.\""}, {"id": "c", "text": "\"It confirms tube placement.\""}, {"id": "d", "text": "\"It helps maintain suction.\""}]'::jsonb, '["a"]', 'The tube site is kept clean and dry to prevent infection. Maintaining suction is done by compressing a drain''s bulb or spring.'),
  ('tube', 44, 'The urine output from a client''s catheter unexpectedly changes. Which action should the nurse take first?', '[{"id": "a", "text": "Assess the client"}, {"id": "b", "text": "Clamp the catheter"}, {"id": "c", "text": "Remove the catheter"}, {"id": "d", "text": "Call the provider before seeing the client"}]'::jsonb, '["a"]', 'When output changes unexpectedly, the nurse assesses first and then calls the provider. Calling before assessing reverses the correct order.'),
  ('tube', 45, 'The nurse is repositioning a client who has a chest tube. Which action is correct?', '[{"id": "a", "text": "Place the drainage unit on the bed above the chest"}, {"id": "b", "text": "Hold the drainage unit level with the shoulders"}, {"id": "c", "text": "Clamp the tube while turning the client"}, {"id": "d", "text": "Keep the drainage unit below chest level"}]'::jsonb, '["d"]', 'The chest tube drainage system is kept below the chest so gravity helps drainage, and the tube is not clamped unless ordered. Placing the unit above the chest works against gravity.'),
  ('tube', 46, 'A client returns from surgery with a tube that removes fluid from the surgical site. Which type of tube is this?', '[{"id": "a", "text": "Urinary catheter"}, {"id": "b", "text": "Jackson-Pratt (JP) drain"}, {"id": "c", "text": "Nasogastric (NG) tube"}, {"id": "d", "text": "Gastrostomy (G) tube"}]'::jsonb, '["b"]', 'Surgical drains such as the JP and Hemovac remove fluid from surgical sites. A urinary catheter drains urine from the bladder.'),
  ('tube', 47, 'The nurse is about to give a feeding through a client''s established nasogastric (NG) tube. Which action is the priority before each use?', '[{"id": "a", "text": "Compress the bulb"}, {"id": "b", "text": "Rotate the tube"}, {"id": "c", "text": "Check placement"}, {"id": "d", "text": "Chill the formula"}]'::jsonb, '["c"]', 'The key safety point for an NG tube is to check placement before each use. Compressing the bulb applies to a JP drain.'),
  ('tube', 48, 'The nurse is performing a routine assessment of a client''s gastrostomy (G) tube. Which assessment is part of G-tube care?', '[{"id": "a", "text": "Compressing the bulb"}, {"id": "b", "text": "Checking for tidaling"}, {"id": "c", "text": "Keeping the bag below the bladder"}, {"id": "d", "text": "Checking for leakage around the tube"}]'::jsonb, '["d"]', 'G-tube care includes checking for leakage around the tube. Tidaling is assessed in a chest tube water seal chamber.'),
  ('tube', 49, 'The nurse is monitoring a client''s chest tube. Which finding requires immediate assessment?', '[{"id": "a", "text": "Sudden change to bloody drainage"}, {"id": "b", "text": "Tube left unclamped"}, {"id": "c", "text": "Drainage unit below the chest"}, {"id": "d", "text": "Tidaling with breathing"}]'::jsonb, '["a"]', 'The nurse assesses for a sudden change in chest tube drainage, and blood is a concerning finding. Tidaling with breathing is normal.'),
  ('tube', 50, 'The nurse teaches a client going home with an indwelling urinary catheter. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll wash my hands before touching it.\""}, {"id": "b", "text": "\"I''ll secure the catheter to my leg.\""}, {"id": "c", "text": "\"I''ll keep the bag below my bladder.\""}, {"id": "d", "text": "\"I''ll hang the bag higher than my bladder at night.\""}]'::jsonb, '["d"]', 'The bag must stay below the bladder to prevent backflow infection, so hanging it higher is incorrect. Securing the catheter to the leg and hand hygiene are correct.'),
  ('family', 1, 'During an admission interview, a client reports living at home with a spouse and their two children. Which family structure does the nurse document?', '[{"id": "a", "text": "Extended family"}, {"id": "b", "text": "Nuclear family"}, {"id": "c", "text": "Blended family"}, {"id": "d", "text": "Alternative family"}]'::jsonb, '["b"]', 'A nuclear family consists of parents and children living together. An extended family also includes grandparents, aunts, or uncles living together.'),
  ('family', 2, 'A client reports living in one home with parents, a grandmother, an aunt, and an uncle. Which family structure does this describe?', '[{"id": "a", "text": "Nuclear family"}, {"id": "b", "text": "Single-parent family"}, {"id": "c", "text": "Extended family"}, {"id": "d", "text": "Blended family"}]'::jsonb, '["c"]', 'An extended family includes grandparents, aunts, and uncles living together. A nuclear family is limited to parents and children.'),
  ('family', 3, 'A nursing student asks the nurse to define a blended family. Which description is accurate?', '[{"id": "a", "text": "Grandparents and other relatives living together in one home"}, {"id": "b", "text": "One parent raising one or more children alone in the home"}, {"id": "c", "text": "Two friends raising a child together outside a traditional home"}, {"id": "d", "text": "Step-parents and step-children mixed into one family unit"}]'::jsonb, '["d"]', 'A blended family has step-parents and step-children mixed into one family. Grandparents and relatives living together describes an extended family.'),
  ('family', 4, 'A mother brings her three children to a clinic and states she is raising them alone. Which family structure does the nurse identify?', '[{"id": "a", "text": "Single-parent family"}, {"id": "b", "text": "Nuclear family"}, {"id": "c", "text": "Alternative family"}, {"id": "d", "text": "Extended family"}]'::jsonb, '["a"]', 'A single-parent family is one parent raising a child or children alone. A nuclear family includes both parents living with the children.'),
  ('family', 5, 'A client explains that she and a close friend share a home and are raising a child together. Which family structure does the nurse identify?', '[{"id": "a", "text": "Blended family"}, {"id": "b", "text": "Alternative family"}, {"id": "c", "text": "Nuclear family"}, {"id": "d", "text": "Single-parent family"}]'::jsonb, '["b"]', 'An alternative family is a living arrangement outside the traditional, such as two friends raising a child. A blended family involves step-parents and step-children.'),
  ('family', 6, 'An older client''s daughter visits daily to help the client dress and eat meals. Which family role is the daughter filling?', '[{"id": "a", "text": "Decision maker"}, {"id": "b", "text": "Financial provider"}, {"id": "c", "text": "Caregiver"}, {"id": "d", "text": "Emotional support"}]'::jsonb, '["c"]', 'The caregiver provides direct care, such as helping the client dress and feed. The decision maker chooses important things such as treatments.'),
  ('family', 7, 'A client tells the nurse that her adult son pays the rent and household bills. Which family role does the son fill?', '[{"id": "a", "text": "Caregiver"}, {"id": "b", "text": "Decision maker"}, {"id": "c", "text": "Emotional support"}, {"id": "d", "text": "Financial provider"}]'::jsonb, '["d"]', 'The financial provider pays for household needs. A caregiver provides direct care such as dressing and feeding.'),
  ('family', 8, 'When the provider presents treatment options, a client says, "My wife chooses what we do about my treatments." Which family role does the wife fill?', '[{"id": "a", "text": "Decision maker"}, {"id": "b", "text": "Caregiver"}, {"id": "c", "text": "Financial provider"}, {"id": "d", "text": "Emotional support"}]'::jsonb, '["a"]', 'The decision maker chooses important things, such as treatments. A caregiver provides direct care such as dressing and feeding.'),
  ('family', 9, 'A client''s sister sits with the client, offers comfort, and helps the client talk through feelings about a new diagnosis. Which family role is the sister filling?', '[{"id": "a", "text": "Caregiver"}, {"id": "b", "text": "Emotional support"}, {"id": "c", "text": "Decision maker"}, {"id": "d", "text": "Financial provider"}]'::jsonb, '["b"]', 'The emotional support role helps with feelings and comfort. A caregiver provides direct physical care such as dressing and feeding.'),
  ('family', 10, 'A client''s daughter provides all of the client''s daily care, pays the household bills, and makes every treatment decision. She tells the nurse, "I''m exhausted and stressed all the time." Which concept does the nurse recognize?', '[{"id": "a", "text": "Role confusion"}, {"id": "b", "text": "Power struggle"}, {"id": "c", "text": "Role strain"}, {"id": "d", "text": "Neglect"}]'::jsonb, '["c"]', 'Role strain is stress that happens when one person has too much responsibility. Role confusion is when no one knows who is in charge, which is not the case here.'),
  ('family', 11, 'During a family meeting, the nurse notices that family members argue, interrupt one another, and do not listen to each other. Which warning sign of dysfunctional family dynamics is present?', '[{"id": "a", "text": "Poor communication"}, {"id": "b", "text": "Role confusion"}, {"id": "c", "text": "Power struggles"}, {"id": "d", "text": "Neglect"}]'::jsonb, '["a"]', 'Poor communication includes arguing and not listening. Power struggles involve fighting over control, and role confusion means no one knows who is in charge.'),
  ('family', 12, 'When the nurse asks who will help make decisions about a client''s discharge, each adult child says that someone else is handling it, and no one knows who is in charge. Which warning sign does this represent?', '[{"id": "a", "text": "Poor communication"}, {"id": "b", "text": "Power struggles"}, {"id": "c", "text": "Neglect"}, {"id": "d", "text": "Role confusion"}]'::jsonb, '["d"]', 'Role confusion occurs when no one knows who''s in charge. Power struggles involve fighting over control rather than an absence of leadership.'),
  ('family', 13, 'Two adult children repeatedly fight at the bedside about which of them will control their father''s care and finances. Which warning sign of dysfunctional family dynamics does the nurse identify?', '[{"id": "a", "text": "Role confusion"}, {"id": "b", "text": "Power struggles"}, {"id": "c", "text": "Role strain"}, {"id": "d", "text": "Alternative family"}]'::jsonb, '["b"]', 'Power struggles involve fighting over control. Role confusion is when no one knows who is in charge, not when members compete to be in charge.'),
  ('family', 14, 'The nurse is assessing several families. Which finding is a warning sign of dysfunctional family dynamics?', '[{"id": "a", "text": "Family members visit the client every evening"}, {"id": "b", "text": "Family members ask questions about home care"}, {"id": "c", "text": "Family members ignore the client''s basic needs"}, {"id": "d", "text": "Family members bring photos for the client''s room"}]'::jsonb, '["c"]', 'Neglect, which includes ignoring needs, is a warning sign of dysfunctional family dynamics. Visiting and asking questions about care suggest involvement.'),
  ('family', 15, 'The nurse is completing an admission assessment. Which question best helps the nurse understand the client''s family?', '[{"id": "a", "text": "\"Who do you consider family?\""}, {"id": "b", "text": "\"Who is your legal next of kin?\""}, {"id": "c", "text": "\"Are you married or single?\""}, {"id": "d", "text": "\"How many siblings do you have?\""}]'::jsonb, '["a"]', 'Nurses should ask clients who they consider family and respect the client''s definition, not just legal relationships. Asking only about legal or marital ties may miss important people.'),
  ('family', 16, 'The nurse is beginning discharge planning for a client who lives alone. Which question should the nurse ask?', '[{"id": "a", "text": "\"Who helps you at home?\""}, {"id": "b", "text": "\"Why don''t you live with your relatives?\""}, {"id": "c", "text": "\"Is your family able to pay for care?\""}, {"id": "d", "text": "\"Do you want to stay in the hospital?\""}]'::jsonb, '["a"]', 'Asking "Who helps you at home?" identifies the people involved in the client''s care for discharge planning. The other questions are judgmental or unrelated to who supports the client.'),
  ('family', 17, 'A client''s brother asks the nurse to teach him about the client''s new medications. The client has not said whether the brother may be involved. Which action should the nurse take first?', '[{"id": "a", "text": "Teach the brother because he is a family member"}, {"id": "b", "text": "Ask the client whether the brother may be included"}, {"id": "c", "text": "Tell the brother he can never receive information"}, {"id": "d", "text": "Give the brother a medication list to take home"}]'::jsonb, '["b"]', 'The nurse includes family in teaching and care if the client allows. Teaching the brother without asking the client ignores the need for permission.'),
  ('family', 18, 'A client tells the nurse that a close friend, who is not legally related, is "my family" and asks that the friend be involved in care. Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"Only legal relatives can be involved in your care.\""}, {"id": "b", "text": "\"Your friend may visit but cannot join any teaching.\""}, {"id": "c", "text": "\"I will include your friend since you consider them family.\""}, {"id": "d", "text": "\"Please name a blood relative to be involved instead.\""}]'::jsonb, '["c"]', 'The nurse should always respect the client''s definition of family, not just legal relationships. Limiting involvement to legal relatives disregards the client''s definition.'),
  ('family', 19, 'Ongoing conflict among a client''s family members is causing the client distress and interfering with recovery. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Refer the family to counseling or social work"}, {"id": "b", "text": "Take the side of the family member who is right"}, {"id": "c", "text": "Ban all family members from visiting the client"}, {"id": "d", "text": "Ignore the conflict because it is a family matter"}]'::jsonb, '["a"]', 'The nurse refers to resources such as counseling when family dynamics cause problems. Taking sides or ignoring the conflict does not support healthy coping.'),
  ('family', 20, 'A client''s spouse, who is the sole caregiver, tells the nurse, "I haven''t slept well in weeks, and I feel worn out all the time." Which concern should the nurse recognize?', '[{"id": "a", "text": "Role confusion"}, {"id": "b", "text": "Caregiver burnout"}, {"id": "c", "text": "Power struggles"}, {"id": "d", "text": "Poor communication"}]'::jsonb, '["b"]', 'The nurse watches for signs of caregiver burnout, such as a caregiver feeling worn out. Role confusion refers to no one knowing who is in charge.'),
  ('family', 21, 'A nursing student makes several statements about family decision-making. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Families may have different beliefs that guide care.\""}, {"id": "b", "text": "\"Every family should make decisions in the same way.\""}, {"id": "c", "text": "\"Roles in a family can differ based on culture.\""}, {"id": "d", "text": "\"I should respect how a family makes decisions.\""}]'::jsonb, '["b"]', 'Nurses respect cultural differences in family roles and decision-making. Expecting all families to decide the same way ignores these differences.'),
  ('family', 22, 'A nursing student states, "Involving the family always helps the client heal." Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"Family can be a resource or a source of stress.\""}, {"id": "b", "text": "\"No, families should be kept away from care.\""}, {"id": "c", "text": "\"Yes, family involvement always improves healing.\""}, {"id": "d", "text": "\"Only legal relatives can help the client heal.\""}]'::jsonb, '["a"]', 'Family can be a resource or a stress, so family involvement does not always help. Keeping families away entirely ignores that family can be a resource.'),
  ('family', 23, 'A nursing student asks the nurse what the term family dynamics means. Which response is accurate?', '[{"id": "a", "text": "The number of people living in the client''s home"}, {"id": "b", "text": "The amount of money each family member earns"}, {"id": "c", "text": "The legal relationships between family members"}, {"id": "d", "text": "How family members relate to and affect each other"}]'::jsonb, '["d"]', 'Family dynamics are how family members relate to and affect each other. Defining family only by legal relationships is incorrect.'),
  ('family', 24, 'A nurse explains to a student why family dynamics are part of the client assessment. Which statement by the nurse is accurate?', '[{"id": "a", "text": "\"Family issues can affect care, healing, and coping.\""}, {"id": "b", "text": "\"Family issues rarely affect a client in the hospital.\""}, {"id": "c", "text": "\"Family issues matter only for pediatric clients.\""}, {"id": "d", "text": "\"Family issues are assessed only by social workers.\""}]'::jsonb, '["a"]', 'Family issues can impact patient care, healing, and coping. They are not limited to pediatric clients or a single discipline.'),
  ('family', 25, 'A client is being discharged after surgery, and the spouse will help with care at home. The nurse plans to include the spouse in discharge teaching. Which action should the nurse take first?', '[{"id": "a", "text": "Begin teaching the spouse in the waiting room"}, {"id": "b", "text": "Give the spouse the discharge papers to sign"}, {"id": "c", "text": "Teach only the client and exclude the spouse"}, {"id": "d", "text": "Obtain the client''s permission to include the spouse"}]'::jsonb, '["d"]', 'Family is included in discharge planning and teaching with the client''s permission. Teaching the spouse before asking the client skips this step.'),
  ('family', 26, 'The family members at a client''s bedside are tense and speaking sharply to one another. Which nursing action is most appropriate?', '[{"id": "a", "text": "Support open communication among the family members"}, {"id": "b", "text": "Take the side of the client''s oldest family member"}, {"id": "c", "text": "Ask all family members to leave and not return"}, {"id": "d", "text": "Ignore the tension and continue routine care"}]'::jsonb, '["a"]', 'The nurse supports communication and healthy coping within the family. Taking sides or ignoring the tension does not promote healthy coping.'),
  ('family', 27, 'The nurse is reviewing the family situations of four clients. Which family member is at greatest risk for role strain?', '[{"id": "a", "text": "A son who shares caregiving with three siblings"}, {"id": "b", "text": "A wife who manages finances while a son gives care"}, {"id": "c", "text": "A daughter who handles all care, bills, and decisions"}, {"id": "d", "text": "A husband who visits while relatives handle care"}]'::jsonb, '["c"]', 'Role strain happens when one person has too much responsibility. The daughter holds every role alone, while the others share responsibilities.'),
  ('family', 28, 'A client''s adult son, who is the only caregiver, tells the nurse, "I can''t keep doing this by myself." Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Tell the son that caring for a parent is his responsibility"}, {"id": "b", "text": "Suggest that the son try harder to stay organized at home"}, {"id": "c", "text": "Advise the son to stop visiting until he feels better"}, {"id": "d", "text": "Involve social services or case management for support"}]'::jsonb, '["d"]', 'The nurse knows when to involve social services, case management, or counseling, such as when a caregiver shows signs of burnout. Dismissing the concern does not address it.'),
  ('family', 29, 'A nursing student makes several statements about family-centered care. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will ask the client who they consider family.\""}, {"id": "b", "text": "\"Only legal relatives should be treated as family.\""}, {"id": "c", "text": "\"I will include family in teaching with permission.\""}, {"id": "d", "text": "\"Family can be either a resource or a stress.\""}]'::jsonb, '["b"]', 'Nurses always respect the client''s definition of family, not just legal relationships. The other statements reflect correct family-centered care.'),
  ('family', 30, 'A client lives with her husband, their son, and her husband''s daughter from a previous marriage. Which family structure does the nurse document?', '[{"id": "a", "text": "Nuclear family"}, {"id": "b", "text": "Extended family"}, {"id": "c", "text": "Alternative family"}, {"id": "d", "text": "Blended family"}]'::jsonb, '["d"]', 'A blended family has step-parents and step-children mixed into one family. A nuclear family consists of parents and their children without step-relationships.'),
  ('family', 31, 'A father brings his two children for checkups and explains that he has raised them alone since his wife died. Which family structure does the nurse identify?', '[{"id": "a", "text": "Nuclear family"}, {"id": "b", "text": "Blended family"}, {"id": "c", "text": "Single-parent family"}, {"id": "d", "text": "Alternative family"}]'::jsonb, '["c"]', 'A single-parent family is one parent raising a child or children alone. A nuclear family has both parents living with the children.'),
  ('family', 32, 'The nurse is reviewing four clients'' living situations. Which client lives in an extended family?', '[{"id": "a", "text": "A client living with a parent and two siblings only"}, {"id": "b", "text": "A client living with parents, grandparents, and an uncle"}, {"id": "c", "text": "A client living with a stepfather and two stepbrothers"}, {"id": "d", "text": "A client living with a friend who helps raise the client"}]'::jsonb, '["b"]', 'An extended family includes grandparents, aunts, or uncles living together. A stepfather and stepbrothers describe a blended family.'),
  ('family', 33, 'A nursing student asks for an example of an alternative family. Which example should the nurse give?', '[{"id": "a", "text": "Two friends raising a child together in one home"}, {"id": "b", "text": "Two parents living with their biological children"}, {"id": "c", "text": "A step-parent living with a spouse''s children"}, {"id": "d", "text": "Grandparents and an aunt living with a family"}]'::jsonb, '["a"]', 'An alternative family is a living arrangement outside the traditional, such as two friends raising a child. A step-parent with a spouse''s children is a blended family.'),
  ('family', 34, 'The nurse is reviewing family structures with a nursing student. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"A single-parent family has one parent raising children.\""}, {"id": "b", "text": "\"A blended family includes step-parents and step-children.\""}, {"id": "c", "text": "\"A nuclear family includes grandparents living in the home.\""}, {"id": "d", "text": "\"An extended family includes aunts and uncles at home.\""}]'::jsonb, '["c"]', 'A nuclear family is parents and children living together; grandparents living in the home make it an extended family. The other statements are accurate.'),
  ('family', 35, 'A nurse is admitting a client whose family members are at the bedside. Which action reflects the assessment component of the nurse''s role with family dynamics?', '[{"id": "a", "text": "Referring the family to a counselor"}, {"id": "b", "text": "Identifying who is involved and who decides"}, {"id": "c", "text": "Including the family in client teaching"}, {"id": "d", "text": "Respecting the family''s cultural beliefs"}]'::jsonb, '["b"]', 'Assessing family dynamics means determining who is involved and who makes decisions. Referring, including in teaching, and respecting beliefs are the refer, support, and respect components.'),
  ('family', 36, 'The nurse determines that a client''s family conflict needs professional help beyond what the nurse can provide. Which action reflects the referral component of the nurse''s role?', '[{"id": "a", "text": "Asking the family who makes decisions"}, {"id": "b", "text": "Teaching the family about medications"}, {"id": "c", "text": "Arranging for social work or counseling"}, {"id": "d", "text": "Respecting the family''s cultural beliefs"}]'::jsonb, '["c"]', 'The referral component involves getting social work or counseling if needed. Asking who makes decisions is part of assessment.'),
  ('family', 37, 'A client''s family holds beliefs about illness that differ from the nurse''s own beliefs. Which approach by the nurse is appropriate?', '[{"id": "a", "text": "Encourage the family to adopt the nurse''s beliefs"}, {"id": "b", "text": "Respect that families may have different beliefs"}, {"id": "c", "text": "Limit the family''s visits until beliefs change"}, {"id": "d", "text": "Avoid discussing care with the family members"}]'::jsonb, '["b"]', 'The nurse respects that different families may have different cultures and beliefs. Pressuring the family to change beliefs does not show respect.'),
  ('family', 38, 'While visiting a client, a family member grabs the client''s arm roughly and yells at the client. Which warning sign of dysfunctional family dynamics does the nurse recognize?', '[{"id": "a", "text": "Role confusion"}, {"id": "b", "text": "Role strain"}, {"id": "c", "text": "Abuse"}, {"id": "d", "text": "Power struggles"}]'::jsonb, '["c"]', 'Neglect or abuse, including harming family members, is a warning sign of dysfunctional family dynamics. Role confusion is when no one knows who is in charge.'),
  ('family', 39, 'Which observation by the nurse is an example of poor communication within a family?', '[{"id": "a", "text": "Siblings fight over who will control the care"}, {"id": "b", "text": "No one knows which member is in charge"}, {"id": "c", "text": "Members ignore the client''s basic needs"}, {"id": "d", "text": "Members talk over each other and don''t listen"}]'::jsonb, '["d"]', 'Poor communication includes arguing and not listening. Fighting over control is a power struggle, not knowing who is in charge is role confusion, and ignoring needs is neglect.'),
  ('family', 40, 'A client recovering from surgery becomes visibly upset after loud family arguments during visiting hours. Which understanding should guide the nurse''s care?', '[{"id": "a", "text": "Family conflict has no effect on physical recovery"}, {"id": "b", "text": "Family problems can cause stress and affect healing"}, {"id": "c", "text": "Family arguments only matter for clients at home"}, {"id": "d", "text": "Family stress affects only the family members"}]'::jsonb, '["b"]', 'Family problems can cause stress for the client and affect healing. Assuming conflict has no effect on recovery contradicts this.'),
  ('family', 41, 'A client preparing for discharge says, "My neighbor is like family to me. She helps me every day." The client asks that the neighbor learn the home care plan. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Include the neighbor in discharge teaching as requested"}, {"id": "b", "text": "Teach only the client''s legal next of kin about home care"}, {"id": "c", "text": "Exclude the neighbor because she is not a relative"}, {"id": "d", "text": "Teach the neighbor later without telling the client"}]'::jsonb, '["a"]', 'Nurses include family in discharge planning and teaching with the client''s permission and respect the client''s definition of family. Excluding the neighbor because she is not a relative ignores the client''s definition.'),
  ('family', 42, 'A client''s husband lives out of state and cannot help with daily care, but he calls every evening to comfort and reassure the client about her worries. Which family role is the husband filling?', '[{"id": "a", "text": "Caregiver"}, {"id": "b", "text": "Decision maker"}, {"id": "c", "text": "Financial provider"}, {"id": "d", "text": "Emotional support"}]'::jsonb, '["d"]', 'The emotional support role helps with feelings and comfort. A caregiver provides direct care, such as helping the client dress and eat.'),
  ('family', 43, 'A client tells the nurse that in her culture, family elders take part in all major health decisions, and she would like them present when treatment options are discussed. Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"Only you may be present when we discuss treatment.\""}, {"id": "b", "text": "\"I will arrange for your elders to be present.\""}, {"id": "c", "text": "\"Your elders can visit after the decision is made.\""}, {"id": "d", "text": "\"Decisions here are made the same way for everyone.\""}]'::jsonb, '["b"]', 'Nurses respect cultural differences in family roles and decision-making. Insisting that every family decide the same way disregards the client''s cultural preferences.'),
  ('family', 44, 'A nurse is discussing the effect of family on client care. Which statement by the nurse reflects accurate understanding?', '[{"id": "a", "text": "\"Family members always support the client''s healing.\""}, {"id": "b", "text": "\"Family members should not be part of client care.\""}, {"id": "c", "text": "\"Family can be a resource or a source of stress.\""}, {"id": "d", "text": "\"Family members only matter at hospital discharge.\""}]'::jsonb, '["c"]', 'Family can be a resource or a stress for the client. Saying family always supports healing overlooks that family problems can cause stress.'),
  ('family', 45, 'The charge nurse observes several nurses interacting with clients'' families. Which action requires correction?', '[{"id": "a", "text": "Asking a client who helps at home"}, {"id": "b", "text": "Teaching a cousin before the client agrees"}, {"id": "c", "text": "Referring a family to a counselor"}, {"id": "d", "text": "Respecting a family''s cultural beliefs"}]'::jsonb, '["b"]', 'The nurse includes family in teaching and care only if the client allows. Teaching a cousin before the client agrees skips the client''s permission.'),
  ('family', 46, 'A nurse is teaching a family caregiver about role strain. Which statement by the caregiver indicates a need for further teaching?', '[{"id": "a", "text": "\"Role strain is stress from having too much responsibility.\""}, {"id": "b", "text": "\"Sharing care with others may help prevent role strain.\""}, {"id": "c", "text": "\"Role strain can happen when one person does everything.\""}, {"id": "d", "text": "\"Role strain happens when many people share the work.\""}]'::jsonb, '["d"]', 'Role strain happens when one person has too much responsibility, not when work is shared. The other statements are consistent with this definition.'),
  ('family', 47, 'A client is admitted with several adult children at the bedside who all want to discuss the client''s treatment. Which action should the nurse take first?', '[{"id": "a", "text": "Determine who is involved and who makes decisions"}, {"id": "b", "text": "Teach all of the children about the treatment plan"}, {"id": "c", "text": "Refer the family to counseling before any discussion"}, {"id": "d", "text": "Ask the children to choose one person to visit"}]'::jsonb, '["a"]', 'The nurse first assesses who is involved and who makes decisions. Teaching everyone before assessing, or referring without an identified problem, skips the assessment.'),
  ('family', 48, 'Which group lists warning signs of dysfunctional family dynamics?', '[{"id": "a", "text": "Shared roles, open communication, mutual respect"}, {"id": "b", "text": "Poor communication, role confusion, power struggles"}, {"id": "c", "text": "Frequent visits, questions about care, family photos"}, {"id": "d", "text": "Cultural beliefs, shared decisions, caregiver support"}]'::jsonb, '["b"]', 'Warning signs of dysfunctional family dynamics include poor communication, role confusion, power struggles, and neglect or abuse. The other lists describe involvement or healthy features.'),
  ('family', 49, 'A home health nurse finds that an older client''s family members have not provided the client with meals or help with hygiene for several days. Which action is most appropriate?', '[{"id": "a", "text": "Praise the family for allowing the client independence"}, {"id": "b", "text": "Accept the situation because it is a family decision"}, {"id": "c", "text": "Involve social services because this suggests neglect"}, {"id": "d", "text": "Ask the client to be more patient with the family"}]'::jsonb, '["c"]', 'Neglect, such as ignoring a family member''s needs, is a warning sign of dysfunctional dynamics, and the nurse knows when to involve social services. Accepting the situation leaves the client''s needs unmet.'),
  ('family', 50, 'A hospitalized client worries about how the household bills will be paid because he is the only family member who pays for household needs. Which family role does the client fill?', '[{"id": "a", "text": "Caregiver"}, {"id": "b", "text": "Emotional support"}, {"id": "c", "text": "Decision maker"}, {"id": "d", "text": "Financial provider"}]'::jsonb, '["d"]', 'The financial provider pays for household needs. The emotional support role helps with feelings and comfort.'),
  ('consent', 1, 'A client scheduled for surgery tomorrow asks the nurse to explain the risks of the procedure so the client can sign the consent form tonight. The surgeon has not yet spoken with the client. Which action should the nurse take?', '[{"id": "a", "text": "Explain the surgical risks and have the client sign the form"}, {"id": "b", "text": "Notify the provider that the client needs the procedure explained"}, {"id": "c", "text": "Ask the charge nurse to obtain the client''s signature tonight"}, {"id": "d", "text": "Give the client a pamphlet and obtain the signature afterward"}]'::jsonb, '["b"]', 'The provider must explain the procedure, risks, benefits, and alternatives directly to the client before consent is signed. Explaining the risks and having the client sign would mean the nurse is obtaining consent, which is the provider''s job.'),
  ('consent', 2, 'A nursing student asks the nurse who is responsible for obtaining informed consent for a client''s scheduled procedure. Which response by the nurse is correct?', '[{"id": "a", "text": "The registered nurse assigned to the client"}, {"id": "b", "text": "The charge nurse on the client''s unit"}, {"id": "c", "text": "The provider, such as an MD, NP, or PA"}, {"id": "d", "text": "The client''s designated family member"}]'::jsonb, '["c"]', 'Only the provider (MD, NP, PA) may obtain informed consent. Nurses reinforce and support understanding but do not obtain consent.'),
  ('consent', 3, 'After the surgeon explains a procedure and leaves, the client asks the nurse, "What did the doctor mean when she talked about the alternatives?" Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Tell the client that only the surgeon may discuss the procedure"}, {"id": "b", "text": "Have the client sign the form and ask questions afterward"}, {"id": "c", "text": "Reinforce the provider''s explanation of the alternatives discussed"}, {"id": "d", "text": "Ask the client''s spouse to explain the alternatives to the client"}]'::jsonb, '["c"]', 'In the educator role, the nurse reinforces the provider''s explanation of the procedure, risks, benefits, and alternatives and clarifies the client''s questions. Refusing to discuss it ignores the educator role, and signing before questions are answered is not appropriate.'),
  ('consent', 4, 'The nurse has reinforced the provider''s explanation of a procedure using a handout. The client still cannot describe what the procedure involves. Which action should the nurse take?', '[{"id": "a", "text": "Notify the provider that the client still does not understand"}, {"id": "b", "text": "Witness the signature because the provider already explained it"}, {"id": "c", "text": "Repeat the explanation until the client agrees to sign the form"}, {"id": "d", "text": "Document that the client understood the teaching that was given"}]'::jsonb, '["a"]', 'The nurse must notify the provider if the client still doesn''t understand. Witnessing the signature anyway would allow consent without understanding.'),
  ('consent', 5, 'The nurse is asked to witness a client''s signature on a consent form. Which finding should cause the nurse to stop the process?', '[{"id": "a", "text": "The client is alert and oriented to person, place, and time"}, {"id": "b", "text": "The client received an opioid for pain 30 minutes ago"}, {"id": "c", "text": "The client signs the form without any hesitation"}, {"id": "d", "text": "The client''s adult daughter is present in the room"}]'::jsonb, '["b"]', 'When witnessing, the nurse verifies the client is not under the influence of sedatives or opioids. Being alert and oriented and signing without hesitation are expected findings for valid consent.'),
  ('consent', 6, 'While preparing a client for a procedure, the nurse discovers the client signed the consent form after receiving sedation. Which action is appropriate?', '[{"id": "a", "text": "Proceed because the provider explained the procedure beforehand"}, {"id": "b", "text": "Have a family member co-sign the existing consent form"}, {"id": "c", "text": "Delay the procedure because the consent is not valid"}, {"id": "d", "text": "Document the sedation and allow the procedure to continue"}]'::jsonb, '["c"]', 'If the client is under sedation, informed consent is invalid and the procedure should be delayed. A prior explanation by the provider does not make a sedated signature valid.'),
  ('consent', 7, 'A client who speaks limited English is about to discuss a procedure with the provider. The client''s adult son, who is fluent in English, offers to translate. Which action should the nurse take?', '[{"id": "a", "text": "Allow the son to translate because he knows the client well"}, {"id": "b", "text": "Ask a bilingual staff member from housekeeping to interpret"}, {"id": "c", "text": "Use gestures and pictures to obtain the client''s signature"}, {"id": "d", "text": "Request a licensed medical interpreter for the discussion"}]'::jsonb, '["d"]', 'A licensed medical interpreter must be used for language barriers, not family. A housekeeping staff member is not a licensed medical interpreter either.'),
  ('consent', 8, 'A nursing student makes the following statements about implied consent. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Consent may be implied when the client is unconscious.\""}, {"id": "b", "text": "\"Implied consent applies when no surrogate is available.\""}, {"id": "c", "text": "\"Consent may be implied in any emergency, even if awake.\""}, {"id": "d", "text": "\"Implied consent is used in emergency situations.\""}]'::jsonb, '["c"]', 'In emergencies, consent may be implied only if the client is unconscious and no surrogate is available. An awake client in an emergency does not meet these conditions.'),
  ('consent', 9, 'A 17-year-old emancipated minor is scheduled for a nonemergency procedure. Who should sign the informed consent?', '[{"id": "a", "text": "The client, because the client is emancipated"}, {"id": "b", "text": "The client''s parents, because the client is under 18"}, {"id": "c", "text": "The nurse caring for the client, as a witness"}, {"id": "d", "text": "The surgeon, on the client''s behalf"}]'::jsonb, '["a"]', 'Minors under 18 require consent from a legal guardian, with exceptions such as emancipated minors. Requiring the parents ignores the emancipation exception.'),
  ('consent', 10, 'A 16-year-old client comes to a clinic seeking reproductive health care. Which understanding should guide the nurse?', '[{"id": "a", "text": "Guardian consent is required for all care of clients under 18"}, {"id": "b", "text": "Reproductive health is an exception to guardian consent rules"}, {"id": "c", "text": "The adolescent must bring an adult to the visit to give consent"}, {"id": "d", "text": "Consent is always implied for clients who are under age 18"}]'::jsonb, '["b"]', 'Minors require consent from a legal guardian, with exceptions that include reproductive health. Stating that all care requires guardian consent ignores this exception.'),
  ('consent', 11, 'An unconscious client arrives in the emergency department after a motor vehicle crash and needs emergency surgery. No family or surrogate can be located. Which statement about consent is accurate?', '[{"id": "a", "text": "Surgery must wait until the client regains consciousness"}, {"id": "b", "text": "The nurse may sign the consent form on the client''s behalf"}, {"id": "c", "text": "Consent may be implied because no surrogate is available"}, {"id": "d", "text": "Any available staff member may act as the surrogate"}]'::jsonb, '["c"]', 'In emergencies, consent may be implied if the client is unconscious and no surrogate is available. Waiting for consciousness would delay emergency care, and the nurse does not sign consent for the client.'),
  ('consent', 12, 'The nurse signs a consent form as the witness for a client''s procedure. What is the nurse verifying with this signature?', '[{"id": "a", "text": "That the client can recite every risk of the procedure"}, {"id": "b", "text": "That the client signed voluntarily and appears competent"}, {"id": "c", "text": "That the provider''s explanation was medically accurate"}, {"id": "d", "text": "That the family agrees with the client''s decision"}]'::jsonb, '["b"]', 'As witness, the nurse verifies the client appears mentally competent, signed voluntarily, is alert and oriented, and is not under the influence of sedatives or opioids. The nurse witnesses the signature, not the explanation.'),
  ('consent', 13, 'A newly hired nurse makes several statements about witnessing informed consent. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I am witnessing the client sign the consent form.\""}, {"id": "b", "text": "\"I verify that the client appears alert and oriented.\""}, {"id": "c", "text": "\"My signature shows I witnessed the explanation.\""}, {"id": "d", "text": "\"I check that the client has not received sedatives.\""}]'::jsonb, '["c"]', 'The nurse witnesses the signature, not the explanation. Verifying alertness and absence of sedatives are correct parts of the witness role.'),
  ('consent', 14, 'As the nurse brings a consent form to the bedside, the client''s spouse says, "Just sign it so we can get this over with." The client looks unsure and quietly says, "I guess so." Which action should the nurse take?', '[{"id": "a", "text": "Witness the signature because the spouse supports the procedure"}, {"id": "b", "text": "Pause the process and alert the provider to the client''s hesitation"}, {"id": "c", "text": "Ask the spouse to sign the consent form instead of the client"}, {"id": "d", "text": "Reassure the client that the procedure is routine and safe"}]'::jsonb, '["b"]', 'As advocate, the nurse confirms the client is not pressured and alerts the provider if the client appears unsure or hesitant. A spouse''s support does not make a pressured decision voluntary.'),
  ('consent', 15, 'After witnessing a client''s signature on a consent form, the nurse documents the event. Which information must the nurse include?', '[{"id": "a", "text": "A statement that the nurse explained the surgical risks"}, {"id": "b", "text": "The date and time that the consent was obtained"}, {"id": "c", "text": "The family''s opinion about the planned procedure"}, {"id": "d", "text": "The nurse''s prediction of the procedure''s outcome"}]'::jsonb, '["b"]', 'Consent documentation includes the date and time of consent, a summary of education given, questions asked and responses provided, and verification that the client appeared competent. The nurse does not explain risks in place of the provider.'),
  ('consent', 16, 'During consent teaching, a client asked the nurse several questions about recovery, and the nurse reinforced the provider''s answers. What should the nurse document about this discussion?', '[{"id": "a", "text": "Only that the consent teaching was completed"}, {"id": "b", "text": "Nothing, because the provider documents teaching"}, {"id": "c", "text": "Only the questions that the provider answered"}, {"id": "d", "text": "The questions asked and the responses provided"}]'::jsonb, '["d"]', 'Consent documentation includes questions asked and responses provided. Documenting only that teaching was completed leaves out required information.'),
  ('consent', 17, 'Which nursing documentation entry about informed consent is most complete?', '[{"id": "a", "text": "\"0900 consent signed. Education reviewed, questions answered, client appeared competent.\""}, {"id": "b", "text": "\"Client consented after the nurse explained the risks and benefits of surgery.\""}, {"id": "c", "text": "\"Consent signed. Family members agreed with the client''s decision to proceed.\""}, {"id": "d", "text": "\"Client seemed nervous about the surgery but signed the consent form anyway.\""}]'::jsonb, '["a"]', 'Documentation should include the time of consent, a summary of education, questions and responses, and verification that the client appeared competent. The other entries omit these elements or describe the nurse explaining risks, which is the provider''s role.'),
  ('consent', 18, 'A client signed consent for surgery yesterday. This morning the client tells the nurse, "I''ve changed my mind. I don''t want the surgery." Which action should the nurse take?', '[{"id": "a", "text": "Remind the client that the consent form is already signed"}, {"id": "b", "text": "Give a prescribed sedative to reduce anxiety and proceed"}, {"id": "c", "text": "Support the client''s right to refuse and notify the provider"}, {"id": "d", "text": "Ask the client''s family to persuade the client to continue"}]'::jsonb, '["c"]', 'The nurse advocates for the client''s right to refuse and notifies the provider when consent is unclear. A signed form does not override the client''s later refusal.'),
  ('consent', 19, 'Just before signing a consent form, a client says, "I''m not sure I really understand what they''re going to do to me." Which action should the nurse take first?', '[{"id": "a", "text": "Stop the process and notify the provider"}, {"id": "b", "text": "Have the client sign and explain things later"}, {"id": "c", "text": "Tell the client that most people feel that way"}, {"id": "d", "text": "Ask the client to sign while the nurse explains"}]'::jsonb, '["a"]', 'The nurse must stop the process if the client expresses doubt or misunderstanding and notify the provider. Reassuring or proceeding would allow consent without understanding.'),
  ('consent', 20, 'When the nurse brings a consent form to an older client, the client is disoriented to time and place. The provider asks the nurse to witness the signature. Which action is appropriate?', '[{"id": "a", "text": "Witness the signature after reorienting the client once"}, {"id": "b", "text": "Withhold witnessing and alert the provider to the confusion"}, {"id": "c", "text": "Have the client mark an X on the form in place of a signature"}, {"id": "d", "text": "Ask the client''s roommate to serve as the witness instead"}]'::jsonb, '["b"]', 'The nurse must never allow a confused client to sign and should alert the provider if the client appears confused. Changing the way the client signs or who witnesses does not fix the client''s lack of orientation.'),
  ('consent', 21, 'After the provider explains a procedure, a client tells the nurse, "I understand things better when I can see pictures." Which action by the nurse is best?', '[{"id": "a", "text": "Provide visual aids that reinforce the provider''s explanation"}, {"id": "b", "text": "Ask the provider to obtain consent from a family member"}, {"id": "c", "text": "Explain new treatment options the provider did not mention"}, {"id": "d", "text": "Postpone all teaching until after the procedure is done"}]'::jsonb, '["a"]', 'In the educator role, the nurse provides education materials or visual aids if needed. The nurse does not introduce new options in place of the provider''s explanation.'),
  ('consent', 22, 'The nurse is reinforcing the provider''s explanation of a procedure with a client. Which statement by the nurse best supports the client''s understanding?', '[{"id": "a", "text": "\"What questions do you have about what the surgeon explained?\""}, {"id": "b", "text": "\"You don''t have any questions about this, do you?\""}, {"id": "c", "text": "\"The surgeon is busy, so let''s sign this form quickly.\""}, {"id": "d", "text": "\"I will answer your questions after you sign the form.\""}]'::jsonb, '["a"]', 'The nurse encourages the client to ask questions as part of the educator role. A closed question or rushing the client discourages questions.'),
  ('consent', 23, 'A nurse is acting as a client advocate during the informed consent process. What is the nurse''s primary goal in this role?', '[{"id": "a", "text": "Ensuring that the client''s decision is voluntary"}, {"id": "b", "text": "Explaining the risks of the planned procedure"}, {"id": "c", "text": "Obtaining the client''s signature on the form"}, {"id": "d", "text": "Choosing the best treatment option for the client"}]'::jsonb, '["a"]', 'As advocate, the nurse protects the client''s autonomy and ensures the decision is voluntary. Explaining risks and obtaining consent are the provider''s responsibilities.'),
  ('consent', 24, 'The charge nurse observes staff members during several informed consent discussions. Which action requires correction?', '[{"id": "a", "text": "A nurse asks a client''s daughter to interpret the risks for the client"}, {"id": "b", "text": "A nurse confirms the client is alert and oriented before witnessing"}, {"id": "c", "text": "A nurse documents the date and time that consent was signed"}, {"id": "d", "text": "A nurse notifies the provider that a client appears confused"}]'::jsonb, '["a"]', 'Family members must never translate medical information; a licensed medical interpreter is required. The other actions are correct parts of the nurse''s role.'),
  ('consent', 25, 'While reinforcing teaching, the nurse realizes the provider never discussed alternatives to the procedure with the client. Which action should the nurse take?', '[{"id": "a", "text": "Explain the alternatives and then witness the signature"}, {"id": "b", "text": "Notify the provider that the explanation is incomplete"}, {"id": "c", "text": "Proceed, because alternatives are optional information"}, {"id": "d", "text": "Have the client sign and document the missing information"}]'::jsonb, '["b"]', 'The nurse notifies the provider if consent is incomplete or unclear; the provider must explain the procedure, risks, benefits, and alternatives directly. The nurse explaining the alternatives would replace the provider''s explanation.'),
  ('consent', 26, 'A client in the preoperative holding area signed a consent form earlier but is now tearful and says, "I don''t know if I should go through with this." Which action should the nurse take?', '[{"id": "a", "text": "Allow the procedure to continue because the form is signed"}, {"id": "b", "text": "Stop the process and notify the provider of the hesitation"}, {"id": "c", "text": "Give a prescribed sedative so the client can relax and proceed"}, {"id": "d", "text": "Ask the operating room team to begin before the client changes"}]'::jsonb, '["b"]', 'The nurse must never allow a procedure to continue if the client shows hesitation. A signed form does not override the client''s current doubt.'),
  ('consent', 27, 'Before witnessing a client''s signature on a consent form, the nurse assesses the client. Which finding indicates the client may sign?', '[{"id": "a", "text": "The client is drowsy after a sedative given an hour ago"}, {"id": "b", "text": "The client asks the nurse to make the decision for them"}, {"id": "c", "text": "The client is alert and oriented and signs voluntarily"}, {"id": "d", "text": "The client says the spouse wants the surgery done now"}]'::jsonb, '["c"]', 'The witness verifies the client is alert and oriented, appears competent, and signed voluntarily. A sedated client cannot give valid consent.'),
  ('consent', 28, 'A nurse orienting to a surgical unit makes several statements about informed consent. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"The provider explains the procedure before consent is signed.\""}, {"id": "b", "text": "\"I can obtain the client''s consent if the provider is busy.\""}, {"id": "c", "text": "\"I can witness the client''s signature on the consent form.\""}, {"id": "d", "text": "\"I should notify the provider if the client seems unsure.\""}]'::jsonb, '["b"]', 'Only the provider may obtain informed consent; nurses do not obtain consent. Witnessing the signature and notifying the provider of uncertainty are appropriate nursing actions.'),
  ('consent', 29, 'The nurse is reviewing consent policies with a newly hired nurse. Which statement by the newly hired nurse indicates understanding of language barriers?', '[{"id": "a", "text": "\"A family member who speaks both languages may translate.\""}, {"id": "b", "text": "\"I will use a licensed medical interpreter for the discussion.\""}, {"id": "c", "text": "\"The client''s child can interpret if no one else is available.\""}, {"id": "d", "text": "\"Speaking slowly in English is enough for informed consent.\""}]'::jsonb, '["b"]', 'A licensed medical interpreter must be used for language barriers, not family. Using a family member or child to translate medical information is never allowed.'),
  ('consent', 30, 'A client received a prescribed sedative as a preprocedure medication. The provider then arrives with the consent form and asks the nurse to witness the client''s signature. How should the nurse respond?', '[{"id": "a", "text": "Witness the signature because the provider explained the procedure"}, {"id": "b", "text": "Tell the provider the consent would be invalid and the procedure delayed"}, {"id": "c", "text": "Have the client initial the form instead of signing the full name"}, {"id": "d", "text": "Ask a family member to sign the form along with the client"}]'::jsonb, '["b"]', 'If the client is under sedation, informed consent is invalid and the procedure should be delayed. Changing how the form is signed does not make consent from a sedated client valid.'),
  ('consent', 31, 'A 15-year-old client is brought to the hospital by a grandparent for a scheduled, nonemergency procedure. The client''s parent is the legal guardian. From whom should consent be obtained?', '[{"id": "a", "text": "The grandparent who brought the client to the hospital"}, {"id": "b", "text": "The client, because the client is old enough to understand"}, {"id": "c", "text": "The client''s parent, who is the client''s legal guardian"}, {"id": "d", "text": "No one, because the client is a minor in the hospital"}]'::jsonb, '["c"]', 'Minors under 18 require consent from a legal guardian unless an exception applies. A grandparent who is not the legal guardian cannot provide consent.'),
  ('consent', 32, 'In which situation may consent for treatment be implied?', '[{"id": "a", "text": "An alert client who refuses to sign the consent form"}, {"id": "b", "text": "A sedated client whose spouse is in the waiting room"}, {"id": "c", "text": "A confused client scheduled for an elective procedure"}, {"id": "d", "text": "An unconscious client in an emergency with no surrogate"}]'::jsonb, '["d"]', 'Consent may be implied in emergencies when the client is unconscious and no surrogate is available. A client whose spouse is available, or one having an elective procedure, does not meet these conditions.'),
  ('consent', 33, 'Which sequence correctly describes the informed consent process for a planned procedure?', '[{"id": "a", "text": "Nurse explains risks, client signs, provider reviews, nurse documents"}, {"id": "b", "text": "Client signs, provider explains risks, nurse documents, nurse reinforces"}, {"id": "c", "text": "Nurse documents, client signs, provider explains risks, nurse reinforces"}, {"id": "d", "text": "Provider explains risks, nurse reinforces, client signs, nurse documents"}]'::jsonb, '["d"]', 'The provider must explain the procedure, risks, benefits, and alternatives first; the nurse then reinforces understanding, witnesses the signature, and documents. The nurse never explains in place of the provider, and consent is never signed before the explanation.'),
  ('consent', 34, 'A nurse''s consent note reads: "10/12, 1400: Consent signed. Reinforced provider''s explanation of risks, benefits, and alternatives. Client asked about recovery time; answered per provider''s explanation." Which required element is missing?', '[{"id": "a", "text": "The date and time the consent was signed"}, {"id": "b", "text": "A summary of the education that was given"}, {"id": "c", "text": "The questions the client asked during teaching"}, {"id": "d", "text": "Verification that the client appeared competent"}]'::jsonb, '["d"]', 'Consent documentation includes date and time, a summary of education, questions and responses, and verification that the client appeared competent. The note contains all elements except the competency verification.'),
  ('consent', 35, 'Which statement best summarizes the nurse''s role in informed consent?', '[{"id": "a", "text": "To obtain, explain, and document the client''s consent"}, {"id": "b", "text": "To decide, explain, sign, and file the consent form"}, {"id": "c", "text": "To interpret, approve, sign, and store the consent"}, {"id": "d", "text": "To support, educate, advocate, and witness for the client"}]'::jsonb, '["d"]', 'The nurse''s primary role is to support, educate, advocate, and witness, not to obtain consent. Obtaining and explaining are the provider''s responsibilities.'),
  ('consent', 36, 'While the nurse prepares to witness a consent form, the client says, "My family will be really upset with me if I don''t sign this." Which action should the nurse take?', '[{"id": "a", "text": "Witness the signature because the family supports the procedure"}, {"id": "b", "text": "Tell the client that the family usually knows what is best"}, {"id": "c", "text": "Confirm the client is not being pressured and alert the provider"}, {"id": "d", "text": "Ask the family to leave so the client can sign more quickly"}]'::jsonb, '["c"]', 'As advocate, the nurse confirms the client is not pressured or coerced and alerts the provider if the client is unsure. Proceeding with family pressure would not ensure a voluntary decision.'),
  ('consent', 37, 'Several visitors are in the room while a client reviews a consent form. Which nursing action best ensures the client feels safe to ask questions?', '[{"id": "a", "text": "Asking the client privately whether there are any concerns"}, {"id": "b", "text": "Reading the form aloud quickly in front of all the visitors"}, {"id": "c", "text": "Telling the client that questions will delay the schedule"}, {"id": "d", "text": "Answering for the client when the provider asks questions"}]'::jsonb, '["a"]', 'As advocate, the nurse ensures the client feels safe to ask questions. Rushing the client or speaking for the client discourages questions and threatens a voluntary decision.'),
  ('consent', 38, 'After the provider explains a procedure and leaves the room, the client asks the nurse a question about what was said. Which action is appropriate for the nurse?', '[{"id": "a", "text": "Clarify the client''s question about the explanation"}, {"id": "b", "text": "Change the procedure to one the client prefers"}, {"id": "c", "text": "Obtain the client''s signature before answering"}, {"id": "d", "text": "Tell the client to ask the surgeon in the OR"}]'::jsonb, '["a"]', 'The nurse''s educator role includes clarifying any questions the client may have. Obtaining a signature before answering questions would not support understanding.'),
  ('consent', 39, 'The nurse is assigned to witness consent for four clients. Which client is able to sign the consent form?', '[{"id": "a", "text": "A client who received a sedative one hour ago"}, {"id": "b", "text": "A client who is alert, oriented, and has had no sedatives"}, {"id": "c", "text": "A client who is disoriented to place and time"}, {"id": "d", "text": "A client who says the spouse is forcing the decision"}]'::jsonb, '["b"]', 'The witness verifies the client is alert and oriented, appears competent, signed voluntarily, and is not under the influence of sedatives or opioids. The other clients are sedated, confused, or pressured.'),
  ('consent', 40, 'The nurse is reinforcing teaching before a client signs consent for an appendectomy. Which client statement should the nurse report to the provider?', '[{"id": "a", "text": "\"I thought the surgeon was removing my gallbladder.\""}, {"id": "b", "text": "\"I understand the risks that the surgeon explained.\""}, {"id": "c", "text": "\"Can I keep a copy of the education sheet you gave me?\""}, {"id": "d", "text": "\"My sister will be driving me home after the surgery.\""}]'::jsonb, '["a"]', 'The nurse must stop the process if the client expresses misunderstanding and notify the provider. The client''s belief that a different organ is being removed shows misunderstanding of the procedure.'),
  ('consent', 41, 'Which entry is appropriate for the nurse to include in documentation of the informed consent process?', '[{"id": "a", "text": "\"Reinforced provider''s explanation of risks using a handout.\""}, {"id": "b", "text": "\"Explained procedure to client and obtained client''s consent.\""}, {"id": "c", "text": "\"Client probably understood the provider''s explanation.\""}, {"id": "d", "text": "\"Client''s daughter translated the risks for the client.\""}]'::jsonb, '["a"]', 'Documentation includes a summary of the education given. The nurse does not explain the procedure and obtain consent, and family members must not translate medical information.'),
  ('consent', 42, 'A provider calls the unit and asks the nurse to "get the consent signed" so that the provider can talk with the client about the procedure later. Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"I will have the client sign now and tell them you will come later.\""}, {"id": "b", "text": "\"I will explain the risks to the client and then witness the signing.\""}, {"id": "c", "text": "\"The client needs your explanation before signing the consent form.\""}, {"id": "d", "text": "\"I will ask the family to sign the form until you are available.\""}]'::jsonb, '["c"]', 'Consent must never be signed without the provider''s direct explanation first. The nurse does not explain risks in place of the provider or obtain consent.'),
  ('consent', 43, 'Before witnessing a postoperative client''s signature on a consent form for a second procedure, which question is most important for the nurse to ask?', '[{"id": "a", "text": "\"Who will be driving you home after discharge?\""}, {"id": "b", "text": "\"Have you received any sedating or opioid medication?\""}, {"id": "c", "text": "\"Do you have a copy of your insurance information?\""}, {"id": "d", "text": "\"Which family members will visit you this evening?\""}]'::jsonb, '["b"]', 'The witness verifies the client is not under the influence of sedatives or opioids, because sedation makes consent invalid. The other questions do not affect the validity of consent.'),
  ('consent', 44, 'A charge nurse is reviewing the informed consent process with a newly hired nurse. Which statement by the newly hired nurse indicates a need for further teaching?', '[{"id": "a", "text": "\"I will notify the provider if the client still doesn''t understand.\""}, {"id": "b", "text": "\"I will reinforce the provider''s explanation if the client asks.\""}, {"id": "c", "text": "\"I will encourage the client to ask any questions about the plan.\""}, {"id": "d", "text": "\"If the client still doesn''t understand, I''ll have them sign anyway.\""}]'::jsonb, '["d"]', 'The nurse must notify the provider if the client still doesn''t understand rather than proceed with signing. Reinforcing and encouraging questions are correct educator actions.'),
  ('consent', 45, 'A client who is about to sign a consent form looks uncertain and keeps rereading the risks section. Which statement by the nurse is most appropriate?', '[{"id": "a", "text": "\"Everyone feels nervous; you should just go ahead and sign.\""}, {"id": "b", "text": "\"The surgeon is waiting, so we need to finish this quickly.\""}, {"id": "c", "text": "\"Your family already agreed to the surgery, so it is fine.\""}, {"id": "d", "text": "\"You seem unsure. I''ll let the provider know you have questions.\""}]'::jsonb, '["d"]', 'As advocate, the nurse alerts the provider if the client appears unsure or hesitant. Encouraging the client to sign despite uncertainty does not protect a voluntary, informed decision.'),
  ('consent', 46, 'The nurse is preparing consent forms for four clients scheduled for procedures. Which client requires consent from a legal guardian?', '[{"id": "a", "text": "A 17-year-old who is an emancipated minor"}, {"id": "b", "text": "A 19-year-old college student living at home"}, {"id": "c", "text": "A 16-year-old seeking reproductive health care"}, {"id": "d", "text": "A 16-year-old scheduled for an elective surgery"}]'::jsonb, '["d"]', 'Minors under 18 require consent from a legal guardian, with exceptions such as emancipated minors and reproductive health care. A 19-year-old is not a minor.'),
  ('consent', 47, 'After the provider explains a recommended procedure, an alert and oriented client declines to sign the consent form. Which action should the nurse take?', '[{"id": "a", "text": "Ask the client''s family member to sign the consent instead"}, {"id": "b", "text": "Explain to the client that the form must be signed today"}, {"id": "c", "text": "Wait until the client is sedated and then ask again"}, {"id": "d", "text": "Respect the refusal and notify the provider of the decision"}]'::jsonb, '["d"]', 'The nurse advocates for the client''s right to refuse and notifies the provider when consent is incomplete. Waiting for sedation would make any consent invalid.'),
  ('consent', 48, 'An alert, oriented client in the emergency department needs an urgent procedure. A new nurse suggests that consent can be implied because it is an emergency. Which response by the charge nurse is correct?', '[{"id": "a", "text": "\"The provider should explain the procedure and obtain consent.\""}, {"id": "b", "text": "\"Consent is implied for every client in the emergency department.\""}, {"id": "c", "text": "\"You may obtain consent yourself to save time in an emergency.\""}, {"id": "d", "text": "\"A family member should sign because this is an emergency.\""}]'::jsonb, '["a"]', 'Consent is implied in emergencies only when the client is unconscious and no surrogate is available; an alert client gives consent after the provider''s explanation. Only the provider may obtain consent.'),
  ('consent', 49, 'Which task related to informed consent may the nurse perform?', '[{"id": "a", "text": "Witness the client''s signature on the consent form"}, {"id": "b", "text": "Explain the risks and benefits of the procedure first"}, {"id": "c", "text": "Obtain the client''s informed consent for the surgery"}, {"id": "d", "text": "Choose the procedure alternatives for the client"}]'::jsonb, '["a"]', 'Nurses may witness the signature and verify the client''s competence and voluntariness. Explaining the procedure and obtaining consent are the provider''s responsibilities.'),
  ('consent', 50, 'Which action best reflects the nurse''s educator role in the informed consent process?', '[{"id": "a", "text": "Obtaining the client''s signature on the form"}, {"id": "b", "text": "Choosing which alternatives the client hears"}, {"id": "c", "text": "Translating the explanation for the client"}, {"id": "d", "text": "Reinforcing the provider''s explanation of risks"}]'::jsonb, '["d"]', 'In the educator role, the nurse reinforces the provider''s explanation of procedure, risks, benefits, and alternatives. Obtaining consent belongs to the provider, and translation requires a licensed medical interpreter.'),
  ('fundamentals', 1, 'A nurse is supervising an unlicensed assistive personnel (UAP) caring for a client at high risk for falls. Which action by the UAP requires correction?', '[{"id": "a", "text": "Raises all four side rails while the client rests"}, {"id": "b", "text": "Places the call light within the client''s reach"}, {"id": "c", "text": "Lowers the bed and locks the wheels after care"}, {"id": "d", "text": "Puts non-slip footwear on the client before walking"}]'::jsonb, '["a"]', 'Only 2 side rails should be raised; raising all 4 constitutes a restraint and requires a physician order. Keeping the call light in reach, the bed low and locked, and non-slip footwear are all fall precautions.'),
  ('fundamentals', 2, 'A client reports lightheadedness when getting out of bed. Blood pressure is 132/78 mmHg lying and 108/74 mmHg standing. How should the nurse interpret these findings?', '[{"id": "a", "text": "An expected postural change needing no follow-up"}, {"id": "b", "text": "Orthostatic hypotension based on the systolic drop"}, {"id": "c", "text": "Hypertension that must be reported immediately"}, {"id": "d", "text": "A normal response because the diastolic is stable"}]'::jsonb, '["b"]', 'The systolic pressure fell 24 mmHg on standing, which meets the threshold of a drop of 20 mmHg or more for orthostatic hypotension. The stable diastolic value does not make the systolic drop normal.'),
  ('fundamentals', 3, 'A nurse is preparing to insert a peripheral IV catheter in a client who has no known infection. Which action reflects standard precautions?', '[{"id": "a", "text": "Omitting gloves because no infection is known"}, {"id": "b", "text": "Wearing an N95 respirator for the procedure"}, {"id": "c", "text": "Donning gloves because blood contact is anticipated"}, {"id": "d", "text": "Wearing gloves only for clients in isolation"}]'::jsonb, '["c"]', 'Standard precautions apply to all patients, and gloves are worn whenever contact with blood or body fluids is anticipated, as it is during IV insertion. An N95 respirator is airborne-precaution PPE, not a standard precaution.'),
  ('fundamentals', 4, 'A nurse has just given a client a subcutaneous injection. What should the nurse do with the used needle?', '[{"id": "a", "text": "Leave it on the bedside tray until charting is done"}, {"id": "b", "text": "Carry it to the medication room to discard later"}, {"id": "c", "text": "Place it in the client''s regular trash container"}, {"id": "d", "text": "Discard it in an approved sharps container right away"}]'::jsonb, '["d"]', 'Under standard precautions, sharps are disposed of in an approved sharps container immediately after use. Delaying disposal or using regular trash does not meet this standard.'),
  ('fundamentals', 5, 'A nurse is about to change the dressing of a client who has a wound infected with MRSA. Which personal protective equipment should the nurse wear?', '[{"id": "a", "text": "Gloves and a gown"}, {"id": "b", "text": "A surgical mask only"}, {"id": "c", "text": "An N95 respirator only"}, {"id": "d", "text": "Gloves without a gown"}]'::jsonb, '["a"]', 'MRSA and wound infections require contact precautions, which call for gloves plus a gown. Masks and respirators are used for droplet and airborne precautions.'),
  ('fundamentals', 6, 'A client is admitted with pertussis. Which precaution should the nurse implement when providing care close to the client?', '[{"id": "a", "text": "A negative-pressure airborne infection isolation room"}, {"id": "b", "text": "A surgical mask as part of droplet precautions"}, {"id": "c", "text": "Gloves and gown as part of contact precautions"}, {"id": "d", "text": "Hand hygiene alone with no additional precautions"}]'::jsonb, '["b"]', 'Pertussis is listed with the droplet precaution diseases, which require a surgical mask. A negative-pressure room is required for airborne diseases such as TB.'),
  ('fundamentals', 7, 'A client with suspected tuberculosis (TB) is being admitted to the medical unit. Which arrangement should the nurse ensure?', '[{"id": "a", "text": "A semi-private room, with staff wearing surgical masks"}, {"id": "b", "text": "A private room with the door open, with staff in gowns"}, {"id": "c", "text": "A negative-pressure AIIR room, with staff wearing N95s"}, {"id": "d", "text": "Any available room, with staff wearing gloves only"}]'::jsonb, '["c"]', 'TB requires airborne precautions: an N95 respirator and a negative-pressure airborne infection isolation room (AIIR). A surgical mask is used for droplet precautions, not airborne.'),
  ('fundamentals', 8, 'A charge nurse is making room assignments for newly admitted clients. Which client requires contact precautions?', '[{"id": "a", "text": "A client with mumps"}, {"id": "b", "text": "A client with measles"}, {"id": "c", "text": "A client with influenza"}, {"id": "d", "text": "A client with VRE"}]'::jsonb, '["d"]', 'VRE is listed with MRSA, C. diff, and wound infections under contact precautions. Mumps and influenza require droplet precautions, and measles requires airborne precautions.'),
  ('fundamentals', 9, 'A nurse observes an unlicensed assistive personnel (UAP) leaving the room of a client who has C. diff. Which action by the UAP requires correction?', '[{"id": "a", "text": "Using alcohol-based hand rub as the only hand hygiene"}, {"id": "b", "text": "Removing the gown and gloves before leaving the room"}, {"id": "c", "text": "Washing hands with soap and water after removing gloves"}, {"id": "d", "text": "Performing hand hygiene before the next client contact"}]'::jsonb, '["a"]', 'Soap and water must be used after caring for a client with C. diff because alcohol does not destroy C. diff spores. Alcohol-based hand rub is used for other clinical situations.'),
  ('fundamentals', 10, 'A nurse educator is teaching newly hired nurses about preventing health care-associated infections (HAIs). Which measure should the educator identify as the most important?', '[{"id": "a", "text": "Wearing gloves for every client contact"}, {"id": "b", "text": "Performing hand hygiene between client contacts"}, {"id": "c", "text": "Placing every client in a private room"}, {"id": "d", "text": "Wearing a gown during all bedside care"}]'::jsonb, '["b"]', 'Hand hygiene is the number one measure to prevent HAIs and is performed between every patient contact. Gloves are worn when blood or body fluid contact is anticipated but do not replace hand hygiene.'),
  ('fundamentals', 11, 'A client who is 1 day postoperative has an oral temperature of 100.8 °F (38.2 °C). Which action should the nurse take?', '[{"id": "a", "text": "Recheck the temperature at the next routine check"}, {"id": "b", "text": "Document the value as within the normal adult range"}, {"id": "c", "text": "Report the temperature to the provider immediately"}, {"id": "d", "text": "Record it as an expected finding after surgery"}]'::jsonb, '["c"]', 'A temperature above 100.4 °F in a post-operative patient is reported to the provider immediately because it may indicate infection or sepsis. Normal adult temperature is 97.8–99.1 °F, so this value is not normal.'),
  ('fundamentals', 12, 'A client''s oxygen saturation on room air is 88%. Which action should the nurse take first?', '[{"id": "a", "text": "Document the reading and recheck it in 1 hour"}, {"id": "b", "text": "Have the client walk in the hall to improve breathing"}, {"id": "c", "text": "Call the provider before starting any intervention"}, {"id": "d", "text": "Initiate supplemental oxygen per protocol"}]'::jsonb, '["d"]', 'An SpO2 below 90% indicates hypoxemia, and oxygen is administered immediately per protocol, followed by notifying the provider. Calling the provider is necessary but should not delay oxygen.'),
  ('fundamentals', 13, 'A nurse reviews the vital signs of an adult client. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Heart rate of 112 bpm"}, {"id": "b", "text": "Temperature of 98.6 °F (37 °C)"}, {"id": "c", "text": "Blood pressure of 116/74 mmHg"}, {"id": "d", "text": "Respiratory rate of 18 breaths/min"}]'::jsonb, '["a"]', 'Normal adult heart rate is 60–100 bpm, and a rate above 100 bpm should be reported. The temperature, blood pressure, and respiratory rate are all within normal adult ranges.'),
  ('fundamentals', 14, 'A client''s blood pressure is 84/52 mmHg. Which action should the nurse take?', '[{"id": "a", "text": "Raise the head of the bed to 90 degrees"}, {"id": "b", "text": "Assess the client for signs of shock"}, {"id": "c", "text": "Document the value as within normal limits"}, {"id": "d", "text": "Recheck the blood pressure at the next shift"}]'::jsonb, '["b"]', 'A systolic BP below 90 mmHg is a report-immediately finding that requires assessment for shock. The normal adult range is 90/60–120/80 mmHg, so this value is not normal.'),
  ('fundamentals', 15, 'A nurse gives a prescribed analgesic to a client who rates pain as 7 on a 0–10 scale. When should the nurse reassess the client''s pain?', '[{"id": "a", "text": "Only if the client asks for more medication"}, {"id": "b", "text": "At the next routine vital sign check in 4 hours"}, {"id": "c", "text": "Within 30 to 60 minutes after the medication"}, {"id": "d", "text": "At the end of the shift during handoff report"}]'::jsonb, '["c"]', 'Pain should always be assessed and reassessed 30–60 minutes after any intervention. Waiting for the client to ask or for a routine check delays evaluation of the intervention.'),
  ('fundamentals', 16, 'A nurse is about to perform an abdominal assessment. In which order should the nurse perform the techniques?', '[{"id": "a", "text": "Inspect, palpate, percuss, auscultate"}, {"id": "b", "text": "Auscultate, inspect, palpate, percuss"}, {"id": "c", "text": "Palpate, percuss, auscultate, inspect"}, {"id": "d", "text": "Inspect, auscultate, percuss, palpate"}]'::jsonb, '["d"]', 'The abdomen is the exception to the standard order: inspect, auscultate, percuss, then palpate. Inspect-palpate-percuss-auscultate is the standard order used for other systems.'),
  ('fundamentals', 17, 'A nursing student is preparing to assess a client''s abdomen. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"I will palpate first so the bowel sounds are easier to hear.\""}, {"id": "b", "text": "\"I will look at the abdomen before I touch it.\""}, {"id": "c", "text": "\"I will listen to bowel sounds before I percuss.\""}, {"id": "d", "text": "\"I will palpate the abdomen as my final step.\""}]'::jsonb, '["a"]', 'Palpating before auscultation stimulates bowel motility and produces artifactual, unreliable bowel sounds. The other statements follow the correct abdominal order of inspect, auscultate, percuss, palpate.'),
  ('fundamentals', 18, 'A nurse is assessing a client''s thorax and lungs. In which order should the nurse perform the techniques?', '[{"id": "a", "text": "Inspect, auscultate, percuss, palpate"}, {"id": "b", "text": "Inspect, palpate, percuss, auscultate"}, {"id": "c", "text": "Auscultate, inspect, palpate, percuss"}, {"id": "d", "text": "Palpate, inspect, auscultate, percuss"}]'::jsonb, '["b"]', 'The standard assessment order for all systems other than the abdomen is inspect, palpate, percuss, auscultate. Inspect-auscultate-percuss-palpate is reserved for the abdominal exception.'),
  ('fundamentals', 19, 'A nurse is documenting the appearance of a client''s surgical wound. Which entry best meets documentation standards?', '[{"id": "a", "text": "\"Wound looks a little worse than it did yesterday.\""}, {"id": "b", "text": "\"Wound appears to be healing nicely this morning.\""}, {"id": "c", "text": "\"Wound 2 × 1 cm, erythematous margins, serous drainage.\""}, {"id": "d", "text": "\"Wound is fairly large and red with some drainage.\""}]'::jsonb, '["c"]', 'Documentation should record objective, measurable findings such as exact dimensions, margin appearance, and drainage type. The other entries are vague or subjective judgments.'),
  ('fundamentals', 20, 'A charge nurse reviews entries written by a newly hired nurse. Which entry requires correction?', '[{"id": "a", "text": "\"Client states, ''I feel dizzy when I stand.''\""}, {"id": "b", "text": "\"Turned to left side at 1000; sacral skin intact.\""}, {"id": "c", "text": "\"Ate 2 crackers and drank 120 mL of juice at lunch.\""}, {"id": "d", "text": "\"Client was uncooperative during morning care.\""}]'::jsonb, '["d"]', 'Labeling a client as uncooperative is a subjective opinion; observable behaviors should be documented instead. Quoting the client verbatim and recording measurable facts are best practices.'),
  ('fundamentals', 21, 'A nurse discovers an error in a handwritten entry in a client''s record. Which action by the nurse violates documentation standards?', '[{"id": "a", "text": "Covering the error with white-out"}, {"id": "b", "text": "Using black ink for the entry"}, {"id": "c", "text": "Signing with full name and title"}, {"id": "d", "text": "Recording only factual findings"}]'::jsonb, '["a"]', 'Nurses must never erase, apply white-out, or overwrite any entry. Black ink, signing with full name and title, and factual content are documentation best practices.'),
  ('fundamentals', 22, 'A nurse realizes that a dressing change performed 3 hours ago was never documented. How should the nurse document this care?', '[{"id": "a", "text": "Enter it at the time of care without any label"}, {"id": "b", "text": "Label it \"Late Entry\" with current date, time, and reason"}, {"id": "c", "text": "Backdate the entry so it fits the original timeline"}, {"id": "d", "text": "Leave it undocumented because the time has passed"}]'::jsonb, '["b"]', 'A late entry is clearly labeled "Late Entry" with the current date, time of entry, and a brief reason for the delay. Backdating or altering an entry without proper labeling is prohibited.'),
  ('fundamentals', 23, 'A competent client who has been informed of the risks and benefits declines a recommended surgery. The nurse supports the client''s decision. Which ethical principle is the nurse upholding?', '[{"id": "a", "text": "Beneficence"}, {"id": "b", "text": "Fidelity"}, {"id": "c", "text": "Autonomy"}, {"id": "d", "text": "Justice"}]'::jsonb, '["c"]', 'Autonomy is the right of a competent patient to make self-determined decisions, such as an informed refusal of treatment. Beneficence involves actively promoting the patient''s best interest.'),
  ('fundamentals', 24, 'A nurse tells a client, "I will be back in 10 minutes with your pain medication," and returns with the medication as promised. Which ethical principle does this demonstrate?', '[{"id": "a", "text": "Veracity"}, {"id": "b", "text": "Justice"}, {"id": "c", "text": "Autonomy"}, {"id": "d", "text": "Fidelity"}]'::jsonb, '["d"]', 'Fidelity is faithfulness to commitments, such as following through on a promise to return with pain medication. Veracity refers to truthfulness in communication.'),
  ('fundamentals', 25, 'A nurse realizes that a client received an incorrect dose of a medication. Which action best reflects the principle of veracity?', '[{"id": "a", "text": "Disclosing the error to the client honestly and promptly"}, {"id": "b", "text": "Waiting to see whether the client develops symptoms"}, {"id": "c", "text": "Telling the client only if the client asks directly"}, {"id": "d", "text": "Asking the oncoming nurse to explain it next shift"}]'::jsonb, '["a"]', 'Veracity is truthfulness and transparency with patients, illustrated by disclosing a medication error honestly and promptly. Delaying or withholding disclosure is not truthful or transparent.'),
  ('fundamentals', 26, 'A nurse provides the same quality of care to a client without health insurance as to a client with full coverage. Which ethical principle is the nurse demonstrating?', '[{"id": "a", "text": "Fidelity"}, {"id": "b", "text": "Justice"}, {"id": "c", "text": "Veracity"}, {"id": "d", "text": "Autonomy"}]'::jsonb, '["b"]', 'Justice is the fair, equitable distribution of care, including equal, unbiased care regardless of socioeconomic status. Fidelity refers to keeping commitments and promises.'),
  ('fundamentals', 27, 'A nurse is about to witness a client''s signature on a surgical consent form. The client asks the nurse about the risks of the procedure. Which action should the nurse take?', '[{"id": "a", "text": "Explain the risks so the client can sign now"}, {"id": "b", "text": "Have the client sign and discuss risks later"}, {"id": "c", "text": "Notify the provider to answer the questions"}, {"id": "d", "text": "Ask a family member to explain the risks"}]'::jsonb, '["c"]', 'The provider is solely responsible for explaining the procedure, risks, benefits, and alternatives; the RN only witnesses the signature. The client must be adequately informed at the time of signing.'),
  ('fundamentals', 28, 'A client received IV sedation 20 minutes ago in preparation for a procedure. The nurse finds that the consent form has not been signed. Which action should the nurse take?', '[{"id": "a", "text": "Obtain the client''s signature before transfer"}, {"id": "b", "text": "Explain the procedure while the client signs"}, {"id": "c", "text": "Have the client initial the form instead"}, {"id": "d", "text": "Withhold the form and notify the provider"}]'::jsonb, '["d"]', 'Consent is invalid if the patient is sedated, so the client cannot sign now, and the provider is responsible for consent. Explaining the procedure is the provider''s role, not the nurse''s.'),
  ('fundamentals', 29, 'A nurse educator is reviewing informed consent with new nurses. Which statement by a new nurse indicates a need for further teaching?', '[{"id": "a", "text": "\"I will explain the procedure and obtain consent.\""}, {"id": "b", "text": "\"My role is to witness the client''s signature.\""}, {"id": "c", "text": "\"The provider explains the risks and alternatives.\""}, {"id": "d", "text": "\"A confused client cannot give valid consent.\""}]'::jsonb, '["a"]', 'The RN''s role is to witness the patient''s signature, not to obtain or explain consent. The provider explains the procedure, and confused patients cannot consent.'),
  ('fundamentals', 30, 'A client has a do-not-resuscitate (DNR) order. Which statement by an unlicensed assistive personnel (UAP) requires correction by the nurse?', '[{"id": "a", "text": "\"I will keep the client clean and comfortable.\""}, {"id": "b", "text": "\"Because the client is DNR, we can stop turning.\""}, {"id": "c", "text": "\"I will offer mouth care to keep the client comfortable.\""}, {"id": "d", "text": "\"I will tell you about any change in the client''s breathing.\""}]'::jsonb, '["b"]', 'A DNR order does not mean withdrawal of all care; comfort and nursing care continue. Stopping repositioning would withdraw nursing care.'),
  ('fundamentals', 31, 'A client scheduled for surgery tomorrow says, "I''m not sure about all of this." Which response by the nurse is most therapeutic?', '[{"id": "a", "text": "\"Why are you worried about such a routine surgery?\""}, {"id": "b", "text": "\"Don''t worry, everything will be fine tomorrow.\""}, {"id": "c", "text": "\"Tell me more about how you''re feeling.\""}, {"id": "d", "text": "\"Are you feeling nervous about the surgery?\""}]'::jsonb, '["c"]', 'An open-ended question such as "Tell me more about how you''re feeling" invites the client to share. "Why" questions feel accusatory, and "everything will be fine" is false reassurance.'),
  ('fundamentals', 32, 'A nurse is completing an admission history for a client who speaks only Armenian. The client''s adult daughter offers to translate. Which action should the nurse take?', '[{"id": "a", "text": "Accept the daughter''s offer to interpret"}, {"id": "b", "text": "Ask a bilingual visitor to interpret"}, {"id": "c", "text": "Use simple English and hand gestures"}, {"id": "d", "text": "Arrange for a certified medical interpreter"}]'::jsonb, '["d"]', 'A certified medical interpreter is used for language barriers, and family members should never be relied on to interpret. Simplified English does not overcome the language barrier.'),
  ('fundamentals', 33, 'A charge nurse observes a nurse talking with a client who was readmitted after not taking prescribed medications at home. Which statement by the nurse requires correction?', '[{"id": "a", "text": "\"Why didn''t you take your medicine at home?\""}, {"id": "b", "text": "\"You said it has been hard to keep up with the pills?\""}, {"id": "c", "text": "\"Tell me more about your routine at home.\""}, {"id": "d", "text": "\"I have some time to sit and talk with you.\""}]'::jsonb, '["a"]', '"Why" questions should be avoided because they can feel accusatory and close dialogue. Restating the client''s words and using open-ended prompts are therapeutic techniques.'),
  ('fundamentals', 34, 'A nurse has finished teaching a client about a new home medication. Which action best confirms that the client understands the instructions?', '[{"id": "a", "text": "Asking the client whether the instructions are clear"}, {"id": "b", "text": "Having the client restate the instructions in own words"}, {"id": "c", "text": "Giving the client a detailed college-level handout"}, {"id": "d", "text": "Having a family member sign the teaching record"}]'::jsonb, '["b"]', 'The teach-back method, in which the patient explains instructions in their own words, is the gold standard to confirm understanding. Asking whether instructions are clear does not confirm comprehension.'),
  ('fundamentals', 35, 'A nurse is preparing written discharge instructions for a client going home after surgery. At which reading level should the materials be written?', '[{"id": "a", "text": "A college reading level"}, {"id": "b", "text": "A high school reading level"}, {"id": "c", "text": "A 5th-grade level or lower"}, {"id": "d", "text": "An 8th-grade reading level"}]'::jsonb, '["c"]', 'All patient education should be delivered at a 5th-grade reading level or lower. Higher reading levels risk the client not understanding the instructions.'),
  ('fundamentals', 36, 'A client with heart failure (CHF) reports increasing shortness of breath. In which position should the nurse place the client?', '[{"id": "a", "text": "Prone, lying face-down"}, {"id": "b", "text": "Supine, flat on the back"}, {"id": "c", "text": "Sims'', on the left side"}, {"id": "d", "text": "High Fowler''s, at 90 degrees"}]'::jsonb, '["d"]', 'High Fowler''s position at 90 degrees is indicated for dyspnea and CHF. Sims'' left lateral is used for enemas and rectal medications.'),
  ('fundamentals', 37, 'A nurse is preparing to administer a prescribed enema. In which position should the nurse place the client?', '[{"id": "a", "text": "Sims'', left side and semi-prone"}, {"id": "b", "text": "High Fowler''s, sitting upright"}, {"id": "c", "text": "Prone, lying face-down flat"}, {"id": "d", "text": "Lithotomy, legs elevated"}]'::jsonb, '["a"]', 'Sims'' (left lateral, semi-prone) position is indicated for enemas, rectal medications, and colonoscopy prep. Lithotomy is used for pelvic and gynecologic examinations.'),
  ('fundamentals', 38, 'A client with acute respiratory distress syndrome (ARDS) has severe hypoxemia. The provider prescribes a position change to improve oxygenation. Which position should the nurse anticipate?', '[{"id": "a", "text": "Lithotomy"}, {"id": "b", "text": "Prone"}, {"id": "c", "text": "Sims'' left lateral"}, {"id": "d", "text": "Supine"}]'::jsonb, '["b"]', 'The prone (face-down) position is indicated for ARDS and COVID-19 with severe hypoxemia. Supine is used after spinal anesthesia or lumbar puncture.'),
  ('fundamentals', 39, 'A nurse is about to give a client the first dose of a newly prescribed antibiotic. Which action should the nurse take first?', '[{"id": "a", "text": "Document the dose in the MAR"}, {"id": "b", "text": "Explain the dosing schedule"}, {"id": "c", "text": "Check the allergy record in the MAR"}, {"id": "d", "text": "Give the dose and watch for a reaction"}]'::jsonb, '["c"]', 'Before every medication, the nurse verifies allergies first by checking the patient''s allergy record in the MAR. Documenting in the MAR occurs only after administration.'),
  ('fundamentals', 40, 'A nurse is preparing to administer an oral medication to a client. Which action best verifies the right patient?', '[{"id": "a", "text": "Confirming the room number and the bed assignment"}, {"id": "b", "text": "Asking the client to name the medication ordered"}, {"id": "c", "text": "Checking the name card posted on the room door"}, {"id": "d", "text": "Scanning the wristband and confirming name and birth date"}]'::jsonb, '["d"]', 'The right patient is verified by scanning the wristband barcode and verbally confirming name and date of birth as two identifiers. A room number or door card is not a patient identifier.'),
  ('fundamentals', 41, 'A client has a routine medication scheduled for 0900. At which time may the nurse administer the medication and still meet the right time?', '[{"id": "a", "text": "0845"}, {"id": "b", "text": "0815"}, {"id": "c", "text": "0945"}, {"id": "d", "text": "1000"}]'::jsonb, '["a"]', 'Medications are administered within ±30 minutes of the scheduled time, so 0830 to 0930 is acceptable for a 0900 dose. The other times fall outside this window.'),
  ('fundamentals', 42, 'A charge nurse is observing a nurse during a medication pass. Which action by the nurse requires correction?', '[{"id": "a", "text": "Scanning the client''s wristband before administration"}, {"id": "b", "text": "Recording the medication in the MAR before giving it"}, {"id": "c", "text": "Giving a STAT dose immediately after it is ordered"}, {"id": "d", "text": "Checking the allergy record before giving a new drug"}]'::jsonb, '["b"]', 'Medications are recorded in the MAR immediately after administration and never before. STAT orders are given immediately, and allergies and two identifiers are verified before administration.'),
  ('fundamentals', 43, 'A client has had an indwelling urinary (Foley) catheter for 4 days. Which group of findings should the nurse recognize as signs of a catheter-associated urinary tract infection (CAUTI)?', '[{"id": "a", "text": "Clear yellow urine and a normal temperature"}, {"id": "b", "text": "Cool, pale, swollen skin near the catheter"}, {"id": "c", "text": "Cloudy urine, fever, and suprapubic tenderness"}, {"id": "d", "text": "Amber urine with no abdominal discomfort"}]'::jsonb, '["c"]', 'CAUTI signs include cloudy urine, fever, and suprapubic tenderness. Cool, pale, swollen skin describes IV infiltration, not CAUTI.'),
  ('fundamentals', 44, 'A nurse is caring for a client who has a new surgical incision and a long-standing chronic leg wound. Which technique should the nurse use for the dressing changes?', '[{"id": "a", "text": "Sterile technique for both wounds"}, {"id": "b", "text": "Clean technique for both wounds"}, {"id": "c", "text": "Clean for the incision, sterile for the chronic wound"}, {"id": "d", "text": "Sterile for the incision, clean for the chronic wound"}]'::jsonb, '["d"]', 'Sterile technique is used for acute or surgical wounds, and clean technique is used for chronic wounds. Option c reverses the two techniques.'),
  ('fundamentals', 45, 'A nurse is preparing to give medication through a client''s nasogastric (NG) tube. Which finding confirms tube placement so the nurse may proceed?', '[{"id": "a", "text": "Gastric aspirate with a pH of 4.5"}, {"id": "b", "text": "Gastric aspirate with a pH of 7.5"}, {"id": "c", "text": "Client denies discomfort at the nares"}, {"id": "d", "text": "Tape remains secure at the nostril"}]'::jsonb, '["a"]', 'NG placement is confirmed by an aspirate pH of 5.5 or less, or by chest X-ray, before feeding or medications. A pH of 7.5 exceeds 5.5, and comfort or secure tape does not confirm placement.'),
  ('fundamentals', 46, 'During a routine check, the nurse finds a client''s peripheral IV site cool, pale, and swollen, with no blood return. Which interpretation and action are correct?', '[{"id": "a", "text": "Phlebitis; continue the infusion and monitor"}, {"id": "b", "text": "Infiltration; discontinue and resite the IV"}, {"id": "c", "text": "Phlebitis; discontinue and resite the IV"}, {"id": "d", "text": "Infiltration; slow the rate and keep the site"}]'::jsonb, '["b"]', 'A cool, pale, swollen site indicates infiltration, and the IV is discontinued and resited. Phlebitis presents with redness, warmth, and a tender cord.'),
  ('fundamentals', 47, 'A nurse is drawing a blood sample for a complete blood count (CBC). Which action is correct?', '[{"id": "a", "text": "Use a green tube and label it at the nurses'' station"}, {"id": "b", "text": "Use a lavender tube and label it at the nurses'' station"}, {"id": "c", "text": "Use a lavender tube and label it at the bedside right away"}, {"id": "d", "text": "Use a green tube and label it at the bedside right away"}]'::jsonb, '["c"]', 'A CBC is drawn in a lavender (EDTA) tube, and all specimens are labeled at the bedside immediately. Green or SST tubes are used for CMP and BMP.'),
  ('fundamentals', 48, 'A nurse receives report on four clients. Which client''s need should the nurse address first?', '[{"id": "a", "text": "A client who wants help calling family members"}, {"id": "b", "text": "A client who is upset about changes in appearance"}, {"id": "c", "text": "A client who wants to talk about future career goals"}, {"id": "d", "text": "A client who is having difficulty breathing"}]'::jsonb, '["d"]', 'Using Maslow''s hierarchy, physiological needs (ABCs) come first, and airway and breathing take priority. Love/belonging, self-esteem, and self-actualization needs are addressed afterward.'),
  ('fundamentals', 49, 'A nurse who is not involved in a client''s care asks the client''s assigned nurse about the client''s diagnosis. Which response by the assigned nurse is appropriate?', '[{"id": "a", "text": "Declining because the coworker has no need to know"}, {"id": "b", "text": "Sharing the diagnosis because the coworker is a nurse"}, {"id": "c", "text": "Sharing it if the coworker promises to keep it private"}, {"id": "d", "text": "Suggesting the coworker read the client''s chart"}]'::jsonb, '["a"]', 'HIPAA protects patient privacy, and information is shared only on a need-to-know basis. Being a nurse does not create a need to know for a client the coworker is not caring for.'),
  ('fundamentals', 50, 'A client reports new onset of dizziness while sitting in a chair. Using the nursing process, which action should the nurse take first?', '[{"id": "a", "text": "Document the client''s report of dizziness"}, {"id": "b", "text": "Assess the client''s current condition"}, {"id": "c", "text": "Implement a new plan of care for dizziness"}, {"id": "d", "text": "Evaluate the response to earlier interventions"}]'::jsonb, '["b"]', 'The nursing process proceeds Assess, Diagnose, Plan, Implement, Evaluate, and the nurse always assesses first. Implementing a plan before assessing skips the first step.'),
  ('documentation', 1, 'A client reports pain at the incision site and says the pain is 8 on a scale of 0 to 10. Which documentation entry by the nurse is most appropriate?', '[{"id": "a", "text": "Client seems fussy and uncomfortable today."}, {"id": "b", "text": "Client states, \"My pain is 8 out of 10.\""}, {"id": "c", "text": "Client is being dramatic about the pain."}, {"id": "d", "text": "Client probably has moderate incision pain."}]'::jsonb, '["b"]', 'Documentation should be objective, and client statements are recorded in quotation marks. "Seems fussy" is an opinion, which is the example of poor charting.'),
  ('documentation', 2, 'The nurse manager reviews entries in a client''s record. Which entry requires correction?', '[{"id": "a", "text": "Client states, \"I slept well last night.\""}, {"id": "b", "text": "Client seems fussy this morning."}, {"id": "c", "text": "Lung sounds assessed after ambulation."}, {"id": "d", "text": "Dressing changed per provider order."}]'::jsonb, '["b"]', 'Documentation must be objective, sticking to facts with no opinions; "seems fussy" is the classic example of a poor entry. The other entries record facts or quoted client statements.'),
  ('documentation', 3, 'Three hours after changing a client''s dressing, the nurse realizes the dressing change was never documented. Which action should the nurse take?', '[{"id": "a", "text": "Chart the dressing change with the original time only"}, {"id": "b", "text": "Leave it uncharted because the care was completed"}, {"id": "c", "text": "Ask the oncoming nurse to chart the dressing change"}, {"id": "d", "text": "Label a late entry with the date, time, and reason"}]'::jsonb, '["d"]', 'If documentation is delayed, the nurse labels it as a late entry with date, time, and reason before charting. Another nurse may never chart for someone else.'),
  ('documentation', 4, 'At the end of a shift, a coworker asks the nurse to chart a medication the coworker gave because the coworker needs to leave. How should the nurse respond?', '[{"id": "a", "text": "Chart the medication and add the coworker''s name"}, {"id": "b", "text": "Chart the medication now and tell the charge nurse"}, {"id": "c", "text": "Decline, because nurses never chart for someone else"}, {"id": "d", "text": "Chart the medication only if the client confirms it"}]'::jsonb, '["c"]', 'Nurses must never chart for someone else; the person who gave the care documents it. Adding the coworker''s name still means charting another person''s care.'),
  ('documentation', 5, 'Which action by a nurse violates documentation rules?', '[{"id": "a", "text": "Deleting an incorrect entry from the client''s chart"}, {"id": "b", "text": "Documenting that the client refused a medication"}, {"id": "c", "text": "Labeling a delayed note as a late entry with a reason"}, {"id": "d", "text": "Recording the client''s words in quotation marks"}]'::jsonb, '["a"]', 'Nurses must never erase or delete entries in the medical record. Documenting refusals, labeling late entries, and quoting client statements are correct practices.'),
  ('documentation', 6, 'A nurse says, "I gave the pain medication, but I was too busy to chart it. Everyone knows I gave it." Which response by the charge nurse is best?', '[{"id": "a", "text": "\"That''s fine, as long as the client felt relief.\""}, {"id": "b", "text": "\"Care that is not charted is considered not done.\""}, {"id": "c", "text": "\"You can chart it tomorrow when you are less busy.\""}, {"id": "d", "text": "\"Just tell the next nurse during the shift report.\""}]'::jsonb, '["b"]', 'If it isn''t charted, it didn''t happen. Waiting hours or days to document is incorrect practice.'),
  ('documentation', 7, 'A client refuses a scheduled medication, and the nurse notifies the provider. What should the nurse document?', '[{"id": "a", "text": "Nothing, because the medication was not given"}, {"id": "b", "text": "The refusal and the person who was notified"}, {"id": "c", "text": "The nurse''s opinion that the client is difficult"}, {"id": "d", "text": "Only that the scheduled dose was held today"}]'::jsonb, '["b"]', 'Refusals and who was notified must always be documented. Skipping documentation of a refusal is incorrect, and opinions do not belong in the chart.'),
  ('documentation', 8, 'After teaching a client how to care for a wound at home, what should the nurse document?', '[{"id": "a", "text": "Only that the wound care teaching was given"}, {"id": "b", "text": "That the client will understand it at home"}, {"id": "c", "text": "The teaching provided and the client''s response"}, {"id": "d", "text": "Nothing until the client is being discharged"}]'::jsonb, '["c"]', 'The nurse should always document patient teaching and the patient''s response. Documenting only that teaching was given assumes it was understood.'),
  ('documentation', 9, 'The nurse gives a client prescribed pain medication. One hour later, the client reports the pain went from 8 to 3. What should the nurse document next?', '[{"id": "a", "text": "The client''s response to the pain medication"}, {"id": "b", "text": "The nurse''s guess about why the pain improved"}, {"id": "c", "text": "Nothing more, since the dose was charted earlier"}, {"id": "d", "text": "A note that the client seemed happier afterward"}]'::jsonb, '["a"]', 'The patient''s response to interventions, such as pain going from 8 to 3, must be documented. Guesses and opinions do not belong in the record.'),
  ('documentation', 10, 'The nurse calls the provider to report a change in a client''s condition and receives new orders. What should the nurse document about the call?', '[{"id": "a", "text": "Only that the provider was contacted by phone"}, {"id": "b", "text": "Only the new orders that the provider gave"}, {"id": "c", "text": "That the provider was called and what was said"}, {"id": "d", "text": "The nurse''s opinion of the provider''s response"}]'::jsonb, '["c"]', 'Communication with providers is documented, including that the nurse called and what was said. Recording only the call or only the orders is incomplete.'),
  ('documentation', 11, 'A client''s condition changes during the shift. Which documentation is appropriate?', '[{"id": "a", "text": "The nurse''s opinion about the client''s family"}, {"id": "b", "text": "A guess about what caused the client''s change"}, {"id": "c", "text": "Criticism of the care given by the prior shift"}, {"id": "d", "text": "The change in condition and the nurse''s assessment"}]'::jsonb, '["d"]', 'Changes in condition and assessments must always be documented. Guesses, opinions, blame, and criticism must never be charted.'),
  ('documentation', 12, 'A nurse completes a client''s morning assessment. When should the nurse document the findings?', '[{"id": "a", "text": "As soon as possible after the care"}, {"id": "b", "text": "At the end of the 12-hour shift"}, {"id": "c", "text": "Before performing the assessment"}, {"id": "d", "text": "The following day during rounds"}]'::jsonb, '["a"]', 'Documentation must be timely, charting as soon as possible after care. Charting before care would be a fake entry, and waiting hours or days is incorrect.'),
  ('documentation', 13, 'The charge nurse reviews several nurses'' charting practices. Which practice requires correction?', '[{"id": "a", "text": "Documenting a medication as given before giving it"}, {"id": "b", "text": "Recording the client''s lung sounds after assessing"}, {"id": "c", "text": "Charting the dressing change right after completing it"}, {"id": "d", "text": "Documenting that the provider was called and what was said"}]'::jsonb, '["a"]', 'Documenting care before it happens is a fake entry, and fake entries are never allowed. The other practices are accurate, timely documentation.'),
  ('documentation', 14, 'A client fell during the night shift. Which entry by the day nurse requires correction?', '[{"id": "a", "text": "Client found on floor beside bed at 0300 per night report."}, {"id": "b", "text": "Client fell because the night nurse ignored the call light."}, {"id": "c", "text": "Provider notified of fall; provider stated to obtain X-ray."}, {"id": "d", "text": "Client states, \"I tried to get up to use the bathroom.\""}]'::jsonb, '["b"]', 'Documentation must never include opinions, blame, or criticism. Blaming the night nurse is not an objective fact.'),
  ('documentation', 15, 'A nurse learns that a neighbor has been admitted to another unit of the hospital. The nurse is not involved in the neighbor''s care. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Open the neighbor''s chart to check on the diagnosis"}, {"id": "b", "text": "Read only the neighbor''s most recent progress note"}, {"id": "c", "text": "Ask a coworker to look up the neighbor''s chart instead"}, {"id": "d", "text": "Avoid opening the neighbor''s chart in the health record"}]'::jsonb, '["d"]', 'Accessing patient information without a job-related need is a HIPAA violation. Having a coworker look it up is still access without a need.'),
  ('documentation', 16, 'A nurse''s login to the electronic health record is locked. A coworker offers to let the nurse chart under the coworker''s login. How should the nurse respond?', '[{"id": "a", "text": "Accept, as long as the coworker stays at the computer"}, {"id": "b", "text": "Decline, because logins must never be shared"}, {"id": "c", "text": "Accept, but write the nurse''s own name in each note"}, {"id": "d", "text": "Decline, and chart on paper under the coworker''s name"}]'::jsonb, '["b"]', 'Passwords and logins must never be shared. Charting under someone else''s name or login is also charting for someone else.'),
  ('documentation', 17, 'A nurse who is documenting in the electronic health record is suddenly called to another client''s room. What should the nurse do before leaving the computer?', '[{"id": "a", "text": "Turn the monitor away from the hallway"}, {"id": "b", "text": "Ask a visitor to watch the workstation"}, {"id": "c", "text": "Log off the computer before walking away"}, {"id": "d", "text": "Minimize the client''s chart on the screen"}]'::jsonb, '["c"]', 'The nurse should log off the computer when done and never leave it unlocked, to protect client privacy. Minimizing the chart or turning the screen leaves it accessible.'),
  ('documentation', 18, 'Before giving medications, a nurse scans the medication and the client''s identification band. Which informatics tool is the nurse using?', '[{"id": "a", "text": "Electronic health record"}, {"id": "b", "text": "Clinical decision support"}, {"id": "c", "text": "Telehealth system"}, {"id": "d", "text": "Bar-code medication administration"}]'::jsonb, '["d"]', 'Bar-code Medication Administration (BCMA) involves scanning meds and patient ID before giving. The electronic health record is the online patient chart.'),
  ('documentation', 19, 'While entering an order, the nurse receives a computer alert warning that the client has a documented drug allergy. Which informatics tool produced this alert?', '[{"id": "a", "text": "Telehealth system"}, {"id": "b", "text": "Clinical decision support system"}, {"id": "c", "text": "Bar-code medication administration"}, {"id": "d", "text": "Online patient portal"}]'::jsonb, '["b"]', 'Clinical Decision Support Systems (CDSS) provide computer alerts that guide decisions. Bar-code medication administration is scanning meds and patient ID before giving.'),
  ('documentation', 20, 'A client who lives far from the clinic will have a follow-up visit with the provider over a video call. Which informatics tool does this represent?', '[{"id": "a", "text": "Clinical decision support"}, {"id": "b", "text": "Bar-code administration"}, {"id": "c", "text": "Telehealth"}, {"id": "d", "text": "Electronic health record"}]'::jsonb, '["c"]', 'Telehealth refers to virtual health care visits. Clinical decision support refers to computer alerts that guide decisions.'),
  ('documentation', 21, 'A nursing student asks what the term informatics means. Which response by the nurse is accurate?', '[{"id": "a", "text": "Using computers and technology to manage health information"}, {"id": "b", "text": "Writing handwritten notes about each client after every shift"}, {"id": "c", "text": "Sharing client information with family through social media"}, {"id": "d", "text": "Teaching clients about medications before they are discharged"}]'::jsonb, '["a"]', 'Informatics means using computers and technology to manage health information. Sharing client information casually violates privacy rules.'),
  ('documentation', 22, 'A client tells the nurse, "I don''t want to walk today because my legs feel weak." Which documentation entry is best?', '[{"id": "a", "text": "Client said something about not wanting to walk today."}, {"id": "b", "text": "Client is lazy and refuses to walk in the hallway today."}, {"id": "c", "text": "Client states, \"I don''t want to walk today because my legs feel weak.\""}, {"id": "d", "text": "Client probably does not want to walk because of being tired."}]'::jsonb, '["c"]', 'Patient statements should be documented in quotation marks rather than paraphrased. The other entries paraphrase, guess, or include opinions.'),
  ('documentation', 23, 'The charge nurse observes staff in the hospital cafeteria. Which behavior requires correction?', '[{"id": "a", "text": "A nurse discussing lunch plans with coworkers"}, {"id": "b", "text": "A nurse discussing a client''s diagnosis with friends"}, {"id": "c", "text": "A nurse reviewing a hospital policy on a phone"}, {"id": "d", "text": "A nurse talking about next week''s staff schedule"}]'::jsonb, '["b"]', 'HIPAA protects patient privacy, and patient information should never be shared casually. The other conversations do not involve client information.'),
  ('documentation', 24, 'The nurse taught a client about a new medication, but the client was distracted and did not ask questions. The nurse plans to chart "Teaching completed; client understands." Which action is best?', '[{"id": "a", "text": "Chart the entry as planned since teaching was given"}, {"id": "b", "text": "Chart only that a handout was left at the bedside"}, {"id": "c", "text": "Wait to chart teaching until the client is discharged"}, {"id": "d", "text": "Document the teaching and the client''s actual response"}]'::jsonb, '["d"]', 'The nurse documents patient teaching and the response rather than assuming teaching is understood. Charting "client understands" without evidence assumes understanding.'),
  ('documentation', 25, 'A nurse uses the "3 R''s" as a reminder of what to document. Which set does this memory aid represent?', '[{"id": "a", "text": "Record, Review, and Revise"}, {"id": "b", "text": "Response, Refusal, and Reported"}, {"id": "c", "text": "Rest, Reposition, and Reassess"}, {"id": "d", "text": "Read, Repeat, and Remember"}]'::jsonb, '["b"]', 'The 3 R''s of documentation are Response, Refusal, and Reported (to whom). The other sets are not the documentation memory aid.'),
  ('documentation', 26, 'The nurse is documenting care for a client. Which item is an example of assessment data?', '[{"id": "a", "text": "A dressing change that the nurse performed"}, {"id": "b", "text": "The client''s pain decreasing after medication"}, {"id": "c", "text": "The client''s lung sounds after ambulation"}, {"id": "d", "text": "A phone call made to the client''s provider"}]'::jsonb, '["c"]', 'Assessments include examples such as vital signs and lung sounds. A dressing change is an intervention, pain decreasing is the client''s response, and the call is communication with a provider.'),
  ('documentation', 27, 'The nurse changes a client''s surgical dressing and prepares to document it. Under which category does this care belong?', '[{"id": "a", "text": "Nursing intervention"}, {"id": "b", "text": "Client assessment"}, {"id": "c", "text": "Client response"}, {"id": "d", "text": "Provider communication"}]'::jsonb, '["a"]', 'Nursing interventions include dressing changes and giving medications. Assessments are findings such as vital signs and lung sounds.'),
  ('documentation', 28, 'During a computer downtime, a nurse must handwrite a progress note. Which basic documentation rule ensures that other staff can read the note?', '[{"id": "a", "text": "Timely"}, {"id": "b", "text": "Objective"}, {"id": "c", "text": "Complete"}, {"id": "d", "text": "Legible"}]'::jsonb, '["d"]', 'Legible documentation means clear writing. Timely refers to charting soon after care, and objective refers to facts without opinions.'),
  ('documentation', 29, 'A nurse documents a dressing change but leaves out the wound assessment and the client''s response. Which basic documentation rule did the nurse fail to follow?', '[{"id": "a", "text": "Legible"}, {"id": "b", "text": "Complete"}, {"id": "c", "text": "Objective"}, {"id": "d", "text": "Timely"}]'::jsonb, '["b"]', 'Complete documentation includes all important information. The entry was not an opinion and was not described as late, so objectivity and timeliness are not the problem.'),
  ('documentation', 30, 'A nurse tells the charge nurse, "I will chart all of my clients'' care at the end of my 12-hour shift so I don''t fall behind." Which response by the charge nurse is best?', '[{"id": "a", "text": "\"Chart your care as soon as possible after giving it.\""}, {"id": "b", "text": "\"That plan works as long as you finish before report.\""}, {"id": "c", "text": "\"Charting once at the end of the shift is most accurate.\""}, {"id": "d", "text": "\"You may chart tomorrow if you run out of time today.\""}]'::jsonb, '["a"]', 'Nurses should chart immediately after care rather than wait hours or days to document. End-of-shift charting is delayed documentation.'),
  ('documentation', 31, 'A nursing student says, "I can look at any client''s chart in the hospital because I am part of the staff." Which response by the nurse is correct?', '[{"id": "a", "text": "\"Yes, as long as you log out when you are finished.\""}, {"id": "b", "text": "\"Only access charts you need for your job.\""}, {"id": "c", "text": "\"Yes, but only during your assigned shift.\""}, {"id": "d", "text": "\"Only if you do not print any information.\""}]'::jsonb, '["b"]', 'Staff should only access charts they need for their job; accessing patient information without a need is a HIPAA violation. Logging out does not make unnecessary access acceptable.'),
  ('documentation', 32, 'A client refuses a dressing change, and the nurse notifies the provider. Which documentation entry is most complete?', '[{"id": "a", "text": "\"Client being difficult again about dressing change.\""}, {"id": "b", "text": "\"Dressing change completed per provider order.\""}, {"id": "c", "text": "\"Client refused dressing change. Provider notified.\""}, {"id": "d", "text": "\"Client refused dressing change this morning.\""}]'::jsonb, '["c"]', 'The nurse documents refusals and who was notified. Recording only the refusal omits the notification, and charting a dressing change that was not done is a fake entry.'),
  ('documentation', 33, 'A nursing student states, "If I gave the care, it still counts even if I forget to document it." Which response by the instructor is best?', '[{"id": "a", "text": "\"Yes, as long as another nurse saw you give the care.\""}, {"id": "b", "text": "\"Yes, documenting care is optional when you are busy.\""}, {"id": "c", "text": "\"Yes, the client can confirm the care if anyone asks.\""}, {"id": "d", "text": "\"No, care that is not charted is considered not done.\""}]'::jsonb, '["d"]', 'The NCLEX golden rule is that if you didn''t chart it, it didn''t happen. Witnesses or client recall do not replace documentation.'),
  ('documentation', 34, 'A nursing student asks why documentation must be accurate and objective. Which response by the nurse is best?', '[{"id": "a", "text": "\"The chart is a personal note for the nurse only.\""}, {"id": "b", "text": "\"The chart is a legal medical record of patient care.\""}, {"id": "c", "text": "\"The chart is shared only with the client''s family.\""}, {"id": "d", "text": "\"The chart is deleted after the client is discharged.\""}]'::jsonb, '["b"]', 'Documentation is recording everything about patient care in a legal medical record. Entries are never erased or deleted.'),
  ('documentation', 35, 'A nurse forgot to take a client''s 1200 vital signs. Which action by the nurse requires correction?', '[{"id": "a", "text": "Charting the 1200 vital signs at normal values"}, {"id": "b", "text": "Taking the client''s vital signs as soon as possible"}, {"id": "c", "text": "Charting only vital signs that were actually taken"}, {"id": "d", "text": "Recording the vital signs right after obtaining them"}]'::jsonb, '["a"]', 'Guessing or fake entries must never be documented. Recording values that were not obtained is a fake entry.'),
  ('documentation', 36, 'The charge nurse walks past a workstation and sees a client''s chart open on an unattended computer. Which action should the charge nurse take?', '[{"id": "a", "text": "Leave the computer open so the nurse can finish"}, {"id": "b", "text": "Turn off the monitor and leave the chart open"}, {"id": "c", "text": "Ask a visitor to tell the nurse the screen is open"}, {"id": "d", "text": "Log out of the computer to protect client privacy"}]'::jsonb, '["d"]', 'Computers should not be left unlocked; staff log out when finished to protect privacy. Turning off the monitor still leaves the chart accessible.'),
  ('documentation', 37, 'A nurse ambulates a client in the hallway. Which documentation entry is objective?', '[{"id": "a", "text": "Client seems lazy about walking today."}, {"id": "b", "text": "Client appears to be faking weakness."}, {"id": "c", "text": "Client ambulated 50 feet in hallway."}, {"id": "d", "text": "Client was difficult during the walk."}]'::jsonb, '["c"]', 'Documentation should include facts only, not opinions or judgments. The other entries are opinions about the client.'),
  ('documentation', 38, 'A client''s lung sounds change, and the nurse calls the provider, who gives a new order. Which documentation is most complete?', '[{"id": "a", "text": "Only that the provider was called"}, {"id": "b", "text": "Only the client''s new lung sounds"}, {"id": "c", "text": "The nurse''s guess about the cause"}, {"id": "d", "text": "The finding, the call, and what was said"}]'::jsonb, '["d"]', 'Documentation includes assessments, changes in condition, and communication with providers, including what was said. Guesses must never be charted.'),
  ('documentation', 39, 'A nurse is administering medications using bar-code medication administration. Which action reflects correct use of this system?', '[{"id": "a", "text": "Scanning only the medication before giving it"}, {"id": "b", "text": "Scanning the medication and the client''s ID first"}, {"id": "c", "text": "Scanning only the client''s ID after the dose"}, {"id": "d", "text": "Scanning the medication after giving the dose"}]'::jsonb, '["b"]', 'BCMA means scanning meds and patient ID before giving. Scanning only one item or scanning after administration does not follow the system.'),
  ('documentation', 40, 'A client asks the nurse what it means that the next appointment will be a telehealth visit. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is a virtual health care visit with your provider.\""}, {"id": "b", "text": "\"It is a computer alert that guides your provider.\""}, {"id": "c", "text": "\"It is the system that scans your medications.\""}, {"id": "d", "text": "\"It is a paper copy of your medical record.\""}]'::jsonb, '["a"]', 'Telehealth refers to virtual health care visits. Computer alerts that guide decisions describe clinical decision support systems.'),
  ('documentation', 41, 'A nursing student asks which informatics tool serves as the online patient chart. Which response by the nurse is correct?', '[{"id": "a", "text": "Clinical decision support system"}, {"id": "b", "text": "Bar-code medication administration"}, {"id": "c", "text": "Electronic health record"}, {"id": "d", "text": "Telehealth"}]'::jsonb, '["c"]', 'The Electronic Health Record (EHR) is the online patient chart. Telehealth refers to virtual visits.'),
  ('documentation', 42, 'A newly hired nurse is learning about the hospital''s clinical decision support system. Which statement by the new nurse indicates understanding?', '[{"id": "a", "text": "\"It provides computer alerts that guide decisions.\""}, {"id": "b", "text": "\"It scans the client''s ID band before medications.\""}, {"id": "c", "text": "\"It allows virtual visits between clients and providers.\""}, {"id": "d", "text": "\"It is the online chart that stores client records.\""}]'::jsonb, '["a"]', 'Clinical Decision Support Systems provide computer alerts that guide decisions. Scanning IDs describes BCMA, virtual visits describe telehealth, and the online chart is the EHR.'),
  ('documentation', 43, 'Which situation is an example of a HIPAA violation?', '[{"id": "a", "text": "A nurse reviews an assigned client''s chart before giving medications"}, {"id": "b", "text": "A nurse looks up a former roommate''s lab results out of concern"}, {"id": "c", "text": "A nurse logs out of the computer before leaving the nurses'' station"}, {"id": "d", "text": "A nurse scans an assigned client''s ID band before giving medications"}]'::jsonb, '["b"]', 'Accessing patient information without a job-related need is a HIPAA violation, even out of concern. Reviewing an assigned client''s chart is part of the nurse''s job.'),
  ('documentation', 44, 'Because of an emergency, a nurse is documenting at 1500 care that was given at 1100. Which entry is documented correctly?', '[{"id": "a", "text": "An entry timed 1100 with no mention of the delay"}, {"id": "b", "text": "An entry labeled late with the date, time, and reason"}, {"id": "c", "text": "An entry left blank for the next shift to complete"}, {"id": "d", "text": "An entry timed 1100 and initialed by the charge nurse"}]'::jsonb, '["b"]', 'When documentation is delayed, the nurse labels the late entry with the date, time, and reason before charting. Timing the note as if it were written at 1100 hides the delay.'),
  ('documentation', 45, 'The charge nurse is reviewing documentation rules with a newly hired nurse. Which statement by the new nurse indicates a need for further teaching?', '[{"id": "a", "text": "\"If I chart late, I will label it as a late entry.\""}, {"id": "b", "text": "\"I include the reason my documentation was delayed.\""}, {"id": "c", "text": "\"If I chart late, I enter the original time only.\""}, {"id": "d", "text": "\"I chart as soon as possible after giving care.\""}]'::jsonb, '["c"]', 'A late entry must be labeled with date, time, and reason before charting. Entering only the original time makes the delayed entry appear timely.'),
  ('documentation', 46, 'A nurse is precepting a new graduate. Which statement by the new graduate indicates a need for further teaching?', '[{"id": "a", "text": "\"I will only chart the care that I personally gave.\""}, {"id": "b", "text": "\"If a coworker is busy, I can chart her assessment.\""}, {"id": "c", "text": "\"I will document client refusals and who I notified.\""}, {"id": "d", "text": "\"I will record client statements in quotation marks.\""}]'::jsonb, '["b"]', 'Nurses must never chart for someone else. The other statements describe correct documentation practices.'),
  ('documentation', 47, 'A nurse is reviewing documentation practices with a group of nursing students. Which student statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I chart facts only and leave out my opinions.\""}, {"id": "b", "text": "\"I log out of the computer when I am finished.\""}, {"id": "c", "text": "\"I document client refusals and who I notified.\""}, {"id": "d", "text": "\"I can erase my entry if I make a mistake in it.\""}]'::jsonb, '["d"]', 'Nurses must never erase or delete entries in the medical record. The other statements reflect correct documentation and privacy practices.'),
  ('documentation', 48, 'After teaching a client the signs of wound infection, which documentation entry best reflects the teaching?', '[{"id": "a", "text": "\"Teaching on infection signs done; client understands.\""}, {"id": "b", "text": "\"Client will probably remember the infection signs.\""}, {"id": "c", "text": "\"Taught infection signs; client restated three signs.\""}, {"id": "d", "text": "\"Handout on infection signs left at client''s bedside.\""}]'::jsonb, '["c"]', 'The nurse documents patient teaching and the patient''s response instead of assuming teaching is understood. The client restating the signs is the documented response.'),
  ('documentation', 49, 'A nurse is reviewing documentation timing with a newly hired nurse. Which statement by the newly hired nurse indicates understanding?', '[{"id": "a", "text": "\"I will chart my assessment right after completing it.\""}, {"id": "b", "text": "\"I will chart all assessments together the next morning.\""}, {"id": "c", "text": "\"I will chart my assessment before I see the client.\""}, {"id": "d", "text": "\"I will chart only if something abnormal is found.\""}]'::jsonb, '["a"]', 'Nurses chart immediately after care. Charting before seeing the client would be a fake entry, and waiting until the next day is delayed documentation.'),
  ('documentation', 50, 'A nurse gives a prescribed pain medication. Which documentation entry includes both the intervention and the client''s response?', '[{"id": "a", "text": "\"Pain medication given as ordered for incision pain.\""}, {"id": "b", "text": "\"Client seemed more comfortable after medication.\""}, {"id": "c", "text": "\"Client will likely need another dose in four hours.\""}, {"id": "d", "text": "\"Pain medication given; pain went from 8/10 to 3/10.\""}]'::jsonb, '["d"]', 'Nursing interventions such as giving meds and the patient''s response, such as pain going from 8 to 3, should be documented. "Seemed more comfortable" is an opinion rather than a measured response.'),
  ('sbar', 1, 'A nurse is calling a provider about a client whose condition has changed. What should the nurse communicate first?', '[{"id": "a", "text": "Her own name and unit, the client, and the problem"}, {"id": "b", "text": "The client''s reason for admission and medications"}, {"id": "c", "text": "Her interpretation of what is causing the change"}, {"id": "d", "text": "The specific orders she would like the provider to give"}]'::jsonb, '["a"]', 'SBAR always starts with Situation, in which the nurse identifies herself and the problem immediately. Admission history is Background, interpretation is Assessment, and requested orders are the Recommendation.'),
  ('sbar', 2, 'A nurse calling a provider says, "This is the nurse from 4 West. I''m calling about the client in room 12." This statement belongs in which part of SBAR?', '[{"id": "a", "text": "Background"}, {"id": "b", "text": "Situation"}, {"id": "c", "text": "Assessment"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["b"]', 'In the Situation, the nurse states her name, role, and unit and identifies the patient. Background covers the reason for admission and history.'),
  ('sbar', 3, 'A nurse prepares to call the provider about a client with heart failure. Which statement belongs in the Situation section of the SBAR report?', '[{"id": "a", "text": "\"He was admitted 3 days ago with a heart failure exacerbation.\""}, {"id": "b", "text": "\"I think he''s fluid-overloaded and decompensating.\""}, {"id": "c", "text": "\"He''s experiencing new-onset shortness of breath right now.\""}, {"id": "d", "text": "\"I''d like you to evaluate him and consider a chest X-ray.\""}]'::jsonb, '["c"]', 'Situation states the immediate issue, such as new-onset shortness of breath. The admission history is Background, the interpretation is Assessment, and the request is the Recommendation.'),
  ('sbar', 4, 'During a phone call to a provider, the nurse says, "She was admitted 2 days ago with a chest infection." In which SBAR section does this statement belong?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Assessment"}, {"id": "c", "text": "Recommendation"}, {"id": "d", "text": "Background"}]'::jsonb, '["d"]', 'Background explains the reason for admission. Situation is the immediate issue happening right now.'),
  ('sbar', 5, 'A nurse calling a provider reports, "His lab results from yesterday were elevated." Which SBAR component does this information support?', '[{"id": "a", "text": "Background"}, {"id": "b", "text": "Situation"}, {"id": "c", "text": "Recommendation"}, {"id": "d", "text": "Assessment"}]'::jsonb, '["a"]', 'Relevant lab results are part of the Background, along with past history, medications, and recent procedures. The Situation is the immediate issue happening now.'),
  ('sbar', 6, 'A nurse giving an SBAR report tells the provider, "He is currently taking furosemide." Into which SBAR section does this statement fit?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Background"}, {"id": "c", "text": "Assessment"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["b"]', 'Medications are part of the Background, which gives clinical history and context. The Assessment holds the nurse''s findings and interpretation.'),
  ('sbar', 7, 'A nurse calling about a client who is now drowsy says, "She had a hip operation yesterday." This statement belongs in which part of SBAR?', '[{"id": "a", "text": "Background"}, {"id": "b", "text": "Situation"}, {"id": "c", "text": "Assessment"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["a"]', 'Operations, procedures, and investigations the client has had are part of the Background. The new drowsiness would be part of the Situation.'),
  ('sbar', 8, 'A nurse reporting a client''s new confusion to a provider adds, "Her normal condition is alert and pain free." Which SBAR component does this statement belong to?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Assessment"}, {"id": "c", "text": "Background"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["c"]', 'The client''s normal condition, such as alert, drowsy, or confused and pain free, is included in the Background. It gives context for the current change.'),
  ('sbar', 9, 'A nurse on the phone with a provider says, "I think the problem is that he is becoming fluid overloaded." In which SBAR section does this statement belong?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Background"}, {"id": "c", "text": "Recommendation"}, {"id": "d", "text": "Assessment"}]'::jsonb, '["d"]', '"I think the problem is" is the nurse''s judgment and belongs in the Assessment. The Recommendation states what the nurse wants or needs.'),
  ('sbar', 10, 'A nurse calls a provider about a client with a new reaction during an infusion and says, "I have stopped the infusion." Into which SBAR section does this statement fit?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Background"}, {"id": "c", "text": "Assessment"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["c"]', 'Actions the nurse has already taken, such as giving oxygen or stopping an infusion, are stated in the Assessment. A request for what to do next would be the Recommendation.'),
  ('sbar', 11, 'A nurse calls a provider and says, "I don''t know what is wrong, but I am worried about him." This statement belongs in which part of SBAR?', '[{"id": "a", "text": "Assessment"}, {"id": "b", "text": "Situation"}, {"id": "c", "text": "Background"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["a"]', 'When the nurse is unsure of the cause, the Assessment can be stated as not knowing what is wrong but being worried. It is still the nurse''s judgment about the client.'),
  ('sbar', 12, 'A nurse is unsure of the cause of a client''s change and tells the provider, "I am not sure what the problem is, but she is deteriorating." Which SBAR component is the nurse communicating?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Background"}, {"id": "c", "text": "Recommendation"}, {"id": "d", "text": "Assessment"}]'::jsonb, '["d"]', 'Stating that the nurse is not sure of the problem but the client is deteriorating is an acceptable Assessment. The nurse does not need a definite cause to give an Assessment.'),
  ('sbar', 13, 'Near the end of a phone call, the nurse tells the provider, "I need you to come and see the client in the next 15 minutes." In which SBAR section does this belong?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Recommendation"}, {"id": "c", "text": "Assessment"}, {"id": "d", "text": "Background"}]'::jsonb, '["b"]', 'The Recommendation states what the nurse needs, such as asking the provider to come see the patient within a set time. The Assessment is the nurse''s interpretation of the problem.'),
  ('sbar', 14, 'After asking the provider to come to the bedside, the nurse adds, "Is there anything I need to do in the meantime?" Which part of SBAR includes this question?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Background"}, {"id": "c", "text": "Recommendation"}, {"id": "d", "text": "Assessment"}]'::jsonb, '["c"]', 'Asking what to do in the meantime is part of the Recommendation. The Assessment instead describes what the nurse thinks is going on.'),
  ('sbar', 15, 'A nurse calling about a client with worsening breathing says, "Would you consider ordering a stat chest X-ray?" This statement belongs in which part of SBAR?', '[{"id": "a", "text": "Recommendation"}, {"id": "b", "text": "Situation"}, {"id": "c", "text": "Assessment"}, {"id": "d", "text": "Background"}]'::jsonb, '["a"]', 'Requesting tests is part of the Recommendation, which states the orders, tests, actions, or clarification the nurse needs.'),
  ('sbar', 16, 'A nurse is preparing to call a provider. Place the statements in the correct SBAR order: (1) "I think he is becoming fluid overloaded." (2) "This is the nurse on 5 East calling about the client in room 9, who has new shortness of breath." (3) "I''d like you to come evaluate him in the next 15 minutes." (4) "He was admitted 2 days ago with heart failure and takes furosemide."', '[{"id": "a", "text": "2, 1, 4, 3"}, {"id": "b", "text": "4, 2, 1, 3"}, {"id": "c", "text": "2, 4, 3, 1"}, {"id": "d", "text": "2, 4, 1, 3"}]'::jsonb, '["d"]', 'SBAR follows Situation (identify self, client, and problem), Background (admission and medications), Assessment (what the nurse thinks is going on), then Recommendation (what the nurse needs).'),
  ('sbar', 17, 'A nurse calls the provider about a client with new shortness of breath and says, "I have given him oxygen." Which SBAR component does this statement belong to?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Assessment"}, {"id": "c", "text": "Background"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["b"]', 'Actions already taken by the nurse, such as giving oxygen or analgesia, are stated in the Assessment. A request for further orders belongs in the Recommendation.'),
  ('sbar', 18, 'A new graduate nurse believes SBAR is used only when calling a provider. Which response by the preceptor is accurate?', '[{"id": "a", "text": "\"SBAR is used only during emergencies.\""}, {"id": "b", "text": "\"SBAR is used only for written charting.\""}, {"id": "c", "text": "\"SBAR is also used for shift handoffs and transfers.\""}, {"id": "d", "text": "\"SBAR is used only by the charge nurse.\""}]'::jsonb, '["c"]', 'SBAR is used for reporting a change to a provider and also for handing off a patient during shift change or transfer and escalating care concerns.'),
  ('sbar', 19, 'A nurse calling a provider about a client''s new chest pain says, "She has a history of diabetes." Into which SBAR section does this statement fit?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Assessment"}, {"id": "c", "text": "Recommendation"}, {"id": "d", "text": "Background"}]'::jsonb, '["d"]', 'Relevant past medical history is part of the Background. The new chest pain itself would be stated in the Situation.'),
  ('sbar', 20, 'A unit manager introduces SBAR for all provider calls. Which outcome is the use of SBAR intended to improve?', '[{"id": "a", "text": "Patient safety"}, {"id": "b", "text": "Length of each report"}, {"id": "c", "text": "Number of provider calls"}, {"id": "d", "text": "Amount of written charting"}]'::jsonb, '["a"]', 'SBAR improves patient safety, communication clarity, and clinical decision-making. It is not described as a way to change report length, call volume, or charting.'),
  ('sbar', 21, 'A nursing student practices an SBAR call with the instructor. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"I will identify myself and the client at the start.\""}, {"id": "b", "text": "\"I will start the call with my recommendation.\""}, {"id": "c", "text": "\"I will keep the background brief and relevant.\""}, {"id": "d", "text": "\"I will share what I think is going on.\""}]'::jsonb, '["b"]', 'SBAR always starts with Situation, not the Recommendation. Identifying self and client first, keeping Background brief, and sharing the nurse''s judgment are correct.'),
  ('sbar', 22, 'A nurse plans to call a provider about a client''s new symptom and intends to read the client''s entire medical history aloud during the Background. What should the charge nurse advise?', '[{"id": "a", "text": "\"Read the full history so nothing is missed.\""}, {"id": "b", "text": "\"Skip the background and go straight to orders.\""}, {"id": "c", "text": "\"Keep the background brief and relevant.\""}, {"id": "d", "text": "\"Give the background after your recommendation.\""}]'::jsonb, '["c"]', 'Background provides context and should be kept brief and relevant. It is not skipped and comes before the Assessment and Recommendation.'),
  ('sbar', 23, 'A charge nurse is teaching staff about SBAR. Which description of the Assessment component is accurate?', '[{"id": "a", "text": "The nurse''s name, role, unit, and the immediate issue"}, {"id": "b", "text": "The reason for admission, history, and medications"}, {"id": "c", "text": "The orders, tests, or actions the nurse is requesting"}, {"id": "d", "text": "The nurse''s clinical findings and interpretation"}]'::jsonb, '["d"]', 'The Assessment shares the nurse''s clinical findings and interpretation. Name, role, and immediate issue are the Situation; admission history is the Background; requests are the Recommendation.'),
  ('sbar', 24, 'A nurse has described a client''s deterioration to the provider. Which recommendation best follows SBAR guidance?', '[{"id": "a", "text": "\"Please come see her within the next 15 minutes.\""}, {"id": "b", "text": "\"Do whatever you think is best for her tonight.\""}, {"id": "c", "text": "\"I just wanted you to be aware of how she is.\""}, {"id": "d", "text": "\"Let me know if you think of anything to do.\""}]'::jsonb, '["a"]', 'The Recommendation shows the nurse is proactive by suggesting specific actions. The other statements are vague and do not clearly state what the nurse needs.'),
  ('sbar', 25, 'A nurse calls the provider, identifies herself and the client, states the client''s new symptom, explains the admission history, and shares her interpretation. She then ends the call. Which SBAR component did she omit?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Background"}, {"id": "c", "text": "Assessment"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["d"]', 'The nurse never stated what she wanted or needed, which is the Recommendation. She did give the Situation, Background, and Assessment.'),
  ('sbar', 26, 'A nurse calls a provider, identifies herself and the client, states the immediate problem, shares her findings and interpretation, and requests an evaluation. She does not mention why the client was admitted or any history. Which SBAR component is missing?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Background"}, {"id": "c", "text": "Assessment"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["b"]', 'The reason for admission and relevant history make up the Background, which the nurse left out. The other three components were included.'),
  ('sbar', 27, 'A nurse calls a provider, identifies herself and the client, describes the new problem, gives the admission history, and asks the provider to come see the client. She does not share any findings or what she thinks is happening. Which SBAR component is missing?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Background"}, {"id": "c", "text": "Assessment"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["c"]', 'The nurse''s findings and interpretation of what is going on make up the Assessment, which was left out. The request to come see the client is the Recommendation.'),
  ('sbar', 28, 'In the SBAR communication tool, what does the letter S stand for?', '[{"id": "a", "text": "Symptoms"}, {"id": "b", "text": "Summary"}, {"id": "c", "text": "Situation"}, {"id": "d", "text": "Status"}]'::jsonb, '["c"]', 'S stands for Situation, which describes what is happening right now.'),
  ('sbar', 29, 'In the SBAR communication tool, what does the letter R stand for?', '[{"id": "a", "text": "Response"}, {"id": "b", "text": "Recommendation"}, {"id": "c", "text": "Results"}, {"id": "d", "text": "Review"}]'::jsonb, '["b"]', 'R stands for Recommendation, which states what the nurse wants or needs.'),
  ('sbar', 30, 'In the SBAR communication tool, what does the letter B stand for?', '[{"id": "a", "text": "Background"}, {"id": "b", "text": "Bedside"}, {"id": "c", "text": "Brief"}, {"id": "d", "text": "Blood pressure"}]'::jsonb, '["a"]', 'B stands for Background, which gives the relevant context or history.'),
  ('sbar', 31, 'In the SBAR communication tool, what does the letter A stand for?', '[{"id": "a", "text": "Action"}, {"id": "b", "text": "Admission"}, {"id": "c", "text": "Allergies"}, {"id": "d", "text": "Assessment"}]'::jsonb, '["d"]', 'A stands for Assessment, which is the nurse''s judgment about what is going on.'),
  ('sbar', 32, 'Which SBAR component answers the question, "What do you want or need?"', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Background"}, {"id": "c", "text": "Recommendation"}, {"id": "d", "text": "Assessment"}]'::jsonb, '["c"]', 'The Recommendation answers what the nurse wants or needs. The Assessment answers what the nurse thinks is going on.'),
  ('sbar', 33, 'Which SBAR component answers the question, "What is the relevant context or history?"', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Background"}, {"id": "c", "text": "Assessment"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["b"]', 'Background provides the relevant context or history. Situation describes what is happening right now.'),
  ('sbar', 34, 'Which SBAR component answers the question, "What do you think is going on?"', '[{"id": "a", "text": "Assessment"}, {"id": "b", "text": "Situation"}, {"id": "c", "text": "Background"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["a"]', 'The Assessment states what the nurse thinks is going on. The Situation states what is happening right now.'),
  ('sbar', 35, 'When identifying the client during the Situation part of an SBAR call, which information should the nurse include?', '[{"id": "a", "text": "The client''s admission date and diagnosis"}, {"id": "b", "text": "The client''s current list of medications"}, {"id": "c", "text": "The nurse''s interpretation of the problem"}, {"id": "d", "text": "The client''s name, age, and location"}]'::jsonb, '["d"]', 'In the Situation, the nurse identifies the patient by name, age, and location. Admission information and medications are Background, and interpretation is Assessment.'),
  ('sbar', 36, 'A nurse is organizing information before calling a provider about a client. Which information belongs in the Assessment section?', '[{"id": "a", "text": "The nurse''s name, role, and unit"}, {"id": "b", "text": "Mental status, pain score, and the nurse''s interpretation"}, {"id": "c", "text": "Reason for admission and current medications"}, {"id": "d", "text": "The orders and tests the nurse is requesting"}]'::jsonb, '["b"]', 'The Assessment includes vital signs, mental status, pain score, and the nurse''s interpretation. Name and unit belong in the Situation, and admission reason belongs in the Background.'),
  ('sbar', 37, 'A nurse is preparing an SBAR call about a client with an unclear order. Which statement belongs in the Recommendation section?', '[{"id": "a", "text": "\"I am the nurse on 2 North.\""}, {"id": "b", "text": "\"He was admitted on Monday.\""}, {"id": "c", "text": "\"I need you to clarify this order.\""}, {"id": "d", "text": "\"I think he is dehydrated.\""}]'::jsonb, '["c"]', 'The Recommendation clearly states what the nurse needs, including orders, tests, actions, or clarification. Identifying the unit is Situation, admission is Background, and the interpretation is Assessment.'),
  ('sbar', 38, 'A nurse is deciding when SBAR is appropriate. Which situation is an example of escalating a care concern using SBAR?', '[{"id": "a", "text": "Charting a routine bed bath"}, {"id": "b", "text": "Ordering the client''s meal tray"}, {"id": "c", "text": "Restocking the supply cart"}, {"id": "d", "text": "Reporting a critical lab result"}]'::jsonb, '["d"]', 'SBAR is used for escalating care concerns such as critical labs and new symptoms. The other activities are routine tasks that do not involve reporting a concern.'),
  ('sbar', 39, 'At shift change, the night nurse gives report to the day nurse. Place the statements in the correct SBAR order: (1) "I''d like you to recheck her pain within the first hour." (2) "She had abdominal surgery yesterday." (3) "This is the night nurse handing off the client in bed 3, who has new pain." (4) "I think her pain is not well controlled."', '[{"id": "a", "text": "3, 2, 4, 1"}, {"id": "b", "text": "2, 3, 4, 1"}, {"id": "c", "text": "3, 4, 2, 1"}, {"id": "d", "text": "3, 2, 1, 4"}]'::jsonb, '["a"]', 'SBAR is also used for shift handoffs and follows Situation, Background (recent surgery), Assessment (what the nurse thinks), then Recommendation (what the nurse wants done).'),
  ('sbar', 40, 'A nurse calling about a client with heart failure says, "His lungs have crackles, he is using accessory muscles, and I think he''s fluid-overloaded." Which SBAR component is the nurse giving?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Background"}, {"id": "c", "text": "Assessment"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["c"]', 'Clinical findings plus the nurse''s interpretation make up the Assessment. Background would include why the client was admitted and his medications.'),
  ('sbar', 41, 'A nurse begins a call: "This is the nurse from 3B. I''m calling about the 76-year-old client in room 4." To complete the Situation, what should the nurse say next?', '[{"id": "a", "text": "The client''s reason for admission"}, {"id": "b", "text": "The nurse''s interpretation of the cause"}, {"id": "c", "text": "The tests the nurse would like ordered"}, {"id": "d", "text": "The client''s immediate problem"}]'::jsonb, '["d"]', 'The Situation includes the nurse''s name, role, unit, client identification, and the immediate issue. Reason for admission is Background, interpretation is Assessment, and tests requested are the Recommendation.'),
  ('sbar', 42, 'A nurse has several findings about a client and must decide what to tell the provider. How does SBAR help the nurse in this situation?', '[{"id": "a", "text": "It replaces the need to report to the provider"}, {"id": "b", "text": "It helps the nurse prioritize what to report"}, {"id": "c", "text": "It allows the nurse to skip the assessment"}, {"id": "d", "text": "It lets the provider decide what the nurse says"}]'::jsonb, '["b"]', 'SBAR helps RNs prioritize what to report to the provider. It does not replace reporting or the nurse''s assessment.'),
  ('sbar', 43, 'A nurse manager encourages staff to use SBAR for every physician call. Which benefit of SBAR is the manager most likely emphasizing?', '[{"id": "a", "text": "It keeps communication organized and professional"}, {"id": "b", "text": "It removes the need for a nursing assessment"}, {"id": "c", "text": "It shortens every call to less than one minute"}, {"id": "d", "text": "It allows the nurse to omit the client''s history"}]'::jsonb, '["a"]', 'SBAR keeps communication organized and professional and improves clarity. It does not remove the Assessment or the Background.'),
  ('sbar', 44, 'A nurse is calling the provider about a client with a problem related to an IV fluid infusion. Which statement belongs in the Recommendation section?', '[{"id": "a", "text": "\"I have already stopped the infusion.\""}, {"id": "b", "text": "\"Should I stop the fluid until you arrive?\""}, {"id": "c", "text": "\"She was admitted on Monday with a chest infection.\""}, {"id": "d", "text": "\"I''m calling about the client in room 7.\""}]'::jsonb, '["b"]', 'Asking whether to stop the fluid in the meantime is part of the Recommendation. Reporting that the infusion has already been stopped is part of the Assessment.'),
  ('sbar', 45, 'A nurse calling a provider says, "I am calling because I am concerned that her temperature is high." In which SBAR section does this statement belong?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Background"}, {"id": "c", "text": "Assessment"}, {"id": "d", "text": "Recommendation"}]'::jsonb, '["a"]', 'Stating why the nurse is calling and what she is concerned about is part of the Situation. Background would describe admission and history.'),
  ('sbar', 46, 'A nurse educator asks which SBAR component requires the nurse to use critical thinking to state a nursing judgment. Which answer is correct?', '[{"id": "a", "text": "Situation"}, {"id": "b", "text": "Background"}, {"id": "c", "text": "Recommendation"}, {"id": "d", "text": "Assessment"}]'::jsonb, '["d"]', 'The Assessment is the nurse''s own nursing judgment and requires critical thinking. The Situation identifies the nurse, client, and immediate issue.'),
  ('sbar', 47, 'A nursing student explains SBAR to a peer. Which statement by the student indicates correct understanding?', '[{"id": "a", "text": "\"Background should include the client''s entire history.\""}, {"id": "b", "text": "\"The Recommendation part of SBAR is optional.\""}, {"id": "c", "text": "\"Assessment is where I share my nursing judgment.\""}, {"id": "d", "text": "\"Situation is where I give my interpretation.\""}]'::jsonb, '["c"]', 'The Assessment is the nurse''s own nursing judgment. Background should be brief and relevant, the Recommendation states what the nurse needs, and interpretation belongs in the Assessment rather than the Situation.'),
  ('sbar', 48, 'A nurse calls the provider about a client whose condition has suddenly worsened. Place the statements in the correct SBAR order: (1) "I don''t know what is wrong, but I am worried." (2) "She was admitted yesterday after a fall." (3) "I need you to come see her now." (4) "I''m the nurse on 6 West calling about the client in room 2, who is newly confused."', '[{"id": "a", "text": "4, 1, 2, 3"}, {"id": "b", "text": "2, 4, 1, 3"}, {"id": "c", "text": "4, 2, 3, 1"}, {"id": "d", "text": "4, 2, 1, 3"}]'::jsonb, '["d"]', 'The call starts with the Situation (nurse, client, problem), then Background (admission), Assessment (not knowing what is wrong but being worried), and Recommendation (asking the provider to come).'),
  ('sbar', 49, 'A charge nurse is coaching a nurse on the purpose of the final part of SBAR. Which statement best describes the Recommendation?', '[{"id": "a", "text": "It identifies the nurse and the client"}, {"id": "b", "text": "It shows the nurse is proactive with specific actions"}, {"id": "c", "text": "It explains the client''s admission history"}, {"id": "d", "text": "It gives the nurse''s interpretation of findings"}]'::jsonb, '["b"]', 'The Recommendation shows the nurse is proactive by suggesting specific actions. Identifying the nurse and client is the Situation, and interpretation is the Assessment.'),
  ('sbar', 50, 'A new graduate nurse asks what SBAR is. Which description is accurate?', '[{"id": "a", "text": "A standardized tool for clear, concise communication"}, {"id": "b", "text": "A form used to document medication administration"}, {"id": "c", "text": "A scoring system for rating a client''s pain level"}, {"id": "d", "text": "A checklist for preparing a client for surgery"}]'::jsonb, '["a"]', 'SBAR is a standardized communication tool used to ensure clear, concise, and effective communication, especially during handoffs, physician calls, and critical situations.'),
  ('triage', 1, 'Following a building collapse, the nurse is triaging victims with tag colors. Which victim should the nurse assess first?', '[{"id": "a", "text": "A victim with minor lacerations on both hands"}, {"id": "b", "text": "A victim with a tension pneumothorax"}, {"id": "c", "text": "A victim with a sprained ankle who is walking"}, {"id": "d", "text": "A victim who is crying with emotional distress"}]'::jsonb, '["b"]', 'Tension pneumothorax is a red-tag (Priority 1) injury, and red-tagged patients are assessed first. Minor lacerations, sprains, and emotional distress are green-tag (Priority 3) examples that can wait.'),
  ('triage', 2, 'At a mass casualty incident, the nurse finds a conscious victim with severe bleeding from a deep thigh wound. Which tag color should the nurse assign?', '[{"id": "a", "text": "Yellow"}, {"id": "b", "text": "Green"}, {"id": "c", "text": "Red"}, {"id": "d", "text": "Black"}]'::jsonb, '["c"]', 'Severe bleeding is listed as a red (Immediate) example: life-threatening but survivable with immediate intervention. Moderate blood loss, not severe bleeding, is a yellow-tag example.'),
  ('triage', 3, 'During a disaster, a victim has burns to both legs with no airway involvement. The victim has a respiratory rate of 20/min, a radial pulse, and follows commands. Which tag color should the nurse assign?', '[{"id": "a", "text": "Yellow"}, {"id": "b", "text": "Red"}, {"id": "c", "text": "Green"}, {"id": "d", "text": "Black"}]'::jsonb, '["a"]', 'Burns without airway involvement are a yellow (Delayed) example: serious but stable enough for care to be delayed. No START criterion for red is present, and the injury is more than a minor green-tag injury.'),
  ('triage', 4, 'After a train derailment, a victim with minor lacerations on the arms walks over to the triage area. The respiratory rate is 18/min and the victim follows commands. Which tag color should the nurse assign?', '[{"id": "a", "text": "Red"}, {"id": "b", "text": "Yellow"}, {"id": "c", "text": "Black"}, {"id": "d", "text": "Green"}]'::jsonb, '["d"]', 'Minor lacerations in a victim who can ambulate are green (Minimal/walking wounded) findings. Yellow is reserved for serious but stable injuries such as burns without airway involvement or moderate blood loss.'),
  ('triage', 5, 'At an MCI, an uninjured adult is crying and visibly upset but is breathing normally, has a radial pulse, follows commands, and is able to walk. Which tag color is appropriate?', '[{"id": "a", "text": "Red"}, {"id": "b", "text": "Green"}, {"id": "c", "text": "Yellow"}, {"id": "d", "text": "Black"}]'::jsonb, '["b"]', 'Emotional distress is listed as a green-tag (Priority 3) example. Distress alone does not meet any red criterion and is not a serious injury requiring a yellow tag.'),
  ('triage', 6, 'Using the START system, the nurse finds a victim who is not breathing. Which action should the nurse take first?', '[{"id": "a", "text": "Assign a black tag immediately"}, {"id": "b", "text": "Assess the capillary refill time"}, {"id": "c", "text": "Reposition the victim''s airway"}, {"id": "d", "text": "Check whether the victim follows commands"}]'::jsonb, '["c"]', 'In START, a victim who is not breathing has the airway repositioned before a tag is assigned. A black tag is assigned only if the victim is still apneic after repositioning, and respirations are assessed before perfusion and mental status.'),
  ('triage', 7, 'A nurse triaging with START repositions the airway of a victim who was not breathing, and the victim begins to breathe. Which tag should the nurse assign?', '[{"id": "a", "text": "Red"}, {"id": "b", "text": "Yellow"}, {"id": "c", "text": "Green"}, {"id": "d", "text": "Black"}]'::jsonb, '["a"]', 'Under START, if breathing starts after the airway is repositioned, the victim is tagged red. A black tag applies only if the victim remains apneic.'),
  ('triage', 8, 'A nurse repositions the airway of a victim who is not breathing at a disaster scene. The victim remains apneic. Which tag should the nurse assign?', '[{"id": "a", "text": "Red"}, {"id": "b", "text": "Yellow"}, {"id": "c", "text": "Black"}, {"id": "d", "text": "Green"}]'::jsonb, '["c"]', 'In START, a victim who is still apneic after airway repositioning is tagged black. A red tag is assigned only if breathing starts after repositioning.'),
  ('triage', 9, 'During START triage, a victim with a scalp wound is breathing at a rate of 34/min. Based on this finding, which tag should the nurse assign?', '[{"id": "a", "text": "Yellow"}, {"id": "b", "text": "Green"}, {"id": "c", "text": "Black"}, {"id": "d", "text": "Red"}]'::jsonb, '["d"]', 'A respiratory rate greater than 30 is an automatic red tag in START. The minor appearance of the wound does not override the respiratory finding.'),
  ('triage', 10, 'A victim at a mass casualty incident is breathing at 8 breaths/min. How should the nurse triage this victim?', '[{"id": "a", "text": "Red, because the respiratory rate is below 10"}, {"id": "b", "text": "Yellow, because the victim is still breathing"}, {"id": "c", "text": "Green, because the respiratory rate is not above 30"}, {"id": "d", "text": "Black, because breathing is too slow to sustain life"}]'::jsonb, '["a"]', 'A respiratory rate below 10 (as well as above 30) is an automatic red tag. Black applies to a victim who stays apneic after airway repositioning, not one who is breathing slowly.'),
  ('triage', 11, 'A victim at a disaster scene has a respiratory rate of 22/min and a capillary refill of 4 seconds. Which tag color should the nurse assign?', '[{"id": "a", "text": "Green"}, {"id": "b", "text": "Red"}, {"id": "c", "text": "Yellow"}, {"id": "d", "text": "Black"}]'::jsonb, '["b"]', 'In START, a capillary refill greater than 2 seconds is an automatic red tag, even when the respiratory rate is within range. Yellow would be inappropriate because perfusion is compromised.'),
  ('triage', 12, 'During START triage, the nurse is unable to palpate a radial pulse on a victim who is breathing at 24/min. Which tag should the nurse assign?', '[{"id": "a", "text": "Yellow"}, {"id": "b", "text": "Green"}, {"id": "c", "text": "Red"}, {"id": "d", "text": "Black"}]'::jsonb, '["c"]', 'Absence of a radial pulse during the perfusion check places the victim in the red category. Black is used for victims who are still apneic after airway repositioning, and this victim is breathing.'),
  ('triage', 13, 'A victim has a respiratory rate of 20/min and a capillary refill of 1 second but cannot follow simple commands. Which tag should the nurse assign?', '[{"id": "a", "text": "Green"}, {"id": "b", "text": "Yellow"}, {"id": "c", "text": "Black"}, {"id": "d", "text": "Red"}]'::jsonb, '["d"]', 'Inability to follow commands on the mental status check is an automatic red tag. Victims who follow commands are the ones tagged yellow or green.'),
  ('triage', 14, 'During START triage, a victim has a respiratory rate of 18/min, a capillary refill of 1 second, and follows commands. What does the nurse conclude about this victim''s tag?', '[{"id": "a", "text": "The victim must be tagged red"}, {"id": "b", "text": "The victim will be tagged yellow or green"}, {"id": "c", "text": "The victim must be tagged black"}, {"id": "d", "text": "The victim will be tagged red or black"}]'::jsonb, '["b"]', 'A victim with respirations and perfusion in range who follows commands is categorized as yellow or green, depending on the injuries. Red is assigned for RR over 30 or under 10, capillary refill over 2 seconds, or inability to follow commands.'),
  ('triage', 15, 'A newly hired nurse asks what the abbreviation START means in disaster triage. Which response by the charge nurse is correct?', '[{"id": "a", "text": "Standard Triage And Rescue Teams"}, {"id": "b", "text": "Systematic Tagging And Response Timing"}, {"id": "c", "text": "Simple Triage And Rapid Treatment"}, {"id": "d", "text": "Sequential Treatment After Rapid Tagging"}]'::jsonb, '["c"]', 'START stands for Simple Triage And Rapid Treatment, a systematic approach to quickly categorize patients in an MCI. The other expansions are not correct.'),
  ('triage', 16, 'A nurse is using the START system at a mass casualty incident. In which order should the nurse evaluate each victim?', '[{"id": "a", "text": "Respirations, perfusion, mental status"}, {"id": "b", "text": "Mental status, respirations, perfusion"}, {"id": "c", "text": "Perfusion, respirations, mental status"}, {"id": "d", "text": "Perfusion, mental status, respirations"}]'::jsonb, '["a"]', 'START evaluates respirations first, then perfusion, then mental status. Starting with perfusion or mental status reverses the order.'),
  ('triage', 17, 'When triaging victims in a disaster, in which order should the nurse assess each victim?', '[{"id": "a", "text": "Breathing, airway, consciousness, circulation"}, {"id": "b", "text": "Circulation, airway, breathing, consciousness"}, {"id": "c", "text": "Consciousness, airway, breathing, circulation"}, {"id": "d", "text": "Airway, breathing, circulation, consciousness"}]'::jsonb, '["d"]', 'The assessment order is airway, then breathing, then circulation, then consciousness. Placing circulation or consciousness first reverses this order.'),
  ('triage', 18, 'A nurse is teaching volunteers about disaster triage. Which sequence correctly lists the order in which tagged victims receive care?', '[{"id": "a", "text": "Red, green, yellow, black"}, {"id": "b", "text": "Red, yellow, green, black"}, {"id": "c", "text": "Yellow, red, green, black"}, {"id": "d", "text": "Black, red, yellow, green"}]'::jsonb, '["b"]', 'Priority order is red, then yellow, then green, with black receiving comfort measures only. Black-tagged victims are not treated first, and yellow comes before green.'),
  ('triage', 19, 'A nurse is explaining the guiding principle of triage during a mass casualty incident. Which statement best reflects this principle?', '[{"id": "a", "text": "The most severely injured victims are always treated first"}, {"id": "b", "text": "Victims are treated in the order in which they arrive"}, {"id": "c", "text": "Care is directed to the greatest good for the greatest number"}, {"id": "d", "text": "Victims who can walk are treated first to clear the scene"}]'::jsonb, '["c"]', 'In an MCI, the principle is the greatest good for the greatest number, focusing on survivable cases. Treating the most severely injured first would divert resources to black-tagged victims who are unlikely to survive.'),
  ('triage', 20, 'At a disaster scene, a victim with massive head trauma remains apneic after the nurse repositions the airway. Which care is appropriate for this victim?', '[{"id": "a", "text": "Comfort measures only"}, {"id": "b", "text": "Immediate aggressive resuscitation"}, {"id": "c", "text": "Care delayed until after red-tagged victims"}, {"id": "d", "text": "Self-care as walking wounded"}]'::jsonb, '["a"]', 'Massive head trauma and remaining apneic after airway repositioning are black-tag findings, and black-tagged victims receive comfort measures only. Delayed care after red patients describes the yellow tag.'),
  ('triage', 21, 'A nurse at an MCI has stabilized all red- and yellow-tagged victims, and resources are available. Which action is appropriate for a black-tagged victim who is still alive?', '[{"id": "a", "text": "Begin extensive life-saving interventions"}, {"id": "b", "text": "Provide pain relief as a comfort measure"}, {"id": "c", "text": "Leave the victim without any care"}, {"id": "d", "text": "Reassign the victim to a red tag"}]'::jsonb, '["b"]', 'Black tag does not mean no care; comfort measures such as pain relief are provided if resources allow. Extensive interventions are not provided to black-tagged victims.'),
  ('triage', 22, 'During a mass casualty incident, which action by a member of the triage team requires correction by the nurse?', '[{"id": "a", "text": "Asking walking wounded victims to help move others"}, {"id": "b", "text": "Repositioning the airway of a victim who is not breathing"}, {"id": "c", "text": "Tagging a victim with a capillary refill of 3 seconds as red"}, {"id": "d", "text": "Giving extensive care to a black-tagged victim while a red-tagged victim waits"}]'::jsonb, '["d"]', 'Extensive interventions are not provided to black-tagged victims, and comfort care must not delay care for red or yellow patients. The other actions follow START and the walking-wounded guidance.'),
  ('triage', 23, 'At an MCI with limited staff, the nurse needs help moving victims away from a hazard. Which victims are most appropriate to ask for help?', '[{"id": "a", "text": "Green-tagged victims"}, {"id": "b", "text": "Yellow-tagged victims"}, {"id": "c", "text": "Red-tagged victims"}, {"id": "d", "text": "Black-tagged victims"}]'::jsonb, '["a"]', 'Green-tagged walking wounded can often assist with evacuation or basic care of others. Yellow-tagged victims have serious injuries and should not be used to help.'),
  ('triage', 24, 'At a disaster site, which victim can safely wait for treatment?', '[{"id": "a", "text": "A victim with an open abdominal wound"}, {"id": "b", "text": "A victim with an airway obstruction requiring intervention"}, {"id": "c", "text": "A victim with moderate blood loss and stable vital signs"}, {"id": "d", "text": "A victim with a respiratory rate of 36/min"}]'::jsonb, '["c"]', 'Moderate blood loss is a yellow (Delayed) example, so this victim can wait. An open abdominal wound, airway obstruction, and RR over 30 are all red (Immediate) findings.'),
  ('triage', 25, 'After an explosion, a victim with a head injury is awake, follows commands, and shows no signs of increased intracranial pressure. Vital signs are stable. Which tag should the nurse assign?', '[{"id": "a", "text": "Red"}, {"id": "b", "text": "Black"}, {"id": "c", "text": "Green"}, {"id": "d", "text": "Yellow"}]'::jsonb, '["d"]', 'A conscious head injury with no signs of increased ICP is a yellow (Delayed) example. Massive head trauma, not a conscious head injury, is listed under black.'),
  ('triage', 26, 'A victim of a highway pileup has an open chest wound. Which priority level should the nurse assign?', '[{"id": "a", "text": "Priority 1 (immediate)"}, {"id": "b", "text": "Priority 2 (delayed)"}, {"id": "c", "text": "Priority 3 (minimal)"}, {"id": "d", "text": "No priority (expectant)"}]'::jsonb, '["a"]', 'Open chest wounds are a red-tag, Priority 1 example requiring immediate intervention. Delayed (Priority 2) care is for serious but stable injuries.'),
  ('triage', 27, 'The nurse is triaging four victims after a tornado. Which victim should receive care first?', '[{"id": "a", "text": "A victim with moderate blood loss from an arm wound"}, {"id": "b", "text": "A victim with an airway obstruction requiring intervention"}, {"id": "c", "text": "A victim with no signs of life after airway repositioning"}, {"id": "d", "text": "A victim with emotional distress who is walking"}]'::jsonb, '["b"]', 'Airway obstruction requiring intervention is a red-tag example and is treated first. A victim with no signs of life is black-tagged and receives comfort measures only, and moderate blood loss is yellow.'),
  ('triage', 28, 'Four victims arrive at a casualty collection point. Which victim should the nurse assess first?', '[{"id": "a", "text": "A victim with a conscious head injury and no signs of increased ICP"}, {"id": "b", "text": "A victim with a sprained wrist who is walking"}, {"id": "c", "text": "A victim with moderate blood loss and stable vital signs"}, {"id": "d", "text": "A victim with unstable vital signs"}]'::jsonb, '["d"]', 'Unstable vital signs are a red-tag example and are assessed first. A conscious head injury and moderate blood loss are yellow examples, and a sprain is green.'),
  ('triage', 29, 'A victim who sprained an ankle during an earthquake is limping but walking without help, breathing at 16/min, and following commands. Which tag should the nurse assign?', '[{"id": "a", "text": "Yellow"}, {"id": "b", "text": "Green"}, {"id": "c", "text": "Red"}, {"id": "d", "text": "Black"}]'::jsonb, '["b"]', 'Sprains and strains are green (Minimal) examples, and a victim who can ambulate is considered walking wounded. Yellow is for serious but stable injuries.'),
  ('triage', 30, 'A nurse is orienting staff to disaster triage. Which description of the yellow tag is accurate?', '[{"id": "a", "text": "Life-threatening injuries that are survivable with immediate intervention"}, {"id": "b", "text": "Minor injuries in victims who can ambulate and care for themselves"}, {"id": "c", "text": "Serious injuries that are stable enough for care to be delayed"}, {"id": "d", "text": "Injuries so severe that survival is unlikely even with immediate care"}]'::jsonb, '["c"]', 'Yellow means serious but not immediately life-threatening injuries, stable enough for care to be delayed without risk. Life-threatening but survivable injuries describe the red tag.'),
  ('triage', 31, 'A nurse is reviewing triage tag colors with a group of nursing students. Which statement by a student indicates a need for further teaching?', '[{"id": "a", "text": "\"Red means ''rescue me now.''\""}, {"id": "b", "text": "\"Yellow means ''you can wait a bit.''\""}, {"id": "c", "text": "\"Green means ''go on your own.''\""}, {"id": "d", "text": "\"Black means ''you can wait a bit.''\""}]'::jsonb, '["d"]', 'Black means "beyond help"; "you can wait a bit" describes yellow. The red, yellow, and green statements match the tag color mnemonics.'),
  ('triage', 32, 'A nurse is explaining treatment timing for each triage tag to volunteers. Which statement by a volunteer indicates correct understanding of the green tag?', '[{"id": "a", "text": "\"Green-tagged victims are treated immediately.\""}, {"id": "b", "text": "\"Green-tagged victims are treated last because they can self-care.\""}, {"id": "c", "text": "\"Green-tagged victims receive comfort measures only.\""}, {"id": "d", "text": "\"Green-tagged victims are treated right after red-tagged victims.\""}]'::jsonb, '["b"]', 'Green-tagged victims have minor injuries and are treated last because they can self-care. Treatment right after red patients describes yellow, and comfort measures only describes black.'),
  ('triage', 33, 'During an MCI, a nurse must choose between treating a victim with a tension pneumothorax and a victim whose injuries make survival unlikely even with immediate care. What is the rationale for treating the victim with the tension pneumothorax first?', '[{"id": "a", "text": "The injury is minor and can be treated quickly"}, {"id": "b", "text": "The injury is life-threatening but survivable with immediate care"}, {"id": "c", "text": "The victim arrived at the triage area first"}, {"id": "d", "text": "The victim is stable enough to be treated later"}]'::jsonb, '["b"]', 'Red-tagged injuries are life-threatening but survivable with immediate intervention, which fits the focus on survivable cases. The other victim fits the black category, where survival is unlikely even with immediate care.'),
  ('triage', 34, 'A victim pulled from a collapsed building has an open abdominal wound and is breathing at 22/min. Which tag color should the nurse assign?', '[{"id": "a", "text": "Yellow"}, {"id": "b", "text": "Green"}, {"id": "c", "text": "Black"}, {"id": "d", "text": "Red"}]'::jsonb, '["d"]', 'Open abdominal wounds are a red (Immediate) example. A normal respiratory rate does not make this wound a delayed (yellow) injury.'),
  ('triage', 35, 'A victim at an MCI is breathing at 24/min, follows commands, and has no palpable radial pulse. The victim asks to wait so others can be treated. How should the nurse tag this victim?', '[{"id": "a", "text": "Green, because the victim follows commands"}, {"id": "b", "text": "Yellow, because the respiratory rate is in range"}, {"id": "c", "text": "Red, because the radial pulse is absent"}, {"id": "d", "text": "Black, because perfusion is inadequate"}]'::jsonb, '["c"]', 'An absent radial pulse is a perfusion criterion for a red tag, regardless of the victim''s ability to follow commands. Black is reserved for victims who stay apneic after airway repositioning or whose survival is unlikely.'),
  ('triage', 36, 'A victim has a respiratory rate of 22/min, a capillary refill of 1 second, and no visible injuries, but stares blankly and does not respond to simple instructions. Which action is appropriate?', '[{"id": "a", "text": "Tag the victim green and ask the victim to walk to the safe area"}, {"id": "b", "text": "Tag the victim yellow because vital signs are in range"}, {"id": "c", "text": "Tag the victim black because the victim is unresponsive"}, {"id": "d", "text": "Tag the victim red because the victim cannot follow commands"}]'::jsonb, '["d"]', 'Being unable to follow commands is an automatic red tag on the START mental status check. Victims who follow commands are the ones placed in yellow or green.'),
  ('triage', 37, 'A victim at a disaster scene is breathing at 28/min and has a capillary refill of 3 seconds. Which tag should the nurse assign?', '[{"id": "a", "text": "Red"}, {"id": "b", "text": "Yellow"}, {"id": "c", "text": "Green"}, {"id": "d", "text": "Black"}]'::jsonb, '["a"]', 'A respiratory rate of 28 does not meet the red criterion, but a capillary refill greater than 2 seconds is an automatic red tag. Perfusion findings must be checked after respirations.'),
  ('triage', 38, 'A nurse is reviewing START criteria with an emergency response team. Which finding automatically places a victim in the red category?', '[{"id": "a", "text": "Respiratory rate of 24/min"}, {"id": "b", "text": "Capillary refill of 1 second"}, {"id": "c", "text": "Capillary refill of 3 seconds"}, {"id": "d", "text": "Ability to follow simple commands"}]'::jsonb, '["c"]', 'Capillary refill greater than 2 seconds is an automatic red tag. A respiratory rate between 10 and 30 and the ability to follow commands do not trigger red.'),
  ('triage', 39, 'A volunteer at an MCI tags a talking, ambulatory victim green, even though the victim''s respiratory rate is 34/min. What should the nurse do?', '[{"id": "a", "text": "Leave the green tag because the victim can walk"}, {"id": "b", "text": "Change the tag to yellow because the victim is talking"}, {"id": "c", "text": "Change the tag to black because breathing is abnormal"}, {"id": "d", "text": "Change the tag to red because the respiratory rate exceeds 30"}]'::jsonb, '["d"]', 'A respiratory rate greater than 30 is an automatic red tag, so the green tag must be corrected. Ability to walk or talk does not override this START criterion.'),
  ('triage', 40, 'The nurse is triaging four victims who are expected to survive. Which victim does the nurse expect to treat last?', '[{"id": "a", "text": "A victim with a tension pneumothorax"}, {"id": "b", "text": "A victim with burns to the legs and no airway involvement"}, {"id": "c", "text": "A victim with moderate blood loss from a forearm wound"}, {"id": "d", "text": "A victim with minor lacerations who is walking"}]'::jsonb, '["d"]', 'Minor lacerations in a walking victim are green (Priority 3), treated last. Burns without airway involvement and moderate blood loss are yellow, and tension pneumothorax is red.'),
  ('triage', 41, 'The family member of a yellow-tagged victim asks why the victim must wait while others are treated. Which response by the nurse is best?', '[{"id": "a", "text": "\"The injuries are serious but stable enough to wait safely.\""}, {"id": "b", "text": "\"The injuries are minor, so self-care is expected.\""}, {"id": "c", "text": "\"The injuries are too severe for treatment to help.\""}, {"id": "d", "text": "\"The injuries will be treated only after all others.\""}]'::jsonb, '["a"]', 'Yellow-tagged patients are seen after red-tagged cases and can wait safely because their injuries are serious but stable. Minor self-care injuries describe green, and injuries beyond help describe black.'),
  ('triage', 42, 'Two victims are brought to the nurse at the same time. One has a respiratory rate of 9/min, and the other is walking and has minor facial lacerations. Which action should the nurse take?', '[{"id": "a", "text": "Treat the walking victim first because care will be quick"}, {"id": "b", "text": "Treat the victim with a respiratory rate of 9/min first"}, {"id": "c", "text": "Treat both victims as delayed priority"}, {"id": "d", "text": "Tag the victim with slow breathing as black"}]'::jsonb, '["b"]', 'A respiratory rate below 10 is an automatic red tag, so this victim is treated first. Minor lacerations in a walking victim are green and can wait.'),
  ('triage', 43, 'A nurse is assessing two red-tagged victims. One has an airway obstruction, and the other has severe bleeding from an arm wound. Based on the triage assessment order, which problem does the nurse address first?', '[{"id": "a", "text": "The severe bleeding, because circulation is assessed first"}, {"id": "b", "text": "The airway obstruction, because the airway is assessed first"}, {"id": "c", "text": "Both equally, because both victims are tagged red"}, {"id": "d", "text": "Neither, until consciousness has been assessed"}]'::jsonb, '["b"]', 'The assessment order is airway, breathing, circulation, then consciousness, so the airway obstruction is addressed first. Circulation and consciousness come later in the sequence.'),
  ('triage', 44, 'Which description best defines the black (expectant) triage tag?', '[{"id": "a", "text": "Serious injuries that can be safely delayed"}, {"id": "b", "text": "Minor injuries in victims able to walk"}, {"id": "c", "text": "Life-threatening injuries that are survivable with prompt care"}, {"id": "d", "text": "Injuries so severe that survival is unlikely even with care"}]'::jsonb, '["d"]', 'Black means no signs of life or injuries so severe that survival is unlikely even with immediate care. Life-threatening but survivable injuries are tagged red.'),
  ('triage', 45, 'Resources are limited at a mass casualty incident. Which victim should NOT receive aggressive intervention?', '[{"id": "a", "text": "A victim with a respiratory rate of 35/min"}, {"id": "b", "text": "A victim who is still apneic after airway repositioning"}, {"id": "c", "text": "A victim with a capillary refill of 3 seconds"}, {"id": "d", "text": "A victim who is unable to follow commands"}]'::jsonb, '["b"]', 'A victim who remains apneic after airway repositioning is tagged black and receives no aggressive intervention. RR over 30, capillary refill over 2 seconds, and inability to follow commands are red findings needing immediate care.'),
  ('triage', 46, 'A nurse is triaging after a factory explosion. Which victim should be tagged green?', '[{"id": "a", "text": "A victim with a strained back who walked to the triage area"}, {"id": "b", "text": "A victim with burns to the torso and no airway involvement"}, {"id": "c", "text": "A victim with moderate blood loss from a leg wound"}, {"id": "d", "text": "A victim with an open abdominal wound"}]'::jsonb, '["a"]', 'Strains are a green (Minimal) example, and a victim who can walk is walking wounded. Burns without airway involvement and moderate blood loss are yellow, and an open abdominal wound is red.'),
  ('triage', 47, 'The nurse is triaging victims after a stadium collapse. Which victim should be tagged yellow?', '[{"id": "a", "text": "A victim with a tension pneumothorax"}, {"id": "b", "text": "A victim with minor lacerations who is walking"}, {"id": "c", "text": "A victim with a conscious head injury and no signs of increased ICP"}, {"id": "d", "text": "A victim with massive head trauma who remains apneic"}]'::jsonb, '["c"]', 'A conscious head injury with no signs of increased ICP is a yellow (Delayed) example. Massive head trauma with persistent apnea is black, and tension pneumothorax is red.'),
  ('triage', 48, 'A nurse is triaging victims with severe bleeding and moderate blood loss after a bus crash. Which statement about these victims is accurate?', '[{"id": "a", "text": "Severe bleeding is tagged red, and moderate blood loss is tagged yellow"}, {"id": "b", "text": "Both are tagged red because each involves blood loss"}, {"id": "c", "text": "Severe bleeding is tagged black, and moderate blood loss is tagged red"}, {"id": "d", "text": "Both are tagged yellow until vital signs become unstable"}]'::jsonb, '["a"]', 'Severe bleeding is a red (Immediate) example, while moderate blood loss is a yellow (Delayed) example. Blood loss alone does not make every victim red.'),
  ('triage', 49, 'A nurse explains why black-tagged victims are not given aggressive treatment during a mass casualty incident. Which statement reflects the correct rationale?', '[{"id": "a", "text": "Black-tagged victims are able to care for themselves"}, {"id": "b", "text": "Black-tagged victims are stable enough to wait safely"}, {"id": "c", "text": "Resources are limited, so care focuses on survivable cases"}, {"id": "d", "text": "Black-tagged victims are treated after green-tagged victims"}]'::jsonb, '["c"]', 'The black tag philosophy is that resources are limited in an MCI, so care focuses on survivable cases. Being able to wait safely describes yellow, and self-care describes green.'),
  ('triage', 50, 'Which victim at a disaster scene is correctly described as "walking wounded"?', '[{"id": "a", "text": "A victim with a tension pneumothorax who is sitting upright"}, {"id": "b", "text": "A victim with burns to the arms who cannot stand"}, {"id": "c", "text": "A victim with unstable vital signs who is talking"}, {"id": "d", "text": "A victim with minor injuries who can ambulate"}]'::jsonb, '["d"]', 'Green-tagged victims with minor injuries who can ambulate and care for themselves are called walking wounded. Tension pneumothorax and unstable vital signs are red findings regardless of posture or speech.'),
  ('amputation', 1, 'A client returned from surgery 4 hours ago after a below-the-knee amputation. How should the nurse position the residual limb?', '[{"id": "a", "text": "Keep the stump flat and avoid elevation"}, {"id": "b", "text": "Place the client prone with the stump flat"}, {"id": "c", "text": "Keep the stump hanging over the bed edge"}, {"id": "d", "text": "Elevate the stump to reduce swelling"}]'::jsonb, '["d"]', 'During the first 24-48 hours, the stump is elevated to help prevent swelling. Lying flat or prone is the positioning used after 48 hours to prevent contractures.'),
  ('amputation', 2, 'A client is on postoperative day 4 after an above-the-knee amputation. Which positioning should the nurse encourage to prevent contractures?', '[{"id": "a", "text": "Sitting with the hip flexed all day"}, {"id": "b", "text": "Keeping a pillow under the stump"}, {"id": "c", "text": "Lying prone several times a day"}, {"id": "d", "text": "Keeping the stump elevated at all times"}]'::jsonb, '["c"]', 'After 48 hours, lying prone (on the stomach) several times a day prevents contractures. A pillow under the stump long-term should be avoided.'),
  ('amputation', 3, 'On postoperative day 5 after a leg amputation, the nurse finds that a UAP has kept a pillow under the client''s stump all day. Which action should the nurse take?', '[{"id": "a", "text": "Praise the UAP for preventing swelling of the residual limb"}, {"id": "b", "text": "Add a second pillow to raise the stump higher for comfort"}, {"id": "c", "text": "Remove the pillow and explain that long-term elevation is avoided"}, {"id": "d", "text": "Leave the pillow in place until the prosthesis is fitted"}]'::jsonb, '["c"]', 'A pillow should not be kept under the stump long-term; after 48 hours, elevation is avoided to prevent contractures. Elevation to reduce swelling applies only to the first 24-48 hours.'),
  ('amputation', 4, 'A nursing student asks why the nurse elevates a client''s residual limb on the evening of surgery. Which response is accurate?', '[{"id": "a", "text": "\"Elevation stretches the hip muscles.\""}, {"id": "b", "text": "\"Elevation helps reduce swelling.\""}, {"id": "c", "text": "\"Elevation shapes the stump for a prosthesis.\""}, {"id": "d", "text": "\"Elevation stops phantom limb pain.\""}]'::jsonb, '["b"]', 'In the first 24-48 hours, the stump is elevated because it reduces swelling. Stretching muscles is the purpose of prone positioning, and shaping the stump is the purpose of compression bandages.'),
  ('amputation', 5, 'A client on postoperative day 3 after an amputation asks why the nurse wants them to lie on their stomach. Which response is best?', '[{"id": "a", "text": "\"It keeps the surgical site clean and dry.\""}, {"id": "b", "text": "\"It reduces swelling in the residual limb.\""}, {"id": "c", "text": "\"It helps shape the stump for a prosthesis.\""}, {"id": "d", "text": "\"It stretches muscles and prevents contractures.\""}]'::jsonb, '["d"]', 'After 48 hours, lying flat or prone stretches muscles and prevents contractures. Reducing swelling is the reason for elevation during the first 24-48 hours.'),
  ('amputation', 6, 'A client on postoperative day 3 after a below-the-knee amputation makes several statements. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll keep my stump clean and dry.\""}, {"id": "b", "text": "\"I''ll lie on my stomach several times each day.\""}, {"id": "c", "text": "\"I''ll keep my stump propped on a pillow at all times.\""}, {"id": "d", "text": "\"I won''t use lotion on my stump unless it''s ordered.\""}]'::jsonb, '["c"]', 'After 48 hours, elevation is avoided, and no pillow is kept under the stump long-term. Lying prone, keeping the stump clean and dry, and avoiding lotion unless ordered are correct.'),
  ('amputation', 7, 'A client recovering from an amputation asks, "What is a contracture?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Swelling of the stump after the surgery.\""}, {"id": "b", "text": "\"Tight muscles that freeze a joint in place.\""}, {"id": "c", "text": "\"Feeling that the missing limb is still there.\""}, {"id": "d", "text": "\"Redness and drainage at the incision.\""}]'::jsonb, '["b"]', 'A contracture is tight muscles that freeze the joint, leaving it in the wrong position. Feeling the missing limb describes phantom limb sensation, and redness with drainage describes infection.'),
  ('amputation', 8, 'The nurse is completing preoperative teaching for a client scheduled for a leg amputation. Which information about phantom limb sensation should the nurse include?', '[{"id": "a", "text": "Feeling the missing part means the surgery failed"}, {"id": "b", "text": "Feeling the missing part after surgery is normal"}, {"id": "c", "text": "Feeling the missing part signals a wound infection"}, {"id": "d", "text": "Feeling the missing part happens only with trauma"}]'::jsonb, '["b"]', 'Before surgery, the nurse teaches that phantom limb sensation, feeling the missing part, is normal. It is not a sign of infection or of a failed surgery.'),
  ('amputation', 9, 'On the day after a below-the-knee amputation, a client says, "It feels like my toes are still there. Am I going crazy?" Which response by the nurse is best?', '[{"id": "a", "text": "\"You should not be feeling anything there at all.\""}, {"id": "b", "text": "\"This means your incision is becoming infected.\""}, {"id": "c", "text": "\"Feeling the missing part is a normal sensation.\""}, {"id": "d", "text": "\"This feeling means your stump needs elevation.\""}]'::jsonb, '["c"]', 'Phantom limb sensation, feeling the missing part, is normal after amputation. It is not a sign of infection, which appears as redness, warmth, and drainage at the surgical site.'),
  ('amputation', 10, 'A client who had a foot amputation 2 days ago reports burning pain in the foot that was removed. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Explain that the pain is imaginary and will pass"}, {"id": "b", "text": "Give the prescribed medication for phantom pain"}, {"id": "c", "text": "Reassure the client that no treatment is needed"}, {"id": "d", "text": "Withhold medication since the foot is no longer there"}]'::jsonb, '["b"]', 'Phantom pain is pain felt in the missing limb; it is real and is treated with medications. Telling the client it is imaginary or needs no treatment is incorrect.'),
  ('amputation', 11, 'The nurse is checking the surgical site of a client a few hours after a below-the-knee amputation. Which characteristics should the nurse assess at the site?', '[{"id": "a", "text": "Hair growth, nail shape, and texture"}, {"id": "b", "text": "Reflexes, gait, and balance"}, {"id": "c", "text": "Drainage, color, and temperature"}, {"id": "d", "text": "Lung sounds, cough, and sputum"}]'::jsonb, '["c"]', 'Post-operative care includes monitoring for bleeding and swelling by checking the surgical site for drainage, color, and temperature. The other findings are not part of the surgical site check.'),
  ('amputation', 12, 'A client who had an above-the-knee amputation reports pain in the missing limb. Which treatment does the nurse anticipate the provider will prescribe?', '[{"id": "a", "text": "No treatment, because the pain is not physically real"}, {"id": "b", "text": "Medications such as antidepressants or anti-seizure drugs"}, {"id": "c", "text": "Keeping the stump elevated on a pillow long-term"}, {"id": "d", "text": "Applying lotion to the stump several times a day"}]'::jsonb, '["b"]', 'Phantom pain is treated with medications, including pain relievers, antidepressants, and anti-seizure medications. Long-term pillow elevation and lotion without an order are avoided.'),
  ('amputation', 13, 'The nurse is teaching stump care to a client in rehabilitation. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll lie on my stomach a few times daily.\""}, {"id": "b", "text": "\"I''ll keep my stump clean and dry.\""}, {"id": "c", "text": "\"I''ll wear my compression bandage.\""}, {"id": "d", "text": "\"I''ll rub lotion on my stump every day.\""}]'::jsonb, '["d"]', 'Stump care includes avoiding lotion unless it is ordered. Keeping the stump clean and dry, using compression bandages, and lying prone are correct.'),
  ('amputation', 14, 'A client who had an amputation is preparing for discharge. Which client statement about stump care indicates correct understanding?', '[{"id": "a", "text": "\"I will soak my stump and leave it damp.\""}, {"id": "b", "text": "\"I will keep my stump moist with lotion.\""}, {"id": "c", "text": "\"I will keep my stump on a pillow for weeks.\""}, {"id": "d", "text": "\"I will keep my stump clean and dry.\""}]'::jsonb, '["d"]', 'Stump care includes keeping it clean and dry, with no lotion unless ordered. Long-term pillow elevation is avoided after the first 24-48 hours.'),
  ('amputation', 15, 'A client in the rehabilitation phase after a leg amputation is preparing for a prosthesis. Which nursing intervention helps prepare the residual limb?', '[{"id": "a", "text": "Keeping the stump elevated whenever the client rests"}, {"id": "b", "text": "Keeping a pillow under the stump for several weeks"}, {"id": "c", "text": "Applying lotion to the stump several times daily"}, {"id": "d", "text": "Applying compression bandages to shape the stump"}]'::jsonb, '["d"]', 'Compression bandages shape the stump to prepare it for a prosthesis (artificial limb). Long-term elevation and lotion without an order are avoided.'),
  ('amputation', 16, 'The nurse is evaluating a client''s understanding of compression bandaging after a below-the-knee amputation. Which statement indicates understanding?', '[{"id": "a", "text": "\"The bandage helps shape my stump for an artificial leg.\""}, {"id": "b", "text": "\"The bandage keeps me from feeling my missing leg.\""}, {"id": "c", "text": "\"The bandage replaces the need to lie on my stomach.\""}, {"id": "d", "text": "\"The bandage lets me apply lotion under it daily.\""}]'::jsonb, '["a"]', 'Compression bandages shape the stump to prepare for a prosthesis (artificial limb). Prone positioning is still needed to prevent contractures.'),
  ('amputation', 17, 'On postoperative day 5, the nurse finds the client''s stump incision red and warm with drainage. Which complication should the nurse suspect?', '[{"id": "a", "text": "Infection"}, {"id": "b", "text": "Contracture"}, {"id": "c", "text": "Phantom limb pain"}, {"id": "d", "text": "Phantom limb sensation"}]'::jsonb, '["a"]', 'Redness, warmth, and drainage at the surgical site are signs of infection. A contracture is a joint frozen in the wrong position, not a change in the incision.'),
  ('amputation', 18, 'The nurse is caring for a client 3 days after an amputation. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Comfort while lying prone for 20 minutes"}, {"id": "b", "text": "A feeling that the missing foot is still present"}, {"id": "c", "text": "Crying and saying they miss the old leg"}, {"id": "d", "text": "Redness, warmth, and drainage at the incision"}]'::jsonb, '["d"]', 'Redness, warmth, and drainage at the surgical site indicate possible infection, a complication. Feeling the missing part is normal, and grief is a normal response.'),
  ('amputation', 19, 'A client with long-standing poor circulation has a stump incision that is healing slowly. Which explanation for this finding is consistent with the client''s history?', '[{"id": "a", "text": "Prone positioning slows healing"}, {"id": "b", "text": "Poor blood flow can slow healing"}, {"id": "c", "text": "Phantom sensation slows healing"}, {"id": "d", "text": "Grieving slows wound healing"}]'::jsonb, '["b"]', 'Delayed healing is a complication because poor blood flow can slow recovery. Prone positioning is used to prevent contractures, and phantom sensation is normal.'),
  ('amputation', 20, 'The nurse is completing a preoperative assessment for a client scheduled for a leg amputation. Which assessment of circulation should the nurse perform?', '[{"id": "a", "text": "Bowel sounds, appetite, and weight"}, {"id": "b", "text": "Reflexes, gait, and muscle strength"}, {"id": "c", "text": "Pulses, color, and temperature of the limb"}, {"id": "d", "text": "Pupils, speech, and orientation"}]'::jsonb, '["c"]', 'Preoperative care includes assessing circulation by checking pulses, color, and temperature. The other assessments are not part of circulation assessment.'),
  ('amputation', 21, 'A client returned to the unit after an amputation. Which assessment should the nurse perform frequently during the postoperative period?', '[{"id": "a", "text": "Height, weight, and BMI"}, {"id": "b", "text": "Color, warmth, and pulses"}, {"id": "c", "text": "Hearing, vision, and smell"}, {"id": "d", "text": "Hair, nails, and teeth"}]'::jsonb, '["b"]', 'After surgery, the nurse assesses color, warmth, and pulses frequently. The other assessments do not evaluate circulation.'),
  ('amputation', 22, 'A client has just returned from surgery after a below-the-knee amputation. Which assessment is the nurse''s priority?', '[{"id": "a", "text": "Teach about fitting a prosthesis"}, {"id": "b", "text": "Check the surgical site for bleeding"}, {"id": "c", "text": "Begin lying the client prone"}, {"id": "d", "text": "Apply lotion to the residual limb"}]'::jsonb, '["b"]', 'Immediately after surgery, the nurse monitors for bleeding and swelling at the surgical site. Prone positioning begins after 48 hours, and prosthesis preparation occurs during rehabilitation.'),
  ('amputation', 23, 'On the morning of a planned amputation, the nurse reviews the preoperative checklist. Which item must be completed before the client goes to surgery?', '[{"id": "a", "text": "A signed consent form"}, {"id": "b", "text": "A fitted prosthesis"}, {"id": "c", "text": "A compression bandage"}, {"id": "d", "text": "A prone positioning trial"}]'::jsonb, '["a"]', 'Preoperative care requires a signed consent form. Compression bandages and prosthesis fitting are part of rehabilitation after surgery.'),
  ('amputation', 24, 'Two days after an amputation, a client cries and says, "I feel like I lost a part of who I am." Which response by the nurse is most appropriate?', '[{"id": "a", "text": "\"It is normal to grieve this loss. Tell me more.\""}, {"id": "b", "text": "\"You should focus on the positive instead.\""}, {"id": "c", "text": "\"Crying will slow down your wound healing.\""}, {"id": "d", "text": "\"Let''s talk about something else for now.\""}]'::jsonb, '["a"]', 'Emotional support is critical, and the nurse should allow grieving because grieving is normal. Redirecting or discouraging the client''s feelings does not allow grieving.'),
  ('amputation', 25, 'A client in rehabilitation after an arm amputation refuses to look at the residual limb and says it looks ugly. How should the nurse interpret this behavior?', '[{"id": "a", "text": "A common body image response needing support"}, {"id": "b", "text": "A sign that the stump is infected"}, {"id": "c", "text": "An unusual reaction needing no follow-up"}, {"id": "d", "text": "A sign of phantom limb sensation"}]'::jsonb, '["a"]', 'Grief, depression, and body image issues are common after amputation and call for emotional support. Infection is identified by redness, warmth, and drainage, not by the client''s feelings.'),
  ('amputation', 26, 'Which statement by a nursing student about caring for a client after an amputation indicates a need for further teaching?', '[{"id": "a", "text": "\"Grieving is abnormal, so I should discourage it.\""}, {"id": "b", "text": "\"Body image concerns are common after amputation.\""}, {"id": "c", "text": "\"Phantom pain is real and is treated with medication.\""}, {"id": "d", "text": "\"Lying prone several times a day prevents contractures.\""}]'::jsonb, '["a"]', 'Grieving is normal, and the nurse should allow it rather than discourage it. The other statements are accurate.'),
  ('amputation', 27, 'A nurse is teaching a community group about conditions that lead to amputation. Which condition should the nurse identify as a top cause?', '[{"id": "a", "text": "Migraine"}, {"id": "b", "text": "Influenza"}, {"id": "c", "text": "Diabetes"}, {"id": "d", "text": "Asthma"}]'::jsonb, '["c"]', 'Diabetes is a top cause of amputation because it leads to poor circulation and infection. The other conditions are not identified as causes of amputation.'),
  ('amputation', 28, 'A client with diabetes asks why the disease increases the risk of losing a limb. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It causes freezing damage to the toes.\""}, {"id": "b", "text": "\"It causes the bones to grow tumors.\""}, {"id": "c", "text": "\"It can cause poor circulation and infection.\""}, {"id": "d", "text": "\"It causes crush injuries to the legs.\""}]'::jsonb, '["c"]', 'Diabetes is a top cause of amputation because it leads to poor circulation and infection. Bone tumors, freezing damage, and crush injuries are separate causes of amputation.'),
  ('amputation', 29, 'A client with poor blood flow to the leg is scheduled for a planned amputation next week. How should the nurse classify this amputation?', '[{"id": "a", "text": "Traumatic"}, {"id": "b", "text": "Elective"}, {"id": "c", "text": "Emergency"}, {"id": "d", "text": "Accidental"}]'::jsonb, '["b"]', 'A planned amputation, for example from poor blood flow, is elective. Traumatic amputations result from accidents such as a car crash or crush injury.'),
  ('amputation', 30, 'The nurse is reviewing the histories of four clients who had amputations. Which client''s amputation is classified as traumatic?', '[{"id": "a", "text": "A client who had a planned surgery for gangrene"}, {"id": "b", "text": "A client who had a planned surgery for poor blood flow"}, {"id": "c", "text": "A client who had a planned surgery for a bone tumor"}, {"id": "d", "text": "A client whose leg was crushed in a car crash"}]'::jsonb, '["d"]', 'A traumatic amputation results from an accident such as a car crash or crush injury. A planned amputation, such as for poor blood flow, is elective.'),
  ('amputation', 31, 'A client is admitted with black, dead tissue on several toes caused by infection. Which term should the nurse use to describe this condition?', '[{"id": "a", "text": "Frostbite"}, {"id": "b", "text": "Ischemia"}, {"id": "c", "text": "Gangrene"}, {"id": "d", "text": "Contracture"}]'::jsonb, '["c"]', 'Gangrene is infection with dead tissue, a common cause of amputation. Ischemia is lack of blood flow, and frostbite is freezing damage.'),
  ('amputation', 32, 'Two weeks after an above-the-knee amputation, a client who has spent most of the day sitting cannot fully straighten the hip. Which complication should the nurse suspect?', '[{"id": "a", "text": "Phantom limb pain"}, {"id": "b", "text": "Infection"}, {"id": "c", "text": "Contracture"}, {"id": "d", "text": "Delayed healing"}]'::jsonb, '["c"]', 'A contracture is a joint frozen in the wrong position and is prevented with positioning. Infection shows as redness, warmth, and drainage at the surgical site.'),
  ('amputation', 33, 'An adolescent with a bone tumor in the leg is scheduled for an amputation. Which cause of amputation does this represent?', '[{"id": "a", "text": "Cancer"}, {"id": "b", "text": "Trauma"}, {"id": "c", "text": "Frostbite"}, {"id": "d", "text": "Ischemia"}]'::jsonb, '["a"]', 'Bone tumors fall under cancer as a cause of amputation. Trauma refers to accidents, and ischemia refers to lack of blood flow.'),
  ('amputation', 34, 'A client scheduled for an amputation because of ischemia asks what ischemia means. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Freezing damage to tissue.\""}, {"id": "b", "text": "\"A lack of blood flow.\""}, {"id": "c", "text": "\"A tumor in the bone.\""}, {"id": "d", "text": "\"A tight, frozen joint.\""}]'::jsonb, '["b"]', 'Poor circulation (ischemia) means a lack of blood flow. Freezing damage is frostbite, and a tight, frozen joint is a contracture.'),
  ('amputation', 35, 'A client who had a leg amputation asks why physical therapy is working on the arms and the other leg. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Therapy strengthens your other muscles.\""}, {"id": "b", "text": "\"Therapy shapes your stump for a prosthesis.\""}, {"id": "c", "text": "\"Therapy reduces swelling in your stump.\""}, {"id": "d", "text": "\"Therapy treats your phantom limb pain.\""}]'::jsonb, '["a"]', 'Physical therapy during rehabilitation strengthens other muscles. Shaping the stump is the role of compression bandages, and swelling is reduced by early elevation.'),
  ('amputation', 36, 'Which positioning plan should the nurse follow for a client after a below-the-knee amputation?', '[{"id": "a", "text": "Keep the stump elevated on a pillow throughout the entire recovery"}, {"id": "b", "text": "Have the client lie prone early, then elevate the stump after 48 hours"}, {"id": "c", "text": "Elevate the stump early, then have the client lie prone after 48 hours"}, {"id": "d", "text": "Keep the stump flat and never elevate it, even right after surgery"}]'::jsonb, '["c"]', 'The stump is elevated in the first 24-48 hours to reduce swelling, then the client lies flat or prone after 48 hours to prevent contractures. Reversing the order or elevating throughout recovery is incorrect.'),
  ('amputation', 37, 'A nurse is planning care for a client scheduled for an amputation tomorrow. Which set of actions belongs to the preoperative phase?', '[{"id": "a", "text": "Elevate the stump and monitor the surgical site for drainage"}, {"id": "b", "text": "Begin prone positioning and apply compression bandages to the stump"}, {"id": "c", "text": "Fit the prosthesis and begin physical therapy to strengthen muscles"}, {"id": "d", "text": "Explain the procedure, assess circulation, teach about phantom limb"}]'::jsonb, '["d"]', 'Preoperative care includes explaining the procedure, assessing circulation, teaching about phantom limb, and emotional support. Prone positioning, compression bandages, and prosthesis preparation come after surgery.'),
  ('amputation', 38, 'A client is entering the rehabilitation phase after a leg amputation. Which set of nursing actions is most appropriate for this phase?', '[{"id": "a", "text": "Physical therapy, prosthesis preparation, and emotional support"}, {"id": "b", "text": "Consent signing, explaining the procedure, and baseline pulses"}, {"id": "c", "text": "Stump elevation, bleeding checks, and first-day pain control"}, {"id": "d", "text": "Preoperative teaching, circulation checks, and consent review"}]'::jsonb, '["a"]', 'Rehabilitation includes physical therapy, preparing for a prosthesis, and emotional support. Consent and procedure explanation are preoperative, and elevation with bleeding checks belongs to the first 48 hours after surgery.'),
  ('amputation', 39, 'A client 1 day after an amputation reports pain at the incision and also pain in the missing foot. Which statement by the nurse correctly distinguishes these?', '[{"id": "a", "text": "\"Neither type of pain needs treatment after an amputation.\""}, {"id": "b", "text": "\"Only the incision pain is real; the missing-limb pain is imagined.\""}, {"id": "c", "text": "\"Only the missing-limb pain is real; incision pain is not expected.\""}, {"id": "d", "text": "\"Both are real pain; one is at the incision and one is in the missing limb.\""}]'::jsonb, '["d"]', 'Post-operative pain includes real pain at the surgical site and phantom pain felt in the missing limb, which is also real and treated with medications. Calling phantom pain imagined is incorrect.'),
  ('amputation', 40, 'The nurse observes a UAP caring for a client''s residual limb in rehabilitation. Which action by the UAP requires correction?', '[{"id": "a", "text": "Reporting redness at the incision"}, {"id": "b", "text": "Drying the stump completely after washing"}, {"id": "c", "text": "Keeping the stump clean during care"}, {"id": "d", "text": "Applying lotion to the stump without an order"}]'::jsonb, '["d"]', 'Stump care includes avoiding lotion unless ordered. Keeping the stump clean and dry and reporting redness, a possible sign of infection, are correct.'),
  ('amputation', 41, 'After a shower, a client in rehabilitation leaves the residual limb damp before putting on the compression bandage. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Apply lotion while the skin is still damp.\""}, {"id": "b", "text": "\"Leave it damp so the skin stays soft.\""}, {"id": "c", "text": "\"Dry the stump well, since it should be kept dry.\""}, {"id": "d", "text": "\"Skip the bandage on the days you shower.\""}]'::jsonb, '["c"]', 'Stump care includes keeping the stump clean and dry. Lotion is avoided unless ordered, and compression bandages are used to shape the stump for a prosthesis.'),
  ('amputation', 42, 'The nurse provides preoperative teaching about phantom limb sensation. Which client statement indicates understanding?', '[{"id": "a", "text": "\"If I feel my leg after surgery, it is infected.\""}, {"id": "b", "text": "\"If I feel my leg after surgery, that is normal.\""}, {"id": "c", "text": "\"If I feel my leg after surgery, call the surgeon.\""}, {"id": "d", "text": "\"If I feel my leg after surgery, I imagined it.\""}]'::jsonb, '["b"]', 'Phantom limb sensation, feeling the missing part, is normal and is taught before surgery. It does not mean the stump is infected.'),
  ('amputation', 43, 'A UAP asks why a client''s residual limb is being wrapped with a compression bandage during rehabilitation. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It shapes the stump to prepare for a prosthesis.\""}, {"id": "b", "text": "\"It treats the client''s phantom limb pain.\""}, {"id": "c", "text": "\"It holds the stump elevated on the pillow.\""}, {"id": "d", "text": "\"It replaces the need for physical therapy.\""}]'::jsonb, '["a"]', 'Compression bandages shape the stump to prepare for a prosthesis. Phantom pain is treated with medications, and physical therapy is still needed to strengthen other muscles.'),
  ('amputation', 44, 'The evening before a scheduled leg amputation, a client is tearful and says, "I don''t know how I''ll live without my leg." Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Ask the provider to postpone the surgery"}, {"id": "b", "text": "Tell the client that crying is not helpful now"}, {"id": "c", "text": "Change the subject to the client''s diet order"}, {"id": "d", "text": "Provide emotional support and let the client grieve"}]'::jsonb, '["d"]', 'Emotional support is part of preoperative care, and grieving is normal. Discouraging crying or changing the subject does not allow the client to grieve.'),
  ('amputation', 45, 'A client is admitted with severe freezing damage to the toes after being stranded outdoors in winter. Which cause of amputation does this represent?', '[{"id": "a", "text": "Frostbite"}, {"id": "b", "text": "Gangrene"}, {"id": "c", "text": "Cancer"}, {"id": "d", "text": "Ischemia"}]'::jsonb, '["a"]', 'Frostbite is freezing damage, one of the common causes of amputation. Gangrene is dead tissue from infection, and ischemia is lack of blood flow.'),
  ('amputation', 46, 'A client is being discharged after a foot amputation. Which finding at the stump should the nurse teach the client to report?', '[{"id": "a", "text": "Redness, warmth, or drainage"}, {"id": "b", "text": "Feeling the missing toes"}, {"id": "c", "text": "Feeling sad about the loss"}, {"id": "d", "text": "Dry, clean skin at the site"}]'::jsonb, '["a"]', 'Redness, warmth, and drainage at the surgical site are signs of infection to monitor for. Feeling the missing part is normal phantom sensation, and grief is a normal response.'),
  ('amputation', 47, 'A client with long-standing poor circulation asks why the nurse warned that the stump might take longer to heal. Which response is accurate?', '[{"id": "a", "text": "\"Lying prone often slows your recovery.\""}, {"id": "b", "text": "\"Poor blood flow can slow your recovery.\""}, {"id": "c", "text": "\"Feeling your missing leg slows recovery.\""}, {"id": "d", "text": "\"Compression bandages slow your recovery.\""}]'::jsonb, '["b"]', 'Delayed healing is a complication because poor blood flow can slow recovery. Prone positioning and compression bandages are part of recommended care.'),
  ('amputation', 48, 'Six hours after an amputation, a client reports pain at the surgical incision. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Tell the client incision pain is not expected"}, {"id": "b", "text": "Provide pain control for the incision pain"}, {"id": "c", "text": "Explain that this is phantom limb sensation"}, {"id": "d", "text": "Have the client lie prone to relieve the pain"}]'::jsonb, '["b"]', 'Pain control is part of post-operative care, and pain at the surgical site is real pain. Phantom sensation and phantom pain are felt in the missing limb, not at the incision.'),
  ('amputation', 49, 'A client 2 days after a leg amputation is withdrawn, refuses visitors, and says he feels hopeless. How should the nurse interpret this?', '[{"id": "a", "text": "This response is rare and needs no intervention"}, {"id": "b", "text": "Withdrawal shows the client has accepted the loss"}, {"id": "c", "text": "These feelings mean the stump is not healing"}, {"id": "d", "text": "Depression is common and needs emotional support"}]'::jsonb, '["d"]', 'Grief, depression, and body image issues are common after amputation, and emotional support is critical. Considering the response rare or needing no follow-up ignores this.'),
  ('amputation', 50, 'A client scheduled for removal of two toes asks whether this is considered an amputation. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"No, amputation refers only to removal after an accident.\""}, {"id": "b", "text": "\"No, amputation means removing an entire arm or leg only.\""}, {"id": "c", "text": "\"Yes, removing all or part of a limb, including toes, is amputation.\""}, {"id": "d", "text": "\"No, amputation refers only to planned surgery for cancer.\""}]'::jsonb, '["c"]', 'Amputation is the surgical removal of all or part of a limb, including fingers and toes. It may be elective or traumatic, not only one or the other.'),
  ('delegation', 1, 'The nurse is caring for a stable client on the first postoperative day. Which task is appropriate for the nurse to delegate to the unlicensed assistive personnel (UAP)?', '[{"id": "a", "text": "Assess the client''s surgical site"}, {"id": "b", "text": "Assist the client with ambulation to the bathroom"}, {"id": "c", "text": "Teach the client about splinting the incision"}, {"id": "d", "text": "Administer the client''s IV antibiotic"}]'::jsonb, '["b"]', 'Assisting a stable post-op client with ambulation is basic care that a UAP can perform. Assessing the surgical site requires nursing judgment and remains an RN task, as do teaching and IV medications.'),
  ('delegation', 2, 'The RN is making assignments for a team that includes a licensed practical nurse (LPN). Which task is most appropriate to delegate to the LPN?', '[{"id": "a", "text": "Administering an enteral feeding through a PEG tube to a stable client"}, {"id": "b", "text": "Performing the admission assessment on a newly arrived client"}, {"id": "c", "text": "Hanging a unit of packed red blood cells for an anemic client"}, {"id": "d", "text": "Developing the nursing care plan for a client with a new diagnosis"}]'::jsonb, '["a"]', 'Enteral feeds such as PEG tube feedings may be delegated to the LPN for a stable client. Initial assessments, blood products, and care plans stay with the RN.'),
  ('delegation', 3, 'A UAP has been assigned to take routine vital signs on a client who suddenly reports new-onset chest pain. The nurse recognizes that continuing to delegate the vital signs for this client would violate which right of delegation?', '[{"id": "a", "text": "Right task"}, {"id": "b", "text": "Right person"}, {"id": "c", "text": "Right circumstance"}, {"id": "d", "text": "Right direction/communication"}]'::jsonb, '["c"]', 'Right circumstance asks whether the patient is stable; new-onset chest pain is the example of a circumstance in which delegation is not appropriate. Vital signs on a stable patient would meet this right.'),
  ('delegation', 4, 'The RN tells a UAP, "Take this client''s blood pressure every hour and report to me if it is over 140." This instruction best demonstrates which right of delegation?', '[{"id": "a", "text": "Right task"}, {"id": "b", "text": "Right supervision/evaluation"}, {"id": "c", "text": "Right circumstance"}, {"id": "d", "text": "Right direction/communication"}]'::jsonb, '["d"]', 'Right direction/communication means the task is explained clearly and specifically, as in giving a frequency and a value to report. Supervision/evaluation refers to the RN following up afterward.'),
  ('delegation', 5, 'After delegating a sterile dressing change to an LPN, the RN returns to the room to check that the dressing change was done correctly. Which right of delegation is the RN fulfilling?', '[{"id": "a", "text": "Right task"}, {"id": "b", "text": "Right supervision/evaluation"}, {"id": "c", "text": "Right person"}, {"id": "d", "text": "Right direction/communication"}]'::jsonb, '["b"]', 'Right supervision/evaluation asks whether the RN followed up to check that the task was done correctly. Right direction/communication concerns how clearly the task was explained before it was done.'),
  ('delegation', 6, 'Before handing off any work, the RN first asks, "Is this something that is safe to delegate at all?" The RN is evaluating which right of delegation?', '[{"id": "a", "text": "Right person"}, {"id": "b", "text": "Right circumstance"}, {"id": "c", "text": "Right task"}, {"id": "d", "text": "Right supervision/evaluation"}]'::jsonb, '["c"]', 'Right task asks whether the task is safe to delegate, such as ambulating a stable post-op patient but not administering IV meds. Right circumstance instead asks whether the patient is stable.'),
  ('delegation', 7, 'The charge nurse is reviewing delegation with a newly hired RN. Which statement by the new RN indicates a need for further teaching?', '[{"id": "a", "text": "\"Once I delegate a task, the UAP becomes accountable for the outcome.\""}, {"id": "b", "text": "\"I can delegate tasks, but I cannot delegate my nursing judgment.\""}, {"id": "c", "text": "\"I need to follow up after delegating to make sure the task was done.\""}, {"id": "d", "text": "\"I should ask whether a task requires nursing judgment before delegating.\""}]'::jsonb, '["a"]', 'The RN is always accountable even after delegating, so accountability does not transfer to the UAP. The other statements correctly describe delegating tasks but not judgment, following up, and screening for nursing judgment.'),
  ('delegation', 8, 'The RN is planning meal assistance on a medical unit. Which client may the RN assign the UAP to feed?', '[{"id": "a", "text": "A client with dysphagia following a stroke"}, {"id": "b", "text": "A client with a casted wrist and no swallowing difficulty"}, {"id": "c", "text": "A newly admitted client who has not yet been assessed"}, {"id": "d", "text": "A client who became unstable during the past hour"}]'::jsonb, '["b"]', 'UAPs may feed non-dysphagia patients, so a stable client with a casted wrist is appropriate. A client with dysphagia should not be fed by the UAP, and new or unstable clients require the RN.'),
  ('delegation', 9, 'The RN observes a UAP caring for a stable client. Which action by the UAP requires the RN to intervene?', '[{"id": "a", "text": "Measuring and recording the client''s urine output"}, {"id": "b", "text": "Turning and repositioning the client in bed"}, {"id": "c", "text": "Assisting the client with a bed bath"}, {"id": "d", "text": "Telling the client the urine output is too low and to drink more"}]'::jsonb, '["d"]', 'UAPs may collect I&O data but must not interpret it; deciding that output is too low and directing the client requires judgment. Measuring and recording output, positioning, and bathing are within UAP basic care.'),
  ('delegation', 10, 'An RN is working with an LPN on a surgical unit. Which task should the RN keep rather than delegate to the LPN?', '[{"id": "a", "text": "Changing a sterile dressing on a stable client"}, {"id": "b", "text": "Collecting a sputum specimen from a stable client"}, {"id": "c", "text": "Inserting a Foley catheter in a stable client"}, {"id": "d", "text": "Completing the discharge of a client going home today"}]'::jsonb, '["d"]', 'Triage and discharge are listed among tasks that are never delegated. Sterile dressing changes, collecting specimens, and Foley insertion on stable patients are LPN tasks.'),
  ('delegation', 11, 'The RN taught a stable client about a low-sodium diet yesterday. Which assignment for the LPN today is appropriate?', '[{"id": "a", "text": "Provide the client''s initial teaching about a newly prescribed medication"}, {"id": "b", "text": "Determine whether the client is ready for discharge home"}, {"id": "c", "text": "Reinforce the low-sodium diet teaching the RN provided yesterday"}, {"id": "d", "text": "Revise the client''s care plan based on new information"}]'::jsonb, '["c"]', 'LPNs may reinforce teaching but not provide the initial teaching. Initial teaching, discharge decisions, and care plans remain RN responsibilities.'),
  ('delegation', 12, 'The provider changes the dose of a stable client''s daily medication. Who should explain the change to the client?', '[{"id": "a", "text": "The RN, because teaching new or changing information is an RN task"}, {"id": "b", "text": "The LPN, because the client''s condition is stable"}, {"id": "c", "text": "The UAP, because the client already knows the medication"}, {"id": "d", "text": "The LPN, because the medication is given by mouth"}]'::jsonb, '["a"]', 'Teaching, especially new or changing information, is never delegated and stays with the RN. Client stability or the oral route does not make initial teaching delegable; LPNs only reinforce teaching.'),
  ('delegation', 13, 'When applying the right person in the five rights of delegation, which question should the RN ask?', '[{"id": "a", "text": "Is the patient''s condition stable?"}, {"id": "b", "text": "Was the task explained clearly and specifically?"}, {"id": "c", "text": "Did I follow up to check the task was done correctly?"}, {"id": "d", "text": "Is the person qualified to do this task?"}]'::jsonb, '["d"]', 'Right person asks whether the person is qualified to do the task. Patient stability is the right circumstance, and clear explanation is the right direction/communication.'),
  ('delegation', 14, 'A stable client requires an indwelling urinary catheter. Which delegation by the RN is appropriate?', '[{"id": "a", "text": "Ask the UAP to insert the Foley catheter"}, {"id": "b", "text": "Ask the LPN to insert the Foley catheter"}, {"id": "c", "text": "Ask the UAP to assess the need for the catheter"}, {"id": "d", "text": "Ask the LPN to plan the client''s catheter care"}]'::jsonb, '["b"]', 'Foley insertion is listed among LPN tasks for stable patients. UAPs cannot do assessments, and care planning is not an LPN task.'),
  ('delegation', 15, 'A stable client with a long-term tracheostomy requires trach care and suctioning. To whom may the RN delegate this care?', '[{"id": "a", "text": "The UAP, because trach care is routine hygiene"}, {"id": "b", "text": "The UAP, after the RN shows how it is done"}, {"id": "c", "text": "No one, because trach care is never delegated"}, {"id": "d", "text": "The LPN, because suctioning and trach care are LPN tasks"}]'::jsonb, '["d"]', 'Suctioning and trach care are listed under what LPNs can do under RN supervision. UAP tasks are limited to routine, low-risk basic care such as bathing and toileting.'),
  ('delegation', 16, 'The RN is caring for four clients with the help of an LPN and a UAP. Which task must the RN perform personally?', '[{"id": "a", "text": "Collecting a urine specimen from a stable client"}, {"id": "b", "text": "Changing a sterile dressing for a stable client"}, {"id": "c", "text": "Administering a unit of blood to an anemic client"}, {"id": "d", "text": "Assisting a stable client with morning bathing"}]'::jsonb, '["c"]', 'IV meds and blood products are never delegated. Specimen collection and sterile dressing changes can go to the LPN, and bathing to the UAP.'),
  ('delegation', 17, 'The RN is reviewing assignments for an LPN. Which client should the RN keep rather than assign to the LPN?', '[{"id": "a", "text": "A stable client who needs scheduled oral medications"}, {"id": "b", "text": "A stable client with a chronic wound needing care"}, {"id": "c", "text": "A stable client receiving enteral feedings"}, {"id": "d", "text": "A client who has developed complications after surgery"}]'::jsonb, '["d"]', 'Patients with complications are on the not-delegate list and stay with the RN. Stable patients needing oral meds, wound care, or enteral feeds can be assigned to the LPN.'),
  ('delegation', 18, 'The RN is deciding which client to assign to an LPN. Which client is the most appropriate choice?', '[{"id": "a", "text": "A client with a stable chronic condition"}, {"id": "b", "text": "A client in an acute condition"}, {"id": "c", "text": "A client who is unstable after a procedure"}, {"id": "d", "text": "A client with a complex set of problems"}]'::jsonb, '["a"]', 'Stable and chronic patients may be delegated. Acute, unstable, and complex patients are on the not-delegate list.'),
  ('delegation', 19, 'A client has just arrived on the unit from the emergency department. Which task cannot be delegated by the RN?', '[{"id": "a", "text": "Changing the client''s bed linens"}, {"id": "b", "text": "Performing the client''s initial assessment"}, {"id": "c", "text": "Assisting the client to the bathroom"}, {"id": "d", "text": "Taking vital signs once the client is stable"}]'::jsonb, '["b"]', 'The initial assessment, the first time the patient is seen, is never delegated. Linen changes, toileting, and vital signs on a stable patient are UAP tasks.'),
  ('delegation', 20, 'A nursing student is discussing delegation with the clinical instructor. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"Only the RN may teach new information to a client.\""}, {"id": "b", "text": "\"The RN stays accountable after delegating a task.\""}, {"id": "c", "text": "\"An LPN may do a new client''s initial assessment if the client is stable.\""}, {"id": "d", "text": "\"A UAP may help a stable client with toileting.\""}]'::jsonb, '["c"]', 'The initial assessment is always done by the RN, even when the client appears stable. The other statements correctly describe RN-only teaching, RN accountability, and UAP basic care.'),
  ('delegation', 21, 'The RN taught a stable client deep-breathing exercises this morning. Which instruction to the LPN is appropriate?', '[{"id": "a", "text": "\"Teach the client the coughing technique I haven''t covered yet.\""}, {"id": "b", "text": "\"Decide whether the client needs more breathing exercises.\""}, {"id": "c", "text": "\"Evaluate whether the client understood my teaching.\""}, {"id": "d", "text": "\"Reinforce the breathing exercises I taught this morning.\""}]'::jsonb, '["d"]', 'Reinforce is a keyword that signals a task can be delegated. New teaching, decisions, and evaluation require nursing judgment and stay with the RN.'),
  ('delegation', 22, 'An RN is uncertain whether a task should be delegated to the UAP. Which question best guides the RN''s decision?', '[{"id": "a", "text": "\"Does this task require nursing judgment?\""}, {"id": "b", "text": "\"Does the UAP have enough time for this task?\""}, {"id": "c", "text": "\"Has the client asked for help with this task?\""}, {"id": "d", "text": "\"Can this task be finished in a few minutes?\""}]'::jsonb, '["a"]', 'When in doubt, the RN asks whether the task requires nursing judgment; if it does, it is RN only. Time available or how quick a task is does not determine whether it is safe to delegate.'),
  ('delegation', 23, 'The RN gives several instructions to a UAP caring for stable clients. Which instruction requires correction?', '[{"id": "a", "text": "\"Turn the client in room 4 every 2 hours.\""}, {"id": "b", "text": "\"Decide whether the client in room 6 can walk alone.\""}, {"id": "c", "text": "\"Help the client in room 8 with a bed bath.\""}, {"id": "d", "text": "\"Change the linens for the client in room 10.\""}]'::jsonb, '["b"]', 'RNs use judgment and do not delegate decisions, so deciding whether a client can walk alone stays with the RN. Turning, bathing, and linen changes are UAP basic care.'),
  ('delegation', 24, 'A stable client on bed rest is unable to change position independently. Which task best fits the role of the UAP?', '[{"id": "a", "text": "Assessing the client''s skin for breakdown"}, {"id": "b", "text": "Teaching the client how to relieve pressure"}, {"id": "c", "text": "Turning and positioning the client on schedule"}, {"id": "d", "text": "Planning the client''s repositioning schedule"}]'::jsonb, '["c"]', 'Positioning and turning is a routine, repetitive, low-risk UAP task. Assessing, teaching, and planning care are not delegated to the UAP.'),
  ('delegation', 25, 'The RN is caring for a stable client with a chronic condition. Which request to the UAP is appropriate?', '[{"id": "a", "text": "\"Explain the client''s new diet to him.\""}, {"id": "b", "text": "\"Assess how the client tolerated breakfast.\""}, {"id": "c", "text": "\"Give the client his morning pill with juice.\""}, {"id": "d", "text": "\"Help the client get dressed for the day.\""}]'::jsonb, '["d"]', 'Bathing, dressing, and toileting are basic care tasks for the UAP. UAPs cannot teach, assess, or give medications.'),
  ('delegation', 26, 'The RN enters a room and sees a UAP handing a stable client a scheduled oral tablet. Which action by the RN is most appropriate?', '[{"id": "a", "text": "Stop the UAP, because UAPs may not administer medications"}, {"id": "b", "text": "Allow it, because oral medications are low-risk"}, {"id": "c", "text": "Allow it, because the client''s condition is stable"}, {"id": "d", "text": "Stop the UAP, because only the RN may give oral medications"}]'::jsonb, '["a"]', 'UAPs cannot do medications. It is not true that only the RN can give oral meds, since LPNs can give oral medications to stable patients.'),
  ('delegation', 27, 'The RN overhears several UAP conversations with clients. Which UAP action requires the RN to intervene?', '[{"id": "a", "text": "Helping a client to the toilet"}, {"id": "b", "text": "Walking with a client in the hallway"}, {"id": "c", "text": "Explaining to a client how a new medication works"}, {"id": "d", "text": "Recording a client''s fluid intake"}]'::jsonb, '["c"]', 'Only RNs teach new information, so the UAP should not explain a new medication. Toileting, ambulating, and recording intake are UAP tasks.'),
  ('delegation', 28, 'An LPN offers to give a scheduled IV medication to a stable client so the RN can catch up. How should the RN respond?', '[{"id": "a", "text": "Accept, because the client is stable"}, {"id": "b", "text": "Decline, because IV medications are not LPN tasks"}, {"id": "c", "text": "Accept, if the LPN reports back afterward"}, {"id": "d", "text": "Decline, because LPNs give no medications"}]'::jsonb, '["b"]', 'LPNs do not give IV meds even for stable patients. LPNs do give oral and some IM/SQ medications, so stating they give no medications is incorrect.'),
  ('delegation', 29, 'The charge nurse reviews an RN''s assignments for an LPN. Which assignment requires correction?', '[{"id": "a", "text": "Perform wound care for a stable client"}, {"id": "b", "text": "Collect a urine specimen from a stable client"}, {"id": "c", "text": "Give an enteral feeding to a stable client"}, {"id": "d", "text": "Write the care plan for a new admission"}]'::jsonb, '["d"]', 'LPNs do not write care plans; care plans are never delegated. Wound care, specimen collection, and enteral feeds on stable patients are LPN tasks.'),
  ('delegation', 30, 'Several clients arrive at once at an urgent care center staffed by an RN, an LPN, and a UAP. Who should triage the clients?', '[{"id": "a", "text": "The RN"}, {"id": "b", "text": "The LPN with the most experience"}, {"id": "c", "text": "The UAP who took the first vital signs"}, {"id": "d", "text": "The LPN, with the RN signing afterward"}]'::jsonb, '["a"]', 'The RN role includes triage, and triage is listed among tasks never delegated. Experience or later co-signature does not make triage an LPN task.'),
  ('delegation', 31, 'The RN delegates ambulation of a stable postoperative client to a UAP. What should the RN do after the UAP reports the walk is finished?', '[{"id": "a", "text": "Document that the UAP is responsible for the outcome"}, {"id": "b", "text": "Assume the task went well because the client is stable"}, {"id": "c", "text": "Follow up to confirm the task was done correctly"}, {"id": "d", "text": "Delegate the next walk to the UAP without review"}]'::jsonb, '["c"]', 'The RN can delegate but must supervise and follow up. Assuming the outcome or shifting responsibility to the UAP ignores that the RN stays accountable.'),
  ('delegation', 32, 'A UAP was assigned to obtain routine vital signs on a stable client. The client''s condition then becomes unstable. What is the RN''s best action?', '[{"id": "a", "text": "Ask the UAP to take vital signs more often and report"}, {"id": "b", "text": "Take over the care of the client personally"}, {"id": "c", "text": "Ask the LPN to monitor the client closely"}, {"id": "d", "text": "Leave the assignment as originally planned"}]'::jsonb, '["b"]', 'Unstable patients are RN only. The UAP and LPN may care only for stable patients, so changing the frequency or reassigning to the LPN is not appropriate.'),
  ('delegation', 33, 'The RN needs a UAP to monitor a stable client''s blood pressure. Which instruction best meets the right direction/communication?', '[{"id": "a", "text": "\"Check his blood pressure now and then today.\""}, {"id": "b", "text": "\"Let me know if anything about him seems off.\""}, {"id": "c", "text": "\"Keep an eye on his blood pressure as needed.\""}, {"id": "d", "text": "\"Take his blood pressure hourly; report if over 140.\""}]'::jsonb, '["d"]', 'Right direction/communication requires a clear and specific explanation, such as a set frequency and a value to report. The other instructions are vague and leave decisions to the UAP.'),
  ('delegation', 34, 'Which description best defines delegation in nursing?', '[{"id": "a", "text": "Assigning tasks to team members while staying accountable for the outcome"}, {"id": "b", "text": "Transferring accountability for the outcome to the person doing the task"}, {"id": "c", "text": "Assigning nursing judgment to the most experienced team member present"}, {"id": "d", "text": "Handing off any task the RN does not have time to finish on the shift"}]'::jsonb, '["a"]', 'Delegation assigns tasks to other team members while the delegator remains accountable for the outcome. Accountability and nursing judgment are not transferred.'),
  ('delegation', 35, 'The RN is supervising an LPN on a medical unit. Which task is appropriate for the RN to delegate to the LPN?', '[{"id": "a", "text": "Triaging a newly arrived client"}, {"id": "b", "text": "Collecting a sputum specimen from a stable client"}, {"id": "c", "text": "Administering a blood transfusion"}, {"id": "d", "text": "Teaching a newly diagnosed client"}]'::jsonb, '["b"]', 'Collecting specimens such as urine or sputum is an LPN task under RN supervision. Triage, blood products, and new teaching are never delegated.'),
  ('delegation', 36, 'A stable client has several medications due. Which medication task is appropriate for the RN to delegate to the LPN?', '[{"id": "a", "text": "Giving an IV push medication"}, {"id": "b", "text": "Hanging a unit of plasma"}, {"id": "c", "text": "Giving a scheduled subcutaneous injection"}, {"id": "d", "text": "Teaching about a new medication"}]'::jsonb, '["c"]', 'LPNs may give oral and some IM/SQ medications. IV medications and blood products are not LPN tasks, and new teaching stays with the RN.'),
  ('delegation', 37, 'The nurse is caring for a stable client after surgery. Which task is inappropriate to delegate to the UAP?', '[{"id": "a", "text": "Assessing the client''s surgical site"}, {"id": "b", "text": "Ambulating the client in the hallway"}, {"id": "c", "text": "Taking the client''s vital signs"}, {"id": "d", "text": "Assisting the client with bathing"}]'::jsonb, '["a"]', 'Assessing the surgical site is RN only because it requires assessment. Ambulation, stable vital signs, and bathing are UAP basic care.'),
  ('delegation', 38, 'The RN has an LPN on the team for the shift. Which client is most appropriate to assign to the LPN?', '[{"id": "a", "text": "A client in an acute condition"}, {"id": "b", "text": "A client with complex care needs"}, {"id": "c", "text": "A client whose condition is unstable"}, {"id": "d", "text": "A stable client who needs routine care"}]'::jsonb, '["d"]', 'Stable patients and routine activities may be delegated. Acute, complex, and unstable patients are on the not-delegate list.'),
  ('delegation', 39, 'The RN is planning vital sign checks for the shift. For which client is it appropriate to delegate vital signs to the UAP?', '[{"id": "a", "text": "A client reporting new-onset chest pain"}, {"id": "b", "text": "A stable client with a chronic condition"}, {"id": "c", "text": "A newly admitted client not yet assessed"}, {"id": "d", "text": "A client who has developed complications"}]'::jsonb, '["b"]', 'UAPs may take vital signs on stable patients. New-onset chest pain, unassessed new admissions, and clients with complications require the RN.'),
  ('delegation', 40, 'A UAP incorrectly performs a task the RN delegated. Which statement about accountability is accurate?', '[{"id": "a", "text": "The UAP alone is accountable for the outcome"}, {"id": "b", "text": "The RN remains accountable for the outcome"}, {"id": "c", "text": "The charge nurse is accountable for the outcome"}, {"id": "d", "text": "No one is accountable if the task was routine"}]'::jsonb, '["b"]', 'Tasks can be delegated, but responsibility is not; the RN is always accountable even after delegating. Accountability does not move to the UAP.'),
  ('delegation', 41, 'The charge nurse reviews the day''s delegated tasks. Which assignment requires correction?', '[{"id": "a", "text": "A UAP turning a stable client every 2 hours"}, {"id": "b", "text": "An LPN giving an enteral feed to a stable client"}, {"id": "c", "text": "A UAP feeding a client who has dysphagia"}, {"id": "d", "text": "An LPN changing a sterile dressing on a stable client"}]'::jsonb, '["c"]', 'UAPs may feed only non-dysphagia patients. Turning by the UAP and enteral feeds and sterile dressing changes by the LPN for stable clients are appropriate.'),
  ('delegation', 42, 'A client is admitted with a new diagnosis. Which responsibility belongs to the RN and should not be delegated?', '[{"id": "a", "text": "Recording the client''s intake and output"}, {"id": "b", "text": "Reinforcing teaching the RN already provided"}, {"id": "c", "text": "Helping the client with toileting"}, {"id": "d", "text": "Developing the client''s plan of care"}]'::jsonb, '["d"]', 'Care plans are never delegated and stay with the RN. Recording I&O and toileting are UAP tasks, and reinforcing teaching may be done by the LPN.'),
  ('delegation', 43, 'While the RN performs an admission assessment, several other tasks are pending. Which task should the RN delegate to the UAP?', '[{"id": "a", "text": "Changing the bed linens for a stable client"}, {"id": "b", "text": "Teaching a stable client about a new inhaler"}, {"id": "c", "text": "Giving a stable client an oral medication"}, {"id": "d", "text": "Triaging a client who just walked in"}]'::jsonb, '["a"]', 'Linen changes are basic UAP care. Teaching, medications, and triage are not UAP tasks.'),
  ('delegation', 44, 'A UAP reports that a client''s skin looks different than earlier in the shift. Which action requires the RN''s critical thinking and should not be delegated?', '[{"id": "a", "text": "Repositioning the client in bed"}, {"id": "b", "text": "Deciding if the provider must be notified"}, {"id": "c", "text": "Helping the client with a bed bath"}, {"id": "d", "text": "Recording the client''s oral intake"}]'::jsonb, '["b"]', 'Nursing judgment or critical thinking is never delegated, so deciding whether to report a change stays with the RN. Repositioning, bathing, and recording intake are UAP tasks.'),
  ('delegation', 45, 'A stable client needs a sterile dressing change. Which delegation is appropriate?', '[{"id": "a", "text": "Delegating the sterile dressing change to the UAP"}, {"id": "b", "text": "Delegating an oral medication to the UAP"}, {"id": "c", "text": "Delegating the sterile dressing change to the LPN"}, {"id": "d", "text": "Delegating a blood transfusion to the LPN"}]'::jsonb, '["c"]', 'Wound care and sterile dressing changes are LPN tasks under RN supervision. UAPs do basic care only and cannot give medications, and LPNs do not give blood.'),
  ('delegation', 46, 'A stable client is at risk for falls when getting out of bed. Which instruction from the RN to the UAP is appropriate?', '[{"id": "a", "text": "\"Teach the client how to use the new walker.\""}, {"id": "b", "text": "\"Assess the client''s balance before each walk.\""}, {"id": "c", "text": "\"Remind the client to call before getting up.\""}, {"id": "d", "text": "\"Decide whether the client may walk alone.\""}]'::jsonb, '["c"]', 'Remind is one of the keywords for tasks that may be delegated. Teaching, assessing, and deciding require nursing judgment and remain with the RN.'),
  ('delegation', 47, 'The RN is assigning clients for the shift. Which client should the RN care for rather than delegate?', '[{"id": "a", "text": "A stable client with a chronic condition"}, {"id": "b", "text": "A complex client with multiple problems"}, {"id": "c", "text": "A stable client needing routine care"}, {"id": "d", "text": "A stable client who needs help walking"}]'::jsonb, '["b"]', 'Complex patients are on the not-delegate list. Stable, chronic, and routine-care patients may be delegated.'),
  ('delegation', 48, 'An RN asks an LPN about the LPN role on the unit. Which statement by the LPN is accurate?', '[{"id": "a", "text": "\"I can do the initial assessment on new admissions.\""}, {"id": "b", "text": "\"I can hang blood if the client is stable.\""}, {"id": "c", "text": "\"I can teach clients about new diagnoses.\""}, {"id": "d", "text": "\"I can give oral medications to stable clients.\""}]'::jsonb, '["d"]', 'LPNs give oral medications to stable patients under RN supervision. Initial assessments, blood products, and initial teaching are not LPN tasks.'),
  ('delegation', 49, 'Which item may the RN delegate to another member of the health care team?', '[{"id": "a", "text": "A task"}, {"id": "b", "text": "Responsibility"}, {"id": "c", "text": "Nursing judgment"}, {"id": "d", "text": "Accountability"}]'::jsonb, '["a"]', 'The RN can delegate tasks but not responsibility or nursing judgment, and the RN remains accountable for the outcome.'),
  ('delegation', 50, 'A UAP asks the RN why some tasks, such as sterile dressing changes, are not assigned to UAPs. The RN explains that tasks delegated to UAPs should be which type?', '[{"id": "a", "text": "Routine, repetitive, and low-risk"}, {"id": "b", "text": "Complex but closely supervised"}, {"id": "c", "text": "Any task once it is demonstrated"}, {"id": "d", "text": "Quick tasks on unstable clients"}]'::jsonb, '["a"]', 'UAP tasks are routine, repetitive, and low-risk basic care. Complex care, unstable patients, and sterile dressing changes are not UAP tasks regardless of demonstration or supervision.'),
  ('scope', 1, 'A UAP reports that a client''s blood pressure is 190/110 mm Hg. What should the RN do first?', '[{"id": "a", "text": "Reassess the client''s blood pressure personally"}, {"id": "b", "text": "Ask the UAP to recheck the blood pressure in an hour"}, {"id": "c", "text": "Document the reading the UAP obtained"}, {"id": "d", "text": "Ask the LPN to recheck the blood pressure"}]'::jsonb, '["a"]', 'RNs must validate abnormal findings reported by UAPs, so the RN reassesses the blood pressure personally first. Delegating the recheck or documenting without validation does not meet this responsibility.'),
  ('scope', 2, 'A newly licensed nurse asks what determines a nurse''s scope of practice. Which factor is NOT one of the determinants?', '[{"id": "a", "text": "The nurse''s licensure level"}, {"id": "b", "text": "The state Nurse Practice Act"}, {"id": "c", "text": "Facility policies and procedures"}, {"id": "d", "text": "A client''s request for a specific nurse"}]'::jsonb, '["d"]', 'Scope of practice is based on licensure level, the state Nurse Practice Act, education and training, and facility policies and procedures. A client''s preference for a particular nurse does not define what a nurse may legally do.'),
  ('scope', 3, 'An RN is moving to a new state to work. Which source sets the state-specific legal rules for what the RN may do?', '[{"id": "a", "text": "The new hospital''s mission statement"}, {"id": "b", "text": "The state Nurse Practice Act"}, {"id": "c", "text": "The previous employer''s policy manual"}, {"id": "d", "text": "A current nursing textbook"}]'::jsonb, '["b"]', 'The state Nurse Practice Act (NPA) contains the state-specific legal rules that define scope. Policies from a former employer or a textbook do not set legal scope in the new state.'),
  ('scope', 4, 'An LPN asks the RN whether she may give IV push medications on the unit. What is the RN''s best response?', '[{"id": "a", "text": "\"Yes, LPNs give IV push medications the same as RNs.\""}, {"id": "b", "text": "\"Yes, as long as the client''s condition is stable.\""}, {"id": "c", "text": "\"Only if state law allows it and you have extra training.\""}, {"id": "d", "text": "\"No, an LPN may never give IV push medications.\""}]'::jsonb, '["c"]', 'LPNs may give IV push medications only in some states with extra training. It is not an automatic LPN task, but it is also not prohibited in every state.'),
  ('scope', 5, 'A stable client is prescribed a unit of packed red blood cells. An experienced LPN offers to start the transfusion. How should the RN respond?', '[{"id": "a", "text": "Accept, because the client is stable"}, {"id": "b", "text": "Accept, if the LPN has done it before"}, {"id": "c", "text": "Accept, if the RN checks the blood first"}, {"id": "d", "text": "Decline, because LPNs may not give blood"}]'::jsonb, '["d"]', 'Blood transfusion is an RN task and is not permitted for the LPN, regardless of stability or experience.'),
  ('scope', 6, 'The RN reviews the care an LPN provided during the shift. Which LPN action is outside the LPN''s scope of practice?', '[{"id": "a", "text": "Formulating a nursing diagnosis for a client"}, {"id": "b", "text": "Giving a scheduled oral medication"}, {"id": "c", "text": "Reinforcing teaching the RN completed"}, {"id": "d", "text": "Recording a stable client''s intake and output"}]'::jsonb, '["a"]', 'Only the RN can formulate a nursing diagnosis; the LPN cannot diagnose. Oral medications, reinforcing teaching, and collecting I&O data are within LPN scope.'),
  ('scope', 7, 'An LPN describes her role in care planning to a nursing student. Which statement by the LPN is accurate?', '[{"id": "a", "text": "\"I develop the care plan for my stable clients.\""}, {"id": "b", "text": "\"I may assist, but the RN develops the care plan.\""}, {"id": "c", "text": "\"I revise the care plan when a client''s condition changes.\""}, {"id": "d", "text": "\"I write the care plan once the RN assesses the client.\""}]'::jsonb, '["b"]', 'The LPN may assist but does not plan care; the RN develops the nursing care plan. Writing or revising the plan is outside LPN scope.'),
  ('scope', 8, 'While giving medications, an LPN notices that a client seems more restless than earlier in the shift. Which action is within the LPN''s scope of practice?', '[{"id": "a", "text": "Perform a comprehensive assessment of the client"}, {"id": "b", "text": "Formulate a new nursing diagnosis for the client"}, {"id": "c", "text": "Observe and report the finding to the RN"}, {"id": "d", "text": "Change the client''s care plan to address restlessness"}]'::jsonb, '["c"]', 'The LPN does no full assessments and may only observe and report. Comprehensive assessment, nursing diagnosis, and care plan changes belong to the RN.'),
  ('scope', 9, 'The charge nurse reviews tasks the RN assigned to a UAP. Which assignment requires correction?', '[{"id": "a", "text": "Assisting a stable client with dressing"}, {"id": "b", "text": "Ambulating a stable client in the hall"}, {"id": "c", "text": "Emptying a stable client''s Foley bag"}, {"id": "d", "text": "Assessing a stable client''s lung sounds"}]'::jsonb, '["d"]', 'A UAP cannot assess, so assessing lung sounds must be done by the RN. Dressing, ambulation, and emptying Foley bags are within UAP scope.'),
  ('scope', 10, 'A client with a new diagnosis of diabetes needs to learn insulin self-injection. Which team member should provide this teaching?', '[{"id": "a", "text": "The RN"}, {"id": "b", "text": "The LPN"}, {"id": "c", "text": "The UAP"}, {"id": "d", "text": "The LPN with the UAP"}]'::jsonb, '["a"]', 'The RN provides initial and complex teaching; the LPN can only reinforce material already taught, and the UAP does not teach. Teaching insulin injections is a task that should not be delegated to the UAP.'),
  ('scope', 11, 'A nursing student asks why initial teaching cannot be delegated to the LPN. What is the best explanation?', '[{"id": "a", "text": "The LPN is not allowed to speak to clients about medications"}, {"id": "b", "text": "The RN must assess learning needs and teaching effectiveness"}, {"id": "c", "text": "The client must sign a consent form for teaching"}, {"id": "d", "text": "Teaching takes too long to fit into the LPN''s assignment"}]'::jsonb, '["b"]', 'Initial or new teaching cannot be delegated because the RN must assess learning needs and effectiveness. Time constraints are not the reason teaching stays with the RN.'),
  ('scope', 12, 'The RN taught a stable client how to perform a dressing change yesterday. Which action by the LPN today is within the LPN''s scope of practice?', '[{"id": "a", "text": "Teaching the client a new medication schedule"}, {"id": "b", "text": "Deciding whether the teaching plan should change"}, {"id": "c", "text": "Reinforcing the dressing-change teaching from yesterday"}, {"id": "d", "text": "Evaluating whether the client is ready for discharge"}]'::jsonb, '["c"]', 'LPNs may reinforce teaching already done by the RN. New teaching, changes to the plan, and discharge decisions require the RN.'),
  ('scope', 13, 'An LPN is caring for several stable clients. Which medication-related task is within the LPN''s scope of practice?', '[{"id": "a", "text": "Hanging a unit of blood for a client"}, {"id": "b", "text": "Titrating a client''s continuous infusion"}, {"id": "c", "text": "Teaching a client about a new medication"}, {"id": "d", "text": "Applying a client''s topical medication"}]'::jsonb, '["d"]', 'LPNs may give oral, IM, SubQ, and topical medications. Blood, medication titration, and initial teaching remain RN responsibilities.'),
  ('scope', 14, 'Which task can the RN delegate to an LPN?', '[{"id": "a", "text": "Creating a nursing care plan for a new client"}, {"id": "b", "text": "Giving IM pain medication to a stable post-op client"}, {"id": "c", "text": "Triaging a client who arrived reporting pain"}, {"id": "d", "text": "Monitoring a post-op client who has become unstable"}]'::jsonb, '["b"]', 'Administering IM pain medications to a stable post-op patient is an appropriate LPN task. Creating a care plan, triage, and monitoring unstable patients are RN responsibilities.'),
  ('scope', 15, 'A client''s continuous medication infusion requires dose adjustments based on response. Who should perform the titration?', '[{"id": "a", "text": "The LPN, because the client is on the LPN''s assignment"}, {"id": "b", "text": "The UAP, after reporting the vital signs to the RN"}, {"id": "c", "text": "The RN, because titration is a complex skill"}, {"id": "d", "text": "The LPN, because titration is a routine task"}]'::jsonb, '["c"]', 'Medication titration is a complex skill that is RN only. It is not a routine task, and the UAP does not administer IV medications.'),
  ('scope', 16, 'The charge nurse reviews the day''s assignments. Which assignment requires correction?', '[{"id": "a", "text": "The LPN performs a simple sterile dressing change"}, {"id": "b", "text": "The UAP performs oral care for a stable client"}, {"id": "c", "text": "The RN performs a sterile procedure"}, {"id": "d", "text": "The UAP performs a sterile procedure"}]'::jsonb, '["d"]', 'UAPs do not perform sterile procedures; their hygiene care is non-sterile. LPNs may perform simple sterile procedures, and RNs may perform sterile procedures.'),
  ('scope', 17, 'An LPN has been caring for a stable client who suddenly becomes unstable. What should happen next?', '[{"id": "a", "text": "The RN takes over monitoring of the client"}, {"id": "b", "text": "The LPN continues care and reports at shift end"}, {"id": "c", "text": "The UAP is assigned to monitor vital signs"}, {"id": "d", "text": "The LPN monitors the client more often"}]'::jsonb, '["a"]', 'Monitoring unstable patients is an RN responsibility; the LPN cares for stable patients only. Increasing LPN or UAP monitoring does not keep the unstable client within scope.'),
  ('scope', 18, 'A student asks why the care of unstable or newly admitted clients cannot be delegated. Which explanation is correct?', '[{"id": "a", "text": "These clients need fewer tasks completed"}, {"id": "b", "text": "These clients must stay in a private room"}, {"id": "c", "text": "These clients have family members who give care"}, {"id": "d", "text": "The RN must monitor them due to unpredictable needs"}]'::jsonb, '["d"]', 'Unstable or new patients cannot be delegated because the RN must monitor them due to unpredictable needs.'),
  ('scope', 19, 'A UAP has finished morning care for a stable client. What may the UAP document in the client''s record?', '[{"id": "a", "text": "An assessment of the client''s surgical wound"}, {"id": "b", "text": "The client''s intake and output for the shift"}, {"id": "c", "text": "A nursing diagnosis based on the client''s mobility"}, {"id": "d", "text": "An evaluation of the client''s understanding of teaching"}]'::jsonb, '["b"]', 'UAPs can chart observations and I&O. Assessments, nursing diagnoses, and teaching evaluations are outside UAP scope.'),
  ('scope', 20, 'An outpatient clinic is staffed by an RN, an LPN, and a UAP. Several clients arrive at the same time with different complaints. Who should triage the clients?', '[{"id": "a", "text": "The LPN"}, {"id": "b", "text": "The UAP"}, {"id": "c", "text": "The RN"}, {"id": "d", "text": "The first available staff member"}]'::jsonb, '["c"]', 'Triage and clinical judgment are RN functions. Assessment and nursing judgment require critical thinking and are RN only, so triage is not given to the LPN or UAP.'),
  ('scope', 21, 'At the start of the shift, the charge nurse divides the unit''s clients among the nurses. This action is best described as which process?', '[{"id": "a", "text": "Delegation"}, {"id": "b", "text": "Assignment"}, {"id": "c", "text": "Supervision"}, {"id": "d", "text": "Triage"}]'::jsonb, '["b"]', 'Assignment is the distribution of routine care and workload, such as assigning patients. Delegation is transferring responsibility for a specific task while keeping accountability.'),
  ('scope', 22, 'Which statement best describes delegation?', '[{"id": "a", "text": "Distributing the unit''s clients among staff at the start of a shift"}, {"id": "b", "text": "Transferring accountability for an outcome to another team member"}, {"id": "c", "text": "Transferring responsibility, not accountability, for a task to another"}, {"id": "d", "text": "Handing over all nursing judgment to the most experienced staff"}]'::jsonb, '["c"]', 'Delegation is transferring responsibility, but not accountability, for a task to someone else. Distributing clients describes assignment.'),
  ('scope', 23, 'An LPN makes an error while performing a task the RN delegated. Which statement about the RN''s accountability is correct?', '[{"id": "a", "text": "The RN remains accountable for the outcome"}, {"id": "b", "text": "The RN is no longer accountable for the task"}, {"id": "c", "text": "Only the LPN is accountable for the outcome"}, {"id": "d", "text": "Accountability passed to the charge nurse"}]'::jsonb, '["a"]', 'The task may be delegated, but the RN remains accountable for the outcome. Delegation transfers responsibility for the task, not accountability.'),
  ('scope', 24, 'Before delegating a task, the RN confirms that the UAP has completed training for it. Which right of delegation is the RN applying?', '[{"id": "a", "text": "Right task"}, {"id": "b", "text": "Right circumstance"}, {"id": "c", "text": "Right direction/communication"}, {"id": "d", "text": "Right person"}]'::jsonb, '["d"]', 'Right person asks whether the delegatee is trained and qualified. Right circumstance asks whether the patient''s condition is stable.'),
  ('scope', 25, 'The RN will be off the unit at a long meeting and considers delegating a task to the UAP during that time. Which right of delegation is most in question?', '[{"id": "a", "text": "Right circumstance"}, {"id": "b", "text": "Right supervision/evaluation"}, {"id": "c", "text": "Right person"}, {"id": "d", "text": "Right task"}]'::jsonb, '["b"]', 'Right supervision/evaluation asks whether the nurse is available to monitor and evaluate. Being away from the unit limits the RN''s ability to supervise.'),
  ('scope', 26, 'Before asking the UAP to ambulate a client, the RN reviews the client''s latest vital signs and confirms the client''s condition is stable. Which right of delegation is the RN applying?', '[{"id": "a", "text": "Right direction/communication"}, {"id": "b", "text": "Right person"}, {"id": "c", "text": "Right circumstance"}, {"id": "d", "text": "Right supervision/evaluation"}]'::jsonb, '["c"]', 'Right circumstance asks whether the patient''s condition is stable. Right person concerns the delegatee''s training and qualifications.'),
  ('scope', 27, 'The RN tells the UAP exactly which stable client needs vital signs, at what time, and which result to report. Which right of delegation does this demonstrate?', '[{"id": "a", "text": "Right direction/communication"}, {"id": "b", "text": "Right task"}, {"id": "c", "text": "Right circumstance"}, {"id": "d", "text": "Right supervision/evaluation"}]'::jsonb, '["a"]', 'Right direction/communication means clear, specific instructions are provided. Supervision/evaluation refers to the nurse being available to monitor and evaluate.'),
  ('scope', 28, 'The RN uses the DELEGATE mnemonic before handing off a task. What does the first letter, D, ask the RN to consider?', '[{"id": "a", "text": "Does the delegatee want the task?"}, {"id": "b", "text": "Does the client prefer a certain staff member?"}, {"id": "c", "text": "Does the facility have enough staff today?"}, {"id": "d", "text": "Does the task require nursing judgment?"}]'::jsonb, '["d"]', 'In DELEGATE, D asks whether the task requires nursing judgment. Staff preference and client preference are not part of the mnemonic.'),
  ('scope', 29, 'The RN realizes she will be too busy to check back on a task she was about to delegate. Which DELEGATE consideration is not being met?', '[{"id": "a", "text": "Legal scope of the delegatee"}, {"id": "b", "text": "Time for supervision and follow-up"}, {"id": "c", "text": "Experience/education of the staff"}, {"id": "d", "text": "Evaluate the patient''s stability"}]'::jsonb, '["b"]', 'T in DELEGATE stands for time for supervision and follow-up. Without time to check back, the RN cannot supervise the delegated task.'),
  ('scope', 30, 'Before delegating, the RN checks the hospital''s written procedures to confirm that UAPs on the unit may perform the task. Which DELEGATE consideration is the RN applying?', '[{"id": "a", "text": "Ensure clear communication"}, {"id": "b", "text": "Evaluate the patient''s stability"}, {"id": "c", "text": "Guidelines/policies of facility"}, {"id": "d", "text": "Time for supervision and follow-up"}]'::jsonb, '["c"]', 'G in DELEGATE stands for guidelines/policies of the facility. Facility policies and procedures are also one of the factors that define scope of practice.'),
  ('scope', 31, 'The RN confirms that state law permits the LPN to perform a task before delegating it. Which DELEGATE consideration is the RN applying?', '[{"id": "a", "text": "Legal scope of the delegatee"}, {"id": "b", "text": "Ensure clear communication"}, {"id": "c", "text": "Time for supervision and follow-up"}, {"id": "d", "text": "Evaluate the patient''s stability"}]'::jsonb, '["a"]', 'L in DELEGATE stands for the legal scope of the delegatee. Clear communication and supervision time are separate considerations.'),
  ('scope', 32, 'A stable client needs blood glucose checks before meals. Which task is appropriate for the RN to delegate to the LPN?', '[{"id": "a", "text": "Formulating a nursing diagnosis for the client"}, {"id": "b", "text": "Triaging the client''s new complaint"}, {"id": "c", "text": "Hanging a unit of blood for the client"}, {"id": "d", "text": "Collecting the client''s blood glucose readings"}]'::jsonb, '["d"]', 'LPNs may collect data such as vitals, I&O, and blood glucose under RN supervision. Nursing diagnosis, triage, and blood transfusion are RN tasks.'),
  ('scope', 33, 'A stable client needs an ECG and a urinary catheter inserted. Which delegation is appropriate?', '[{"id": "a", "text": "The LPN performs the ECG and catheter insertion"}, {"id": "b", "text": "The UAP performs the catheter insertion"}, {"id": "c", "text": "The UAP plans the client''s catheter care"}, {"id": "d", "text": "The LPN develops the client''s care plan"}]'::jsonb, '["a"]', 'Performing an ECG and catheter insertion may be delegated to the LPN; catheter insertion is not listed among UAP tasks. Neither the UAP nor the LPN plans care.'),
  ('scope', 34, 'A stable client is on bed rest after a minor procedure. Which task is appropriate for the RN to delegate to the UAP?', '[{"id": "a", "text": "Assessing the client''s joint mobility"}, {"id": "b", "text": "Performing range-of-motion exercises"}, {"id": "c", "text": "Teaching the client leg exercises"}, {"id": "d", "text": "Planning the client''s activity goals"}]'::jsonb, '["b"]', 'Ambulation, repositioning, and range of motion (ROM) may be delegated to UAPs. Assessing, teaching, and planning are not UAP tasks.'),
  ('scope', 35, 'A stable client needs a stool specimen collected. Which team member may the RN ask to collect it?', '[{"id": "a", "text": "Only the RN"}, {"id": "b", "text": "Only the charge nurse"}, {"id": "c", "text": "The UAP"}, {"id": "d", "text": "Only the provider"}]'::jsonb, '["c"]', 'Specimen collection, such as urine or stool, may be delegated to UAPs. It does not have to be done by the RN.'),
  ('scope', 36, 'A stable client has an indwelling urinary catheter. Which task is appropriate for the UAP?', '[{"id": "a", "text": "Inserting a new urinary catheter"}, {"id": "b", "text": "Deciding whether the output is adequate"}, {"id": "c", "text": "Teaching the client about catheter care"}, {"id": "d", "text": "Emptying the Foley bag and recording the output"}]'::jsonb, '["d"]', 'UAPs may empty Foley bags and record I&O. Catheter insertion is an LPN or RN task, and interpreting output and teaching require the RN.'),
  ('scope', 37, 'The RN is organizing morning care for stable clients. Which task is appropriate to delegate to the UAP?', '[{"id": "a", "text": "Providing oral care to a client"}, {"id": "b", "text": "Performing a sterile dressing change"}, {"id": "c", "text": "Giving an IM medication to a client"}, {"id": "d", "text": "Reinforcing the RN''s diet teaching"}]'::jsonb, '["a"]', 'Non-sterile hygiene care such as oral care and toileting is a UAP task. Sterile dressing changes, IM medications, and reinforcing teaching are LPN tasks.'),
  ('scope', 38, 'Which task is within the scope of the LPN but not within the scope of the UAP?', '[{"id": "a", "text": "Assisting a client with bathing"}, {"id": "b", "text": "Performing a comprehensive assessment"}, {"id": "c", "text": "Giving a stable client an IM medication"}, {"id": "d", "text": "Administering a blood transfusion"}]'::jsonb, '["c"]', 'LPNs may give oral, IM, SubQ, and topical medications, while UAPs do not administer medications. Bathing is a UAP task, and comprehensive assessment and blood transfusion belong to the RN.'),
  ('scope', 39, 'A client needs an IV push medication. The LPN on the unit has not received extra training for this skill. Who should give the medication?', '[{"id": "a", "text": "The LPN, because the client is stable"}, {"id": "b", "text": "The RN, because IV pushes are an RN task"}, {"id": "c", "text": "The UAP, with the RN watching"}, {"id": "d", "text": "The LPN, with the RN signing afterward"}]'::jsonb, '["b"]', 'IV push medications are given by the RN; the LPN may do so only if trained and allowed by state law. Client stability or a co-signature does not make it an LPN task.'),
  ('scope', 40, 'The nurse educator reviews LPN scope with a group of new nurses. Which statement by a new nurse indicates a need for further teaching?', '[{"id": "a", "text": "\"LPNs can reinforce teaching the RN has done.\""}, {"id": "b", "text": "\"LPNs can give medications to stable clients.\""}, {"id": "c", "text": "\"LPNs can do simple wound care on stable clients.\""}, {"id": "d", "text": "\"LPNs can care for unstable clients if experienced.\""}]'::jsonb, '["d"]', 'LPNs care for stable patients only; unstable patients are an RN responsibility regardless of LPN experience. The other statements correctly describe LPN scope.'),
  ('scope', 41, 'A new RN discusses what may be delegated. Which statement by the new RN indicates a need for further teaching?', '[{"id": "a", "text": "\"I can delegate vital signs on stable clients to the UAP.\""}, {"id": "b", "text": "\"I can let the LPN use clinical judgment about my clients.\""}, {"id": "c", "text": "\"I should use the five rights before delegating a task.\""}, {"id": "d", "text": "\"I can delegate oral medications for stable clients to the LPN.\""}]'::jsonb, '["b"]', 'Clinical judgment is never delegated and stays with the RN. Delegating stable vital signs to the UAP, using the five rights, and delegating oral medications to the LPN are appropriate.'),
  ('scope', 42, 'A coworker asks an LPN to perform a procedure the LPN has never done and is unsure is permitted. Which principle should guide the LPN?', '[{"id": "a", "text": "The coworker becomes responsible if the LPN agrees"}, {"id": "b", "text": "Any task is acceptable if a coworker requests it"}, {"id": "c", "text": "Facility staffing needs override licensure level"}, {"id": "d", "text": "The LPN is responsible for knowing what she may legally do"}]'::jsonb, '["d"]', 'Each nurse is responsible for knowing what she can legally and ethically do in her role. A coworker''s request or staffing needs do not change scope of practice.'),
  ('scope', 43, 'The RN is considering delegating a task to a UAP who started on the unit today and has not yet been oriented to it. Which DELEGATE consideration is most relevant?', '[{"id": "a", "text": "Guidelines/policies of facility"}, {"id": "b", "text": "Experience/education of the staff"}, {"id": "c", "text": "Evaluate the patient''s stability"}, {"id": "d", "text": "Ensure clear communication"}]'::jsonb, '["b"]', 'One E in DELEGATE stands for the experience/education of the staff, which is the concern with a newly started UAP. Patient stability is a separate consideration.'),
  ('scope', 44, 'The RN is assigning tasks to a UAP. Which task is appropriate to delegate?', '[{"id": "a", "text": "Teaching a client how to perform insulin injections"}, {"id": "b", "text": "Measuring intake and output for a stable client"}, {"id": "c", "text": "Monitoring a client whose condition is unstable"}, {"id": "d", "text": "Formulating a nursing diagnosis for a client"}]'::jsonb, '["b"]', 'Measuring I&O for a stable patient is appropriate for the UAP. Teaching insulin injections, monitoring unstable clients, and nursing diagnosis are RN responsibilities.'),
  ('scope', 45, 'A client''s condition has changed, and the current plan of care no longer fits the client''s needs. Who should adjust the care plan?', '[{"id": "a", "text": "The LPN caring for the client"}, {"id": "b", "text": "The UAP who noticed the change"}, {"id": "c", "text": "The RN responsible for the client"}, {"id": "d", "text": "The LPN, with the UAP''s input"}]'::jsonb, '["c"]', 'Care plan creation and adjustment is an RN responsibility and cannot be delegated. The LPN may assist but does not plan care.'),
  ('scope', 46, 'A student asks why assessment cannot be delegated to the LPN or UAP. What is the best explanation?', '[{"id": "a", "text": "Assessment requires critical thinking, so it is RN only"}, {"id": "b", "text": "Assessment takes longer than other nursing tasks"}, {"id": "c", "text": "Assessment must be done by the provider first"}, {"id": "d", "text": "Assessment is done only once per shift"}]'::jsonb, '["a"]', 'Assessment or nursing judgment requires critical thinking and is RN only. Time required is not the reason it cannot be delegated.'),
  ('scope', 47, 'A stable client has a surgical incision that needs a simple sterile dressing change. Which team member may perform it?', '[{"id": "a", "text": "The UAP, with the RN present"}, {"id": "b", "text": "The UAP, after watching the RN"}, {"id": "c", "text": "Only the provider"}, {"id": "d", "text": "The LPN"}]'::jsonb, '["d"]', 'LPNs may perform wound care and sterile dressing changes, limited to simple sterile procedures. UAPs do not perform sterile procedures.'),
  ('scope', 48, 'A client has just been admitted to the medical unit from the emergency department. The RN has an LPN and a UAP available. Who should provide the client''s initial care?', '[{"id": "a", "text": "The RN"}, {"id": "b", "text": "The LPN"}, {"id": "c", "text": "The UAP"}, {"id": "d", "text": "The LPN with the UAP"}]'::jsonb, '["a"]', 'Unstable or new patients cannot be delegated because the RN must monitor them. The RN also performs the initial assessment.'),
  ('scope', 49, 'A UAP asks which clients she may help with bathing and dressing today. What is the RN''s best response?', '[{"id": "a", "text": "\"Any client, including those who are unstable.\""}, {"id": "b", "text": "\"Only clients who were admitted within the hour.\""}, {"id": "c", "text": "\"Clients whose condition is stable.\""}, {"id": "d", "text": "\"Only clients who need sterile procedures.\""}]'::jsonb, '["c"]', 'UAPs can assist with basic care tasks such as ADLs, vitals, and hygiene on stable patients. Unstable and new patients require the RN.'),
  ('scope', 50, 'Before delegating, the RN plans to give the UAP specific instructions about what to report. Which DELEGATE consideration does this reflect?', '[{"id": "a", "text": "Assign tasks only within capability"}, {"id": "b", "text": "Legal scope of the delegatee"}, {"id": "c", "text": "Time for supervision and follow-up"}, {"id": "d", "text": "Ensure clear communication"}]'::jsonb, '["d"]', 'The final E in DELEGATE stands for ensure clear communication. Legal scope and supervision time are separate considerations.'),
  ('cam', 1, 'A client who takes warfarin tells the nurse, "I started taking ginkgo biloba to help my memory." What should the nurse do?', '[{"id": "a", "text": "Tell the client this herb is safe because it is natural"}, {"id": "b", "text": "Inform the provider about the ginkgo use promptly"}, {"id": "c", "text": "Advise the client to double the warfarin dose"}, {"id": "d", "text": "Note the herb and review it at the next visit"}]'::jsonb, '["b"]', 'Ginkgo biloba increases bleeding risk when combined with warfarin, so the nurse should inform the provider immediately. Waiting until the next visit delays action on a known interaction.'),
  ('cam', 2, 'During an admission history, a client lists ginkgo biloba among home supplements. For which purpose does the nurse recognize this herb is commonly used?', '[{"id": "a", "text": "Treating depression"}, {"id": "b", "text": "Boosting energy"}, {"id": "c", "text": "Enhancing memory"}, {"id": "d", "text": "Promoting relaxation"}]'::jsonb, '["c"]', 'Ginkgo biloba is used for memory enhancement. Depression is the purpose of St. John''s Wort, and an energy boost is the purpose of ginseng.'),
  ('cam', 3, 'A client who takes daily aspirin asks the nurse whether it is safe to start ginkgo biloba. Which response by the nurse is best?', '[{"id": "a", "text": "\"Ginkgo can raise your blood pressure, so check it daily.\""}, {"id": "b", "text": "\"Ginkgo increases bleeding risk and should be avoided with aspirin.\""}, {"id": "c", "text": "\"Ginkgo may make your aspirin less effective at relieving pain.\""}, {"id": "d", "text": "\"Ginkgo is safe with aspirin because it is a plant product.\""}]'::jsonb, '["b"]', 'Ginkgo biloba carries a bleeding risk and should be avoided with warfarin and aspirin. Raising blood pressure is the risk associated with ginseng, not ginkgo.'),
  ('cam', 4, 'A client receiving warfarin reports using several complementary products at home. Which product is the priority concern for the nurse?', '[{"id": "a", "text": "Lavender essential oil"}, {"id": "b", "text": "Ginseng"}, {"id": "c", "text": "Ginkgo biloba"}, {"id": "d", "text": "A daily multivitamin"}]'::jsonb, '["c"]', 'Ginkgo biloba increases bleeding risk and should be avoided with warfarin. Ginseng''s listed risk is raising blood pressure, not a bleeding interaction with warfarin.'),
  ('cam', 5, 'A client tells the nurse about taking St. John''s Wort. For which condition does the nurse recognize this herb is commonly used?', '[{"id": "a", "text": "Depression"}, {"id": "b", "text": "Memory loss"}, {"id": "c", "text": "Low energy"}, {"id": "d", "text": "Muscle pain"}]'::jsonb, '["a"]', 'St. John''s Wort is used for depression. Memory enhancement is the purpose of ginkgo biloba, and an energy boost is the purpose of ginseng.'),
  ('cam', 6, 'A client who takes an oral contraceptive plans to begin St. John''s Wort. Which information should the nurse include in teaching?', '[{"id": "a", "text": "St. John''s Wort raises blood pressure"}, {"id": "b", "text": "St. John''s Wort increases bleeding risk"}, {"id": "c", "text": "St. John''s Wort can decrease the effect of birth control"}, {"id": "d", "text": "St. John''s Wort has no known drug interactions"}]'::jsonb, '["c"]', 'St. John''s Wort decreases the effect of many drugs, including birth control. Bleeding risk is linked to ginkgo biloba, and raised blood pressure to ginseng.'),
  ('cam', 7, 'The nurse has taught a client who uses birth control pills about St. John''s Wort. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will tell my provider I am taking St. John''s Wort.\""}, {"id": "b", "text": "\"St. John''s Wort may make my birth control less effective.\""}, {"id": "c", "text": "\"I should ask about interactions before starting any herb.\""}, {"id": "d", "text": "\"St. John''s Wort will not affect my birth control pills.\""}]'::jsonb, '["d"]', 'St. John''s Wort decreases the effect of many drugs, including birth control, so the belief that it has no effect needs correction. Telling the provider and checking interactions are correct.'),
  ('cam', 8, 'A client says, "I have been feeling tired, so a friend suggested an herb for more energy." Which herb does the nurse recognize is commonly used for this purpose?', '[{"id": "a", "text": "Ginkgo biloba"}, {"id": "b", "text": "Ginseng"}, {"id": "c", "text": "St. John''s Wort"}, {"id": "d", "text": "Lavender"}]'::jsonb, '["b"]', 'Ginseng is used as an energy boost. Ginkgo biloba is used for memory, St. John''s Wort for depression, and lavender for relaxation.'),
  ('cam', 9, 'A client with hypertension asks about several supplements. Which supplement should the nurse identify as a concern for this client?', '[{"id": "a", "text": "Ginseng"}, {"id": "b", "text": "Lavender oil"}, {"id": "c", "text": "A daily vitamin"}, {"id": "d", "text": "Ginkgo biloba"}]'::jsonb, '["a"]', 'Ginseng raises blood pressure, which is a concern for a client with hypertension. Ginkgo biloba''s listed risk is bleeding, not raised blood pressure.'),
  ('cam', 10, 'A client reports taking ginseng daily for energy. Which assessment is most important for the nurse to monitor in relation to this herb?', '[{"id": "a", "text": "Memory"}, {"id": "b", "text": "Mood"}, {"id": "c", "text": "Blood pressure"}, {"id": "d", "text": "Skin integrity"}]'::jsonb, '["c"]', 'The risk to know for ginseng is that it raises blood pressure. Memory relates to ginkgo biloba, and mood relates to St. John''s Wort.'),
  ('cam', 11, 'A client asks the nurse what to watch for before trying acupuncture. Which risk should the nurse discuss?', '[{"id": "a", "text": "Raised blood pressure"}, {"id": "b", "text": "Infection if needles are not sterile"}, {"id": "c", "text": "Decreased effect of birth control"}, {"id": "d", "text": "Injury if a fracture is present"}]'::jsonb, '["b"]', 'The risk to know for acupuncture is infection if needles are not sterile. Harm with fractures is the risk listed for massage, and raised blood pressure is listed for ginseng.'),
  ('cam', 12, 'A client with chronic pain plans to start acupuncture. The client asks what acupuncture is part of. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Ayurveda, the traditional Indian healing system\""}, {"id": "b", "text": "\"Energy therapy, like Reiki and therapeutic touch\""}, {"id": "c", "text": "\"Traditional Chinese Medicine, which also uses herbs and diet\""}, {"id": "d", "text": "\"Manipulative therapy, like chiropractic and massage\""}]'::jsonb, '["c"]', 'Traditional Chinese Medicine uses herbs, acupuncture (tiny needles), diet, and exercise. Ayurveda uses diet, yoga, herbs, and massage and is not described as using acupuncture.'),
  ('cam', 13, 'A client with a leg fracture asks the nurse for a massage to relieve pain. Which response by the nurse is appropriate?', '[{"id": "a", "text": "Arrange massage of the fractured leg right away"}, {"id": "b", "text": "Explain massage is unsafe with fractures and offer other pain relief"}, {"id": "c", "text": "Refuse the request and end the conversation"}, {"id": "d", "text": "Teach the client to gently massage the leg independently"}]'::jsonb, '["b"]', 'Massage is contraindicated with fractures because it can cause further injury, so the nurse explains this and offers alternative pain management. Simply refusing does not address the client''s pain.'),
  ('cam', 14, 'A client with a known bleeding disorder asks whether a massage could help with stress. Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"Massage is fine because it is a natural therapy.\""}, {"id": "b", "text": "\"Massage may be unsafe with a bleeding disorder.\""}, {"id": "c", "text": "\"Massage is only unsafe for people who take ginseng.\""}, {"id": "d", "text": "\"Massage is unsafe only if the needles are not sterile.\""}]'::jsonb, '["b"]', 'Therapies like massage are unsafe in fractures or bleeding disorders. Needle sterility is the risk associated with acupuncture, not massage.'),
  ('cam', 15, 'A client with osteoarthritis practices daily meditation along with the prescribed medications. How should the nurse classify this use of meditation?', '[{"id": "a", "text": "Alternative medicine"}, {"id": "b", "text": "Conventional medicine"}, {"id": "c", "text": "Emergency care"}, {"id": "d", "text": "Complementary medicine"}]'::jsonb, '["d"]', 'Complementary medicine is used along with, not instead of, regular medicine. Alternative medicine is used instead of regular medicine.'),
  ('cam', 16, 'A client has stopped all prescribed medications and now uses only herbal remedies to manage a chronic illness. How should the nurse classify this practice?', '[{"id": "a", "text": "Complementary medicine"}, {"id": "b", "text": "Alternative medicine"}, {"id": "c", "text": "Energy therapy"}, {"id": "d", "text": "Manipulative therapy"}]'::jsonb, '["b"]', 'Alternative medicine is used instead of regular medicine. Complementary medicine is used along with regular medicine, which is not the case here.'),
  ('cam', 17, 'A nurse is discussing CAM with colleagues. Which statement about how most clients use CAM is accurate?', '[{"id": "a", "text": "Most clients use CAM to replace regular medical care"}, {"id": "b", "text": "Most clients use CAM only during emergencies"}, {"id": "c", "text": "Most clients use CAM along with regular medical care"}, {"id": "d", "text": "Most clients stop CAM once they are hospitalized"}]'::jsonb, '["c"]', 'Most patients use CAM with regular care, not to replace it. Using CAM instead of regular care describes alternative medicine, which is not the usual pattern.'),
  ('cam', 18, 'A client with anxiety asks what meditation involves. Which description by the nurse is accurate?', '[{"id": "a", "text": "Quietly focusing the mind"}, {"id": "b", "text": "Slow, flowing movements"}, {"id": "c", "text": "Visualizing calming scenes"}, {"id": "d", "text": "Adjusting the spine and joints"}]'::jsonb, '["a"]', 'Meditation is quietly focusing the mind. Slow, flowing movements describe tai chi, and visualizing calming scenes describes guided imagery.'),
  ('cam', 19, 'A client asks how yoga differs from other mind-body therapies. Which description of yoga by the nurse is accurate?', '[{"id": "a", "text": "Slow, flowing movements without set postures"}, {"id": "b", "text": "Physical postures combined with breathing control"}, {"id": "c", "text": "Hand hovering over the body to direct energy"}, {"id": "d", "text": "Rubbing the muscles to promote relaxation"}]'::jsonb, '["b"]', 'Yoga combines physical postures with breathing control. Slow, flowing movements describe tai chi, and hand hovering describes Reiki.'),
  ('cam', 20, 'An older adult at a community center practices a therapy made up of slow, flowing movements. Which therapy is the client most likely practicing?', '[{"id": "a", "text": "Reiki"}, {"id": "b", "text": "Guided imagery"}, {"id": "c", "text": "Chiropractic care"}, {"id": "d", "text": "Tai chi"}]'::jsonb, '["d"]', 'Tai chi is described as slow, flowing movements. Guided imagery involves visualizing calming scenes, and Reiki is energy healing by hand hovering.'),
  ('cam', 21, 'Before a painful procedure, the nurse coaches a client to picture a quiet beach and the sound of waves. Which therapy is the nurse using?', '[{"id": "a", "text": "Meditation"}, {"id": "b", "text": "Therapeutic touch"}, {"id": "c", "text": "Guided imagery"}, {"id": "d", "text": "Aromatherapy"}]'::jsonb, '["c"]', 'Guided imagery involves visualizing calming scenes. Meditation is quietly focusing the mind, and aromatherapy uses essential oils.'),
  ('cam', 22, 'A client who has trouble relaxing at bedtime asks about aromatherapy. Which example should the nurse give?', '[{"id": "a", "text": "Ginseng tea to boost energy"}, {"id": "b", "text": "Lavender essential oil for relaxation"}, {"id": "c", "text": "Ginkgo biloba to improve memory"}, {"id": "d", "text": "Acupuncture needles to relieve pain"}]'::jsonb, '["b"]', 'Aromatherapy uses essential oils, such as lavender for relaxation. Ginseng and ginkgo are herbal supplements, a biologically based therapy.'),
  ('cam', 23, 'A client asks which group of CAM therapies focuses on the connection between the mind and body. Which therapies should the nurse list?', '[{"id": "a", "text": "Meditation, yoga, tai chi, and guided imagery"}, {"id": "b", "text": "Massage, chiropractic, and osteopathic care"}, {"id": "c", "text": "Reiki and therapeutic touch"}, {"id": "d", "text": "Herbal supplements, special diets, and vitamins"}]'::jsonb, '["a"]', 'Mind-body therapies include meditation, yoga, tai chi, guided imagery, and aromatherapy. Massage and chiropractic care are manipulative and body-based therapies.'),
  ('cam', 24, 'A client reports following a ketogenic diet as part of a personal wellness plan. In which CAM category does the nurse place this practice?', '[{"id": "a", "text": "Mind-body therapy"}, {"id": "b", "text": "Energy therapy"}, {"id": "c", "text": "Manipulative and body-based therapy"}, {"id": "d", "text": "Biologically based therapy"}]'::jsonb, '["d"]', 'Biologically based therapies use natural substances and include special diets such as the ketogenic diet. Energy therapies focus on body energy fields.'),
  ('cam', 25, 'A client takes vitamins, minerals, and herbal supplements daily. Which category of CAM is the client using?', '[{"id": "a", "text": "Biologically based therapies"}, {"id": "b", "text": "Mind-body therapies"}, {"id": "c", "text": "Energy therapies"}, {"id": "d", "text": "Whole medical systems"}]'::jsonb, '["a"]', 'Biologically based therapies use natural substances, including herbal supplements and vitamins/minerals. Mind-body therapies such as meditation and yoga do not involve ingested substances.'),
  ('cam', 26, 'A client with back pain visits a practitioner who adjusts the spine and joints. Which therapy is the client receiving?', '[{"id": "a", "text": "Reiki"}, {"id": "b", "text": "Chiropractic care"}, {"id": "c", "text": "Tai chi"}, {"id": "d", "text": "Therapeutic touch"}]'::jsonb, '["b"]', 'Chiropractic care involves adjusting the spine and joints. Reiki and therapeutic touch are energy therapies that use hand positions over the body.'),
  ('cam', 27, 'A client receives osteopathic manipulation for neck pain. In which CAM category does this therapy belong?', '[{"id": "a", "text": "Energy therapies"}, {"id": "b", "text": "Biologically based therapies"}, {"id": "c", "text": "Manipulative and body-based therapies"}, {"id": "d", "text": "Mind-body therapies"}]'::jsonb, '["c"]', 'Osteopathic manipulation, which moves muscles and bones, is a manipulative and body-based therapy that works on the body with the hands. Energy therapies focus on body energy fields.'),
  ('cam', 28, 'A client describes a session in which a practitioner hovered hands over the client''s body to promote energy healing. Which therapy did the client receive?', '[{"id": "a", "text": "Massage therapy"}, {"id": "b", "text": "Osteopathic manipulation"}, {"id": "c", "text": "Chiropractic care"}, {"id": "d", "text": "Reiki"}]'::jsonb, '["d"]', 'Reiki is energy healing by hand hovering. Massage, osteopathic manipulation, and chiropractic care work on the body with the hands.'),
  ('cam', 29, 'A nurse is explaining therapeutic touch to a client. Which description is accurate?', '[{"id": "a", "text": "Rubbing muscles to help them relax"}, {"id": "b", "text": "Moving hands over the body to direct energy"}, {"id": "c", "text": "Adjusting the spine and joints by hand"}, {"id": "d", "text": "Inserting tiny needles into the skin"}]'::jsonb, '["b"]', 'Therapeutic touch is moving the hands over the body to direct energy, making it an energy therapy. Rubbing muscles describes massage, and tiny needles describe acupuncture.'),
  ('cam', 30, 'A client with postoperative pain refuses the prescribed pain medication and asks for therapeutic touch instead. Which action should the nurse take?', '[{"id": "a", "text": "Insist that the client take the pain medication"}, {"id": "b", "text": "Tell the client that therapeutic touch is not effective"}, {"id": "c", "text": "Respect the choice, document it, and arrange therapeutic touch if available"}, {"id": "d", "text": "Give the pain medication without telling the client"}]'::jsonb, '["c"]', 'The nurse respects the patient''s choice, documents the request, and arranges therapeutic touch if available. Insisting on medication disregards the client''s right to use CAM.'),
  ('cam', 31, 'A client who declined pain medication has just received therapeutic touch for pain. What is the nurse''s next priority?', '[{"id": "a", "text": "Reassess the client''s pain regularly"}, {"id": "b", "text": "Discontinue all pain assessments"}, {"id": "c", "text": "Administer the declined pain medication"}, {"id": "d", "text": "Schedule massage therapy for the client"}]'::jsonb, '["a"]', 'After arranging therapeutic touch, the nurse should reassess pain regularly. Stopping pain assessment would leave the effectiveness of the therapy unevaluated.'),
  ('cam', 32, 'A client of Indian heritage describes a traditional healing system that uses diet, yoga, herbs, and massage to restore balance. Which system is the client describing?', '[{"id": "a", "text": "Traditional Chinese Medicine"}, {"id": "b", "text": "Reiki"}, {"id": "c", "text": "Chiropractic care"}, {"id": "d", "text": "Ayurveda"}]'::jsonb, '["d"]', 'Ayurveda is the Indian system that uses diet, yoga, herbs, and massage for balance. Traditional Chinese Medicine uses herbs, acupuncture, diet, and exercise.'),
  ('cam', 33, 'A client asks which CAM systems are considered whole medical systems. Which response by the nurse is accurate?', '[{"id": "a", "text": "Reiki and therapeutic touch"}, {"id": "b", "text": "Traditional Chinese Medicine and Ayurveda"}, {"id": "c", "text": "Massage and chiropractic care"}, {"id": "d", "text": "Yoga and guided imagery"}]'::jsonb, '["b"]', 'Whole medical systems are big traditional healing systems such as Traditional Chinese Medicine and Ayurveda. Reiki and therapeutic touch are energy therapies.'),
  ('cam', 34, 'A nurse is completing an admission interview. The client has not mentioned any CAM use. What should the nurse do?', '[{"id": "a", "text": "Assume the client does not use any CAM"}, {"id": "b", "text": "Ask the client about CAM use during the intake"}, {"id": "c", "text": "Wait until the client brings up CAM use"}, {"id": "d", "text": "Ask about CAM only if the client takes warfarin"}]'::jsonb, '["b"]', 'The nurse should assess CAM use during intake because many patients do not volunteer this information. Waiting for the client to mention it may miss important use.'),
  ('cam', 35, 'Which question should the nurse use to assess a client''s use of supplements?', '[{"id": "a", "text": "\"You don''t take any herbs, do you?\""}, {"id": "b", "text": "\"Do you take ginkgo biloba?\""}, {"id": "c", "text": "\"Are you taking anything you shouldn''t be?\""}, {"id": "d", "text": "\"What vitamins, herbs, or supplements do you take?\""}]'::jsonb, '["d"]', 'An open-ended question such as "What vitamins, herbs, or supplements do you take?" is recommended. Asking only about one herb or using a leading question limits the information obtained.'),
  ('cam', 36, 'A nurse overhears a colleague assessing a client''s CAM use. Which statement by the colleague requires correction?', '[{"id": "a", "text": "\"Those herbal remedies are a waste of money.\""}, {"id": "b", "text": "\"Can you tell me about any therapies you use at home?\""}, {"id": "c", "text": "\"I will add your supplements to your medical record.\""}, {"id": "d", "text": "\"I will check whether your herbs interact with your medicines.\""}]'::jsonb, '["a"]', 'CAM use should be asked about non-judgmentally because patients may hide CAM use if they fear judgment. Documenting supplements and checking interactions are appropriate actions.'),
  ('cam', 37, 'A client reports using lavender aromatherapy and tai chi. After discussing these practices, what should the nurse do with this information?', '[{"id": "a", "text": "Record it only if a drug interaction is found"}, {"id": "b", "text": "Share it verbally with the next nurse only"}, {"id": "c", "text": "Document all CAM use in the medical record"}, {"id": "d", "text": "Omit it because these therapies are not drugs"}]'::jsonb, '["c"]', 'All CAM use should be documented in the medical record because it is essential for a complete record and safety. Recording only when an interaction exists leaves the record incomplete.'),
  ('cam', 38, 'A client says, "Herbal supplements are sold in stores, so they are regulated the same way as my prescriptions." Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Herbal supplements are not FDA-regulated like prescription drugs.\""}, {"id": "b", "text": "\"Herbal supplements are regulated more strictly than prescription drugs.\""}, {"id": "c", "text": "\"Herbal supplements have the same FDA regulation as prescription drugs.\""}, {"id": "d", "text": "\"Herbal supplements are safe because they have no drug interactions.\""}]'::jsonb, '["a"]', 'Herbal supplements are NOT FDA-regulated like prescription drugs. Some herbs and supplements also interact with prescribed medicines, so claiming they have no interactions is incorrect.'),
  ('cam', 39, 'A client calls the clinic describing symptoms of a heart attack and says, "I will try my herbal remedy at home first and see if it helps." Which response by the nurse is best?', '[{"id": "a", "text": "\"Try the herbal remedy and call back in an hour.\""}, {"id": "b", "text": "\"Use the remedy along with some meditation at home.\""}, {"id": "c", "text": "\"Herbal remedies cannot replace emergency care; get help now.\""}, {"id": "d", "text": "\"Take a double dose of the herbal remedy right away.\""}]'::jsonb, '["c"]', 'CAM is not a substitute for emergency care such as for heart attacks. Delaying care to try a home remedy or meditation is unsafe.'),
  ('cam', 40, 'A client explains that a healing practice is part of the client''s family and spiritual traditions. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Discourage the practice because it is not evidence-based"}, {"id": "b", "text": "Respect the practice while ensuring it is safe"}, {"id": "c", "text": "Ignore the practice and focus on prescribed care"}, {"id": "d", "text": "Report the client for using unapproved therapy"}]'::jsonb, '["b"]', 'CAM is often tied to cultural and spiritual beliefs, so the nurse respects cultural practices while ensuring safe practices. Discouraging or ignoring the practice is judgmental.'),
  ('cam', 41, 'A client wants to continue an herbal supplement during hospitalization. Which action by the nurse best supports safe use alongside conventional care?', '[{"id": "a", "text": "Allow the client to take it without telling anyone"}, {"id": "b", "text": "Remove the supplement from the client''s room secretly"}, {"id": "c", "text": "Tell the client all supplements are banned in hospitals"}, {"id": "d", "text": "Collaborate with the provider about the supplement"}]'::jsonb, '["d"]', 'Collaborating with providers ensures safe integration of CAM with conventional care. Allowing undisclosed use bypasses interaction checks and documentation.'),
  ('cam', 42, 'A client starting several herbal products says, "They are natural, so they can''t hurt me." Why is it important for the nurse to provide teaching?', '[{"id": "a", "text": "Clients may not know about potential dangers"}, {"id": "b", "text": "Herbal products are always unsafe to use"}, {"id": "c", "text": "Clients must stop all CAM when ill"}, {"id": "d", "text": "Teaching is needed only for prescription drugs"}]'::jsonb, '["a"]', 'The nurse educates about risks because patients may not know about potential dangers. The nurse respects CAM choices within safety limits, so herbal products should not be presented as always unsafe.'),
  ('cam', 43, 'A nurse is using the memory trick "ASSESS-RESPECT-DOCUMENT" for CAM. Which set of actions matches this trick?', '[{"id": "a", "text": "Discourage CAM, refer the client, and record the refusal"}, {"id": "b", "text": "Ask about CAM, honor choices within safety limits, and chart CAM use"}, {"id": "c", "text": "Assess vital signs, respect privacy, and document pain"}, {"id": "d", "text": "Avoid CAM questions, respect silence, and document medications only"}]'::jsonb, '["b"]', 'ASSESS means always ask about CAM use, RESPECT means honor patient choices within safety limits, and DOCUMENT means record all CAM therapies in the chart. Discouraging CAM conflicts with respecting patient choices.'),
  ('cam', 44, 'A client taking several prescribed medications reports starting a new herbal supplement. Which nursing action is a priority?', '[{"id": "a", "text": "Tell the client to stop all prescribed medications"}, {"id": "b", "text": "Check for interactions between the herb and the medications"}, {"id": "c", "text": "Advise the client to take the herb at bedtime only"}, {"id": "d", "text": "Reassure the client that herbs do not affect medications"}]'::jsonb, '["b"]', 'The nurse checks for drug interactions because herbals can interfere with medications. Reassuring the client that herbs do not affect medications is incorrect.'),
  ('cam', 45, 'Which action by a nurse caring for a client who uses CAM requires correction?', '[{"id": "a", "text": "Asking about CAM use during the admission interview"}, {"id": "b", "text": "Asking about supplements in a non-judgmental way"}, {"id": "c", "text": "Teaching the client about supplement interactions"}, {"id": "d", "text": "Leaving CAM use out of the chart because it is not prescribed"}]'::jsonb, '["d"]', 'CAM use must be documented thoroughly because it is essential for a complete medical record and safety. Assessing, asking non-judgmentally, and teaching about interactions are correct actions.'),
  ('cam', 46, 'A client with muscle tension and no other health problems asks what massage therapy can do. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Massage is mainly used to enhance memory.\""}, {"id": "b", "text": "\"Massage is mainly used to boost energy.\""}, {"id": "c", "text": "\"Massage is used for relaxation and pain relief.\""}, {"id": "d", "text": "\"Massage is used to direct the body''s energy.\""}]'::jsonb, '["c"]', 'Massage is used for relaxation and pain relief by rubbing muscles. Directing body energy describes therapeutic touch, an energy therapy.'),
  ('cam', 47, 'A nurse is reviewing requests for massage therapy on a unit. Which client is the most appropriate candidate?', '[{"id": "a", "text": "A client with a recent leg fracture"}, {"id": "b", "text": "A client with a bleeding disorder"}, {"id": "c", "text": "A client with a fractured wrist in a cast"}, {"id": "d", "text": "A client with muscle tension and anxiety"}]'::jsonb, '["d"]', 'Massage is used for relaxation and pain relief, and is unsafe in fractures or bleeding disorders. The clients with fractures or a bleeding disorder are not safe candidates.'),
  ('cam', 48, 'A nurse is teaching a group about energy therapies. Which therapy should the nurse include as an example?', '[{"id": "a", "text": "Therapeutic touch"}, {"id": "b", "text": "Chiropractic care"}, {"id": "c", "text": "Osteopathic manipulation"}, {"id": "d", "text": "Guided imagery"}]'::jsonb, '["a"]', 'Energy therapies focus on body energy fields and include Reiki and therapeutic touch. Chiropractic care and osteopathic manipulation are manipulative and body-based therapies.'),
  ('cam', 49, 'A client asks the nurse which group of CAM therapies works on the body with the hands. Which therapies should the nurse name?', '[{"id": "a", "text": "Reiki and therapeutic touch"}, {"id": "b", "text": "Meditation and guided imagery"}, {"id": "c", "text": "Massage, chiropractic care, and osteopathic manipulation"}, {"id": "d", "text": "Herbal supplements and special diets"}]'::jsonb, '["c"]', 'Manipulative and body-based therapies work on the body with the hands and include massage, chiropractic care, and osteopathic manipulation. Reiki and therapeutic touch are energy therapies.'),
  ('cam', 50, 'A client who uses ginkgo biloba, ginseng, and St. John''s Wort asks why the nurse needs to know about them. Which response is most accurate?', '[{"id": "a", "text": "\"Some herbs interact with prescribed medicines.\""}, {"id": "b", "text": "\"Herbs are only recorded for billing purposes.\""}, {"id": "c", "text": "\"All herbs must be stopped before any treatment.\""}, {"id": "d", "text": "\"Herbs are tracked because they are always harmful.\""}]'::jsonb, '["a"]', 'Nurses ask about herbals because some herbs and supplements interact with prescribed medicines. CAM choices are respected, so stopping all herbs or calling them always harmful is incorrect.'),
  ('bmi', 1, 'A client weighs 200 lb and is 70 inches tall. Which BMI and weight category should the nurse document?', '[{"id": "a", "text": "28.7, obese"}, {"id": "b", "text": "28.7, overweight"}, {"id": "c", "text": "2,008.6, obese"}, {"id": "d", "text": "0.04, underweight"}]'::jsonb, '["b"]', '(200 × 703) ÷ (70 × 70) = 140,600 ÷ 4,900 = 28.7, which falls in the overweight range of 25–29.9. 2,008.6 results from dividing by height without squaring it.'),
  ('bmi', 2, 'A nurse measures a client at 120 lb and 64 inches tall. How should the nurse classify this client''s BMI?', '[{"id": "a", "text": "20.6, underweight"}, {"id": "b", "text": "1,318.1, obese"}, {"id": "c", "text": "20.6, overweight"}, {"id": "d", "text": "20.6, normal"}]'::jsonb, '["d"]', '(120 × 703) ÷ (64 × 64) = 84,360 ÷ 4,096 = 20.6, which is in the normal range of 18.5–24.9. 1,318.1 results from dividing by height without squaring it.'),
  ('bmi', 3, 'During an admission assessment, a client weighs 250 lb and is 68 inches tall. Which BMI classification is correct?', '[{"id": "a", "text": "38.0, obese class II"}, {"id": "b", "text": "38.0, obese class I"}, {"id": "c", "text": "38.0, morbidly obese"}, {"id": "d", "text": "2,584.6, morbidly obese"}]'::jsonb, '["a"]', '(250 × 703) ÷ (68 × 68) = 175,750 ÷ 4,624 = 38.0, which falls in obese class II (35–39.9). Class I ends at 34.9, and morbid obesity begins at 40.'),
  ('bmi', 4, 'A client who weighs 100 lb and is 62 inches tall attends a clinic visit. What is the client''s BMI category?', '[{"id": "a", "text": "18.3, normal"}, {"id": "b", "text": "1,133.9, obese"}, {"id": "c", "text": "18.3, underweight"}, {"id": "d", "text": "0.03, underweight"}]'::jsonb, '["c"]', '(100 × 703) ÷ (62 × 62) = 70,300 ÷ 3,844 = 18.3, which is less than 18.5 and therefore underweight. The normal range begins at 18.5.'),
  ('bmi', 5, 'A client weighs 300 lb and is 70 inches tall. Based on the client''s BMI, which nursing action is indicated?', '[{"id": "a", "text": "Encourage a 5-10% weight loss only"}, {"id": "b", "text": "Encourage a high-calorie diet"}, {"id": "c", "text": "Reinforce maintaining the current lifestyle"}, {"id": "d", "text": "Refer for bariatric surgery evaluation"}]'::jsonb, '["d"]', '(300 × 703) ÷ 4,900 = 43.0, which is morbidly obese (40 or more), so referral for bariatric surgery evaluation and intensive weight management is indicated. A 5-10% weight loss goal is the intervention listed for the overweight range.'),
  ('bmi', 6, 'A client is 67 inches tall and weighs 220 lb. Which BMI category applies to this client?', '[{"id": "a", "text": "Overweight"}, {"id": "b", "text": "Obese class I"}, {"id": "c", "text": "Obese class II"}, {"id": "d", "text": "Morbidly obese"}]'::jsonb, '["b"]', '(220 × 703) ÷ (67 × 67) = 154,660 ÷ 4,489 = 34.5, which falls in obese class I (30–34.9). Class II starts at 35.'),
  ('bmi', 7, 'A client who is 60 inches tall weighs 160 lb. The nurse calculates the BMI. Which result is correct?', '[{"id": "a", "text": "31.2"}, {"id": "b", "text": "2.7"}, {"id": "c", "text": "1,874.7"}, {"id": "d", "text": "0.04"}]'::jsonb, '["a"]', '(160 × 703) ÷ (60 × 60) = 112,480 ÷ 3,600 = 31.2. 0.04 results from omitting the 703 conversion factor, and 1,874.7 from not squaring the height.'),
  ('bmi', 8, 'A client weighs 140 lb and is 65 inches tall. The nurse calculates the client''s BMI. Which category should the nurse document?', '[{"id": "a", "text": "Underweight"}, {"id": "b", "text": "Overweight"}, {"id": "c", "text": "Normal"}, {"id": "d", "text": "Obese class I"}]'::jsonb, '["c"]', '(140 × 703) ÷ (65 × 65) = 98,420 ÷ 4,225 = 23.3, which is within the normal range of 18.5–24.9. Overweight begins at 25.'),
  ('bmi', 9, 'A client weighs 90 kg and is 1.75 m tall. Which BMI and category are correct?', '[{"id": "a", "text": "51.4, morbidly obese"}, {"id": "b", "text": "29.4, obese class I"}, {"id": "c", "text": "29.4, normal"}, {"id": "d", "text": "29.4, overweight"}]'::jsonb, '["d"]', '90 ÷ (1.75 × 1.75) = 90 ÷ 3.0625 = 29.4, which is overweight (25–29.9). 51.4 results from dividing by height without squaring it.'),
  ('bmi', 10, 'A client who is 1.70 m tall weighs 50 kg. Which BMI category should the nurse document?', '[{"id": "a", "text": "Normal"}, {"id": "b", "text": "Underweight"}, {"id": "c", "text": "Overweight"}, {"id": "d", "text": "Obese class I"}]'::jsonb, '["b"]', '50 ÷ (1.70 × 1.70) = 50 ÷ 2.89 = 17.3, which is below 18.5 and therefore underweight. Overweight would be chosen only if the height were not squared (50 ÷ 1.70 = 29.4).'),
  ('bmi', 11, 'A client weighs 110 kg and is 1.60 m tall. Which BMI should the nurse calculate?', '[{"id": "a", "text": "68.8"}, {"id": "b", "text": "30,207.0"}, {"id": "c", "text": "43.0"}, {"id": "d", "text": "34.4"}]'::jsonb, '["c"]', '110 ÷ (1.60 × 1.60) = 110 ÷ 2.56 = 43.0. 30,207.0 results from wrongly applying the U.S. conversion factor 703 to metric units, and 68.8 from not squaring the height.'),
  ('bmi', 12, 'A client weighs 72 kg and is 1.80 m tall. Which nursing intervention best matches this client''s BMI category?', '[{"id": "a", "text": "Encourage a high-calorie diet"}, {"id": "b", "text": "Encourage a 5-10% weight loss"}, {"id": "c", "text": "Screen for diabetes and hypertension"}, {"id": "d", "text": "Maintain a healthy lifestyle and exercise"}]'::jsonb, '["d"]', '72 ÷ (1.80 × 1.80) = 72 ÷ 3.24 = 22.2, a normal BMI, so the nurse encourages maintaining a healthy lifestyle, balanced diet, and regular exercise. A 5-10% weight loss is encouraged for the overweight range.'),
  ('bmi', 13, 'A client is 1.70 m tall and weighs 100 kg. Which classification is correct?', '[{"id": "a", "text": "Obese class I"}, {"id": "b", "text": "Overweight"}, {"id": "c", "text": "Obese class II"}, {"id": "d", "text": "Morbidly obese"}]'::jsonb, '["a"]', '100 ÷ (1.70 × 1.70) = 100 ÷ 2.89 = 34.6, which falls in obese class I (30–34.9). Class II begins at 35.'),
  ('bmi', 14, 'A client weighs 120 kg and is 1.75 m tall. Which BMI and category should the nurse document?', '[{"id": "a", "text": "68.6, morbidly obese"}, {"id": "b", "text": "39.2, morbidly obese"}, {"id": "c", "text": "39.2, obese class II"}, {"id": "d", "text": "39.2, obese class I"}]'::jsonb, '["c"]', '120 ÷ 3.0625 = 39.2, which falls in obese class II (35–39.9). Morbid obesity starts at a BMI of 40 or more.'),
  ('bmi', 15, 'A client weighs 58 kg and is 1.55 m tall. Which BMI and category should the nurse document?', '[{"id": "a", "text": "24.1, overweight"}, {"id": "b", "text": "24.1, normal"}, {"id": "c", "text": "37.4, obese class II"}, {"id": "d", "text": "24.1, underweight"}]'::jsonb, '["b"]', '58 ÷ (1.55 × 1.55) = 58 ÷ 2.4025 = 24.1, which is within the normal range of 18.5–24.9. 37.4 results from dividing by height without squaring it.'),
  ('bmi', 16, 'A client who weighs 45 kg and is 1.60 m tall has a BMI calculated by the nurse. Which follow-up assessment is most appropriate?', '[{"id": "a", "text": "Screen for eating disorders and malabsorption"}, {"id": "b", "text": "Screen for sleep apnea and joint problems"}, {"id": "c", "text": "Refer for bariatric surgery evaluation"}, {"id": "d", "text": "Encourage a 5-10% weight loss"}]'::jsonb, '["a"]', '45 ÷ 2.56 = 17.6, which is underweight, so the nurse assesses for eating disorders and malabsorption. Sleep apnea and joint problems are associated with obesity.'),
  ('bmi', 17, 'A nurse is calculating the BMI of a client whose weight is in pounds and height is in inches. Which formula should the nurse use?', '[{"id": "a", "text": "Weight × 703 ÷ height"}, {"id": "b", "text": "Weight × 703 ÷ (height × height)"}, {"id": "c", "text": "Weight ÷ (height × height)"}, {"id": "d", "text": "Height × height ÷ (weight × 703)"}]'::jsonb, '["b"]', 'In U.S. units, weight in pounds is multiplied by 703 and divided by height in inches squared. Omitting 703 is the metric formula, which is not used for pounds and inches.'),
  ('bmi', 18, 'A nurse is calculating BMI for a client measured in kilograms and meters. Which formula is correct?', '[{"id": "a", "text": "Weight × 703 ÷ (height × height)"}, {"id": "b", "text": "Weight ÷ (height × height)"}, {"id": "c", "text": "Weight ÷ height"}, {"id": "d", "text": "(Height × height) ÷ weight"}]'::jsonb, '["b"]', 'The metric formula divides weight in kilograms by height in meters squared. The 703 factor is used only for U.S. units.'),
  ('bmi', 19, 'A nursing student calculates the BMI of a client who weighs 68 kg and is 1.65 m tall by multiplying 68 by 703 before dividing by height squared. What should the instructor tell the student?', '[{"id": "a", "text": "703 is used only with pounds and inches"}, {"id": "b", "text": "703 should be used to divide, not multiply"}, {"id": "c", "text": "Height should not be squared in metric units"}, {"id": "d", "text": "Weight must first be converted to pounds"}]'::jsonb, '["a"]', '703 is the conversion factor for U.S. units only; the metric formula is weight in kilograms divided by height in meters squared. Height is squared in both formulas.'),
  ('bmi', 20, 'A nurse is calculating the BMI of a client who is 65 inches tall. Which value should the nurse use as the denominator?', '[{"id": "a", "text": "130"}, {"id": "b", "text": "65"}, {"id": "c", "text": "4,225"}, {"id": "d", "text": "45,695"}]'::jsonb, '["c"]', 'Height squared means height × height, so 65 × 65 = 4,225. 130 results from multiplying height by 2 instead of squaring it.'),
  ('bmi', 21, 'A nursing student calculates a BMI of 2,008.6 for a client who weighs 200 lb and is 70 inches tall. Which error did the student most likely make?', '[{"id": "a", "text": "Omitted the 703 conversion factor"}, {"id": "b", "text": "Used the metric formula"}, {"id": "c", "text": "Squared the weight instead of height"}, {"id": "d", "text": "Divided by height without squaring it"}]'::jsonb, '["d"]', '200 × 703 ÷ 70 = 2,008.6; the height must be squared (70 × 70 = 4,900), giving the correct BMI of 28.7. Omitting 703 would give a value near 0.04.'),
  ('bmi', 22, 'A client''s calculated BMI is 17.0. How should the nurse classify this result?', '[{"id": "a", "text": "Normal"}, {"id": "b", "text": "Overweight"}, {"id": "c", "text": "Obese class I"}, {"id": "d", "text": "Underweight"}]'::jsonb, '["d"]', 'A BMI less than 18.5 is classified as underweight. The normal range begins at 18.5.'),
  ('bmi', 23, 'A client''s BMI is exactly 18.5. Which category should the nurse document?', '[{"id": "a", "text": "Underweight"}, {"id": "b", "text": "Normal"}, {"id": "c", "text": "Overweight"}, {"id": "d", "text": "Obese class I"}]'::jsonb, '["b"]', 'The normal range is 18.5–24.9, so a BMI of 18.5 is normal. Underweight applies only to values less than 18.5.'),
  ('bmi', 24, 'A client with a BMI of 27 asks what this number means. Which response by the nurse is correct?', '[{"id": "a", "text": "Your BMI is in the overweight range."}, {"id": "b", "text": "Your BMI is in the normal range."}, {"id": "c", "text": "Your BMI is in the obese range."}, {"id": "d", "text": "Your BMI is in the underweight range."}]'::jsonb, '["a"]', 'A BMI of 25–29.9 is classified as overweight. Obesity begins at a BMI of 30.'),
  ('bmi', 25, 'A client''s BMI is exactly 30. Which statement by the nurse is accurate?', '[{"id": "a", "text": "This BMI is in the overweight range."}, {"id": "b", "text": "This BMI is in the morbidly obese range."}, {"id": "c", "text": "This BMI is in the obese range."}, {"id": "d", "text": "This BMI is in the normal range."}]'::jsonb, '["c"]', 'A BMI of 30 or greater is obese (class I is 30–34.9). The overweight range ends at 29.9.'),
  ('bmi', 26, 'A client has a BMI of 36. Which health risk level should the nurse associate with this BMI?', '[{"id": "a", "text": "Lowest health risk"}, {"id": "b", "text": "Very high risk for comorbidities"}, {"id": "c", "text": "Increased risk for chronic diseases"}, {"id": "d", "text": "Extremely high risk; may need surgery"}]'::jsonb, '["b"]', 'A BMI of 36 is obese class II (35–39.9), which carries a very high risk for comorbidities. Extremely high risk with possible surgery applies to a BMI of 40 or more.'),
  ('bmi', 27, 'A nurse is reviewing four clients'' BMI values. Which client should the nurse identify as meeting the criteria for morbid obesity?', '[{"id": "a", "text": "BMI of 34"}, {"id": "b", "text": "BMI of 38"}, {"id": "c", "text": "BMI of 29"}, {"id": "d", "text": "BMI of 41"}]'::jsonb, '["d"]', 'Morbid obesity (class III) is a BMI of 40 or more, so only the client with a BMI of 41 qualifies. A BMI of 38 is obese class II.'),
  ('bmi', 28, 'A client with a BMI of 32 asks which health problems this BMI places him at high risk for. Which response is most accurate?', '[{"id": "a", "text": "Diabetes and hypertension"}, {"id": "b", "text": "Malnutrition and weak immunity"}, {"id": "c", "text": "Anemia and osteoporosis"}, {"id": "d", "text": "No added weight-related risk"}]'::jsonb, '["a"]', 'Obese class I (30–34.9) carries a high risk for diabetes and hypertension. Malnutrition and weak immunity are risks of being underweight.'),
  ('bmi', 29, 'A client has a BMI of 16.8. Which conditions should the nurse recognize this client is at risk for?', '[{"id": "a", "text": "Sleep apnea and joint problems"}, {"id": "b", "text": "Pre-diabetes and elevated cholesterol"}, {"id": "c", "text": "Anemia and osteoporosis"}, {"id": "d", "text": "Stroke and heart disease"}]'::jsonb, '["c"]', 'A BMI under 18.5 is underweight and is associated with malnutrition, anemia, osteoporosis, and weakened immunity. Sleep apnea and joint problems are associated with obesity.'),
  ('bmi', 30, 'A client with a BMI of 22 asks how her weight affects her health. Which response by the nurse is accurate?', '[{"id": "a", "text": "You have an increased risk for chronic diseases."}, {"id": "b", "text": "You have the lowest risk for weight-related problems."}, {"id": "c", "text": "You have a high risk for diabetes and hypertension."}, {"id": "d", "text": "You have a risk for malnutrition and weak immunity."}]'::jsonb, '["b"]', 'A normal BMI (18.5–24.9) carries the lowest risk for weight-related health problems. Increased risk for chronic diseases applies to the overweight range.'),
  ('bmi', 31, 'A client with a BMI of 26 asks whether this weight affects long-term health. Which response by the nurse is accurate?', '[{"id": "a", "text": "This BMI carries the lowest health risk."}, {"id": "b", "text": "This BMI carries a risk of malnutrition."}, {"id": "c", "text": "This BMI increases your risk for chronic diseases."}, {"id": "d", "text": "This BMI means you may need surgery."}]'::jsonb, '["c"]', 'A BMI of 25–29.9 is overweight, which carries an increased risk for chronic diseases. The lowest health risk applies to the normal range of 18.5–24.9.'),
  ('bmi', 32, 'A client''s BMI is 27.5. Which conditions should the nurse plan to assess for, based on this BMI category?', '[{"id": "a", "text": "Malnutrition and weakened immunity"}, {"id": "b", "text": "Anemia and osteoporosis"}, {"id": "c", "text": "Reduced life expectancy"}, {"id": "d", "text": "Pre-diabetes and elevated cholesterol"}]'::jsonb, '["d"]', 'The overweight range (25–29.9) is associated with pre-diabetes, hypertension, and elevated cholesterol. Malnutrition and weakened immunity are associated with being underweight.'),
  ('bmi', 33, 'A nurse is caring for a client with a BMI of 33. Which condition is associated with this client''s BMI category?', '[{"id": "a", "text": "Osteoporosis"}, {"id": "b", "text": "Sleep apnea"}, {"id": "c", "text": "Anemia"}, {"id": "d", "text": "Malnutrition"}]'::jsonb, '["b"]', 'Obesity (BMI 30 or higher) is associated with type 2 diabetes, heart disease, stroke, sleep apnea, and joint problems. Osteoporosis, anemia, and malnutrition are associated with being underweight.'),
  ('bmi', 34, 'A client with a BMI of 44 asks about long-term effects of this weight. Which statement by the nurse is accurate?', '[{"id": "a", "text": "This BMI carries the lowest health risk."}, {"id": "b", "text": "This BMI is linked to malnutrition and anemia."}, {"id": "c", "text": "This BMI is linked to reduced life expectancy."}, {"id": "d", "text": "This BMI is linked mainly to pre-diabetes."}]'::jsonb, '["c"]', 'A BMI of 40 or more (morbidly obese) is associated with severe chronic conditions and reduced life expectancy. Pre-diabetes is listed for the overweight range.'),
  ('bmi', 35, 'A nurse is planning care for a client with a BMI of 17.2. Which intervention is most appropriate?', '[{"id": "a", "text": "Encourage a high-calorie diet and monitor weight"}, {"id": "b", "text": "Encourage a 5-10% weight loss with exercise"}, {"id": "c", "text": "Refer for bariatric surgery evaluation"}, {"id": "d", "text": "Begin comprehensive weight management"}]'::jsonb, '["a"]', 'For an underweight client (BMI under 18.5), the nurse assesses nutrition, encourages a high-calorie diet, and monitors weight. Weight loss interventions are for overweight and obese clients.'),
  ('bmi', 36, 'A client with a BMI of 28 asks how much weight to aim to lose at first. Which goal should the nurse encourage?', '[{"id": "a", "text": "40-50% of body weight"}, {"id": "b", "text": "25-30% of body weight"}, {"id": "c", "text": "1-2% of body weight"}, {"id": "d", "text": "5-10% of body weight"}]'::jsonb, '["d"]', 'For overweight clients (BMI 25–29.9), the nurse encourages a 5-10% weight loss along with diet modification and exercise.'),
  ('bmi', 37, 'A client who weighs 200 lb has a BMI of 28. The nurse encourages weight loss within the recommended range. Which target amount of weight loss is appropriate?', '[{"id": "a", "text": "2 to 4 lb"}, {"id": "b", "text": "50 to 60 lb"}, {"id": "c", "text": "10 to 20 lb"}, {"id": "d", "text": "80 to 100 lb"}]'::jsonb, '["c"]', 'The overweight range calls for a 5-10% weight loss; 5-10% of 200 lb is 10 to 20 lb. 2 to 4 lb would be only 1-2% of body weight.'),
  ('bmi', 38, 'A nurse is planning care for a client with a BMI of 31. Which intervention best fits this client''s BMI category?', '[{"id": "a", "text": "Encourage a high-calorie diet"}, {"id": "b", "text": "Comprehensive weight management and lifestyle changes"}, {"id": "c", "text": "Maintenance of the current lifestyle"}, {"id": "d", "text": "Assessment for malabsorption"}]'::jsonb, '["b"]', 'For obesity (BMI 30 or more), interventions include comprehensive weight management, lifestyle changes, and possible medication. A high-calorie diet is for underweight clients.'),
  ('bmi', 39, 'A newly admitted client has a BMI of 34. Which screening should the nurse anticipate?', '[{"id": "a", "text": "Diabetes, hypertension, and high cholesterol"}, {"id": "b", "text": "Eating disorders and malabsorption"}, {"id": "c", "text": "Anemia and osteoporosis"}, {"id": "d", "text": "Bariatric surgery eligibility only"}]'::jsonb, '["a"]', 'A BMI of 30 or more (obese) calls for screening for diabetes, hypertension, and high cholesterol. Screening for eating disorders and malabsorption applies to underweight clients.'),
  ('bmi', 40, 'A nurse is reviewing four clients'' BMI values. Which client should the nurse identify as possibly qualifying for bariatric surgery?', '[{"id": "a", "text": "BMI of 26"}, {"id": "b", "text": "BMI of 33"}, {"id": "c", "text": "BMI of 37"}, {"id": "d", "text": "BMI of 42"}]'::jsonb, '["d"]', 'A BMI of 40 or more (morbidly obese) may qualify a client for bariatric surgery. A BMI of 37 is obese class II, not morbid obesity.'),
  ('bmi', 41, 'A client with a BMI of 45 is being discharged from the clinic. Which referral is most appropriate?', '[{"id": "a", "text": "Nutrition referral for a high-calorie diet"}, {"id": "b", "text": "Eating disorder evaluation"}, {"id": "c", "text": "Bariatric surgery evaluation"}, {"id": "d", "text": "No referral; maintain current lifestyle"}]'::jsonb, '["c"]', 'A BMI of 40 or more warrants consideration of a bariatric surgery referral and intensive weight management. A high-calorie diet and eating disorder evaluation apply to underweight clients.'),
  ('bmi', 42, 'A nurse is teaching a client about body mass index. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "BMI screens for weight status."}, {"id": "b", "text": "BMI can be calculated with metric units."}, {"id": "c", "text": "BMI is linked to risk for chronic disease."}, {"id": "d", "text": "BMI diagnoses my health condition."}]'::jsonb, '["d"]', 'BMI is a screening tool, not a diagnostic test, so the client''s statement that it diagnoses a condition needs correction. The other statements are accurate.'),
  ('bmi', 43, 'A muscular college athlete has a BMI of 29 and asks if this means he has too much body fat. Which response by the nurse is best?', '[{"id": "a", "text": "BMI does not account for muscle mass."}, {"id": "b", "text": "BMI of 29 confirms excess body fat."}, {"id": "c", "text": "BMI is the best measure of body fat."}, {"id": "d", "text": "BMI is only valid for women."}]'::jsonb, '["a"]', 'A limitation of BMI is that it does not account for muscle mass, so athletes may have a high BMI but low fat. Stating that the BMI confirms excess fat ignores this limitation.'),
  ('bmi', 44, 'A nurse is measuring waist circumference during a health screening. Which female client has a waist measurement indicating increased risk?', '[{"id": "a", "text": "Waist of 30 inches"}, {"id": "b", "text": "Waist of 33 inches"}, {"id": "c", "text": "Waist of 37 inches"}, {"id": "d", "text": "Waist of 35 inches"}]'::jsonb, '["c"]', 'For women, a waist circumference greater than 35 inches indicates increased risk, so 37 inches qualifies. A waist of exactly 35 inches is not greater than 35.'),
  ('bmi', 45, 'A nurse is measuring waist circumference for male clients at a health fair. Which client''s measurement indicates increased risk?', '[{"id": "a", "text": "Waist of 42 inches"}, {"id": "b", "text": "Waist of 38 inches"}, {"id": "c", "text": "Waist of 36 inches"}, {"id": "d", "text": "Waist of 40 inches"}]'::jsonb, '["a"]', 'For men, a waist circumference greater than 40 inches indicates increased risk, so only 42 inches qualifies. A waist of exactly 40 inches is not greater than 40.'),
  ('bmi', 46, 'A woman with a BMI of 23 has a waist circumference of 38 inches. She says her weight is not a concern because her BMI is normal. How should the nurse respond?', '[{"id": "a", "text": "Agree, because a normal BMI rules out any weight-related risk"}, {"id": "b", "text": "Explain that her waist size also indicates increased risk"}, {"id": "c", "text": "Explain that her BMI places her in the overweight range"}, {"id": "d", "text": "Agree, because waist size matters only for men"}]'::jsonb, '["b"]', 'Waist circumference is important in addition to BMI, and a waist greater than 35 inches in women indicates increased risk. A BMI of 23 is normal, not overweight.'),
  ('bmi', 47, 'A nurse is reviewing the BMI cut-off values with a student. Which set lists the correct lower limits for normal, overweight, obese class I, obese class II, and morbid obesity?', '[{"id": "a", "text": "18.5, 25, 30, 35, 40"}, {"id": "b", "text": "18, 24, 29, 34, 39"}, {"id": "c", "text": "18.5, 26, 31, 36, 41"}, {"id": "d", "text": "20, 25, 30, 35, 45"}]'::jsonb, '["a"]', 'Normal begins at 18.5, overweight at 25, obese class I at 30, class II at 35, and morbid obesity (class III) at 40. The other sets shift one or more cut-offs.'),
  ('bmi', 48, 'A nurse is reviewing four clients'' BMI values to prioritize screening for diabetes, hypertension, and high cholesterol. Which client should be screened?', '[{"id": "a", "text": "BMI of 19"}, {"id": "b", "text": "BMI of 24"}, {"id": "c", "text": "BMI of 17"}, {"id": "d", "text": "BMI of 31"}]'::jsonb, '["d"]', 'A BMI of 30 or more (obese) indicates the need to screen for diabetes, hypertension, and high cholesterol. BMIs of 19 and 24 are normal, and 17 is underweight.'),
  ('bmi', 49, 'A client''s BMI decreased from 31.5 to 28.8 over six months of a weight management program. How should the nurse evaluate this change?', '[{"id": "a", "text": "The client moved from obese to overweight."}, {"id": "b", "text": "The client moved from overweight to normal."}, {"id": "c", "text": "The client remains in the obese class I range."}, {"id": "d", "text": "The client moved from obese class II to class I."}]'::jsonb, '["a"]', 'A BMI of 31.5 is obese class I (30–34.9), and 28.8 is overweight (25–29.9), so the client has moved from obese to overweight. Normal does not begin until below 25.'),
  ('bmi', 50, 'An underweight client receiving nutritional care has a BMI that increased from 17.4 to 19.2. How should the nurse evaluate this outcome?', '[{"id": "a", "text": "The client is still underweight."}, {"id": "b", "text": "The client is now overweight."}, {"id": "c", "text": "The client is now in the normal range."}, {"id": "d", "text": "The client is now obese class I."}]'::jsonb, '["c"]', 'A BMI of 19.2 falls within the normal range of 18.5–24.9, so the client has moved from underweight to normal. Underweight applies only below 18.5.'),
  ('calculations', 1, 'A nurse is to infuse 1,000 mL of normal saline over 8 hours by gravity. The drop factor on the tubing is 15 gtt/mL. At what rate should the nurse set the infusion?', '[{"id": "a", "text": "2 gtt/min"}, {"id": "b", "text": "125 gtt/min"}, {"id": "c", "text": "31 gtt/min"}, {"id": "d", "text": "1,875 gtt/min"}]'::jsonb, '["c"]', 'Convert 8 hours to 480 minutes, then (1,000 × 15) ÷ 480 = 31.25, which rounds to 31 gtt/min. 1,875 gtt/min results from dividing by 8 hours instead of 480 minutes.'),
  ('calculations', 2, 'A client is prescribed 500 mL of IV fluid to infuse over 4 hours by gravity drip using tubing with a drop factor of 20 gtt/mL. Which drip rate should the nurse set?', '[{"id": "a", "text": "125 gtt/min"}, {"id": "b", "text": "42 gtt/min"}, {"id": "c", "text": "41 gtt/min"}, {"id": "d", "text": "2,500 gtt/min"}]'::jsonb, '["b"]', '4 hours = 240 minutes; (500 × 20) ÷ 240 = 41.67, which rounds to the nearest whole number, 42 gtt/min. 41 gtt/min drops the decimal instead of rounding to the nearest whole number.'),
  ('calculations', 3, 'A nurse is preparing a gravity infusion of 1,000 mL over 6 hours using macrodrip tubing labeled 10 gtt/mL. What drip rate should the nurse calculate?', '[{"id": "a", "text": "28 gtt/min"}, {"id": "b", "text": "167 gtt/min"}, {"id": "c", "text": "27 gtt/min"}, {"id": "d", "text": "1,667 gtt/min"}]'::jsonb, '["a"]', '6 hours × 60 = 360 minutes; (1,000 × 10) ÷ 360 = 27.78, rounded to 28 gtt/min. 1,667 gtt/min comes from dividing by 6 hours without converting to minutes.'),
  ('calculations', 4, 'A child is to receive 100 mL of IV fluid over 1 hour by gravity using microdrip tubing. Which drip rate should the nurse set?', '[{"id": "a", "text": "25 gtt/min"}, {"id": "b", "text": "100 gtt/min"}, {"id": "c", "text": "2 gtt/min"}, {"id": "d", "text": "6,000 gtt/min"}]'::jsonb, '["b"]', 'Microdrip tubing delivers 60 gtt/mL, so (100 × 60) ÷ 60 minutes = 100 gtt/min. 25 gtt/min would result from using a macrodrip factor of 15 gtt/mL instead of 60 gtt/mL.'),
  ('calculations', 5, 'A nurse in a critical care unit must infuse 250 mL over 3 hours by gravity using microdrip tubing. What is the correct drip rate?', '[{"id": "a", "text": "83 gtt/min"}, {"id": "b", "text": "84 gtt/min"}, {"id": "c", "text": "21 gtt/min"}, {"id": "d", "text": "5,000 gtt/min"}]'::jsonb, '["a"]', '3 hours = 180 minutes; (250 × 60) ÷ 180 = 83.33, which rounds to 83 gtt/min. 21 gtt/min results from using 15 gtt/mL instead of the microdrip factor of 60 gtt/mL.'),
  ('calculations', 6, 'An adult client is prescribed 1,200 mL of IV fluid over 10 hours. The infusion will run by gravity with tubing that has a drop factor of 15 gtt/mL. What rate should the nurse set?', '[{"id": "a", "text": "1,800 gtt/min"}, {"id": "b", "text": "40 gtt/min"}, {"id": "c", "text": "120 gtt/min"}, {"id": "d", "text": "30 gtt/min"}]'::jsonb, '["d"]', '10 hours = 600 minutes; (1,200 × 15) ÷ 600 = 30 gtt/min. 40 gtt/min results from using a drop factor of 20 instead of the 15 gtt/mL on the tubing.'),
  ('calculations', 7, 'A nurse must infuse 100 mL of an IV antibiotic over 30 minutes by gravity using tubing with a drop factor of 10 gtt/mL. Which drip rate is correct?', '[{"id": "a", "text": "33 gtt/min"}, {"id": "b", "text": "3 gtt/min"}, {"id": "c", "text": "1 gtt/min"}, {"id": "d", "text": "50 gtt/min"}]'::jsonb, '["a"]', 'The time is already in minutes, so (100 × 10) ÷ 30 = 33.33, rounded to 33 gtt/min. 1 gtt/min results from wrongly multiplying 30 minutes by 60 as if it were hours.'),
  ('calculations', 8, 'A nurse is to give 50 mL of IV fluid over 20 minutes by gravity. The tubing drop factor is 20 gtt/mL. What drip rate should the nurse use?', '[{"id": "a", "text": "50 gtt/min"}, {"id": "b", "text": "1 gtt/min"}, {"id": "c", "text": "150 gtt/min"}, {"id": "d", "text": "25 gtt/min"}]'::jsonb, '["a"]', '(50 × 20) ÷ 20 minutes = 50 gtt/min. 150 gtt/min uses the microdrip factor of 60 gtt/mL instead of the 20 gtt/mL printed on the tubing.'),
  ('calculations', 9, 'A client is prescribed 900 mL of IV fluid over 5 hours by gravity drip. The tubing drop factor is 15 gtt/mL. What drip rate should the nurse calculate?', '[{"id": "a", "text": "45 gtt/min"}, {"id": "b", "text": "2,700 gtt/min"}, {"id": "c", "text": "60 gtt/min"}, {"id": "d", "text": "180 gtt/min"}]'::jsonb, '["a"]', '5 hours = 300 minutes; (900 × 15) ÷ 300 = 45 gtt/min. 2,700 gtt/min results from dividing by 5 hours instead of 300 minutes.'),
  ('calculations', 10, 'An infant is to receive 60 mL of IV fluid over 2 hours by gravity using microdrip tubing. Which drip rate is correct?', '[{"id": "a", "text": "1,800 gtt/min"}, {"id": "b", "text": "0.5 gtt/min"}, {"id": "c", "text": "5 gtt/min"}, {"id": "d", "text": "30 gtt/min"}]'::jsonb, '["d"]', '2 hours = 120 minutes; (60 × 60) ÷ 120 = 30 gtt/min. 5 gtt/min results from using a macrodrip factor of 10 gtt/mL instead of the 60 gtt/mL microdrip factor.'),
  ('calculations', 11, 'A nurse must infuse 1,500 mL over 12 hours by gravity using tubing labeled 10 gtt/mL. What is the correct drip rate?', '[{"id": "a", "text": "21 gtt/min"}, {"id": "b", "text": "20 gtt/min"}, {"id": "c", "text": "1,250 gtt/min"}, {"id": "d", "text": "125 gtt/min"}]'::jsonb, '["a"]', '12 hours = 720 minutes; (1,500 × 10) ÷ 720 = 20.83, rounded to the nearest whole number, 21 gtt/min. 20 gtt/min drops the decimal rather than rounding to the nearest whole number.'),
  ('calculations', 12, 'A client is to receive 2,000 mL of IV fluid over 24 hours by gravity. The tubing drop factor is 10 gtt/mL. Which drip rate should the nurse set?', '[{"id": "a", "text": "833 gtt/min"}, {"id": "b", "text": "13 gtt/min"}, {"id": "c", "text": "83 gtt/min"}, {"id": "d", "text": "14 gtt/min"}]'::jsonb, '["d"]', '24 hours × 60 = 1,440 minutes; (2,000 × 10) ÷ 1,440 = 13.89, rounded to 14 gtt/min. 833 gtt/min results from dividing by 24 hours without converting to minutes.'),
  ('calculations', 13, 'A nurse is to infuse 1,000 mL over 10 hours by gravity using tubing with a drop factor of 20 gtt/mL. What drip rate is correct?', '[{"id": "a", "text": "33 gtt/min"}, {"id": "b", "text": "2,000 gtt/min"}, {"id": "c", "text": "34 gtt/min"}, {"id": "d", "text": "25 gtt/min"}]'::jsonb, '["a"]', '10 hours = 600 minutes; (1,000 × 20) ÷ 600 = 33.33, rounded to the nearest whole number, 33 gtt/min. 34 gtt/min rounds up incorrectly, and 2,000 gtt/min uses hours instead of minutes.'),
  ('calculations', 14, 'A client is prescribed 600 mL of IV fluid over 4 hours by gravity. The macrodrip tubing has a drop factor of 10 gtt/mL. What drip rate should the nurse set?', '[{"id": "a", "text": "50 gtt/min"}, {"id": "b", "text": "1,500 gtt/min"}, {"id": "c", "text": "25 gtt/min"}, {"id": "d", "text": "150 gtt/min"}]'::jsonb, '["c"]', '4 hours = 240 minutes; (600 × 10) ÷ 240 = 25 gtt/min. 150 is the volume per hour (600 ÷ 4) and ignores the drop factor and minute conversion.'),
  ('calculations', 15, 'A child in the pediatric unit is to receive 400 mL over 8 hours by gravity using microdrip tubing. What drip rate should the nurse calculate?', '[{"id": "a", "text": "8 gtt/min"}, {"id": "b", "text": "50 gtt/min"}, {"id": "c", "text": "3,000 gtt/min"}, {"id": "d", "text": "1 gtt/min"}]'::jsonb, '["b"]', '8 hours = 480 minutes; (400 × 60) ÷ 480 = 50 gtt/min. 1 gtt/min results from leaving the 60 gtt/mL microdrip factor out of the formula.'),
  ('calculations', 16, 'A nurse is reviewing clients'' IV infusions. For which infusion does the nurse need to calculate a drip rate in gtt/min?', '[{"id": "a", "text": "IV fluids running by gravity drip"}, {"id": "b", "text": "IV fluids running through an infusion pump"}, {"id": "c", "text": "A child''s weight recorded in pounds"}, {"id": "d", "text": "An oral antibiotic ordered in mg/kg/day"}]'::jsonb, '["a"]', 'Drip rate (gtt/min) calculations are used when IV fluids run via gravity drip, not a pump. A mg/kg/day order requires a weight-based dosage calculation instead.'),
  ('calculations', 17, 'A nurse is calculating a gravity drip rate and needs the drop factor. Where should the nurse obtain this value?', '[{"id": "a", "text": "From the total infusion time"}, {"id": "b", "text": "From the client''s weight in kilograms"}, {"id": "c", "text": "From the IV fluid bag label"}, {"id": "d", "text": "From the IV tubing being used"}]'::jsonb, '["d"]', 'The drop factor (gtt/mL) is given on the tubing, for example 10, 15, 20, or 60 gtt/mL. The fluid bag provides the volume, not the drop factor.'),
  ('calculations', 18, 'A nurse on a pediatric unit is setting up a gravity infusion with microdrip tubing. Which drop factor should the nurse use in the calculation?', '[{"id": "a", "text": "20 gtt/mL"}, {"id": "b", "text": "15 gtt/mL"}, {"id": "c", "text": "10 gtt/mL"}, {"id": "d", "text": "60 gtt/mL"}]'::jsonb, '["d"]', 'Microdrip tubing is 60 gtt/mL and is common for pediatrics and critical care. 10, 15, and 20 gtt/mL are macrodrip drop factors used for regular adult IVs.'),
  ('calculations', 19, 'A nurse preceptor is reviewing IV tubing with a newly hired nurse. Which statement by the new nurse requires correction?', '[{"id": "a", "text": "Microdrip tubing is common in critical care."}, {"id": "b", "text": "Macrodrip tubing delivers 60 gtt/mL."}, {"id": "c", "text": "Macrodrip tubing may deliver 10 gtt/mL."}, {"id": "d", "text": "Regular adult IVs commonly use macrodrip."}]'::jsonb, '["b"]', 'Macrodrip tubing delivers 10, 15, or 20 gtt/mL; 60 gtt/mL is the microdrip factor. The other statements are accurate.'),
  ('calculations', 20, 'A nurse is calculating the drip rate for 1,000 mL to infuse over 5 hours by gravity. Which value should the nurse use for time in the formula?', '[{"id": "a", "text": "5"}, {"id": "b", "text": "12"}, {"id": "c", "text": "3,000"}, {"id": "d", "text": "300"}]'::jsonb, '["d"]', 'Time must be in minutes, so 5 hours × 60 = 300 minutes. Using 5 leaves the time in hours, which gives a wrong answer.'),
  ('calculations', 21, 'A nurse calculates a gravity drip rate of 27.78 gtt/min. The order gives no special rounding instruction. At what rate should the nurse set the infusion?', '[{"id": "a", "text": "27 gtt/min"}, {"id": "b", "text": "28 gtt/min"}, {"id": "c", "text": "27.8 gtt/min"}, {"id": "d", "text": "30 gtt/min"}]'::jsonb, '["b"]', 'Drip rates are rounded to the nearest whole number unless told otherwise, so 27.78 becomes 28 gtt/min. 27 gtt/min drops the decimal instead of rounding to the nearest whole number.'),
  ('calculations', 22, 'To infuse 1,000 mL over 8 hours with a 15 gtt/mL set, a nurse divides 1,000 by 480 to get 2.08, rounds this to 2, and multiplies by 15 to get 30 gtt/min. What error did the nurse make?', '[{"id": "a", "text": "Used the wrong drop factor"}, {"id": "b", "text": "Used the wrong volume to infuse"}, {"id": "c", "text": "Did not convert hours to minutes"}, {"id": "d", "text": "Rounded before the final step"}]'::jsonb, '["d"]', 'Rounding should occur at the end only; (1,000 × 15) ÷ 480 = 31.25, so the correct rate is 31 gtt/min. The nurse did convert 8 hours to 480 minutes correctly.'),
  ('calculations', 23, 'A nursing student is calculating the gravity drip rate for 100 mL of fluid to infuse over 30 minutes. Which action by the student requires correction?', '[{"id": "a", "text": "Multiplying 30 minutes by 60"}, {"id": "b", "text": "Using the drop factor on the tubing"}, {"id": "c", "text": "Rounding the final answer to a whole number"}, {"id": "d", "text": "Placing 100 mL as the volume"}]'::jsonb, '["a"]', 'The time is already in minutes; multiplying by 60 is only done to convert hours to minutes, so this creates a wrong unit and a wrong answer. Rounding the final answer to the nearest whole number is correct.'),
  ('calculations', 24, 'A nurse is calculating the drip rate for an infusion ordered over several hours. In which order should the nurse perform the steps?', '[{"id": "a", "text": "Convert hours to minutes, apply the formula, round the answer"}, {"id": "b", "text": "Apply the formula, round the answer, convert hours to minutes"}, {"id": "c", "text": "Round the answer, convert hours to minutes, apply the formula"}, {"id": "d", "text": "Apply the formula with hours, round, then multiply by 60"}]'::jsonb, '["a"]', 'First convert hours to minutes, then apply the formula, and round only at the end. Rounding first or applying the formula with hours produces errors.'),
  ('calculations', 25, 'A child weighs 22 lb. The provider orders ceftriaxone 50 mg/kg/day. How many milligrams per day should the nurse administer?', '[{"id": "a", "text": "500 mg/day"}, {"id": "b", "text": "2,420 mg/day"}, {"id": "c", "text": "1,100 mg/day"}, {"id": "d", "text": "227 mg/day"}]'::jsonb, '["a"]', '22 lb ÷ 2.2 = 10 kg, and 10 kg × 50 mg/kg = 500 mg/day. 1,100 mg/day results from using the weight in pounds without converting to kilograms.'),
  ('calculations', 26, 'A child who weighs 44 lb is prescribed a medication at 20 mg/kg/day. What daily dose should the nurse prepare?', '[{"id": "a", "text": "1,936 mg/day"}, {"id": "b", "text": "400 mg/day"}, {"id": "c", "text": "880 mg/day"}, {"id": "d", "text": "182 mg/day"}]'::jsonb, '["b"]', '44 lb ÷ 2.2 = 20 kg; 20 kg × 20 mg/kg = 400 mg/day. 1,936 mg/day results from multiplying the pounds by 2.2 instead of dividing.'),
  ('calculations', 27, 'A toddler weighs 33 lb. A medication is ordered at 10 mg/kg/day. How many milligrams per day should the nurse give?', '[{"id": "a", "text": "726 mg/day"}, {"id": "b", "text": "150 mg/day"}, {"id": "c", "text": "330 mg/day"}, {"id": "d", "text": "68 mg/day"}]'::jsonb, '["b"]', '33 lb ÷ 2.2 = 15 kg; 15 kg × 10 mg/kg = 150 mg/day. 330 mg/day uses the weight in pounds without converting to kilograms.'),
  ('calculations', 28, 'A child weighs 12 kg. The prescribed dose is 25 mg/kg/day. What daily dose should the nurse administer?', '[{"id": "a", "text": "660 mg/day"}, {"id": "b", "text": "37 mg/day"}, {"id": "c", "text": "136 mg/day"}, {"id": "d", "text": "300 mg/day"}]'::jsonb, '["d"]', 'The weight is already in kilograms, so 12 kg × 25 mg/kg = 300 mg/day. 136 mg/day results from dividing an already-metric weight by 2.2 again.'),
  ('calculations', 29, 'A school-age child weighs 66 lb and is prescribed a medication at 15 mg/kg/day. How many milligrams per day should the nurse administer?', '[{"id": "a", "text": "2,178 mg/day"}, {"id": "b", "text": "205 mg/day"}, {"id": "c", "text": "990 mg/day"}, {"id": "d", "text": "450 mg/day"}]'::jsonb, '["d"]', '66 lb ÷ 2.2 = 30 kg; 30 kg × 15 mg/kg = 450 mg/day. 990 mg/day results from multiplying the weight in pounds by the mg/kg dose.'),
  ('calculations', 30, 'An infant weighs 11 lb and is prescribed a medication at 40 mg/kg/day. What daily dose should the nurse prepare?', '[{"id": "a", "text": "200 mg/day"}, {"id": "b", "text": "91 mg/day"}, {"id": "c", "text": "440 mg/day"}, {"id": "d", "text": "968 mg/day"}]'::jsonb, '["a"]', '11 lb ÷ 2.2 = 5 kg; 5 kg × 40 mg/kg = 200 mg/day. 968 mg/day results from multiplying the pounds by 2.2 instead of dividing.'),
  ('calculations', 31, 'An infant weighs 8 kg. A medication is ordered at 40 mg/kg/day. What total daily dose should the nurse give?', '[{"id": "a", "text": "320 mg/day"}, {"id": "b", "text": "145 mg/day"}, {"id": "c", "text": "704 mg/day"}, {"id": "d", "text": "5 mg/day"}]'::jsonb, '["a"]', '8 kg × 40 mg/kg = 320 mg/day; no conversion is needed because the weight is already in kilograms. 145 mg/day results from dividing the kilogram weight by 2.2 unnecessarily.'),
  ('calculations', 32, 'A child who weighs 77 lb is prescribed a medication at 10 mg/kg/day. What daily dose should the nurse administer?', '[{"id": "a", "text": "770 mg/day"}, {"id": "b", "text": "159 mg/day"}, {"id": "c", "text": "350 mg/day"}, {"id": "d", "text": "1,694 mg/day"}]'::jsonb, '["c"]', '77 lb ÷ 2.2 = 35 kg; 35 kg × 10 mg/kg = 350 mg/day. 770 mg/day results from using pounds without converting to kilograms.'),
  ('calculations', 33, 'A nurse needs a client''s weight in kilograms for a mg/kg medication order. The client weighs 88 lb. Which weight should the nurse use?', '[{"id": "a", "text": "193.6 kg"}, {"id": "b", "text": "85.8 kg"}, {"id": "c", "text": "40 kg"}, {"id": "d", "text": "90.2 kg"}]'::jsonb, '["c"]', 'Pounds are converted to kilograms by dividing by 2.2: 88 ÷ 2.2 = 40 kg. 193.6 kg results from multiplying by 2.2 instead of dividing.'),
  ('calculations', 34, 'A nurse is teaching a group of nursing students about weight-based dosing. Which statement by a student indicates a need for further teaching?', '[{"id": "a", "text": "I check the safe range before giving a pediatric dose."}, {"id": "b", "text": "I multiply the weight in pounds by 2.2 to get kilograms."}, {"id": "c", "text": "I convert pounds to kilograms before using the formula."}, {"id": "d", "text": "I use the weight in kilograms in the dosage formula."}]'::jsonb, '["b"]', 'Pounds are converted to kilograms by dividing by 2.2, not multiplying. The other statements reflect correct weight-based dosing practice.'),
  ('calculations', 35, 'A nurse is preparing a medication ordered in mg/kg for a child whose weight is recorded in kilograms. Which formula should the nurse use?', '[{"id": "a", "text": "Dosage = weight (lb) × mg/kg ordered"}, {"id": "b", "text": "Dosage = weight (kg) ÷ mg/kg ordered"}, {"id": "c", "text": "Dosage = weight (kg) × mg/kg ordered"}, {"id": "d", "text": "Dosage = mg/kg ordered ÷ weight (kg)"}]'::jsonb, '["c"]', 'Weight-based dosage equals the weight in kilograms multiplied by the mg/kg ordered. Using pounds or dividing the values produces an incorrect dose.'),
  ('calculations', 36, 'The safe dose range for a medication is 10–20 mg/kg/day. A child who weighs 15 kg is prescribed this medication. What is the safe total daily dose range?', '[{"id": "a", "text": "25–35 mg/day"}, {"id": "b", "text": "10–20 mg/day"}, {"id": "c", "text": "150–300 mg/day"}, {"id": "d", "text": "330–660 mg/day"}]'::jsonb, '["c"]', 'Minimum 10 mg/kg × 15 kg = 150 mg/day and maximum 20 mg/kg × 15 kg = 300 mg/day. 330–660 mg/day results from multiplying the kilogram weight by 2.2 before calculating.'),
  ('calculations', 37, 'A child weighing 20 kg is prescribed a medication with a safe dose range of 5–10 mg/kg/day. What is the safe daily dose range for this child?', '[{"id": "a", "text": "220–440 mg/day"}, {"id": "b", "text": "45–91 mg/day"}, {"id": "c", "text": "5–10 mg/day"}, {"id": "d", "text": "100–200 mg/day"}]'::jsonb, '["d"]', '5 mg/kg × 20 kg = 100 mg/day (minimum) and 10 mg/kg × 20 kg = 200 mg/day (maximum). 45–91 mg/day results from dividing a weight already in kilograms by 2.2.'),
  ('calculations', 38, 'A child weighs 55 lb. The safe dose range for a prescribed medication is 6–8 mg/kg/day. What is the safe daily dose range?', '[{"id": "a", "text": "330–440 mg/day"}, {"id": "b", "text": "726–968 mg/day"}, {"id": "c", "text": "150–200 mg/day"}, {"id": "d", "text": "68–91 mg/day"}]'::jsonb, '["c"]', '55 lb ÷ 2.2 = 25 kg; 6 × 25 = 150 mg/day and 8 × 25 = 200 mg/day. 330–440 mg/day results from using the weight in pounds.'),
  ('calculations', 39, 'A child who weighs 18 kg is prescribed a medication with a safe range of 25–50 mg/kg/day. Which daily dose range is safe for this child?', '[{"id": "a", "text": "990–1,980 mg/day"}, {"id": "b", "text": "205–409 mg/day"}, {"id": "c", "text": "450–900 mg/day"}, {"id": "d", "text": "25–50 mg/day"}]'::jsonb, '["c"]', '25 mg/kg × 18 kg = 450 mg/day and 50 mg/kg × 18 kg = 900 mg/day. 205–409 mg/day results from dividing a weight already in kilograms by 2.2.'),
  ('calculations', 40, 'A child weighing 10 kg has an order for a medication at 300 mg/day. The safe range is 10–20 mg/kg/day. What should the nurse do?', '[{"id": "a", "text": "Give the dose and monitor the child closely"}, {"id": "b", "text": "Give the dose because it was prescribed"}, {"id": "c", "text": "Give 200 mg and document the change"}, {"id": "d", "text": "Withhold the dose and verify with a pharmacist"}]'::jsonb, '["d"]', 'The maximum safe dose is 20 mg/kg × 10 kg = 200 mg/day, so 300 mg/day is unsafe; never exceed the maximum safe dose even if it was ordered, and verify with another nurse or pharmacist. Giving the dose because it was prescribed ignores this safety rule.'),
  ('calculations', 41, 'A child weighs 44 lb and is prescribed a medication at 350 mg/day. The safe range is 10–20 mg/kg/day. How should the nurse interpret this order?', '[{"id": "a", "text": "It is below the minimum safe dose."}, {"id": "b", "text": "It is within the safe range."}, {"id": "c", "text": "It exceeds the maximum safe dose."}, {"id": "d", "text": "It equals the maximum safe dose."}]'::jsonb, '["b"]', '44 lb ÷ 2.2 = 20 kg, so the safe range is 10 × 20 = 200 mg/day to 20 × 20 = 400 mg/day, and 350 mg/day falls within it. It is neither above the 400 mg maximum nor equal to it.'),
  ('calculations', 42, 'A child weighs 33 lb and has an order for 600 mg/day of a medication with a maximum safe dose of 20 mg/kg/day. A nurse says, ''This is safe because 33 × 20 = 660 mg.'' How should the charge nurse respond?', '[{"id": "a", "text": "Agree, because 600 mg is below 660 mg"}, {"id": "b", "text": "Disagree; the maximum is 300 mg/day, so it is unsafe"}, {"id": "c", "text": "Disagree; the maximum is 1,452 mg/day, so it is low"}, {"id": "d", "text": "Agree, because pounds may be used for children"}]'::jsonb, '["b"]', '33 lb ÷ 2.2 = 15 kg, and 15 kg × 20 mg/kg = 300 mg/day, so 600 mg/day exceeds the maximum. The nurse''s error was using pounds instead of kilograms.'),
  ('calculations', 43, 'A nurse is checking whether a pediatric dose ordered for a child weighing in pounds falls within a stated safe range. In which order should the nurse perform the steps?', '[{"id": "a", "text": "Convert weight to kg, calculate the range, compare the ordered dose"}, {"id": "b", "text": "Calculate the range, convert weight, compare the ordered dose"}, {"id": "c", "text": "Convert weight to kg, compare the ordered dose, calculate the range"}, {"id": "d", "text": "Compare the ordered dose, convert weight, calculate the range"}]'::jsonb, '["a"]', 'Weight must be in kilograms before applying the formula; then the minimum and maximum safe doses are calculated so the ordered dose can be compared against them. Calculating the range before converting uses the wrong unit.'),
  ('calculations', 44, 'A nurse completes a pediatric dosage calculation and the result seems much higher than expected. What should the nurse do first?', '[{"id": "a", "text": "Administer the calculated dose as planned"}, {"id": "b", "text": "Round the dose down to a whole number"}, {"id": "c", "text": "Stop and recalculate the dose"}, {"id": "d", "text": "Give half of the calculated dose"}]'::jsonb, '["c"]', 'If a calculated dose seems too high or too low, the nurse should stop and recalculate. Giving the dose or altering it without rechecking risks an unsafe dose.'),
  ('calculations', 45, 'After recalculating a weight-based dose for a child, a nurse remains unsure whether the result is correct. Which action is most appropriate?', '[{"id": "a", "text": "Use the child''s weight in pounds instead"}, {"id": "b", "text": "Give the dose and recheck it afterward"}, {"id": "c", "text": "Verify the calculation with a pharmacist"}, {"id": "d", "text": "Round the result to a whole number"}]'::jsonb, '["c"]', 'In clinical practice, calculations should be verified with another nurse or pharmacist. Giving the dose first and rechecking later does not prevent an unsafe dose.'),
  ('calculations', 46, 'A nurse educator is reviewing calculation methods with new graduates. Which method should the educator identify as the safest?', '[{"id": "a", "text": "Rounding each step to a whole number"}, {"id": "b", "text": "Estimating from a previous similar dose"}, {"id": "c", "text": "Dimensional analysis, canceling units step by step"}, {"id": "d", "text": "Mental math without writing the units"}]'::jsonb, '["c"]', 'Dimensional analysis (factor-label method) is the safest method because units are canceled step by step until only the desired unit remains. Rounding at each step introduces error because rounding should be done only at the end.'),
  ('calculations', 47, 'A nurse is mentoring a new graduate on medication calculations. Which statement by the new graduate indicates correct understanding?', '[{"id": "a", "text": "Pounds and kilograms can be used interchangeably."}, {"id": "b", "text": "I can skip unit labels once I know the formula."}, {"id": "c", "text": "I round each step so the numbers stay easy to handle."}, {"id": "d", "text": "A wrong unit means a wrong answer, so I recheck conversions."}]'::jsonb, '["d"]', 'Units must be read carefully and conversions rechecked because a wrong unit gives a wrong answer. Rounding should occur only at the end, not mid-calculation.'),
  ('calculations', 48, 'A child in the pediatric intensive care unit is to receive 30 mL of IV fluid over 1 hour by gravity using microdrip tubing. What drip rate should the nurse set?', '[{"id": "a", "text": "1,800 gtt/min"}, {"id": "b", "text": "30 gtt/min"}, {"id": "c", "text": "5 gtt/min"}, {"id": "d", "text": "0.5 gtt/min"}]'::jsonb, '["b"]', '(30 × 60) ÷ 60 minutes = 30 gtt/min. 1,800 gtt/min results from leaving the time as 1 hour instead of converting it to 60 minutes.'),
  ('calculations', 49, 'A child''s weight is recorded as 48.4 lb. Before calculating a mg/kg dose, which weight should the nurse use in the formula?', '[{"id": "a", "text": "46.2 kg"}, {"id": "b", "text": "106.5 kg"}, {"id": "c", "text": "48.4 kg"}, {"id": "d", "text": "22 kg"}]'::jsonb, '["d"]', '48.4 lb ÷ 2.2 = 22 kg. 106.5 kg results from multiplying by 2.2, and 48.4 kg uses the pound value without converting.'),
  ('calculations', 50, 'A client is to receive 1,000 mL of IV fluid over 12 hours by gravity using tubing with a drop factor of 15 gtt/mL. Which drip rate should the nurse set?', '[{"id": "a", "text": "83 gtt/min"}, {"id": "b", "text": "21 gtt/min"}, {"id": "c", "text": "1,250 gtt/min"}, {"id": "d", "text": "20 gtt/min"}]'::jsonb, '["b"]', '12 hours = 720 minutes; (1,000 × 15) ÷ 720 = 20.83, which rounds to 21 gtt/min. 20 gtt/min drops the decimal instead of rounding to the nearest whole number.'),
  ('precautions', 1, 'A nurse is preparing to enter the room of a client with active tuberculosis (TB). Which item of personal protective equipment is essential?', '[{"id": "a", "text": "Eye protection only"}, {"id": "b", "text": "Surgical mask"}, {"id": "c", "text": "Gloves only"}, {"id": "d", "text": "N95 respirator mask"}]'::jsonb, '["d"]', 'TB requires airborne precautions, which call for an N95 respirator mask. A surgical mask is the PPE for droplet precautions, not airborne.'),
  ('precautions', 2, 'A child with measles is being admitted to the pediatric unit. Which room assignment is most appropriate?', '[{"id": "a", "text": "Private negative-pressure room with the door closed"}, {"id": "b", "text": "Semi-private room with a child who has influenza"}, {"id": "c", "text": "Private room with the door propped open"}, {"id": "d", "text": "Shared room with a child who has MRSA"}]'::jsonb, '["a"]', 'Measles requires airborne precautions: a private negative-pressure room with the door kept closed. Leaving the door open defeats the airborne room setup.'),
  ('precautions', 3, 'The charge nurse observes care for a client with chickenpox (varicella). Which action by a staff member requires correction?', '[{"id": "a", "text": "Leaving the room door open for better observation"}, {"id": "b", "text": "Wearing an N95 respirator mask in the room"}, {"id": "c", "text": "Keeping the client in a negative-pressure room"}, {"id": "d", "text": "Performing hand hygiene before and after care"}]'::jsonb, '["a"]', 'Chickenpox requires airborne precautions, and the door must be kept closed. Wearing an N95, using negative pressure, and hand hygiene are correct.'),
  ('precautions', 4, 'A nurse will be standing at the bedside within 3 feet of a client with influenza to give medications. Which mask should the nurse wear?', '[{"id": "a", "text": "N95 respirator"}, {"id": "b", "text": "Surgical mask"}, {"id": "c", "text": "No mask is needed"}, {"id": "d", "text": "Cloth face covering"}]'::jsonb, '["b"]', 'Influenza requires droplet precautions, which call for a surgical mask when within 3 feet. The N95 respirator is the PPE for airborne precautions.'),
  ('precautions', 5, 'A client on droplet precautions for mumps needs to be transported to radiology. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Transport the client without any added protection"}, {"id": "b", "text": "Have the client wear gloves and a gown during transport"}, {"id": "c", "text": "Cancel the test until precautions are discontinued"}, {"id": "d", "text": "Have the client wear a mask while out of the room"}]'::jsonb, '["d"]', 'For droplet precautions, the client wears a mask if leaving the room. Gloves and gown are the barrier PPE for contact precautions.'),
  ('precautions', 6, 'A client has a wound infected with methicillin-resistant Staphylococcus aureus (MRSA). Which personal protective equipment should the nurse put on before entering the room?', '[{"id": "a", "text": "N95 respirator"}, {"id": "b", "text": "Gloves and gown"}, {"id": "c", "text": "Surgical mask"}, {"id": "d", "text": "Eye protection only"}]'::jsonb, '["b"]', 'MRSA requires contact precautions, which call for gloves and gown when entering the room. Masks are used for airborne and droplet precautions.'),
  ('precautions', 7, 'A nurse has just finished providing care for a client with Clostridioides difficile (C. diff). Which hand hygiene method should the nurse use?', '[{"id": "a", "text": "Wipe hands with a disinfectant cloth"}, {"id": "b", "text": "Use alcohol-based hand gel"}, {"id": "c", "text": "Wash hands with soap and water"}, {"id": "d", "text": "Remove gloves and skip hand hygiene"}]'::jsonb, '["c"]', 'For C. diff, hands are washed with soap and water, not alcohol gel. Alcohol gel is the tempting choice but does not work on C. diff.'),
  ('precautions', 8, 'A nurse overhears a UAP talking after caring for a client with C. diff. Which statement by the UAP requires the nurse to intervene?', '[{"id": "a", "text": "\"I''ll leave the blood pressure cuff in the room.\""}, {"id": "b", "text": "\"I''ll wash my hands with soap and water.\""}, {"id": "c", "text": "\"I''ll put on gloves and a gown next time.\""}, {"id": "d", "text": "\"I''ll use the alcohol gel since it''s faster.\""}]'::jsonb, '["d"]', 'After C. diff care, handwashing with soap and water is required because alcohol gel does not work. Gloves, gown, and keeping equipment in the room are correct contact precautions.'),
  ('precautions', 9, 'A student nurse asks why soap and water are required instead of alcohol gel after caring for a client with C. diff. Which response is accurate?', '[{"id": "a", "text": "\"Alcohol gel spreads C. diff through the air.\""}, {"id": "b", "text": "\"Alcohol does not kill C. diff spores.\""}, {"id": "c", "text": "\"Soap and water are used for every client.\""}, {"id": "d", "text": "\"C. diff is spread only by droplets.\""}]'::jsonb, '["b"]', 'Soap and water are used for C. diff because alcohol does not kill spores. C. diff is spread by touching, which is why contact precautions are used, not droplet.'),
  ('precautions', 10, 'A client with vancomycin-resistant Enterococcus (VRE) needs frequent blood pressure checks. Which equipment practice is appropriate?', '[{"id": "a", "text": "Keep a blood pressure cuff in the client''s room"}, {"id": "b", "text": "Bring the hallway cuff in and out of each room"}, {"id": "c", "text": "Share the cuff with the next client without cleaning"}, {"id": "d", "text": "Check blood pressure only with gloves and no gown"}]'::jsonb, '["a"]', 'Under contact precautions, equipment stays in the room or is disinfected. Moving an uncleaned cuff between clients spreads germs that travel by touch.'),
  ('precautions', 11, 'A nurse is caring for a client on contact precautions for MRSA and another client with no infection. Which action by the nurse requires correction?', '[{"id": "a", "text": "Using the same stethoscope on both clients without cleaning it"}, {"id": "b", "text": "Putting on gloves and a gown before entering the MRSA room"}, {"id": "c", "text": "Leaving a dedicated thermometer in the MRSA client''s room"}, {"id": "d", "text": "Checking the isolation sign before entering the MRSA room"}]'::jsonb, '["a"]', 'Equipment used under contact precautions stays in the room or is disinfected, so carrying an uncleaned stethoscope to another client is unsafe. The other actions are correct.'),
  ('precautions', 12, 'A client with MRSA must be admitted, and no private rooms are available. Which roommate is most appropriate?', '[{"id": "a", "text": "A client who also has MRSA"}, {"id": "b", "text": "A client who has influenza"}, {"id": "c", "text": "A client who has tuberculosis"}, {"id": "d", "text": "A client with no known infection"}]'::jsonb, '["a"]', 'Contact precautions use a private room or sharing with a client who has the same infection. A client with influenza or TB has a different infection requiring different precautions.'),
  ('precautions', 13, 'A client with influenza needs a bed, and no private rooms are open. Which roommate assignment is appropriate?', '[{"id": "a", "text": "A client recovering from surgery"}, {"id": "b", "text": "A client who has measles"}, {"id": "c", "text": "A client who has C. diff"}, {"id": "d", "text": "A client who also has influenza"}]'::jsonb, '["d"]', 'Droplet precautions use a private room or cohorting with a client who has the same infection. Measles and C. diff are different infections with different precaution types.'),
  ('precautions', 14, 'A client who appears healthy is admitted for elective knee surgery and has no known infection. Which type of precautions should the nurse use?', '[{"id": "a", "text": "Airborne precautions"}, {"id": "b", "text": "Standard precautions"}, {"id": "c", "text": "Droplet precautions"}, {"id": "d", "text": "No precautions are needed"}]'::jsonb, '["b"]', 'Standard precautions are used with every client, even if they look healthy. Airborne and droplet precautions are added only when a client has a known infection spread that way.'),
  ('precautions', 15, 'Which statement by a newly hired nurse about standard precautions indicates a need for further teaching?', '[{"id": "a", "text": "\"They include hand hygiene and safe sharps disposal.\""}, {"id": "b", "text": "\"I use them for every client, all of the time.\""}, {"id": "c", "text": "\"I use them only for clients with known infections.\""}, {"id": "d", "text": "\"They include gloves when touching body fluids.\""}]'::jsonb, '["c"]', 'Standard precautions are basic infection control for all patients, all the time. Extra transmission-based precautions are what get added for known infections.'),
  ('precautions', 16, 'A nurse is caring for a client with no known infection. Which task requires the nurse to wear gloves under standard precautions?', '[{"id": "a", "text": "Taking a radial pulse on intact skin"}, {"id": "b", "text": "Cleaning drainage from a skin tear"}, {"id": "c", "text": "Delivering a meal tray to the bedside"}, {"id": "d", "text": "Adjusting the television for the client"}]'::jsonb, '["b"]', 'Gloves are worn when touching blood, body fluids, broken skin, or mucous membranes. Touching intact skin or delivering a tray does not involve these.'),
  ('precautions', 17, 'A nurse is about to irrigate a large wound, and splashing of fluid is likely. Which equipment should the nurse wear in addition to gloves?', '[{"id": "a", "text": "Mask, gown, and eye protection"}, {"id": "b", "text": "N95 respirator only"}, {"id": "c", "text": "Gown only"}, {"id": "d", "text": "No additional equipment"}]'::jsonb, '["a"]', 'Under standard precautions, a mask, gown, and eye protection are worn if splashing is likely. An N95 respirator is specific to airborne precautions.'),
  ('precautions', 18, 'After giving a subcutaneous injection, a nurse is observed placing the cap back on the used needle. What should the charge nurse tell the nurse?', '[{"id": "a", "text": "\"Recap it if no sharps box is near.\""}, {"id": "b", "text": "\"Recap it only with two hands.\""}, {"id": "c", "text": "\"Never recap a used needle.\""}, {"id": "d", "text": "\"Recap it before you leave the room.\""}]'::jsonb, '["c"]', 'Safe sharps disposal is part of standard precautions, and needles are never recapped. Every other option still involves recapping.'),
  ('precautions', 19, 'Which statement by a nursing student about needle safety indicates correct understanding of standard precautions?', '[{"id": "a", "text": "\"I only need sharps safety for clients with known infections.\""}, {"id": "b", "text": "\"I will recap the needle before carrying it to the sharps box.\""}, {"id": "c", "text": "\"I will dispose of the needle safely without recapping it.\""}, {"id": "d", "text": "\"I will recap the needle if the client appears healthy.\""}]'::jsonb, '["c"]', 'Safe sharps disposal without recapping is part of standard precautions for every client. Standard precautions apply even when the client looks healthy.'),
  ('precautions', 20, 'A client is admitted with an open wound that has large amounts of drainage. Which type of transmission-based precautions does the nurse implement?', '[{"id": "a", "text": "No added precautions"}, {"id": "b", "text": "Airborne precautions"}, {"id": "c", "text": "Droplet precautions"}, {"id": "d", "text": "Contact precautions"}]'::jsonb, '["d"]', 'Open wounds with drainage require contact precautions because the germs spread by touching. Airborne and droplet precautions are for germs that spread through the air or by coughing and sneezing.'),
  ('precautions', 21, 'A client is admitted with suspected meningitis. Which type of transmission-based precautions does the nurse anticipate?', '[{"id": "a", "text": "Airborne precautions"}, {"id": "b", "text": "Droplet precautions"}, {"id": "c", "text": "Contact precautions"}, {"id": "d", "text": "Standard precautions only"}]'::jsonb, '["b"]', 'Meningitis is listed with flu and mumps under droplet precautions. Airborne precautions are for TB, measles, and chickenpox.'),
  ('precautions', 22, 'A nurse is assigned a client with tuberculosis and a client with influenza. Which plan for masks is correct?', '[{"id": "a", "text": "No mask for either client"}, {"id": "b", "text": "Surgical mask for the TB client; N95 for the flu client"}, {"id": "c", "text": "Surgical mask for both clients"}, {"id": "d", "text": "N95 for the TB client; surgical mask for the flu client"}]'::jsonb, '["d"]', 'TB is airborne and requires an N95 mask, while influenza is droplet and requires a surgical mask. The reversed pairing confuses airborne and droplet PPE.'),
  ('precautions', 23, 'A family member asks why a client with influenza is on droplet precautions instead of airborne precautions. Which explanation is accurate?', '[{"id": "a", "text": "\"Flu germs are tiny and float in the air for long periods.\""}, {"id": "b", "text": "\"Flu germs are bigger and travel about 3 to 6 feet.\""}, {"id": "c", "text": "\"Flu germs spread only when someone touches the client.\""}, {"id": "d", "text": "\"Flu germs are killed only by soap and water.\""}]'::jsonb, '["b"]', 'Droplet precautions are for bigger germs that travel about 3-6 feet when coughing, sneezing, or talking. Very tiny germs that float in the air require airborne precautions.'),
  ('precautions', 24, 'The parent of a child with measles asks why the room door must stay closed. Which response by the nurse is best?', '[{"id": "a", "text": "\"The germs are tiny and float in the air.\""}, {"id": "b", "text": "\"The germs only spread by touching surfaces.\""}, {"id": "c", "text": "\"The germs fall within 3 feet of your child.\""}, {"id": "d", "text": "\"The closed door keeps your child warmer.\""}]'::jsonb, '["a"]', 'Measles is an airborne disease caused by very tiny germs that float in the air, so the door is kept closed. Spread by touch describes contact precautions, and travel within a few feet describes droplet precautions.'),
  ('precautions', 25, 'Which statement by a nurse about N95 respirator masks is accurate?', '[{"id": "a", "text": "\"Any mask size fits, so testing is not needed.\""}, {"id": "b", "text": "\"Fit testing is needed only once in a career.\""}, {"id": "c", "text": "\"Health care workers need fit testing every year.\""}, {"id": "d", "text": "\"An N95 is used for clients with influenza.\""}]'::jsonb, '["c"]', 'N95 fit testing is required annually for health care workers. Influenza is a droplet illness that calls for a surgical mask, not an N95.'),
  ('precautions', 26, 'A nurse arrives at a client''s room to administer a medication. What should the nurse do before entering the room?', '[{"id": "a", "text": "Check the isolation sign on the door"}, {"id": "b", "text": "Ask the client which germs they have"}, {"id": "c", "text": "Remove all PPE before going in"}, {"id": "d", "text": "Wait for the client to open the door"}]'::jsonb, '["a"]', 'The nurse should always check the isolation sign on the client''s door before entering so the correct PPE can be used. Asking the client is not a reliable way to identify the precautions needed.'),
  ('precautions', 27, 'A nurse walks into the room of a client on contact precautions and then puts on a gown and gloves at the bedside. Which statement by the charge nurse is appropriate?', '[{"id": "a", "text": "\"Contact precautions do not require any PPE.\""}, {"id": "b", "text": "\"Put on your PPE only if you touch the client.\""}, {"id": "c", "text": "\"Contact precautions require only a surgical mask.\""}, {"id": "d", "text": "\"Put on your PPE before you enter the room.\""}]'::jsonb, '["d"]', 'PPE is put on (donned) before entering the room, and contact precautions require gloves and gown when entering. Waiting until touching the client or using only a mask is incorrect.'),
  ('precautions', 28, 'A client is admitted with a new cough, and the cause has not yet been identified. The nurse is unsure which precautions to use. What is the best action?', '[{"id": "a", "text": "Use fewer precautions so the client is not alarmed"}, {"id": "b", "text": "Use no precautions until the diagnosis is confirmed"}, {"id": "c", "text": "Avoid entering the room until results are available"}, {"id": "d", "text": "Use more protective precautions until it is clarified"}]'::jsonb, '["d"]', 'When in doubt, the nurse should err on the side of more protection. Using no or fewer precautions risks spreading an unknown infection.'),
  ('precautions', 29, 'Which statement by a nursing student about airborne precautions indicates correct understanding?', '[{"id": "a", "text": "\"Measles, TB, and varicella need only gloves and a gown in any room.\""}, {"id": "b", "text": "\"Mumps, flu, and meningitis need an N95 and a negative-pressure room.\""}, {"id": "c", "text": "\"MRSA, VRE, and C. diff need an N95 and a negative-pressure room.\""}, {"id": "d", "text": "\"Measles, TB, and varicella need an N95 and a negative-pressure room.\""}]'::jsonb, '["d"]', 'The MTV memory trick lists measles, TB, and varicella as airborne diseases needing an N95 and negative pressure. Mumps, flu, and meningitis are droplet diseases, and MRSA, VRE, and C. diff are contact diseases.'),
  ('precautions', 30, 'A client with mumps is being admitted, and the nurse is assigning a room. Which placement is most appropriate?', '[{"id": "a", "text": "A semi-private room with a client who has MRSA"}, {"id": "b", "text": "A shared room with a client who has no infection"}, {"id": "c", "text": "A private room"}, {"id": "d", "text": "An open ward bed near the nurses'' station"}]'::jsonb, '["c"]', 'Mumps requires droplet precautions, which use a private room or sharing with a client who has the same infection. A roommate with MRSA or with no infection does not have the same infection.'),
  ('precautions', 31, 'A client is placed on precautions for vancomycin-resistant Enterococcus (VRE). Which PPE does the nurse put on before entering the room?', '[{"id": "a", "text": "Surgical mask only"}, {"id": "b", "text": "N95 respirator"}, {"id": "c", "text": "Gloves and gown"}, {"id": "d", "text": "No PPE is needed"}]'::jsonb, '["c"]', 'VRE requires contact precautions, meaning gloves and gown when entering the room. Masks are the PPE for airborne and droplet precautions.'),
  ('precautions', 32, 'A UAP is preparing to bathe a client on contact precautions for MRSA. Which action by the UAP requires correction?', '[{"id": "a", "text": "Leaving the client''s basin in the room"}, {"id": "b", "text": "Putting on a gown before entering the room"}, {"id": "c", "text": "Putting on gloves before entering the room"}, {"id": "d", "text": "Wearing only a surgical mask into the room"}]'::jsonb, '["d"]', 'Contact precautions for MRSA require gloves and gown for barrier protection; a surgical mask alone is the droplet PPE. Gown, gloves, and keeping equipment in the room are correct.'),
  ('precautions', 33, 'Four clients need admission, and only one negative-pressure room is available. Which client should be placed in this room?', '[{"id": "a", "text": "A client with MRSA"}, {"id": "b", "text": "A client with influenza"}, {"id": "c", "text": "A client with tuberculosis"}, {"id": "d", "text": "A client with mumps"}]'::jsonb, '["c"]', 'Tuberculosis is an airborne disease requiring a negative-pressure room. Influenza and mumps need droplet precautions, and MRSA needs contact precautions, none of which require negative pressure.'),
  ('precautions', 34, 'A nurse is teaching a UAP about standard precautions. Which practice should the nurse include as part of care for every client?', '[{"id": "a", "text": "A gown worn for every client"}, {"id": "b", "text": "An N95 mask at every bedside"}, {"id": "c", "text": "A negative-pressure room"}, {"id": "d", "text": "Hand hygiene before and after care"}]'::jsonb, '["d"]', 'Hand hygiene is part of standard precautions used with all patients. N95 masks and negative-pressure rooms are airborne precautions for specific infections.'),
  ('precautions', 35, 'A nurse is drawing blood from a client who looks healthy and has no known infection. Which action is appropriate?', '[{"id": "a", "text": "Wear an N95 respirator only"}, {"id": "b", "text": "Skip gloves because the client looks healthy"}, {"id": "c", "text": "Wear gloves for the blood draw"}, {"id": "d", "text": "Wear gloves only if the client has a fever"}]'::jsonb, '["c"]', 'Standard precautions apply to every client, even those who look healthy, and include gloves when touching blood. Skipping gloves because the client looks healthy is incorrect.'),
  ('precautions', 36, 'A UAP is about to change the linens of a client who has an open wound with drainage. Which action by the UAP requires correction?', '[{"id": "a", "text": "Putting on PPE before entering the room"}, {"id": "b", "text": "Checking the isolation sign before entering"}, {"id": "c", "text": "Entering the room wearing gloves but no gown"}, {"id": "d", "text": "Leaving the client''s equipment in the room"}]'::jsonb, '["c"]', 'An open wound with drainage requires contact precautions, which call for both gloves and gown when entering. Checking the sign, donning PPE before entering, and keeping equipment in the room are correct.'),
  ('precautions', 37, 'Which statement about transmission-based precautions is accurate?', '[{"id": "a", "text": "They are used for every client at all times."}, {"id": "b", "text": "They replace standard precautions for the client."}, {"id": "c", "text": "They are added based on how the germ spreads."}, {"id": "d", "text": "They are chosen based on the client''s age."}]'::jsonb, '["c"]', 'When a client has a known infection, extra protections are added based on how the germ spreads. Standard precautions are the ones used for every client at all times.'),
  ('precautions', 38, 'A nurse will be within 3 feet of a client with meningitis while assessing the client''s neck. Which PPE is required for this precaution type?', '[{"id": "a", "text": "Surgical mask"}, {"id": "b", "text": "N95 respirator"}, {"id": "c", "text": "Gown only"}, {"id": "d", "text": "No mask needed"}]'::jsonb, '["a"]', 'Meningitis requires droplet precautions, so a surgical mask is worn when within 3 feet. An N95 is the PPE for airborne diseases.'),
  ('precautions', 39, 'A family member asks what a negative-pressure room does for a client with chickenpox. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It kills germs on the client''s skin.\""}, {"id": "b", "text": "\"Air is pushed out into the hallway to dilute germs.\""}, {"id": "c", "text": "\"Air is sucked out so germs don''t float away.\""}, {"id": "d", "text": "\"It lets staff enter without any mask.\""}]'::jsonb, '["c"]', 'A negative-pressure room has air sucked out so germs don''t float away. It does not kill germs on the skin, and staff still use the airborne precautions PPE.'),
  ('precautions', 40, 'A nurse cares for a client with MRSA and then a client with C. diff. Which statement about hand hygiene for these clients is correct?', '[{"id": "a", "text": "Alcohol gel is enough after the C. diff client"}, {"id": "b", "text": "Soap and water are needed after the C. diff client"}, {"id": "c", "text": "Soap and water are needed only after MRSA"}, {"id": "d", "text": "Hand hygiene is not needed if gloves were worn"}]'::jsonb, '["b"]', 'Handwashing with soap and water is needed after C. diff because alcohol doesn''t work on spores. Hand hygiene is part of standard precautions for every patient.'),
  ('precautions', 41, 'A client with VRE is admitted, and the only open bed is in a semi-private room. Which roommate is acceptable?', '[{"id": "a", "text": "A client who has influenza"}, {"id": "b", "text": "A client who has measles"}, {"id": "c", "text": "A client who also has VRE"}, {"id": "d", "text": "A client with no known infection"}]'::jsonb, '["c"]', 'Contact precautions use a private room or sharing with a client who has the same infection. Sharing with a client with a different infection or no infection is not acceptable.'),
  ('precautions', 42, 'The nurse is reviewing equipment use for a client on contact precautions for MRSA. Which practice is correct?', '[{"id": "a", "text": "The unit stethoscope is moved room to room"}, {"id": "b", "text": "A dedicated stethoscope is kept in the room"}, {"id": "c", "text": "Equipment is cleaned only at discharge"}, {"id": "d", "text": "Equipment is stored in the hallway cart"}]'::jsonb, '["b"]', 'Under contact precautions, equipment stays in the room or is disinfected. Moving shared equipment between rooms without disinfecting it spreads germs by touch.'),
  ('precautions', 43, 'A nurse caring for a client with no known infection is planning care for the shift. In which situation should the nurse add a mask, gown, and eye protection?', '[{"id": "a", "text": "Reviewing discharge medications with the client"}, {"id": "b", "text": "Taking an oral temperature with a probe cover"}, {"id": "c", "text": "Assisting the client to walk in the hallway"}, {"id": "d", "text": "Suctioning secretions when splashing is likely"}]'::jsonb, '["d"]', 'Under standard precautions, mask, gown, and eye protection are added if splashing is likely. The other tasks do not involve a likely splash.'),
  ('precautions', 44, 'A nurse is about to provide mouth care to a client with no known infection. Which action is appropriate under standard precautions?', '[{"id": "a", "text": "Wear gloves before touching the client''s mouth"}, {"id": "b", "text": "Wear an N95 respirator during mouth care"}, {"id": "c", "text": "Provide mouth care without gloves"}, {"id": "d", "text": "Wear gloves only if the client has MRSA"}]'::jsonb, '["a"]', 'Standard precautions include gloves when touching mucous membranes, such as the mouth, for every client. An N95 is for airborne precautions only.'),
  ('precautions', 45, 'Which statement by a nursing student about precautions indicates a need for further teaching?', '[{"id": "a", "text": "\"A client with measles needs droplet precautions.\""}, {"id": "b", "text": "\"A client with mumps needs droplet precautions.\""}, {"id": "c", "text": "\"A client with TB needs airborne precautions.\""}, {"id": "d", "text": "\"A client with VRE needs contact precautions.\""}]'::jsonb, '["a"]', 'Measles is an airborne disease (with TB and chickenpox), not droplet. Mumps is droplet, TB is airborne, and VRE is contact.'),
  ('precautions', 46, 'The charge nurse observes care for a client with active tuberculosis. Which action requires correction?', '[{"id": "a", "text": "A nurse keeps the room door closed"}, {"id": "b", "text": "A nurse enters the room wearing a surgical mask"}, {"id": "c", "text": "A nurse wears a fit-tested N95 respirator"}, {"id": "d", "text": "A nurse checks the isolation sign first"}]'::jsonb, '["b"]', 'TB requires airborne precautions with an N95 mask; a surgical mask is used for droplet precautions. Keeping the door closed, using a fit-tested N95, and checking the sign are correct.'),
  ('precautions', 47, 'A client with influenza is being taught about droplet precautions. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I''ll wear a mask when I leave my room.\""}, {"id": "b", "text": "\"I''ll wear gloves when I leave my room.\""}, {"id": "c", "text": "\"I''ll keep my door open for fresh air.\""}, {"id": "d", "text": "\"I can share a room with anyone.\""}]'::jsonb, '["a"]', 'Under droplet precautions, the client wears a mask if leaving the room. The client needs a private room or a roommate with the same infection, not just anyone.'),
  ('precautions', 48, 'The charge nurse is monitoring care for a client with mumps. Which action by a nurse requires correction?', '[{"id": "a", "text": "Wearing a surgical mask when close to the client"}, {"id": "b", "text": "Giving care at the bedside without a mask"}, {"id": "c", "text": "Keeping the client in a private room"}, {"id": "d", "text": "Having the client wear a mask during transport"}]'::jsonb, '["b"]', 'Mumps requires droplet precautions with a surgical mask when within 3 feet. A private room and having the client wear a mask when leaving are correct.'),
  ('precautions', 49, 'The nurse is evaluating a newly hired nurse on a unit with several isolation rooms. Which observation shows correct practice?', '[{"id": "a", "text": "Entering first, then asking which precautions apply"}, {"id": "b", "text": "Reading the isolation sign on the door before entering"}, {"id": "c", "text": "Putting on PPE after reaching the client''s bedside"}, {"id": "d", "text": "Recapping a used needle before placing it in the sharps box"}]'::jsonb, '["b"]', 'The isolation sign on the door is always checked before entering, and PPE is put on before entering the room. Needles are never recapped.'),
  ('precautions', 50, 'A UAP says, "I don''t need gloves to empty this client''s urinal because he looks healthy." Which response by the nurse is best?', '[{"id": "a", "text": "\"You are correct; he has no known infection.\""}, {"id": "b", "text": "\"Standard precautions apply to every client.\""}, {"id": "c", "text": "\"Gloves are needed only on contact precautions.\""}, {"id": "d", "text": "\"Use an N95 mask instead of gloves.\""}]'::jsonb, '["b"]', 'Standard precautions apply to every client even if they look healthy, and gloves are worn when touching body fluids. Gloves are not reserved only for contact precautions.'),
  ('blood', 1, 'A client with active bleeding has a critically low fibrinogen level. Which blood product does the nurse anticipate the provider will prescribe to replace fibrinogen?', '[{"id": "a", "text": "Packed red blood cells"}, {"id": "b", "text": "Cryoprecipitate"}, {"id": "c", "text": "Platelets"}, {"id": "d", "text": "Irradiated red blood cells"}]'::jsonb, '["b"]', 'Cryoprecipitate is very rich in specific clotting proteins such as fibrinogen. Platelets help blood clot, but they are cells rather than a concentrated source of fibrinogen.'),
  ('blood', 2, 'A client with a low hemoglobin reports fatigue. The provider orders a transfusion to increase the blood''s ability to carry oxygen. Which product should the nurse expect to administer?', '[{"id": "a", "text": "Platelets"}, {"id": "b", "text": "Plasma"}, {"id": "c", "text": "Packed red blood cells"}, {"id": "d", "text": "Cryoprecipitate"}]'::jsonb, '["c"]', 'Packed red blood cells replace red blood cells, which carry oxygen. Plasma, platelets, and cryoprecipitate are given for clotting needs, not oxygen-carrying capacity.'),
  ('blood', 3, 'A client with a very low platelet count is about to receive a platelet transfusion and asks what it will do. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"These cells will carry oxygen to your tissues.\""}, {"id": "b", "text": "\"These cells will help your blood clot.\""}, {"id": "c", "text": "\"These cells will help you fight infection.\""}, {"id": "d", "text": "\"This product will control your water balance.\""}]'::jsonb, '["b"]', 'Platelets are cells that help blood clot. Carrying oxygen is the role of red blood cells, and fighting infection is the role of white blood cells.'),
  ('blood', 4, 'A nursing student asks the nurse to describe plasma before it is transfused to a client. Which description is accurate?', '[{"id": "a", "text": "Blood treated with radiation for weak immune systems"}, {"id": "b", "text": "Red blood cells packed together to carry oxygen"}, {"id": "c", "text": "The liquid part of blood that contains clotting factors"}, {"id": "d", "text": "Cells that must be refrigerated to fight infection"}]'::jsonb, '["c"]', 'Plasma is the liquid part of blood and contains clotting factors. Red blood cells that carry oxygen describe packed red blood cells, and radiation-treated blood describes irradiated blood.'),
  ('blood', 5, 'The nurse is preparing to administer a unit of packed red blood cells. Which finding requires the nurse to hold the transfusion?', '[{"id": "a", "text": "No provider prescription for the transfusion is in the chart"}, {"id": "b", "text": "The type and crossmatch has been completed by the lab"}, {"id": "c", "text": "The client has signed the transfusion consent form"}, {"id": "d", "text": "Baseline vital signs have been taken and recorded"}]'::jsonb, '["a"]', 'A provider''s order (prescription) is required before giving blood. A completed type and crossmatch, signed consent, and baseline vital signs are all expected pre-checks, not reasons to hold the unit.'),
  ('blood', 6, 'Before a transfusion, the nurse confirms a provider prescription, a completed type and crossmatch, baseline vital signs, and an 18-gauge IV. Which pre-administration requirement is still needed?', '[{"id": "a", "text": "Refrigeration of the platelet unit"}, {"id": "b", "text": "Tubing primed with dextrose 5% in water"}, {"id": "c", "text": "The ordered antibiotic added to the unit"}, {"id": "d", "text": "A consent form signed by the client"}]'::jsonb, '["d"]', 'A signed consent form showing the client agrees is one of the required pre-checks. Only normal saline is used to prime the tubing, no medications go into the blood line, and platelets are stored at room temperature.'),
  ('blood', 7, 'A client scheduled for a transfusion asks why blood was drawn for a type and crossmatch. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It finds donor blood that matches your blood.\""}, {"id": "b", "text": "\"It measures how long your blood takes to clot.\""}, {"id": "c", "text": "\"It checks how well your kidneys are working.\""}, {"id": "d", "text": "\"It measures how much oxygen is in your blood.\""}]'::jsonb, '["a"]', 'A type and crossmatch is a lab test to find matching donor blood. Clotting time is measured by coagulation studies such as PT and aPTT, and kidney function by BUN and creatinine.'),
  ('blood', 8, 'Before starting a prescribed unit of packed red blood cells, the nurse finds that the client has developed a fever. Which action should the nurse take?', '[{"id": "a", "text": "Start the blood slowly for the first 15 minutes"}, {"id": "b", "text": "Call the provider before giving the blood"}, {"id": "c", "text": "Begin the blood and recheck the temperature in 1 hour"}, {"id": "d", "text": "Start the blood and stay with the client"}]'::jsonb, '["b"]', 'If a fever is present before starting, the nurse calls the provider before giving the blood. Starting the transfusion slowly or staying with the client does not address a fever that is present before the blood is hung.'),
  ('blood', 9, 'Which statement by a newly hired nurse about pre-transfusion assessment indicates a need for further teaching?', '[{"id": "a", "text": "\"I will check blood pressure, heart rate, and respirations first.\""}, {"id": "b", "text": "\"I will take the client''s temperature before I start the blood.\""}, {"id": "c", "text": "\"If the client has a fever, I will start the blood and watch closely.\""}, {"id": "d", "text": "\"I need a signed consent form before I hang the unit.\""}]'::jsonb, '["c"]', 'A fever before starting means the nurse calls the provider before giving blood, so starting the blood needs correction. Taking temperature, blood pressure, heart rate, and respiratory rate and confirming signed consent are correct pre-checks.'),
  ('blood', 10, 'Which set of data must the nurse obtain from the client immediately before starting a blood transfusion?', '[{"id": "a", "text": "Pain score, bowel sounds, skin turgor, reflexes"}, {"id": "b", "text": "Weight, height, blood glucose, urine output"}, {"id": "c", "text": "Temperature, blood pressure, heart rate, respiratory rate"}, {"id": "d", "text": "Pupil size, grip strength, gait, orientation"}]'::jsonb, '["c"]', 'Vital signs, meaning temperature, blood pressure, heart rate, and respiratory rate, are taken before starting a transfusion. The other sets are not the required pre-transfusion vital signs.'),
  ('blood', 11, 'The nurse is establishing IV access for a client who will receive packed red blood cells. Which catheter is most appropriate?', '[{"id": "a", "text": "27-gauge butterfly needle"}, {"id": "b", "text": "24-gauge catheter"}, {"id": "c", "text": "26-gauge catheter"}, {"id": "d", "text": "18-gauge catheter"}]'::jsonb, '["d"]', 'Blood is usually given through a large-bore IV of 18 or 20 gauge. The other choices are not the large-bore 18- or 20-gauge access recommended for transfusion.'),
  ('blood', 12, 'Two nurses are checking a unit of packed red blood cells together at the bedside. Which items must they verify?', '[{"id": "a", "text": "Right surgeon, right procedure, and right site"}, {"id": "b", "text": "Right room, right diet, and right activity level"}, {"id": "c", "text": "Right pharmacy, right dose, and right diluent"}, {"id": "d", "text": "Right patient, right blood type, and right unit"}]'::jsonb, '["d"]', 'The blood product is checked with another nurse for the right patient, right blood type, and right unit. The other combinations are not part of the blood product check.'),
  ('blood', 13, 'The charge nurse observes a nurse preparing to hang a unit of blood. Which action by the nurse requires correction?', '[{"id": "a", "text": "Priming the tubing with 0.9% sodium chloride"}, {"id": "b", "text": "Checking the blood type with a second nurse"}, {"id": "c", "text": "Verifying the unit alone to save time"}, {"id": "d", "text": "Taking a full set of vital signs before starting"}]'::jsonb, '["c"]', 'Identification and blood type must be checked carefully with two-nurse verification, so checking alone is unsafe. Priming with 0.9% normal saline and taking vital signs before starting are correct actions.'),
  ('blood', 14, 'The nurse begins a unit of packed red blood cells. How should the nurse manage the infusion during the first 15 minutes?', '[{"id": "a", "text": "Run it very slowly while watching for a reaction"}, {"id": "b", "text": "Run it at a fast rate so it finishes sooner"}, {"id": "c", "text": "Run it at the full rate and return in 1 hour"}, {"id": "d", "text": "Run it at a moderate rate while helping others"}]'::jsonb, '["a"]', 'The first 15 minutes are run very slowly while the nurse watches for transfusion reactions. Running it fast or leaving the client ignores the fact that most reactions occur early.'),
  ('blood', 15, 'The nurse started a client''s blood transfusion 3 minutes ago when another client asks for help to the bathroom. Which action is most appropriate?', '[{"id": "a", "text": "Stay with the transfusing client and ask another staff member to help"}, {"id": "b", "text": "Leave the transfusing client briefly, since reactions tend to occur late"}, {"id": "c", "text": "Increase the blood rate first, then go to assist the other client"}, {"id": "d", "text": "Tell the transfusing client to call if any symptoms develop, then leave"}]'::jsonb, '["a"]', 'The nurse must stay with the client for the first 15 minutes because most reactions occur early. Leaving because reactions supposedly occur late reverses this rule.'),
  ('blood', 16, 'A nursing student asks why the nurse remains at the bedside at the start of every blood transfusion. Which response is accurate?', '[{"id": "a", "text": "\"Medications must be added to the tubing.\""}, {"id": "b", "text": "\"The unit must finish within 15 minutes.\""}, {"id": "c", "text": "\"Reactions usually occur in the last hour.\""}, {"id": "d", "text": "\"Most transfusion reactions occur early.\""}]'::jsonb, '["d"]', 'The nurse stays for the first 15 minutes because most reactions occur early. The unit is infused within 4 hours, not 15 minutes, and medications are never added to blood tubing.'),
  ('blood', 17, 'A unit of packed red blood cells was started at 0900. By what time must the infusion be completed?', '[{"id": "a", "text": "1000"}, {"id": "b", "text": "1300"}, {"id": "c", "text": "1100"}, {"id": "d", "text": "1500"}]'::jsonb, '["b"]', 'Blood must be infused within 4 hours maximum, so a unit started at 0900 must finish by 1300. Finishing at 1500 would exceed the 4-hour limit.'),
  ('blood', 18, 'A nurse explains to a student why a unit of blood must not hang longer than 4 hours. Which explanation is accurate?', '[{"id": "a", "text": "\"The blood loses its blood type after 4 hours.\""}, {"id": "b", "text": "\"Bacteria can grow in the blood if it hangs longer.\""}, {"id": "c", "text": "\"Platelets turn into red cells after 4 hours.\""}, {"id": "d", "text": "\"The client must receive medications by then.\""}]'::jsonb, '["b"]', 'Blood is infused within 4 hours and never longer because of the risk of bacteria growing. The other explanations are not reasons given for the time limit.'),
  ('blood', 19, 'Which IV solution should the nurse use to prime the tubing for a blood transfusion?', '[{"id": "a", "text": "Dextrose 5% in water"}, {"id": "b", "text": "0.9% sodium chloride"}, {"id": "c", "text": "Lactated Ringer''s"}, {"id": "d", "text": "0.45% sodium chloride"}]'::jsonb, '["b"]', 'Only normal saline (0.9% sodium chloride) is used to prime and flush the IV for a transfusion. Other IV solutions are not used with blood.'),
  ('blood', 20, 'A nurse is observed setting up a blood transfusion. Which action requires correction?', '[{"id": "a", "text": "Using an 18-gauge IV catheter for the transfusion"}, {"id": "b", "text": "Checking the unit with a second nurse at the bedside"}, {"id": "c", "text": "Taking vital signs before the transfusion begins"}, {"id": "d", "text": "Priming the blood tubing with dextrose 5% in water"}]'::jsonb, '["d"]', 'Only normal saline (0.9% sodium chloride) may be used to prime and flush the IV during a transfusion. Two-nurse checks, baseline vital signs, and an 18-gauge IV are correct.'),
  ('blood', 21, 'A client receiving packed red blood cells through the only IV line is due for an IV antibiotic. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Piggyback the antibiotic into the blood line slowly"}, {"id": "b", "text": "Inject the antibiotic into the blood tubing port"}, {"id": "c", "text": "Add the antibiotic directly into the unit of blood"}, {"id": "d", "text": "Avoid giving the antibiotic through the blood tubing"}]'::jsonb, '["d"]', 'No medications are given in the same IV line during a transfusion. Injecting, adding, or piggybacking the drug into the blood line all violate this rule.'),
  ('blood', 22, 'Ten minutes into a transfusion of packed red blood cells, the client reports chills and back pain. What is the nurse''s first action?', '[{"id": "a", "text": "Notify the provider"}, {"id": "b", "text": "Stop the transfusion"}, {"id": "c", "text": "Slow the transfusion rate"}, {"id": "d", "text": "Recheck vital signs in 15 minutes"}]'::jsonb, '["b"]', 'Chills and back pain are signs of a transfusion reaction, and the transfusion is stopped immediately. Notifying the provider follows stopping the blood and starting normal saline with new tubing.'),
  ('blood', 23, 'The nurse is monitoring a client during a blood transfusion. Which finding suggests a transfusion reaction?', '[{"id": "a", "text": "Temperature unchanged from baseline"}, {"id": "b", "text": "Heart rate slower than baseline"}, {"id": "c", "text": "Warm, dry skin with no complaints"}, {"id": "d", "text": "Dark-colored urine"}]'::jsonb, '["d"]', 'Dark urine (hemoglobinuria) from breakdown of red cells is a sign of a transfusion reaction. A reaction causes a fast heart rate (tachycardia) and fever, not a slower heart rate or unchanged temperature.'),
  ('blood', 24, 'Which change in vital signs during a blood transfusion should the nurse recognize as a possible transfusion reaction?', '[{"id": "a", "text": "Blood pressure falls and heart rate rises"}, {"id": "b", "text": "Blood pressure rises and heart rate falls"}, {"id": "c", "text": "Blood pressure rises and heart rate rises"}, {"id": "d", "text": "Blood pressure falls and heart rate falls"}]'::jsonb, '["a"]', 'Hypotension (low blood pressure) and tachycardia (fast heart rate) are signs of a transfusion reaction. The other combinations reverse one or both directions.'),
  ('blood', 25, 'During a transfusion, a client''s urine becomes dark. The nurse understands this finding reflects which process?', '[{"id": "a", "text": "Excess platelets passing into urine"}, {"id": "b", "text": "Clearing of the saline flush"}, {"id": "c", "text": "Expected effect of irradiated blood"}, {"id": "d", "text": "Breakdown of red blood cells"}]'::jsonb, '["d"]', 'Dark urine during a transfusion is hemoglobinuria caused by breakdown of red cells, a sign of a transfusion reaction. It is not an expected or harmless finding.'),
  ('blood', 26, 'The nurse has just stopped a blood transfusion because the client developed difficulty breathing. Which action should the nurse take next?', '[{"id": "a", "text": "Flush the blood tubing with dextrose"}, {"id": "b", "text": "Start normal saline using new tubing"}, {"id": "c", "text": "Restart the blood at a slower rate"}, {"id": "d", "text": "Hang a new unit through the same line"}]'::jsonb, '["b"]', 'After stopping the transfusion, the nurse starts normal saline with new tubing. Restarting blood or using the blood tubing would continue exposure to the product.'),
  ('blood', 27, 'After stopping a transfusion for a suspected reaction, which action by the nurse requires correction?', '[{"id": "a", "text": "Remaining with the client to continue monitoring"}, {"id": "b", "text": "Starting normal saline through a new set of tubing"}, {"id": "c", "text": "Running normal saline through the existing blood tubing"}, {"id": "d", "text": "Notifying the provider about the client''s symptoms"}]'::jsonb, '["c"]', 'Normal saline is started with new tubing after a suspected reaction, not through the tubing that held blood. Staying with the client and notifying the provider are correct steps.'),
  ('blood', 28, 'A client receiving blood develops fever, chills, and tachycardia. Which sequence of nursing actions is correct?', '[{"id": "a", "text": "Stop transfusion, start saline with new tubing, notify provider"}, {"id": "b", "text": "Notify provider, stop transfusion, start saline with new tubing"}, {"id": "c", "text": "Start saline through blood tubing, stop transfusion, notify provider"}, {"id": "d", "text": "Slow transfusion, notify provider, stop transfusion if worse"}]'::jsonb, '["a"]', 'The transfusion is stopped first, then normal saline is started with new tubing, and the provider is notified while the nurse stays with the client. Calling first or slowing the blood delays stopping the transfusion.'),
  ('blood', 29, 'The nurse stopped a transfusion, started normal saline with new tubing, and notified the provider about the client''s chills and back pain. Which action is most appropriate now?', '[{"id": "a", "text": "Hang a new unit of blood at a slower rate"}, {"id": "b", "text": "Leave to obtain the next unit from the blood bank"}, {"id": "c", "text": "Restart the blood now that the provider knows"}, {"id": "d", "text": "Stay with the client and continue monitoring"}]'::jsonb, '["d"]', 'When a reaction is suspected, the nurse stays with the client. Restarting or hanging more blood is unsafe because the transfusion is stopped when a reaction is suspected.'),
  ('blood', 30, 'Which statement by a new nurse about managing a suspected transfusion reaction indicates a need for further teaching?', '[{"id": "a", "text": "\"I will stop the transfusion right away if I suspect a reaction.\""}, {"id": "b", "text": "\"If chills begin, I will slow the blood and keep it running.\""}, {"id": "c", "text": "\"I will start normal saline using a new set of tubing.\""}, {"id": "d", "text": "\"I will stay with the client and notify the provider.\""}]'::jsonb, '["b"]', 'Chills are a reaction sign, and the transfusion must be stopped immediately, not slowed and continued. The other statements reflect the correct stop, saline with new tubing, stay, and notify steps.'),
  ('blood', 31, 'At the start of the shift, the nurse reviews four clients on the unit. Which client should the nurse assess first?', '[{"id": "a", "text": "A client whose transfusion ended 2 hours ago with stable vitals"}, {"id": "b", "text": "A client asking for written discharge instructions"}, {"id": "c", "text": "A client whose blood transfusion was started 5 minutes ago"}, {"id": "d", "text": "A client requesting help choosing tomorrow''s menu"}]'::jsonb, '["c"]', 'The nurse stays with a transfusing client for the first 15 minutes because most reactions occur early. A client whose transfusion ended hours ago with stable vital signs is lower priority.'),
  ('blood', 32, 'A unit of platelets is delivered to the nursing unit for a client. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Place it in the unit refrigerator until needed"}, {"id": "b", "text": "Keep it at room temperature and give it promptly"}, {"id": "c", "text": "Store it in the freezer until the next shift"}, {"id": "d", "text": "Leave it at the bedside to hang late in the shift"}]'::jsonb, '["b"]', 'Platelets are stored at room temperature and must be used quickly. Refrigeration (cold storage) applies to packed red blood cells, not platelets.'),
  ('blood', 33, 'A nurse is reviewing storage requirements for blood products. Which statement is accurate?', '[{"id": "a", "text": "Platelets may be held without any time limit."}, {"id": "b", "text": "Platelets must be kept in cold storage."}, {"id": "c", "text": "Packed red blood cells are kept at room temperature."}, {"id": "d", "text": "Packed red blood cells must be refrigerated."}]'::jsonb, '["d"]', 'Packed red blood cells must be refrigerated in cold storage. Platelets are the product kept at room temperature, and they must be used quickly.'),
  ('blood', 34, 'The nurse reviews transfusion orders for four clients. For which client is irradiated blood most likely prescribed?', '[{"id": "a", "text": "A client taking warfarin with a high INR"}, {"id": "b", "text": "A client with a low fibrinogen level"}, {"id": "c", "text": "A client with a severely weakened immune system"}, {"id": "d", "text": "A client with a normal hemoglobin level"}]'::jsonb, '["c"]', 'Irradiated blood is treated with radiation and used for clients with weak immune systems. A low fibrinogen level is treated with cryoprecipitate.'),
  ('blood', 35, 'A client whose immune system is weakened asks what "irradiated blood" means. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is only the liquid part of blood.\""}, {"id": "b", "text": "\"It contains extra clotting proteins.\""}, {"id": "c", "text": "\"It has been treated with radiation.\""}, {"id": "d", "text": "\"It has been kept at room temperature.\""}]'::jsonb, '["c"]', 'Irradiated blood is blood treated with radiation for clients with weak immune systems. Extra clotting proteins describe cryoprecipitate, and the liquid part of blood describes plasma.'),
  ('blood', 36, 'When should the nurse obtain vital signs for a client receiving a blood transfusion?', '[{"id": "a", "text": "Before, during, and after the transfusion"}, {"id": "b", "text": "Only before the transfusion is started"}, {"id": "c", "text": "Only after the transfusion is complete"}, {"id": "d", "text": "Only at the start and the end of the unit"}]'::jsonb, '["a"]', 'Vital signs are taken before, during, and after a blood transfusion. Checking only at the start or end would miss changes such as hypotension or tachycardia during the infusion.'),
  ('blood', 37, 'A female client being evaluated for a transfusion has a hemoglobin of 8.4 g/dL. How should the nurse interpret this result?', '[{"id": "a", "text": "Below the normal range for a female"}, {"id": "b", "text": "Within the normal range for a female"}, {"id": "c", "text": "Above the normal range for a female"}, {"id": "d", "text": "At the upper limit of normal for a female"}]'::jsonb, '["a"]', 'The normal hemoglobin for a female is 12-16 g/dL, so 8.4 g/dL is below normal. It is not within or above the female range.'),
  ('blood', 38, 'A female client''s hematocrit is 31%. How should the nurse interpret this result?', '[{"id": "a", "text": "Within the normal range for a female"}, {"id": "b", "text": "Below the normal range for a female"}, {"id": "c", "text": "Above the normal range for a female"}, {"id": "d", "text": "Within the normal range for a male"}]'::jsonb, '["b"]', 'The normal hematocrit for a female is 37-47%, so 31% is below normal. It is also below the male range of 42-52%.'),
  ('blood', 39, 'The nurse is reviewing a client''s morning laboratory results. Which result should the nurse report as outside the normal range?', '[{"id": "a", "text": "Hemoglobin 13 g/dL (female)"}, {"id": "b", "text": "White blood cells 7,500/mm³"}, {"id": "c", "text": "Platelets 62,000/mm³"}, {"id": "d", "text": "Fasting glucose 88 mg/dL"}]'::jsonb, '["c"]', 'Normal platelets are 150,000-400,000/mm³, so 62,000/mm³ is low. White blood cells of 7,500/mm³, a female hemoglobin of 13 g/dL, and fasting glucose of 88 mg/dL are within normal ranges.'),
  ('blood', 40, 'A client taking warfarin has an INR of 4.8. Which concern should the nurse identify?', '[{"id": "a", "text": "Normal clotting ability"}, {"id": "b", "text": "Increased risk of clotting"}, {"id": "c", "text": "Expected therapeutic effect"}, {"id": "d", "text": "Increased risk of bleeding"}]'::jsonb, '["d"]', 'The expected INR on warfarin is 2-3, and a high INR means bleeding risk. A low INR, not a high one, indicates clotting risk.'),
  ('blood', 41, 'A client taking warfarin has an INR of 2.4. How should the nurse interpret this result?', '[{"id": "a", "text": "Too high, indicating a high bleed risk"}, {"id": "b", "text": "Too low, indicating a high clot risk"}, {"id": "c", "text": "Within the expected range for warfarin"}, {"id": "d", "text": "Normal for a client not on warfarin"}]'::jsonb, '["c"]', 'The INR goal is 2-3 for a client on warfarin, so 2.4 is expected. The normal INR without warfarin is 0.8-1.1, so 2.4 would not be normal for a client not taking it.'),
  ('blood', 42, 'Which statement by a nursing student about the INR indicates correct understanding?', '[{"id": "a", "text": "\"A high INR means a higher risk of clots.\""}, {"id": "b", "text": "\"A low INR means a higher risk of clots.\""}, {"id": "c", "text": "\"A low INR means a higher risk of bleeding.\""}, {"id": "d", "text": "\"The INR is a test of kidney function.\""}]'::jsonb, '["b"]', 'A low INR indicates clot risk and a high INR indicates bleed risk. Kidney function is measured by BUN and creatinine, not the INR.'),
  ('blood', 43, 'The nurse reviews a client''s coagulation and blood count results. Which result is outside the normal range?', '[{"id": "a", "text": "PT 19 seconds"}, {"id": "b", "text": "PT 12 seconds"}, {"id": "c", "text": "INR 1.0"}, {"id": "d", "text": "Platelets 250,000/mm³"}]'::jsonb, '["a"]', 'The normal prothrombin time is 11-13.5 seconds, so 19 seconds is prolonged. A PT of 12 seconds, an INR of 1.0, and platelets of 250,000/mm³ are normal.'),
  ('blood', 44, 'A client''s white blood cell count is 16,500/mm³. How should the nurse interpret this result?', '[{"id": "a", "text": "Above normal; WBCs carry oxygen"}, {"id": "b", "text": "Below normal; WBCs fight infection"}, {"id": "c", "text": "Above normal; WBCs fight infection"}, {"id": "d", "text": "Within normal; WBCs help blood clot"}]'::jsonb, '["c"]', 'The normal WBC count is 5,000-10,000/mm³, so 16,500/mm³ is above normal, and white blood cells fight infection. Carrying oxygen is the role of red blood cells, and clotting is the role of platelets.'),
  ('blood', 45, 'A client''s creatinine level is elevated on a basic metabolic panel. Which body function should the nurse recognize is reflected by this test?', '[{"id": "a", "text": "Kidney function"}, {"id": "b", "text": "Blood clotting"}, {"id": "c", "text": "Oxygen transport"}, {"id": "d", "text": "Water balance"}]'::jsonb, '["a"]', 'Creatinine, like BUN, reflects kidney function. Water balance is the role of sodium, and oxygen transport relates to hemoglobin.'),
  ('blood', 46, 'The nurse is reviewing a client''s arterial blood gas. Which value reflects the acidity or alkalinity of the blood?', '[{"id": "a", "text": "pH"}, {"id": "b", "text": "PaCO₂"}, {"id": "c", "text": "HCO₃⁻"}, {"id": "d", "text": "SaO₂"}]'::jsonb, '["a"]', 'The pH reflects blood acidity/alkalinity. PaCO₂ reflects carbon dioxide level (respiratory control), and SaO₂ is the percentage of hemoglobin carrying oxygen.'),
  ('blood', 47, 'A client''s fasting blood glucose is 142 mg/dL. How should the nurse interpret this result?', '[{"id": "a", "text": "At the low end of normal"}, {"id": "b", "text": "Within the normal fasting range"}, {"id": "c", "text": "Below the normal fasting range"}, {"id": "d", "text": "Above the normal fasting range"}]'::jsonb, '["d"]', 'The normal fasting glucose is 70-100 mg/dL, so 142 mg/dL is above normal. It is not within or below that range.'),
  ('blood', 48, 'A client receiving packed red blood cells asks what the hemoglobin test measures. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The cells that help you fight infection.\""}, {"id": "b", "text": "\"The time it takes for blood to clot.\""}, {"id": "c", "text": "\"The protein in blood that carries oxygen.\""}, {"id": "d", "text": "\"The mineral that controls water balance.\""}]'::jsonb, '["c"]', 'Hemoglobin is the oxygen-carrying protein. Clotting time is measured by PT and aPTT, and sodium controls water balance.'),
  ('blood', 49, 'The nurse wants to know what percentage of a client''s hemoglobin is carrying oxygen. Which value should the nurse review?', '[{"id": "a", "text": "SaO₂"}, {"id": "b", "text": "PaCO₂"}, {"id": "c", "text": "HCO₃⁻"}, {"id": "d", "text": "aPTT"}]'::jsonb, '["a"]', 'SaO₂ (oxygen saturation) is the percentage of hemoglobin carrying oxygen. PaCO₂ reflects carbon dioxide level, and aPTT is a clotting test.'),
  ('blood', 50, 'A male client''s hemoglobin is 15.2 g/dL. How should the nurse interpret this result?', '[{"id": "a", "text": "Below the normal range for a male"}, {"id": "b", "text": "Within the normal range for a male"}, {"id": "c", "text": "Above the normal range for a male"}, {"id": "d", "text": "Critically low for a male"}]'::jsonb, '["b"]', 'The normal hemoglobin for a male is 14-18 g/dL, so 15.2 g/dL is normal. It is not below or above that range.'),
  ('head_to_toe', 1, 'A nurse is about to perform an admission assessment on a client sitting in a chair. When does the general survey portion of the assessment begin?', '[{"id": "a", "text": "After the vital signs are obtained"}, {"id": "b", "text": "The moment the nurse first sees the client"}, {"id": "c", "text": "After the nurse palpates the head and neck"}, {"id": "d", "text": "Once the client is positioned on the exam table"}]'::jsonb, '["b"]', 'The general survey starts the moment the nurse sees the patient, before any physical contact. It is not delayed until after vital signs or palpation.'),
  ('head_to_toe', 2, 'During the general survey of a newly admitted client, which action is appropriate for the nurse to perform?', '[{"id": "a", "text": "Palpating the cervical lymph nodes"}, {"id": "b", "text": "Percussing the posterior chest"}, {"id": "c", "text": "Observing the client''s gait and use of a walker"}, {"id": "d", "text": "Auscultating bowel sounds in all quadrants"}]'::jsonb, '["c"]', 'The general survey is done before touching the patient and includes mobility, such as gait and use of assistive devices. Palpation, percussion, and auscultation involve contact and occur in later system assessments.'),
  ('head_to_toe', 3, 'A client is admitted to the medical unit, and the nurse performs a complete initial examination. Which type of assessment is the nurse performing?', '[{"id": "a", "text": "Comprehensive"}, {"id": "b", "text": "Focused"}, {"id": "c", "text": "Ongoing"}, {"id": "d", "text": "General survey only"}]'::jsonb, '["a"]', 'A comprehensive assessment is the complete admission or initial examination. A focused assessment targets a specific system or problem, and an ongoing assessment is a shift assessment.'),
  ('head_to_toe', 4, 'A client who was admitted yesterday suddenly reports new pain in the right ear. Which type of assessment should the nurse perform?', '[{"id": "a", "text": "Comprehensive assessment"}, {"id": "b", "text": "Admission assessment"}, {"id": "c", "text": "Discharge assessment"}, {"id": "d", "text": "Focused assessment"}]'::jsonb, '["d"]', 'A focused assessment evaluates a specific system or problem, such as new ear pain. A comprehensive assessment is a complete admission or initial examination.'),
  ('head_to_toe', 5, 'At the start of the shift, a nurse assesses each assigned client to monitor for changes since the previous shift. Which type of assessment is this?', '[{"id": "a", "text": "Focused"}, {"id": "b", "text": "Ongoing"}, {"id": "c", "text": "Comprehensive"}, {"id": "d", "text": "Initial"}]'::jsonb, '["b"]', 'An ongoing assessment is a shift assessment or monitoring for changes. A comprehensive assessment is the complete admission or initial examination.'),
  ('head_to_toe', 6, 'A nurse completes the general survey of a client during a head-to-toe assessment. Which step should the nurse perform next?', '[{"id": "a", "text": "Assess the abdomen"}, {"id": "b", "text": "Assess the neurological system"}, {"id": "c", "text": "Obtain the vital signs"}, {"id": "d", "text": "Inspect the skin, hair, and nails"}]'::jsonb, '["c"]', 'In the step-by-step guide, vital signs follow the general survey, and the head and face come next. The abdomen, neurological system, and skin are assessed later in the sequence.'),
  ('head_to_toe', 7, 'A nurse is assessing a client''s respiratory system. After inspecting the chest, which technique should the nurse use next?', '[{"id": "a", "text": "Auscultation"}, {"id": "b", "text": "Percussion"}, {"id": "c", "text": "Palpation"}, {"id": "d", "text": "Inspection of the abdomen"}]'::jsonb, '["c"]', 'The standard order is inspect, palpate, percuss, then auscultate, so palpation of the chest follows inspection. Auscultation comes last for the chest.'),
  ('head_to_toe', 8, 'A nurse is preparing to assess the abdomen of a client. Which sequence should the nurse follow?', '[{"id": "a", "text": "Inspect, palpate, percuss, auscultate"}, {"id": "b", "text": "Inspect, auscultate, percuss, palpate"}, {"id": "c", "text": "Auscultate, inspect, palpate, percuss"}, {"id": "d", "text": "Palpate, percuss, auscultate, inspect"}]'::jsonb, '["b"]', 'The abdomen is the exception to the standard order: inspect, auscultate, percuss, then palpate. Inspect, palpate, percuss, auscultate is the standard order used for other areas.'),
  ('head_to_toe', 9, 'A nursing student asks why the abdomen is auscultated before it is palpated. Which response by the nurse is correct?', '[{"id": "a", "text": "To avoid altering the bowel sounds"}, {"id": "b", "text": "To reduce the client''s risk of falling"}, {"id": "c", "text": "To check the gag reflex first"}, {"id": "d", "text": "To keep the abdomen from cooling"}]'::jsonb, '["a"]', 'The nurse auscultates the abdomen before palpation to avoid altering bowel sounds. The other responses do not explain the abdominal exception.'),
  ('head_to_toe', 10, 'A nurse observes a student assessing a client''s abdomen. Which action by the student requires correction?', '[{"id": "a", "text": "Inspecting the abdomen for scars and distention"}, {"id": "b", "text": "Listening for bowel sounds in all quadrants"}, {"id": "c", "text": "Palpating for tenderness before listening for bowel sounds"}, {"id": "d", "text": "Percussing the abdomen for tympany"}]'::jsonb, '["c"]', 'In the abdomen, the nurse always auscultates before palpation to avoid altering bowel sounds. Inspection, auscultation in all quadrants, and percussion for tympany are correct.'),
  ('head_to_toe', 11, 'While inspecting a client''s face, a nurse notes drooping of one side of the mouth. The nurse recognizes this finding may indicate which condition?', '[{"id": "a", "text": "Jaundice"}, {"id": "b", "text": "Otorrhea"}, {"id": "c", "text": "Stroke or Bell''s palsy"}, {"id": "d", "text": "Paralytic ileus"}]'::jsonb, '["c"]', 'Facial asymmetry may indicate stroke or Bell''s palsy. Jaundice is shown by yellow sclera, and otorrhea is ear drainage.'),
  ('head_to_toe', 12, 'A nurse is assessing a client''s head and face. Which structures does the nurse palpate during this step?', '[{"id": "a", "text": "Scalp, temporal arteries, and sinuses"}, {"id": "b", "text": "Carotid arteries, trachea, and thyroid"}, {"id": "c", "text": "Precordium, apical impulse, and ribs"}, {"id": "d", "text": "Radial, femoral, and pedal pulses"}]'::jsonb, '["a"]', 'During the head and face step, the nurse palpates for scalp tenderness, the temporal arteries, and the sinuses. Trachea alignment is palpated during the neck step.'),
  ('head_to_toe', 13, 'A nurse inspects the eyes of a healthy adult client. Which finding is expected?', '[{"id": "a", "text": "Yellow sclera"}, {"id": "b", "text": "Pink, moist conjunctiva"}, {"id": "c", "text": "Unequal pupil size"}, {"id": "d", "text": "Involuntary eye movement"}]'::jsonb, '["b"]', 'Expected findings are pink, moist conjunctiva and white sclera. Yellow sclera, unequal pupils, and involuntary eye movement are abnormal findings.'),
  ('head_to_toe', 14, 'While inspecting a client''s eyes, a nurse notes that the sclerae are yellow. How should the nurse document this finding?', '[{"id": "a", "text": "Nystagmus"}, {"id": "b", "text": "Anisocoria"}, {"id": "c", "text": "Expected finding"}, {"id": "d", "text": "Jaundice"}]'::jsonb, '["d"]', 'Yellow sclera indicates jaundice, an abnormal finding. Anisocoria refers to unequal pupils, and nystagmus refers to involuntary eye movement.'),
  ('head_to_toe', 15, 'A nurse checks a client''s pupils and finds the right pupil is 3 mm and the left pupil is 6 mm. Which term describes this finding?', '[{"id": "a", "text": "Anisocoria"}, {"id": "b", "text": "Nystagmus"}, {"id": "c", "text": "PERRLA"}, {"id": "d", "text": "Leukoplakia"}]'::jsonb, '["a"]', 'Unequal pupils are called anisocoria, an abnormal finding. PERRLA describes normal pupils that are equal, round, and reactive.'),
  ('head_to_toe', 16, 'A nurse documents "PERRLA" after assessing a client''s eyes. What does the final letter "A" in this abbreviation represent?', '[{"id": "a", "text": "Acuity"}, {"id": "b", "text": "Accommodation"}, {"id": "c", "text": "Alignment"}, {"id": "d", "text": "Anisocoria"}]'::jsonb, '["b"]', 'PERRLA stands for Pupils Equal, Round, Reactive to Light and Accommodation. Acuity is tested separately with a Snellen chart.'),
  ('head_to_toe', 17, 'A family member reports that an older client often asks people to repeat themselves. Which assessment should the nurse perform during the ear examination?', '[{"id": "a", "text": "Snellen chart"}, {"id": "b", "text": "Gag reflex check"}, {"id": "c", "text": "Heel-to-shin test"}, {"id": "d", "text": "Whisper test"}]'::jsonb, '["d"]', 'Hearing is checked with the whisper test during the ear assessment. The Snellen chart tests vision, and the gag reflex tests cranial nerves IX and X.'),
  ('head_to_toe', 18, 'A nurse inspects a client''s external ear and notes fluid draining from the ear canal. Which term describes this abnormal finding?', '[{"id": "a", "text": "Otorrhea"}, {"id": "b", "text": "Nystagmus"}, {"id": "c", "text": "Leukoplakia"}, {"id": "d", "text": "Crepitus"}]'::jsonb, '["a"]', 'Otorrhea is ear drainage, an abnormal ear finding. Leukoplakia refers to white patches in the mouth, and crepitus is a musculoskeletal finding.'),
  ('head_to_toe', 19, 'A nurse is assessing a client''s nose. Which action correctly checks nasal patency?', '[{"id": "a", "text": "Inspecting the septum with a light only"}, {"id": "b", "text": "Palpating the frontal sinuses"}, {"id": "c", "text": "Testing each nostril separately"}, {"id": "d", "text": "Asking the client to sniff once"}]'::jsonb, '["c"]', 'Patency is checked by testing both nostrils. Palpating the sinuses checks for tenderness, and inspecting the septum checks alignment rather than airflow.'),
  ('head_to_toe', 20, 'A nurse checks a client''s gag reflex during the mouth and throat assessment. Which cranial nerves is the nurse testing?', '[{"id": "a", "text": "Cranial nerves I and II"}, {"id": "b", "text": "Cranial nerves III and IV"}, {"id": "c", "text": "Cranial nerves VII and VIII"}, {"id": "d", "text": "Cranial nerves IX and X"}]'::jsonb, '["d"]', 'The gag reflex checks cranial nerves IX and X. The other pairs are not tested by the gag reflex.'),
  ('head_to_toe', 21, 'While inspecting a client''s oral mucosa, a nurse notes white patches on the inside of the cheek. Which term should the nurse use to document this finding?', '[{"id": "a", "text": "Petechiae"}, {"id": "b", "text": "Leukoplakia"}, {"id": "c", "text": "Cyanosis"}, {"id": "d", "text": "Jaundice"}]'::jsonb, '["b"]', 'Leukoplakia refers to white patches and is an abnormal mouth finding. Petechiae are small red spots, and cyanosis is a bluish color change.'),
  ('head_to_toe', 22, 'A nurse is assessing a client''s neck. Which finding should the nurse look for by inspection?', '[{"id": "a", "text": "Jugular vein distention"}, {"id": "b", "text": "Carotid bruits"}, {"id": "c", "text": "Tracheal alignment by touch"}, {"id": "d", "text": "Lymph node tenderness"}]'::jsonb, '["a"]', 'Neck inspection includes symmetry, masses, and jugular vein distention (JVD). Lymph nodes and tracheal alignment are palpated, and carotid bruits are auscultated.'),
  ('head_to_toe', 23, 'A nurse is performing head-to-toe assessments on four clients. For which client is auscultation of the carotid arteries for bruits indicated?', '[{"id": "a", "text": "A 19-year-old with a sprained ankle"}, {"id": "b", "text": "A 24-year-old with seasonal allergies"}, {"id": "c", "text": "A 68-year-old with known vascular disease"}, {"id": "d", "text": "A 30-year-old with a minor skin rash"}]'::jsonb, '["c"]', 'The carotids are auscultated for bruits if the client is older than middle age or has suspected vascular disease. The younger clients have neither indication.'),
  ('head_to_toe', 24, 'A nurse percusses a client''s posterior chest and hears dullness over the right lower lobe. How should the nurse interpret this finding?', '[{"id": "a", "text": "Normal air-filled lung tissue"}, {"id": "b", "text": "Possible fluid or consolidation"}, {"id": "c", "text": "Expected tympany of the lung"}, {"id": "d", "text": "Normal finding over the lung base"}]'::jsonb, '["b"]', 'Resonance is the normal percussion sound over the lungs, while dullness suggests fluid or consolidation. Tympany is the normal percussion sound of the abdomen, not the lungs.'),
  ('head_to_toe', 25, 'A nurse is auscultating a client''s lungs. Which approach is correct?', '[{"id": "a", "text": "Listen over the anterior chest only"}, {"id": "b", "text": "Listen over the posterior chest only"}, {"id": "c", "text": "Listen anteriorly, posteriorly, and laterally"}, {"id": "d", "text": "Listen over one side and assume symmetry"}]'::jsonb, '["c"]', 'Lung sounds are auscultated anteriorly, posteriorly, and laterally, and findings are compared bilaterally. Listening over one area only misses parts of the lungs.'),
  ('head_to_toe', 26, 'A nurse auscultates the lungs of four clients. Which finding should the nurse document as abnormal?', '[{"id": "a", "text": "Vesicular sounds"}, {"id": "b", "text": "Clear sounds bilaterally"}, {"id": "c", "text": "Equal sounds bilaterally"}, {"id": "d", "text": "Rhonchi"}]'::jsonb, '["d"]', 'Crackles, wheezes, rhonchi, and stridor are abnormal lung sounds. Lung sounds that are clear and equal bilaterally, including vesicular sounds, are normal.'),
  ('head_to_toe', 27, 'A nurse is auscultating a client''s heart. In which sequence should the nurse move through the auscultation areas?', '[{"id": "a", "text": "Mitral, tricuspid, Erb''s point, pulmonic, aortic"}, {"id": "b", "text": "Aortic, pulmonic, Erb''s point, tricuspid, mitral"}, {"id": "c", "text": "Pulmonic, aortic, mitral, tricuspid, Erb''s point"}, {"id": "d", "text": "Erb''s point, aortic, pulmonic, mitral, tricuspid"}]'::jsonb, '["b"]', 'Heart sounds are auscultated in the order aortic, pulmonic, Erb''s point, tricuspid, then mitral. Starting at the mitral area reverses the sequence.'),
  ('head_to_toe', 28, 'During the cardiovascular assessment, which finding does the nurse locate by palpation?', '[{"id": "a", "text": "Point of maximal impulse"}, {"id": "b", "text": "Jugular vein distention"}, {"id": "c", "text": "S1 and S2 heart sounds"}, {"id": "d", "text": "Carotid bruits"}]'::jsonb, '["a"]', 'The apical impulse, or point of maximal impulse (PMI), is palpated. Heart sounds and bruits are auscultated, and JVD is inspected.'),
  ('head_to_toe', 29, 'A nurse auscultates the heart of four clients. Which finding should the nurse report as abnormal?', '[{"id": "a", "text": "Clear S1"}, {"id": "b", "text": "Clear S2"}, {"id": "c", "text": "Regular \"lub-dub\""}, {"id": "d", "text": "A murmur"}]'::jsonb, '["d"]', 'S1 ("lub") and S2 ("dub") are normal heart sounds, while a murmur is abnormal. The other options describe normal findings.'),
  ('head_to_toe', 30, 'A nurse palpates a client''s dorsalis pedis pulses and grades them as 2+ bilaterally. How should the nurse interpret this finding?', '[{"id": "a", "text": "Normal pulse strength"}, {"id": "b", "text": "Absent pulses"}, {"id": "c", "text": "Bounding pulses"}, {"id": "d", "text": "Weak pulses needing follow-up"}]'::jsonb, '["a"]', 'Pulses are graded on a 0–4+ scale, and 2+ is normal. A 2+ grade does not indicate absent, weak, or bounding pulses.'),
  ('head_to_toe', 31, 'A nurse assesses capillary refill in a client''s fingers. Which finding should the nurse report?', '[{"id": "a", "text": "Refill in 1 second"}, {"id": "b", "text": "Refill in 1.5 seconds"}, {"id": "c", "text": "Refill in 4 seconds"}, {"id": "d", "text": "Refill in less than 2 seconds"}]'::jsonb, '["c"]', 'A capillary refill of less than 2 seconds is normal, so a refill time of 4 seconds is abnormal. The other times are within the normal limit.'),
  ('head_to_toe', 32, 'A nurse is assessing peripheral pulses in a client''s lower extremities. Which pulse is located on the foot?', '[{"id": "a", "text": "Brachial"}, {"id": "b", "text": "Radial"}, {"id": "c", "text": "Popliteal"}, {"id": "d", "text": "Dorsalis pedis"}]'::jsonb, '["d"]', 'The peripheral pulses assessed include the radial, brachial, femoral, popliteal, posterior tibial, and dorsalis pedis; the dorsalis pedis is the foot pulse. The popliteal pulse is behind the knee.'),
  ('head_to_toe', 33, 'A nurse auscultates a client''s abdomen and counts 18 bowel sounds per minute in each quadrant. How should the nurse interpret this finding?', '[{"id": "a", "text": "Within the normal range"}, {"id": "b", "text": "Absent bowel sounds"}, {"id": "c", "text": "A sign of ileus"}, {"id": "d", "text": "Too few to be normal"}]'::jsonb, '["a"]', 'Bowel sounds of 5–30 per minute in all quadrants are normal. Absent bowel sounds, not 18 per minute, suggest ileus.'),
  ('head_to_toe', 34, 'A nurse completes abdominal assessments on four clients. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Flat abdominal contour"}, {"id": "b", "text": "Absent bowel sounds"}, {"id": "c", "text": "Tympany on percussion"}, {"id": "d", "text": "Soft, non-tender abdomen"}]'::jsonb, '["b"]', 'Absent bowel sounds are an abnormal finding associated with ileus. Tympany on percussion and a soft, non-tender abdomen are normal findings.'),
  ('head_to_toe', 35, 'A nurse percusses a client''s abdomen. Which percussion sound is the expected normal finding?', '[{"id": "a", "text": "Resonance"}, {"id": "b", "text": "Dullness"}, {"id": "c", "text": "Tympany"}, {"id": "d", "text": "Flatness"}]'::jsonb, '["c"]', 'Tympany is the normal abdominal percussion sound, while dullness suggests fluid or a mass. Resonance is the normal percussion sound over the lungs.'),
  ('head_to_toe', 36, 'A nurse has finished auscultating and percussing a client''s abdomen. How should the nurse proceed with palpation?', '[{"id": "a", "text": "Deep palpation only"}, {"id": "b", "text": "Light palpation, then deep palpation"}, {"id": "c", "text": "Deep palpation, then light palpation"}, {"id": "d", "text": "Skip palpation if bowel sounds are present"}]'::jsonb, '["b"]', 'The abdomen is palpated light then deep for tenderness and masses. Starting with deep palpation reverses the expected order.'),
  ('head_to_toe', 37, 'A nurse is palpating the abdomen of a client who reports abdominal pain. Which finding is abnormal?', '[{"id": "a", "text": "Soft abdomen"}, {"id": "b", "text": "Non-tender abdomen"}, {"id": "c", "text": "Rounded contour"}, {"id": "d", "text": "Guarding"}]'::jsonb, '["d"]', 'Guarding and rigidity are abnormal abdominal findings. A soft, non-tender abdomen is normal, and a rounded contour is a described contour type.'),
  ('head_to_toe', 38, 'A nurse reviews a client''s intake and output and finds a urine output of 300 mL over the past 24 hours. How should the nurse interpret this finding?', '[{"id": "a", "text": "Oliguria, which is abnormal"}, {"id": "b", "text": "Expected daily output"}, {"id": "c", "text": "Hematuria, which is abnormal"}, {"id": "d", "text": "Normal output for a resting client"}]'::jsonb, '["a"]', 'Oliguria is a urine output of less than 400 mL/day and is an abnormal finding. Hematuria refers to blood in the urine, not low volume.'),
  ('head_to_toe', 39, 'A client reports frequent urination and burning, and the urine appears red-tinged. Which abnormal genitourinary finding does the red-tinged urine suggest?', '[{"id": "a", "text": "Oliguria"}, {"id": "b", "text": "Otorrhea"}, {"id": "c", "text": "Hematuria"}, {"id": "d", "text": "Leukoplakia"}]'::jsonb, '["c"]', 'Hematuria is blood in the urine and is an abnormal genitourinary finding. Oliguria refers to low urine output.'),
  ('head_to_toe', 40, 'A client who has not voided for several hours reports lower abdominal fullness. Which genitourinary assessment is indicated?', '[{"id": "a", "text": "Palpate the bladder for distention"}, {"id": "b", "text": "Auscultate the carotid arteries"}, {"id": "c", "text": "Test the gag reflex"}, {"id": "d", "text": "Perform the whisper test"}]'::jsonb, '["a"]', 'The bladder is palpated if distention is suspected. The other assessments belong to the neck, mouth, and ear examinations.'),
  ('head_to_toe', 41, 'A nurse is testing a client''s muscle strength during the musculoskeletal assessment. Which scale should the nurse use to grade strength?', '[{"id": "a", "text": "0–4+ scale"}, {"id": "b", "text": "0–5 scale"}, {"id": "c", "text": "0–10 scale"}, {"id": "d", "text": "1–3 scale"}]'::jsonb, '["b"]', 'Strength testing uses a 0–5 scale. The 0–4+ scale is used for grading pulses and reflexes.'),
  ('head_to_toe', 42, 'A nurse performs a musculoskeletal assessment on four clients. Which finding should the nurse document as abnormal?', '[{"id": "a", "text": "Symmetric muscle bulk"}, {"id": "b", "text": "Joints without swelling"}, {"id": "c", "text": "Full active range of motion"}, {"id": "d", "text": "Crepitus"}]'::jsonb, '["d"]', 'Atrophy, contractures, and crepitus are abnormal musculoskeletal findings. Symmetric muscle bulk, joints without swelling, and full range of motion do not indicate a problem.'),
  ('head_to_toe', 43, 'A client correctly states name, the hospital name, and the date but cannot explain why the client is hospitalized. How should the nurse document orientation?', '[{"id": "a", "text": "Oriented to person, place, and time only"}, {"id": "b", "text": "Alert and oriented ×4"}, {"id": "c", "text": "Oriented to person only"}, {"id": "d", "text": "Fully oriented to situation"}]'::jsonb, '["a"]', 'Orientation is assessed to person, place, time, and situation, and alert and oriented ×4 is normal. This client is not oriented to situation, so the client is not oriented ×4.'),
  ('head_to_toe', 44, 'A client with diabetes reports numbness and tingling in both feet. Which term should the nurse use to document this neurological finding?', '[{"id": "a", "text": "Crepitus"}, {"id": "b", "text": "Paresthesia"}, {"id": "c", "text": "Nystagmus"}, {"id": "d", "text": "Atrophy"}]'::jsonb, '["b"]', 'Paresthesia means numbness or tingling and is an abnormal neurological finding. Crepitus and atrophy are musculoskeletal findings.'),
  ('head_to_toe', 45, 'A nurse assesses the skin of an older client with vomiting. Which technique does the nurse use to evaluate the client''s hydration?', '[{"id": "a", "text": "Inspecting nail color"}, {"id": "b", "text": "Palpating skin turgor"}, {"id": "c", "text": "Percussing the abdomen"}, {"id": "d", "text": "Testing the gag reflex"}]'::jsonb, '["b"]', 'During the skin assessment, the nurse palpates temperature, moisture, and turgor, which reflects hydration. Nail inspection checks for clubbing and capillary refill, not hydration.'),
  ('head_to_toe', 46, 'A nurse is inspecting the skin of a client and notes multiple small red spots on the forearms. Which term describes this finding?', '[{"id": "a", "text": "Cyanosis"}, {"id": "b", "text": "Jaundice"}, {"id": "c", "text": "Pallor"}, {"id": "d", "text": "Petechiae"}]'::jsonb, '["d"]', 'Petechiae are small red spots and are an abnormal skin finding. Cyanosis, jaundice, and pallor describe skin color changes rather than small red spots.'),
  ('head_to_toe', 47, 'A nurse assesses the radial pulses and hand grips of a client. Which approach reflects a key principle of the head-to-toe assessment?', '[{"id": "a", "text": "Assess only the dominant side"}, {"id": "b", "text": "Compare left and right sides for symmetry"}, {"id": "c", "text": "Assess the side nearest the nurse"}, {"id": "d", "text": "Skip one side if the first is normal"}]'::jsonb, '["b"]', 'The nurse always compares bilaterally, left versus right, for symmetry. Assessing only one side misses unequal findings.'),
  ('head_to_toe', 48, 'Two hours after a normal shift assessment, a client becomes suddenly short of breath. What should the nurse do?', '[{"id": "a", "text": "Wait for the next scheduled assessment"}, {"id": "b", "text": "Repeat the full admission assessment tomorrow"}, {"id": "c", "text": "Perform an immediate focused reassessment"}, {"id": "d", "text": "Document the earlier normal findings"}]'::jsonb, '["c"]', 'If the patient''s condition changes, the nurse performs an immediate focused reassessment. Waiting for the next scheduled assessment delays recognition of a problem.'),
  ('head_to_toe', 49, 'During the general survey, a nurse observes that a client is holding the chest and breathing with visible effort. How should this observation guide the nurse''s next actions?', '[{"id": "a", "text": "Ignore it until the systems review is complete"}, {"id": "b", "text": "Postpone assessment until the client rests"}, {"id": "c", "text": "Document it without further assessment"}, {"id": "d", "text": "Use it to direct a focused assessment"}]'::jsonb, '["d"]', 'Abnormal findings in the general survey may guide the nurse to do a focused assessment. Ignoring or only documenting the finding delays evaluation.'),
  ('head_to_toe', 50, 'A nurse is assessing a client''s radial pulse during the vital signs step. Which characteristics should the nurse evaluate?', '[{"id": "a", "text": "Rate, rhythm, strength, and symmetry"}, {"id": "b", "text": "Rate, depth, and effort only"}, {"id": "c", "text": "Location, intensity, and quality"}, {"id": "d", "text": "Color, moisture, and turgor"}]'::jsonb, '["a"]', 'The pulse is assessed for rate, rhythm, strength, and symmetry. Depth and effort describe respirations, and location, intensity, and quality describe pain.'),
  ('diagnosis', 1, 'A nursing student asks a preceptor what a nursing diagnosis is. Which response by the preceptor is accurate?', '[{"id": "a", "text": "It is the provider''s name for the client''s disease."}, {"id": "b", "text": "It is a clinical judgment about the client''s response to a health problem."}, {"id": "c", "text": "It is the list of the client''s prescribed treatments."}, {"id": "d", "text": "It is the laboratory test that confirms the client''s illness."}]'::jsonb, '["b"]', 'A nursing diagnosis is a clinical judgment (the nurse''s decision) about a patient''s response to a health problem. The name of the disease is a medical diagnosis, not a nursing diagnosis.'),
  ('diagnosis', 2, 'A nurse educator is reviewing nursing diagnoses with a group of students. Which statement by a student indicates a need for further teaching?', '[{"id": "a", "text": "A nursing diagnosis focuses on what the client feels or needs."}, {"id": "b", "text": "A nursing diagnosis reflects the nurse''s clinical judgment."}, {"id": "c", "text": "A nursing diagnosis addresses the client''s response to illness."}, {"id": "d", "text": "A nursing diagnosis names the client''s disease."}]'::jsonb, '["d"]', 'A nursing diagnosis is about what the patient feels or needs, not about the disease itself. Naming the disease describes a medical diagnosis.'),
  ('diagnosis', 3, 'A nurse documents: ''Acute pain related to surgical incision as evidenced by grimacing and rating pain 8/10.'' Which part of this statement is the problem?', '[{"id": "a", "text": "Acute pain"}, {"id": "b", "text": "Surgical incision"}, {"id": "c", "text": "Grimacing"}, {"id": "d", "text": "Rating pain 8/10"}]'::jsonb, '["a"]', 'The problem (P) states what is wrong, here ''Acute pain.'' The surgical incision is the etiology, and grimacing and the pain rating are the symptoms.'),
  ('diagnosis', 4, 'A client''s care plan includes: ''Impaired skin integrity related to immobility as evidenced by redness on sacrum.'' Which component identifies the etiology?', '[{"id": "a", "text": "Impaired skin integrity"}, {"id": "b", "text": "Redness on sacrum"}, {"id": "c", "text": "Immobility"}, {"id": "d", "text": "Sacrum"}]'::jsonb, '["c"]', 'The etiology (E) is what is causing the problem and follows ''related to,'' so immobility is the etiology. Redness on the sacrum follows ''as evidenced by'' and is the symptom.'),
  ('diagnosis', 5, 'A nurse writes: ''Impaired physical mobility related to pain after surgery as evidenced by refusal to walk, grimacing, slow movement.'' Which portion represents the symptoms?', '[{"id": "a", "text": "Impaired physical mobility"}, {"id": "b", "text": "Refusal to walk, grimacing, slow movement"}, {"id": "c", "text": "Pain after surgery"}, {"id": "d", "text": "Impaired physical mobility after surgery"}]'::jsonb, '["b"]', 'The symptoms (S) show how you know the problem exists and follow ''as evidenced by.'' Pain after surgery follows ''related to'' and is the etiology.'),
  ('diagnosis', 6, 'A nursing student is writing an actual nursing diagnosis. Which phrase should the student use to introduce the etiology?', '[{"id": "a", "text": "As evidenced by"}, {"id": "b", "text": "Risk for"}, {"id": "c", "text": "As manifested by the disease"}, {"id": "d", "text": "Related to"}]'::jsonb, '["d"]', 'The etiology, or what is causing the problem, is written as ''related to.'' ''As evidenced by'' introduces the symptoms.'),
  ('diagnosis', 7, 'A nurse is completing an actual nursing diagnosis and is ready to list the assessment findings that show the problem exists. Which phrase should the nurse use?', '[{"id": "a", "text": "As evidenced by"}, {"id": "b", "text": "Related to"}, {"id": "c", "text": "Risk for"}, {"id": "d", "text": "Caused by the disease"}]'::jsonb, '["a"]', 'The symptoms, or how you know, are written as ''as evidenced by.'' ''Related to'' introduces the etiology, not the findings.'),
  ('diagnosis', 8, 'A nurse reads a care plan entry: ''Risk for infection R/T surgical incision.'' What does the abbreviation R/T introduce?', '[{"id": "a", "text": "The symptoms"}, {"id": "b", "text": "The problem"}, {"id": "c", "text": "The etiology"}, {"id": "d", "text": "The medical diagnosis"}]'::jsonb, '["c"]', 'R/T is the common abbreviation for ''related to,'' which introduces the etiology. Symptoms are introduced by AEB.'),
  ('diagnosis', 9, 'A nurse reviews the entry ''Acute pain R/T surgical incision AEB grimacing.'' Which component follows the abbreviation AEB?', '[{"id": "a", "text": "The etiology"}, {"id": "b", "text": "The symptoms"}, {"id": "c", "text": "The problem"}, {"id": "d", "text": "The risk factor"}]'::jsonb, '["b"]', 'AEB stands for ''as evidenced by,'' the common abbreviation for symptoms, so grimacing is a symptom. The etiology follows R/T.'),
  ('diagnosis', 10, 'A nurse manager is auditing care plans. Which nursing diagnosis is written correctly as an actual diagnosis?', '[{"id": "a", "text": "Pneumonia related to lung infection as evidenced by secretions"}, {"id": "b", "text": "Diabetes mellitus related to altered mobility as evidenced by grimacing"}, {"id": "c", "text": "Risk for falls related to altered mobility as evidenced by a fall"}, {"id": "d", "text": "Impaired skin integrity related to immobility as evidenced by redness on sacrum"}]'::jsonb, '["d"]', 'This statement contains a nursing problem, an etiology after ''related to,'' and symptoms after ''as evidenced by.'' Pneumonia and diabetes mellitus are medical diagnoses, and a ''Risk for'' diagnosis should not include ''as evidenced by.'''),
  ('diagnosis', 11, 'A client is 1 day after abdominal surgery and has no signs of infection. Which nursing diagnosis is written correctly?', '[{"id": "a", "text": "Risk for infection related to surgical incision"}, {"id": "b", "text": "Risk for infection as evidenced by surgical incision"}, {"id": "c", "text": "Risk for infection related to incision as evidenced by redness"}, {"id": "d", "text": "Infection related to surgical incision"}]'::jsonb, '["a"]', 'A risk diagnosis uses ''Risk for'' plus the problem and etiology, with no ''as evidenced by,'' because the problem has not happened yet. Adding symptoms makes a risk diagnosis incorrect.'),
  ('diagnosis', 12, 'A charge nurse reviews nursing diagnoses written by a new nurse. Which entry requires correction?', '[{"id": "a", "text": "Acute pain related to surgical incision as evidenced by grimacing"}, {"id": "b", "text": "Risk for falls related to altered mobility"}, {"id": "c", "text": "Risk for falls related to altered mobility as evidenced by unsteady gait"}, {"id": "d", "text": "Risk for infection related to surgical incision"}]'::jsonb, '["c"]', '''Risk for'' diagnoses do not include ''as evidenced by'' because the problem has not happened yet, so this entry needs correction. The other entries follow the correct actual or risk format.'),
  ('diagnosis', 13, 'A client has a new surgical incision that is clean and dry with no signs of infection. Which nursing diagnosis is most appropriate?', '[{"id": "a", "text": "Impaired gas exchange"}, {"id": "b", "text": "Risk for infection"}, {"id": "c", "text": "Chronic pain"}, {"id": "d", "text": "Ineffective coping"}]'::jsonb, '["b"]', '''Risk for'' is added when no symptoms are showing yet but danger is there; the incision creates a higher chance of infection. Nothing in the scenario suggests trouble moving oxygen and carbon dioxide.'),
  ('diagnosis', 14, 'An older adult client has altered mobility but has not fallen during the hospital stay. Which nursing diagnosis should the nurse write?', '[{"id": "a", "text": "Impaired skin integrity related to altered mobility"}, {"id": "b", "text": "Falls related to altered mobility as evidenced by weakness"}, {"id": "c", "text": "Risk for falls as evidenced by altered mobility"}, {"id": "d", "text": "Risk for falls related to altered mobility"}]'::jsonb, '["d"]', 'A risk diagnosis is written as Risk for + problem + etiology with no symptoms, as in ''Risk for falls related to altered mobility.'' Placing altered mobility after ''as evidenced by'' wrongly adds symptoms to a risk diagnosis.'),
  ('diagnosis', 15, 'A nurse is reviewing a client''s chart. Which entry is a medical diagnosis rather than a nursing diagnosis?', '[{"id": "a", "text": "Diabetes mellitus"}, {"id": "b", "text": "Deficient fluid volume"}, {"id": "c", "text": "Risk for falls"}, {"id": "d", "text": "Ineffective coping"}]'::jsonb, '["a"]', 'Diabetes mellitus is the doctor''s diagnosis and is not a nursing diagnosis. Deficient fluid volume, Risk for falls, and Ineffective coping are nursing diagnoses.'),
  ('diagnosis', 16, 'A client admitted with pneumonia has thick secretions that are difficult to clear. Which nursing diagnosis should the nurse include in the care plan?', '[{"id": "a", "text": "Pneumonia related to secretions"}, {"id": "b", "text": "Lung infection related to pneumonia"}, {"id": "c", "text": "Ineffective airway clearance related to secretions"}, {"id": "d", "text": "Pneumonia as evidenced by secretions"}]'::jsonb, '["c"]', 'Medical diagnoses like pneumonia should never be included directly; the nurse focuses on the client''s need, such as ineffective airway clearance related to secretions. The other options use the medical diagnosis.'),
  ('diagnosis', 17, 'A nursing student writes ''Pneumonia related to lung infection'' as a nursing diagnosis. Which feedback should the instructor give?', '[{"id": "a", "text": "It needs an ''as evidenced by'' section."}, {"id": "b", "text": "It is a medical diagnosis, not a nursing diagnosis."}, {"id": "c", "text": "It should begin with ''Risk for.''"}, {"id": "d", "text": "It is correct as written."}]'::jsonb, '["b"]', '''Pneumonia related to lung infection'' is incorrect because it is a medical diagnosis. Adding symptoms would not fix it, because the problem statement itself is a disease.'),
  ('diagnosis', 18, 'A client is having trouble moving oxygen and carbon dioxide. Which nursing diagnosis best describes this problem?', '[{"id": "a", "text": "Deficient fluid volume"}, {"id": "b", "text": "Ineffective coping"}, {"id": "c", "text": "Impaired skin integrity"}, {"id": "d", "text": "Impaired gas exchange"}]'::jsonb, '["d"]', 'Impaired gas exchange means trouble moving oxygen and carbon dioxide. Deficient fluid volume refers to dehydration.'),
  ('diagnosis', 19, 'A client reports sudden pain that began after a procedure earlier today and is expected to be short-term. Which nursing diagnosis is most appropriate?', '[{"id": "a", "text": "Acute pain"}, {"id": "b", "text": "Chronic pain"}, {"id": "c", "text": "Ineffective coping"}, {"id": "d", "text": "Risk for infection"}]'::jsonb, '["a"]', 'Acute pain is sudden, short-term pain. Chronic pain is long-term, ongoing pain.'),
  ('diagnosis', 20, 'A client reports back pain that has been ongoing for several years. Which nursing diagnosis should the nurse select?', '[{"id": "a", "text": "Acute pain"}, {"id": "b", "text": "Impaired gas exchange"}, {"id": "c", "text": "Chronic pain"}, {"id": "d", "text": "Risk for falls"}]'::jsonb, '["c"]', 'Chronic pain is long-term, ongoing pain, which matches pain lasting several years. Acute pain is sudden and short-term.'),
  ('diagnosis', 21, 'A client is admitted with dehydration from not taking in enough fluids. Which nursing diagnosis best reflects this problem?', '[{"id": "a", "text": "Impaired gas exchange"}, {"id": "b", "text": "Deficient fluid volume"}, {"id": "c", "text": "Impaired skin integrity"}, {"id": "d", "text": "Ineffective coping"}]'::jsonb, '["b"]', 'Deficient fluid volume means dehydration, or not enough fluids. Impaired gas exchange refers to trouble moving oxygen and carbon dioxide.'),
  ('diagnosis', 22, 'During a skin assessment, the nurse finds an area of broken skin on a client''s heel. Which nursing diagnosis is most appropriate?', '[{"id": "a", "text": "Risk for falls"}, {"id": "b", "text": "Deficient fluid volume"}, {"id": "c", "text": "Chronic pain"}, {"id": "d", "text": "Impaired skin integrity"}]'::jsonb, '["d"]', 'Impaired skin integrity means damaged or broken skin. Risk for falls means the client is more likely to fall.'),
  ('diagnosis', 23, 'A client recently diagnosed with a serious illness is having trouble handling stress and emotions. Which nursing diagnosis should the nurse consider?', '[{"id": "a", "text": "Ineffective coping"}, {"id": "b", "text": "Acute pain"}, {"id": "c", "text": "Impaired gas exchange"}, {"id": "d", "text": "Deficient fluid volume"}]'::jsonb, '["a"]', 'Ineffective coping means trouble handling stress or emotions. Acute pain is sudden, short-term pain.'),
  ('diagnosis', 24, 'A family member asks what ''Risk for infection'' in the client''s care plan means. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The client currently has an infection."}, {"id": "b", "text": "The client''s infection is long-term and ongoing."}, {"id": "c", "text": "The client has a higher chance of infection happening."}, {"id": "d", "text": "The client''s infection has been ruled out completely."}]'::jsonb, '["c"]', 'Risk for infection means a higher chance of infection happening; the problem has not occurred yet. Saying the client currently has an infection describes an actual problem.'),
  ('diagnosis', 25, 'A nurse is explaining the diagnosis ''Risk for falls'' to a client''s daughter. Which statement by the daughter shows understanding?', '[{"id": "a", "text": "My mother fell earlier today."}, {"id": "b", "text": "My mother is more likely to fall."}, {"id": "c", "text": "My mother has broken skin from a fall."}, {"id": "d", "text": "My mother has long-term pain from a fall."}]'::jsonb, '["b"]', 'Risk for falls means the client is more likely to fall; a risk diagnosis means no symptoms yet. Saying the mother already fell describes a problem that has happened.'),
  ('diagnosis', 26, 'A nurse is writing nursing diagnoses for a client''s care plan. Which source should the nurse use for diagnosis labels?', '[{"id": "a", "text": "The provider''s list of medical diagnoses"}, {"id": "b", "text": "The client''s laboratory report"}, {"id": "c", "text": "The client''s own description of the disease"}, {"id": "d", "text": "The NANDA-I list of official terms"}]'::jsonb, '["d"]', 'Nursing diagnoses should use the NANDA-I list, and NCLEX tests only official terms. The provider''s medical diagnoses are not nursing diagnoses.'),
  ('diagnosis', 27, 'A nursing student asks what NANDA-I stands for. Which answer is correct?', '[{"id": "a", "text": "North American Nursing Diagnosis Association International"}, {"id": "b", "text": "National Association of Nursing Diagnosis Assessment International"}, {"id": "c", "text": "North American Nurses Disease Association International"}, {"id": "d", "text": "National Alliance for Nursing Data and Analysis International"}]'::jsonb, '["a"]', 'NANDA-I stands for North American Nursing Diagnosis Association International, the source of official nursing diagnosis terms. The other options are not the correct name.'),
  ('diagnosis', 28, 'A nurse is deciding whether to write an actual diagnosis or a ''Risk for'' diagnosis. When should the nurse add ''Risk for''?', '[{"id": "a", "text": "When symptoms are present and confirmed"}, {"id": "b", "text": "When the provider has made a medical diagnosis"}, {"id": "c", "text": "When no symptoms are showing yet, but danger is there"}, {"id": "d", "text": "When the problem has lasted a long time"}]'::jsonb, '["c"]', '''Risk for'' is added when no symptoms are showing yet but danger is there. When symptoms are present, an actual diagnosis with ''as evidenced by'' is written.'),
  ('diagnosis', 29, 'A nursing student asks why ''Risk for'' diagnoses do not include an ''as evidenced by'' section. Which response by the instructor is correct?', '[{"id": "a", "text": "Risk diagnoses do not need an etiology."}, {"id": "b", "text": "The problem has not happened yet."}, {"id": "c", "text": "Risk diagnoses are medical diagnoses."}, {"id": "d", "text": "The symptoms are listed in the provider''s notes."}]'::jsonb, '["b"]', '''Risk for'' diagnoses do not have ''as evidenced by'' because the problem has not happened yet. Risk diagnoses still include an etiology (Risk for + Problem + Etiology).'),
  ('diagnosis', 30, 'A nurse is teaching students the structure of an actual nursing diagnosis. Which components should the nurse include?', '[{"id": "a", "text": "Problem and etiology only"}, {"id": "b", "text": "Risk for, problem, and etiology"}, {"id": "c", "text": "Medical diagnosis, etiology, and symptoms"}, {"id": "d", "text": "Problem, etiology, and symptoms"}]'::jsonb, '["d"]', 'An actual diagnosis uses the PES format: Problem + Etiology + Symptoms. Risk for + problem + etiology is the format for a risk diagnosis.'),
  ('diagnosis', 31, 'A nurse is writing a risk nursing diagnosis. Which format should the nurse use?', '[{"id": "a", "text": "Risk for + problem + etiology"}, {"id": "b", "text": "Problem + etiology + symptoms"}, {"id": "c", "text": "Risk for + problem + symptoms"}, {"id": "d", "text": "Medical diagnosis + etiology"}]'::jsonb, '["a"]', 'A risk diagnosis is written as Risk for + Problem + Etiology with no symptoms. Problem + etiology + symptoms is the format for an actual diagnosis.'),
  ('diagnosis', 32, 'A nurse is selecting nursing diagnoses for a client''s care plan. Which principle should guide the nurse''s selection?', '[{"id": "a", "text": "Choose the provider''s disease label as the problem."}, {"id": "b", "text": "Choose problems that only the provider can treat."}, {"id": "c", "text": "Choose problems the nurse can treat or manage."}, {"id": "d", "text": "Choose the client''s laboratory diagnosis as the problem."}]'::jsonb, '["c"]', 'Nursing diagnoses focus on what the nurse can treat or manage. Using the provider''s disease label would make it a medical diagnosis.'),
  ('diagnosis', 33, 'A new nurse is reviewing how nursing diagnoses differ from medical diagnoses. Which statement by the new nurse indicates correct understanding?', '[{"id": "a", "text": "Nursing diagnoses restate the client''s disease."}, {"id": "b", "text": "Nursing diagnoses are patient problems, not diseases."}, {"id": "c", "text": "Nursing diagnoses are made by the provider."}, {"id": "d", "text": "Nursing diagnoses always include ''Risk for.''"}]'::jsonb, '["b"]', 'Nursing diagnoses are patient problems, not diseases. Only risk diagnoses begin with ''Risk for''; actual diagnoses use the PES format.'),
  ('diagnosis', 34, 'A nurse documents: ''Acute pain related to surgical incision as evidenced by grimacing and rating pain 8/10.'' How should this diagnosis be classified?', '[{"id": "a", "text": "Risk diagnosis"}, {"id": "b", "text": "Medical diagnosis"}, {"id": "c", "text": "Incomplete diagnosis missing etiology"}, {"id": "d", "text": "Actual diagnosis"}]'::jsonb, '["d"]', 'This statement includes a problem, etiology, and symptoms, so it is an actual diagnosis in PES format. A risk diagnosis would have no ''as evidenced by'' section.'),
  ('diagnosis', 35, 'A nurse is caring for a client on prolonged bed rest. Which assessment finding indicates the nurse should write an actual diagnosis rather than a risk diagnosis?', '[{"id": "a", "text": "Redness is present on the client''s sacrum."}, {"id": "b", "text": "The client is expected to remain on bed rest."}, {"id": "c", "text": "The client has a new surgical incision."}, {"id": "d", "text": "The client has altered mobility but no injury."}]'::jsonb, '["a"]', 'Redness on the sacrum is a symptom that is already present, which supports an actual diagnosis with ''as evidenced by.'' Risk diagnoses are used when no symptoms are showing yet.'),
  ('diagnosis', 36, 'A client 1 day after surgery refuses to walk, grimaces, and moves slowly because of pain. Which nursing diagnosis is written correctly for this client?', '[{"id": "a", "text": "Risk for impaired physical mobility related to pain after surgery as evidenced by refusal to walk"}, {"id": "b", "text": "Impaired physical mobility related to pain after surgery as evidenced by refusal to walk, grimacing, slow movement"}, {"id": "c", "text": "Pain after surgery related to impaired physical mobility as evidenced by refusal to walk, grimacing"}, {"id": "d", "text": "Impaired physical mobility related to refusal to walk as evidenced by pain after surgery, grimacing"}]'::jsonb, '["b"]', 'The problem is impaired physical mobility, the etiology is pain after surgery, and the symptoms are refusal to walk, grimacing, and slow movement. Option d reverses the etiology and the symptoms, and a ''Risk for'' diagnosis should not include ''as evidenced by.'''),
  ('diagnosis', 37, 'A nurse is explaining the purpose of ''Risk for'' diagnoses to a student. Which statement by the nurse is accurate?', '[{"id": "a", "text": "They describe problems that already have symptoms."}, {"id": "b", "text": "They replace the provider''s medical diagnosis."}, {"id": "c", "text": "They describe long-term, ongoing problems."}, {"id": "d", "text": "They focus on preventing a future problem."}]'::jsonb, '["d"]', '''Risk for'' means no symptoms yet and is used for future problem prevention. Problems that already have symptoms are written as actual diagnoses.'),
  ('diagnosis', 38, 'A nurse is reviewing common nursing diagnoses with a student. Which statement by the student about impaired gas exchange indicates a need for further teaching?', '[{"id": "a", "text": "It describes trouble moving oxygen and carbon dioxide."}, {"id": "b", "text": "It is a nursing diagnosis rather than a disease."}, {"id": "c", "text": "It describes dehydration from not enough fluids."}, {"id": "d", "text": "It can be written with an etiology and symptoms."}]'::jsonb, '["c"]', 'Dehydration from not enough fluids describes deficient fluid volume, not impaired gas exchange. Impaired gas exchange means trouble moving oxygen and carbon dioxide.'),
  ('diagnosis', 39, 'A nurse is teaching about pain-related nursing diagnoses. Which statement by a student indicates a need for further teaching?', '[{"id": "a", "text": "Chronic pain is sudden, short-term pain."}, {"id": "b", "text": "Acute pain is sudden, short-term pain."}, {"id": "c", "text": "Chronic pain is long-term, ongoing pain."}, {"id": "d", "text": "Acute and chronic pain are nursing diagnoses."}]'::jsonb, '["a"]', 'Chronic pain is long-term, ongoing pain; sudden, short-term pain describes acute pain. The other statements are accurate.'),
  ('diagnosis', 40, 'A nurse is checking a student''s matching of nursing diagnoses to their meanings. Which pairing is correct?', '[{"id": "a", "text": "Impaired skin integrity — trouble handling stress"}, {"id": "b", "text": "Deficient fluid volume — damaged or broken skin"}, {"id": "c", "text": "Impaired gas exchange — more likely to fall"}, {"id": "d", "text": "Ineffective coping — trouble handling stress or emotions"}]'::jsonb, '["d"]', 'Ineffective coping means trouble handling stress or emotions. Damaged or broken skin describes impaired skin integrity, not deficient fluid volume.'),
  ('diagnosis', 41, 'A client is grimacing and rates incision pain 8/10. A student writes ''Acute pain related to surgical incision.'' What should the instructor tell the student to add?', '[{"id": "a", "text": "A ''Risk for'' label"}, {"id": "b", "text": "The medical diagnosis"}, {"id": "c", "text": "The symptoms after ''as evidenced by''"}, {"id": "d", "text": "A second etiology"}]'::jsonb, '["c"]', 'Because symptoms are present, this is an actual diagnosis and needs the S component: ''as evidenced by grimacing and rating pain 8/10.'' A ''Risk for'' label is used only when no symptoms are showing yet.'),
  ('diagnosis', 42, 'A student writes ''Impaired skin integrity as evidenced by redness on sacrum'' for an immobile client. Which component is missing?', '[{"id": "a", "text": "The problem"}, {"id": "b", "text": "The etiology"}, {"id": "c", "text": "The symptoms"}, {"id": "d", "text": "The ''Risk for'' label"}]'::jsonb, '["b"]', 'The statement lacks the etiology, the cause written after ''related to'' (here, immobility). The problem and symptoms are already present, and ''Risk for'' is not used when symptoms exist.'),
  ('diagnosis', 43, 'A nurse documents ''Risk for falls related to altered mobility.'' What does ''altered mobility'' represent in this statement?', '[{"id": "a", "text": "The etiology"}, {"id": "b", "text": "The symptoms"}, {"id": "c", "text": "The problem"}, {"id": "d", "text": "The medical diagnosis"}]'::jsonb, '["a"]', 'In a risk diagnosis (Risk for + Problem + Etiology), the phrase after ''related to'' is the etiology, the cause. Risk diagnoses have no symptoms.'),
  ('diagnosis', 44, 'A nurse is caring for a client with dehydration. Which statement by a nursing student about the diagnosis ''Deficient fluid volume'' is accurate?', '[{"id": "a", "text": "It means the client has too much fluid."}, {"id": "b", "text": "It means the client has trouble with oxygen exchange."}, {"id": "c", "text": "It means the client has broken skin."}, {"id": "d", "text": "It means the client does not have enough fluids."}]'::jsonb, '["d"]', 'Deficient fluid volume means dehydration, or not enough fluids. Trouble moving oxygen and carbon dioxide describes impaired gas exchange.'),
  ('diagnosis', 45, 'A nursing student is writing a care plan for a client with heart failure. Which approach to the nursing diagnosis is correct?', '[{"id": "a", "text": "Use ''heart failure'' as the problem statement."}, {"id": "b", "text": "Focus on the client''s response, not the disease label."}, {"id": "c", "text": "Copy the provider''s diagnosis into the problem."}, {"id": "d", "text": "List the disease after ''as evidenced by.''"}]'::jsonb, '["b"]', 'Good nursing diagnoses focus on the patient''s response, not the doctor''s disease label. Using the disease as the problem would turn it into a medical diagnosis.'),
  ('diagnosis', 46, 'A client tells the nurse, ''Since I got this news, I can''t deal with the stress, and I keep breaking down.'' Which nursing diagnosis does this statement support?', '[{"id": "a", "text": "Impaired gas exchange"}, {"id": "b", "text": "Deficient fluid volume"}, {"id": "c", "text": "Impaired skin integrity"}, {"id": "d", "text": "Ineffective coping"}]'::jsonb, '["d"]', 'The client describes trouble handling stress and emotions, which is the meaning of ineffective coping. Impaired skin integrity refers to damaged or broken skin.'),
  ('diagnosis', 47, 'A nurse is writing an actual nursing diagnosis. In which order should the components be written?', '[{"id": "a", "text": "Etiology, then problem, then ''as evidenced by'' symptoms"}, {"id": "b", "text": "Problem, then ''as evidenced by'' symptoms, then ''related to'' cause"}, {"id": "c", "text": "Problem, then ''related to'' cause, then ''as evidenced by'' symptoms"}, {"id": "d", "text": "''As evidenced by'' symptoms, then problem, then ''related to'' cause"}]'::jsonb, '["c"]', 'An actual diagnosis follows PES: the problem, then the etiology written as ''related to,'' then the symptoms written as ''as evidenced by.'' Placing symptoms before the etiology reverses the format.'),
  ('diagnosis', 48, 'A nursing student says the letters PES stand for ''Problem, Etiology, Solution.'' Which correction should the instructor make?', '[{"id": "a", "text": "P stands for Prevention."}, {"id": "b", "text": "S stands for Symptoms."}, {"id": "c", "text": "E stands for Evaluation."}, {"id": "d", "text": "S stands for Severity."}]'::jsonb, '["b"]', 'PES stands for Problem, Etiology, and Symptoms, so S means Symptoms, which show how you know. P correctly stands for Problem and E for Etiology.'),
  ('diagnosis', 49, 'A nurse is teaching a student what each part of a nursing diagnosis answers. Which question does the problem component answer?', '[{"id": "a", "text": "What is causing it?"}, {"id": "b", "text": "How do you know?"}, {"id": "c", "text": "What is wrong?"}, {"id": "d", "text": "What is the disease?"}]'::jsonb, '["c"]', 'The problem (P) states what is wrong. ''What is causing it?'' is answered by the etiology, and ''How do you know?'' by the symptoms.'),
  ('diagnosis', 50, 'A nurse is reviewing four nursing diagnoses in a client''s care plan. Which one is a risk diagnosis?', '[{"id": "a", "text": "Risk for infection related to surgical incision"}, {"id": "b", "text": "Acute pain related to surgical incision as evidenced by grimacing"}, {"id": "c", "text": "Impaired skin integrity related to immobility as evidenced by redness"}, {"id": "d", "text": "Impaired physical mobility related to pain after surgery as evidenced by slow movement"}]'::jsonb, '["a"]', 'A risk diagnosis begins with ''Risk for'' and has no symptoms, because risk diagnoses mean no symptoms yet. The other options include ''as evidenced by'' and are actual diagnoses.'),
  ('vitals', 1, 'A nurse reviews the vital signs of an adult client 1 day after abdominal surgery: temperature 98.8°F, heart rate 92 bpm, respiratory rate 18/min, blood pressure 84/50 mmHg, and SpO₂ 97%. Which finding should the nurse address first?', '[{"id": "a", "text": "Temperature of 98.8°F"}, {"id": "b", "text": "Heart rate of 92 bpm"}, {"id": "c", "text": "Blood pressure of 84/50 mmHg"}, {"id": "d", "text": "SpO₂ of 97%"}]'::jsonb, '["c"]', 'A blood pressure below 90/60 mmHg places the client at risk for hypoperfusion, or inadequate blood flow to organs. The temperature, heart rate, and SpO₂ all fall within the normal adult ranges.'),
  ('vitals', 2, 'A client''s blood pressure has dropped to 82/54 mmHg. Which group of assessments is most important for the nurse to perform?', '[{"id": "a", "text": "Mental status, urine output, and skin color"}, {"id": "b", "text": "Fall history, gait, and vision"}, {"id": "c", "text": "Pain rating, coping, and sleep"}, {"id": "d", "text": "Hearing, grooming, and hygiene"}]'::jsonb, '["a"]', 'With a blood pressure below 90/60 mmHg, the nurse assesses mental status, urine output, and skin color/temperature for signs of hypoperfusion. Fall history and gait are fall-risk factors, not perfusion assessments.'),
  ('vitals', 3, 'A nurse is reviewing an adult client''s vital signs. Which value is within the expected normal range?', '[{"id": "a", "text": "Respiratory rate of 24 breaths/min"}, {"id": "b", "text": "Heart rate of 108 bpm"}, {"id": "c", "text": "Temperature of 100.6°F"}, {"id": "d", "text": "Oxygen saturation of 96%"}]'::jsonb, '["d"]', 'Normal oxygen saturation is 95–100%. A respiratory rate above 20, a heart rate above 100, and a temperature above 99.5°F are all outside the normal adult ranges.'),
  ('vitals', 4, 'A client has a temperature of 101.2°F. The provider prescribes blood cultures and an IV antibiotic. Which action should the nurse take first?', '[{"id": "a", "text": "Start the IV antibiotic"}, {"id": "b", "text": "Collect the blood cultures"}, {"id": "c", "text": "Recheck the temperature in 4 hours"}, {"id": "d", "text": "Apply cold therapy to the client"}]'::jsonb, '["b"]', 'Cultures must be collected before antibiotics are started. Giving the antibiotic first is the tempting but incorrect choice.'),
  ('vitals', 5, 'A client 2 days after surgery has a new temperature of 101°F. Which data should the nurse review to evaluate this finding?', '[{"id": "a", "text": "WBC count and possible source of infection"}, {"id": "b", "text": "Fall history and use of assistive devices"}, {"id": "c", "text": "FLACC score and consolability"}, {"id": "d", "text": "Hearing and vision deficits"}]'::jsonb, '["a"]', 'A temperature above 100.4°F suggests possible infection, so the nurse assesses the WBC count and the source of infection. Fall history and sensory deficits relate to fall risk, not fever.'),
  ('vitals', 6, 'A client with a scheduled dose of a beta blocker has an apical heart rate of 52 bpm. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Give the dose and recheck the rate in 1 hour"}, {"id": "b", "text": "Give half the dose and document the rate"}, {"id": "c", "text": "Give the dose with a full glass of water"}, {"id": "d", "text": "Hold the dose and assess for symptoms"}]'::jsonb, '["d"]', 'For bradycardia (heart rate below 60), the nurse holds medications such as beta blockers and assesses for symptoms. Giving the dose could further lower the heart rate.'),
  ('vitals', 7, 'A postoperative client has a heart rate of 118 bpm. Which question by the nurse helps identify a likely cause of this finding?', '[{"id": "a", "text": "\"Do you wear glasses or hearing aids?\""}, {"id": "b", "text": "\"How would you rate your pain from 0 to 10?\""}, {"id": "c", "text": "\"Have you fallen at home in the past?\""}, {"id": "d", "text": "\"Would you like a dietitian to visit?\""}]'::jsonb, '["b"]', 'For tachycardia (above 100 bpm), the nurse assesses for pain, anxiety, fever, dehydration, and bleeding. Sensory deficits and fall history are fall-risk factors, not causes of tachycardia.'),
  ('vitals', 8, 'A client''s heart rate is 46 bpm. In addition to assessing for symptoms, which assessments should the nurse perform to check perfusion?', '[{"id": "a", "text": "Gait, balance, and muscle strength"}, {"id": "b", "text": "Pain location, quality, and duration"}, {"id": "c", "text": "Capillary refill, level of consciousness, and blood pressure"}, {"id": "d", "text": "Skin turgor, oral mucosa, and weight"}]'::jsonb, '["c"]', 'When the heart rate is below 60 or above 100, the nurse always checks capillary refill, level of consciousness, and blood pressure to evaluate perfusion. Gait and balance relate to fall risk rather than perfusion.'),
  ('vitals', 9, 'An 84-year-old client is suspected of having a urinary tract infection, but the client''s temperature is 98.6°F. How should the nurse interpret the temperature?', '[{"id": "a", "text": "Older adults may not show a fever even with infection"}, {"id": "b", "text": "A normal temperature rules out infection in this client"}, {"id": "c", "text": "Older adults typically have a higher temperature baseline"}, {"id": "d", "text": "The thermometer is most likely malfunctioning"}]'::jsonb, '["a"]', 'Older adults have a lower temperature baseline and may not show fever even when an infection is present. A normal reading therefore does not rule out infection.'),
  ('vitals', 10, 'A 79-year-old client reports dizziness each time the client stands up from the bed. The nurse recognizes that older adults are more prone to which problem?', '[{"id": "a", "text": "Elevated temperature baseline"}, {"id": "b", "text": "Higher resting heart rate"}, {"id": "c", "text": "Increased respiratory rate"}, {"id": "d", "text": "Orthostatic hypotension"}]'::jsonb, '["d"]', 'Older adults are more prone to orthostatic hypotension. They tend to have a lower, not higher, temperature baseline and may have a lower heart rate at rest.'),
  ('vitals', 11, 'A nurse is teaching a student about vital signs in infants compared with adults. Which statement by the nurse is accurate?', '[{"id": "a", "text": "Infants have lower heart and respiratory rates"}, {"id": "b", "text": "Infants have higher heart and respiratory rates"}, {"id": "c", "text": "Infants have a higher blood pressure"}, {"id": "d", "text": "Infants have a lower respiratory rate only"}]'::jsonb, '["b"]', 'Infants have higher heart and respiratory rates and a lower blood pressure than adults. Stating that infants have lower rates reverses the expected direction.'),
  ('vitals', 12, 'A nurse is precepting a new graduate on a pediatric unit. Which statement by the new graduate indicates a need for further teaching about infant vital signs?', '[{"id": "a", "text": "\"An infant''s heart rate is normally higher than an adult''s.\""}, {"id": "b", "text": "\"An infant normally breathes faster than an adult.\""}, {"id": "c", "text": "\"An infant''s blood pressure is normally higher than an adult''s.\""}, {"id": "d", "text": "\"An infant''s vital signs differ from adult ranges.\""}]'::jsonb, '["c"]', 'Infants have a lower blood pressure than adults, so this statement needs correction. Higher heart and respiratory rates are expected in infants.'),
  ('vitals', 13, 'Over 4 hours, a client''s blood pressure readings are 118/78, 108/70, 98/66, and 92/62 mmHg. Which interpretation by the nurse is most appropriate?', '[{"id": "a", "text": "The steady downward trend needs further assessment"}, {"id": "b", "text": "No action is needed because each reading is normal"}, {"id": "c", "text": "Only the first reading needs to be documented"}, {"id": "d", "text": "The readings are expected and need no comparison"}]'::jsonb, '["a"]', 'The nurse should compare readings to the client''s baseline and assess trends over time, not just single readings. Each value is within range, but the consistent decline warrants further assessment.'),
  ('vitals', 14, 'A client rates pain as 5 on a 0–10 numeric scale. How should the nurse classify this pain level?', '[{"id": "a", "text": "No pain"}, {"id": "b", "text": "Mild pain"}, {"id": "c", "text": "Severe pain"}, {"id": "d", "text": "Moderate pain"}]'::jsonb, '["d"]', 'On the numeric scale, 4–6 indicates moderate pain. Mild pain is 1–3 and severe pain is 7–10.'),
  ('vitals', 15, 'Four clients rate their pain on a 0–10 numeric scale. Which client''s rating indicates severe pain?', '[{"id": "a", "text": "A client who rates pain as 3"}, {"id": "b", "text": "A client who rates pain as 8"}, {"id": "c", "text": "A client who rates pain as 6"}, {"id": "d", "text": "A client who rates pain as 1"}]'::jsonb, '["b"]', 'A rating of 7–10 on the numeric scale indicates severe pain. A rating of 6 is the upper limit of moderate pain, and 1–3 is mild pain.'),
  ('vitals', 16, 'A nurse is selecting a pain scale for several clients. For which client is the 0–10 numeric scale most appropriate?', '[{"id": "a", "text": "An alert 45-year-old adult after knee surgery"}, {"id": "b", "text": "A 6-month-old infant with an ear infection"}, {"id": "c", "text": "A client with advanced dementia who is nonverbal"}, {"id": "d", "text": "A sedated client who cannot speak"}]'::jsonb, '["a"]', 'The numeric scale is used for adults and older children. Infants, nonverbal clients, and cognitively impaired clients are assessed with the FLACC scale.'),
  ('vitals', 17, 'A nurse needs to assess pain in a 4-year-old child after a minor procedure. Which pain scale is most appropriate?', '[{"id": "a", "text": "0–10 numeric scale"}, {"id": "b", "text": "FLACC scale"}, {"id": "c", "text": "Wong-Baker FACES scale"}, {"id": "d", "text": "Fall risk scale"}]'::jsonb, '["c"]', 'The Wong-Baker FACES scale is used for children ages 3 and older, who point to the face that matches their pain. The numeric scale is intended for adults and older children.'),
  ('vitals', 18, 'An adult client who does not speak the nurse''s language appears uncomfortable after surgery, and an interpreter is not immediately available. Which tool should the nurse use to assess pain?', '[{"id": "a", "text": "A verbal 0–10 numeric scale"}, {"id": "b", "text": "A written pain diary"}, {"id": "c", "text": "An orthostatic vital sign check"}, {"id": "d", "text": "The Wong-Baker FACES scale"}]'::jsonb, '["d"]', 'The Wong-Baker FACES scale is appropriate for patients with language barriers because the patient points to the face that matches the pain level. A verbal numeric scale depends on shared language.'),
  ('vitals', 19, 'A nurse is caring for a client with advanced cognitive impairment who cannot report pain. Which pain scale should the nurse use?', '[{"id": "a", "text": "0–10 numeric scale"}, {"id": "b", "text": "FLACC scale"}, {"id": "c", "text": "Self-rated pain diary"}, {"id": "d", "text": "Verbal description scale"}]'::jsonb, '["b"]', 'The FLACC scale is used for infants, nonverbal patients, and cognitively impaired patients. The numeric scale requires the client to self-report a number.'),
  ('vitals', 20, 'A nurse uses the FLACC scale to assess a nonverbal client. Which behavior is one of the five assessed by this scale?', '[{"id": "a", "text": "Consolability"}, {"id": "b", "text": "Blood pressure"}, {"id": "c", "text": "Pupil size"}, {"id": "d", "text": "Oxygen saturation"}]'::jsonb, '["a"]', 'FLACC assesses face, legs, activity, cry, and consolability. Blood pressure and oxygen saturation are vital signs, not FLACC behaviors.'),
  ('vitals', 21, 'A nurse scores an infant''s pain using the FLACC scale. Which statement about this scoring is correct?', '[{"id": "a", "text": "Each behavior is scored 1–5, for a total of 5–25"}, {"id": "b", "text": "Each behavior is scored 0–1, for a total of 0–5"}, {"id": "c", "text": "Each behavior is scored 0–2, for a total of 0–10"}, {"id": "d", "text": "Each behavior is scored 0–10, for a total of 0–50"}]'::jsonb, '["c"]', 'Each of the five FLACC behaviors is scored 0–2, producing a total score of 0–10. The other options misstate both the item and total ranges.'),
  ('vitals', 22, 'A client received an IV opioid for postoperative pain 30 minutes ago. Which finding is the priority for the nurse to report?', '[{"id": "a", "text": "Pain rating decreased from 7 to 4"}, {"id": "b", "text": "Heart rate of 84 bpm"}, {"id": "c", "text": "Oxygen saturation of 97%"}, {"id": "d", "text": "Respiratory rate of 9 breaths/min"}]'::jsonb, '["d"]', 'The nurse monitors for respiratory depression with opioids, and a respiratory rate of 9 is below the normal 12–20 breaths per minute. The heart rate and SpO₂ are within normal ranges, and the drop in pain shows the drug is working.'),
  ('vitals', 23, 'A nurse administers an analgesic to a client with acute postoperative pain. When should the nurse reassess the client''s pain?', '[{"id": "a", "text": "At the end of the shift"}, {"id": "b", "text": "30–60 minutes after the dose"}, {"id": "c", "text": "Before the next scheduled dose only"}, {"id": "d", "text": "Immediately after giving the dose"}]'::jsonb, '["b"]', 'Pain should be reassessed 30–60 minutes after an intervention to assess effectiveness. Waiting until the end of the shift or the next dose delays evaluation.'),
  ('vitals', 24, 'A client has had arthritis pain for several years. Which nursing goal is the priority focus for this client?', '[{"id": "a", "text": "Improving the client''s ability to perform ADLs"}, {"id": "b", "text": "Eliminating all pain within 24 hours"}, {"id": "c", "text": "Relying only on opioid medications"}, {"id": "d", "text": "Limiting activity to complete bed rest"}]'::jsonb, '["a"]', 'For chronic pain such as arthritis, the nursing goal is to improve function by focusing on ADLs and quality of life. Chronic pain management combines non-pharmacologic approaches with medications rather than relying on medication alone.'),
  ('vitals', 25, 'A nurse teaches a client with fibromyalgia about managing chronic pain. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"Distraction may help me cope with the pain.\""}, {"id": "b", "text": "\"I can try heat or cold on painful areas.\""}, {"id": "c", "text": "\"Medication is the only way to manage my pain.\""}, {"id": "d", "text": "\"Relaxation techniques may lower my pain.\""}]'::jsonb, '["c"]', 'Long-term chronic pain management combines non-pharmacologic approaches with medications, so medication alone is a misconception. Relaxation, distraction, and heat/cold therapy are coping strategies the nurse teaches.'),
  ('vitals', 26, 'A nurse is caring for four clients. Which client is experiencing acute pain?', '[{"id": "a", "text": "A client with fibromyalgia for 3 years"}, {"id": "b", "text": "A client with neuropathy for 1 year"}, {"id": "c", "text": "A client with chronic back pain for 2 years"}, {"id": "d", "text": "A client with pain 1 day after surgery"}]'::jsonb, '["d"]', 'Post-operative pain is an example of acute pain, which has a sudden onset and short-term duration. Fibromyalgia, neuropathy, and chronic back pain are examples of chronic pain.'),
  ('vitals', 27, 'A nursing student asks how to distinguish chronic pain from acute pain. Which response by the nurse is accurate?', '[{"id": "a", "text": "Chronic pain is ongoing and lasts more than 3–6 months"}, {"id": "b", "text": "Chronic pain has a sudden onset after an injury"}, {"id": "c", "text": "Chronic pain is short-term and follows a procedure"}, {"id": "d", "text": "Chronic pain always resolves within 1 month"}]'::jsonb, '["a"]', 'Chronic pain is ongoing and lasts more than 3–6 months. Sudden onset and short-term duration describe acute pain.'),
  ('vitals', 28, 'A client rates pain as 8 out of 10 while talking calmly with visitors. Which response by the nurse is most appropriate?', '[{"id": "a", "text": "Record a lower rating that fits the behavior"}, {"id": "b", "text": "Accept the client''s rating as reported"}, {"id": "c", "text": "Delay treatment until the client appears distressed"}, {"id": "d", "text": "Ask the visitors to rate the client''s pain"}]'::jsonb, '["b"]', 'Pain is subjective, so the nurse believes the patient''s report. Changing the rating to match observed behavior disregards the client''s self-report.'),
  ('vitals', 29, 'A nurse is planning care for an immobile client. Which intervention may the nurse perform without a provider''s order?', '[{"id": "a", "text": "Starting oxygen therapy"}, {"id": "b", "text": "Inserting a urinary catheter"}, {"id": "c", "text": "Turning and repositioning the client"}, {"id": "d", "text": "Administering a PRN medication"}]'::jsonb, '["c"]', 'Turning and repositioning is an independent intervention the RN can do without a provider order. Oxygen therapy, urinary catheters, and medications are dependent interventions that require an order.'),
  ('vitals', 30, 'A nurse is reviewing planned care for a client. Which intervention requires a provider''s order before the nurse can perform it?', '[{"id": "a", "text": "Inserting a urinary catheter"}, {"id": "b", "text": "Teaching about the medication schedule"}, {"id": "c", "text": "Completing a fall risk assessment"}, {"id": "d", "text": "Performing hand hygiene"}]'::jsonb, '["a"]', 'Inserting a urinary catheter is a dependent intervention that requires a provider order. Patient education, fall risk assessment, and hand hygiene are independent nursing interventions.'),
  ('vitals', 31, 'A client with poor appetite needs an individualized nutrition plan. Which type of intervention is a referral to the dietitian?', '[{"id": "a", "text": "Independent"}, {"id": "b", "text": "Dependent"}, {"id": "c", "text": "Delegated"}, {"id": "d", "text": "Collaborative"}]'::jsonb, '["d"]', 'Collaborative interventions involve working with other disciplines, such as a dietitian for a nutrition plan. Independent interventions are performed by the RN alone.'),
  ('vitals', 32, 'After receiving report, a nurse must decide which client to see first. Which client should the nurse assess first?', '[{"id": "a", "text": "A client with chronic back pain asking about the next dose"}, {"id": "b", "text": "A client with SpO₂ of 88% and labored breathing"}, {"id": "c", "text": "A stable client awaiting discharge teaching"}, {"id": "d", "text": "A client with arthritis requesting a heat pack"}]'::jsonb, '["b"]', 'Using the ABCs (airway, breathing, circulation), the client with low oxygen saturation and labored breathing is seen first. The other clients are stable or have chronic needs.'),
  ('vitals', 33, 'A nurse is prioritizing care for four clients. Which client should the nurse see first?', '[{"id": "a", "text": "A client with long-standing neuropathy pain rated 4"}, {"id": "b", "text": "A client with stable vital signs who wants a bath"}, {"id": "c", "text": "A client who suddenly became confused 10 minutes ago"}, {"id": "d", "text": "A client with fibromyalgia asking for a warm blanket"}]'::jsonb, '["c"]', 'Acute or sudden changes take priority over chronic or stable conditions. Neuropathy and fibromyalgia are chronic problems, and the client wanting a bath is stable.'),
  ('vitals', 34, 'Using Maslow''s hierarchy, which client need should the nurse address first?', '[{"id": "a", "text": "Restoring fluid intake in a dehydrated client"}, {"id": "b", "text": "Discussing self-esteem concerns with a client"}, {"id": "c", "text": "Arranging social visits for a lonely client"}, {"id": "d", "text": "Exploring hobbies with a bored client"}]'::jsonb, '["a"]', 'Maslow''s hierarchy directs the nurse to meet physiological needs first. Fluid needs are physiological, while self-esteem and social needs come later.'),
  ('vitals', 35, 'An RN is making assignments on a medical unit. Which task is most appropriate to delegate to unlicensed assistive personnel (UAP)?', '[{"id": "a", "text": "Assessing a client with a new change in status"}, {"id": "b", "text": "Giving oral medications to a stable client"}, {"id": "c", "text": "Changing a surgical dressing on a stable client"}, {"id": "d", "text": "Measuring vital signs on a stable client"}]'::jsonb, '["d"]', 'UAPs can take vital signs for stable patients. Medication administration and wound care are LPN tasks, and assessment is the RN''s role.'),
  ('vitals', 36, 'An RN is delegating tasks to an LPN. Which task is appropriate for the LPN?', '[{"id": "a", "text": "Caring for a client with unstable vital signs"}, {"id": "b", "text": "Performing a dressing change on a stable client"}, {"id": "c", "text": "Giving an IV push medication to a stable client"}, {"id": "d", "text": "Completing the initial assessment of a new admission"}]'::jsonb, '["b"]', 'LPNs/LVNs can care for stable patients and perform wound care and dressing changes. IV push medications are excluded for LPNs in most states, and assessment is the RN''s role.'),
  ('vitals', 37, 'An RN observes an LPN caring for a stable client. Which action by the LPN requires correction?', '[{"id": "a", "text": "Giving a scheduled oral medication"}, {"id": "b", "text": "Changing a simple wound dressing"}, {"id": "c", "text": "Administering a medication by IV push"}, {"id": "d", "text": "Performing routine monitoring"}]'::jsonb, '["c"]', 'LPNs can administer medications but not by IV push in most states. Routine monitoring, oral medications, and dressing changes are within the LPN role for stable patients.'),
  ('vitals', 38, 'A nurse observes unlicensed assistive personnel (UAP) settling a high-fall-risk client into bed. Which action by the UAP requires correction?', '[{"id": "a", "text": "Raising all four side rails"}, {"id": "b", "text": "Placing the call light within reach"}, {"id": "c", "text": "Putting non-slip socks on the client"}, {"id": "d", "text": "Lowering the bed to its lowest position"}]'::jsonb, '["a"]', 'Raising all four side rails is considered a restraint; 2–3 side rails are used instead. The call light within reach, non-slip socks, and a low bed are correct fall-prevention measures.'),
  ('vitals', 39, 'A charge nurse reviews tasks for the shift. Which task should the RN keep rather than delegate?', '[{"id": "a", "text": "Ambulating a stable client in the hallway"}, {"id": "b", "text": "Assessing a client whose condition has changed"}, {"id": "c", "text": "Helping a stable client with toileting"}, {"id": "d", "text": "Bathing a client who is ready for discharge"}]'::jsonb, '["b"]', 'RNs assess, LPNs implement stable care, and UAPs do ADLs. Ambulation, toileting, and bathing are tasks UAPs can perform.'),
  ('vitals', 40, 'A nurse gives a PRN analgesic at 0900 and plans to chart it at the end of the shift. Which response by the charge nurse is most appropriate?', '[{"id": "a", "text": "\"Charting later is fine for stable clients.\""}, {"id": "b", "text": "\"Only abnormal findings need prompt charting.\""}, {"id": "c", "text": "\"PRN doses do not need to be documented.\""}, {"id": "d", "text": "\"Document medication administration right away.\""}]'::jsonb, '["d"]', 'Medication administrations are documented immediately. Abnormal assessments must also be documented immediately, but they are not the only items requiring prompt documentation.'),
  ('vitals', 41, 'A nurse telephones the provider about a client''s heart rate of 44 bpm and receives new instructions. Which action regarding documentation is correct?', '[{"id": "a", "text": "Document the provider notification now"}, {"id": "b", "text": "Document the call only if the rate worsens"}, {"id": "c", "text": "Wait until the provider writes a note"}, {"id": "d", "text": "Report the call verbally at shift change only"}]'::jsonb, '["a"]', 'Provider notifications are documented immediately; if it is not documented, it did not happen. Relying on verbal report or waiting leaves no record of the notification.'),
  ('vitals', 42, 'A client reports new abdominal discomfort to the nurse. According to the nursing process, what should the nurse do first?', '[{"id": "a", "text": "Administer the prescribed analgesic"}, {"id": "b", "text": "Set a goal for pain relief"}, {"id": "c", "text": "Collect subjective and objective data"}, {"id": "d", "text": "Evaluate whether the goal was met"}]'::jsonb, '["c"]', 'Assessment, the collection of subjective and objective data, is always first. Jumping to implementation such as giving an analgesic before assessing is incorrect unless the patient is in immediate danger.'),
  ('vitals', 43, 'A nursing student is reviewing the nursing process. Which sequence of steps is correct?', '[{"id": "a", "text": "Diagnosis, assessment, planning, evaluation, implementation"}, {"id": "b", "text": "Assessment, diagnosis, planning, implementation, evaluation"}, {"id": "c", "text": "Assessment, planning, diagnosis, implementation, evaluation"}, {"id": "d", "text": "Planning, assessment, diagnosis, implementation, evaluation"}]'::jsonb, '["b"]', 'ADPIE stands for assessment, diagnosis, planning, implementation, and evaluation, followed in order. Each other option places a step out of sequence.'),
  ('vitals', 44, 'Forty-five minutes after giving an analgesic, a nurse asks the client to rate the pain again to determine whether the pain-relief goal was met. Which step of the nursing process is the nurse performing?', '[{"id": "a", "text": "Assessment"}, {"id": "b", "text": "Diagnosis"}, {"id": "c", "text": "Planning"}, {"id": "d", "text": "Evaluation"}]'::jsonb, '["d"]', 'Evaluation asks whether the goal was met and involves reassessing as needed. Planning is setting goals and expected outcomes, not checking whether they were achieved.'),
  ('vitals', 45, 'A nurse enters a room and finds a client choking on food and unable to speak. Which action should the nurse take?', '[{"id": "a", "text": "Intervene immediately to relieve the obstruction"}, {"id": "b", "text": "Complete a full head-to-toe assessment first"}, {"id": "c", "text": "Obtain a full set of vital signs first"}, {"id": "d", "text": "Document the finding before acting"}]'::jsonb, '["a"]', 'The nurse always assesses first unless the patient is in immediate danger, such as choking or cardiac arrest. Completing an assessment first would delay a life-saving action.'),
  ('vitals', 46, 'A nurse is reviewing the admission data of four clients. Which client has the highest risk for falls?', '[{"id": "a", "text": "A 30-year-old with a sprained wrist"}, {"id": "b", "text": "A 42-year-old admitted for observation"}, {"id": "c", "text": "A 78-year-old taking opioids with prior falls"}, {"id": "d", "text": "A 25-year-old with seasonal allergies"}]'::jsonb, '["c"]', 'History of falls, age over 65, and medications such as opioids are high-risk factors for falls. The younger clients have none of the listed risk factors.'),
  ('vitals', 47, 'A nurse is planning care for a client at high risk for falls. Which intervention should the nurse include?', '[{"id": "a", "text": "Keep the bed in its highest position"}, {"id": "b", "text": "Place the call light within the client''s reach"}, {"id": "c", "text": "Store personal items across the room"}, {"id": "d", "text": "Assess fall risk on admission only"}]'::jsonb, '["b"]', 'Placing the call light within reach is a fall-prevention measure. The bed should be kept in its lowest position, frequently used items kept at the bedside, and fall risk reassessed every shift.'),
  ('vitals', 48, 'A newly hired nurse asks how often fall risk should be reassessed for hospitalized clients. Which response by the preceptor is correct?', '[{"id": "a", "text": "Only on admission"}, {"id": "b", "text": "Only after a fall occurs"}, {"id": "c", "text": "Only at discharge"}, {"id": "d", "text": "Every shift"}]'::jsonb, '["d"]', 'Fall risk should be reassessed regularly, every shift. Assessing only on admission or after a fall misses changes in the client''s risk.'),
  ('vitals', 49, 'A nurse measures oral temperatures in Celsius for four adult clients. Which reading is outside the normal range?', '[{"id": "a", "text": "36.6°C"}, {"id": "b", "text": "37.0°C"}, {"id": "c", "text": "36.2°C"}, {"id": "d", "text": "37.4°C"}]'::jsonb, '["c"]', 'The normal temperature range is 36.5–37.5°C (97.7–99.5°F). A reading of 36.2°C is below this range, while the others fall within it.'),
  ('vitals', 50, 'A client''s blood pressure is 80/48 mmHg, and the provider has prescribed IV fluids for hypotension. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Hold the fluids until the next reading"}, {"id": "b", "text": "Initiate the ordered fluids and notify the provider"}, {"id": "c", "text": "Ambulate the client to improve circulation"}, {"id": "d", "text": "Document the reading and recheck at shift end"}]'::jsonb, '["b"]', 'For a blood pressure below 90/60, the nurse initiates fluids if ordered, notifies the provider, and monitors continuously for shock symptoms. Waiting until the next reading or shift end delays treatment of hypoperfusion.'),
  ('bowel_sounds', 1, 'The nurse is about to perform an abdominal assessment on a newly admitted client. Which sequence of techniques is correct?', '[{"id": "a", "text": "Inspect, percuss, palpate, auscultate"}, {"id": "b", "text": "Inspect, auscultate, percuss, palpate"}, {"id": "c", "text": "Inspect, palpate, percuss, auscultate"}, {"id": "d", "text": "Auscultate, inspect, palpate, percuss"}]'::jsonb, '["b"]', 'The abdomen is assessed in the order inspect, auscultate, percuss, palpate (I-A-P-P). Inspect, palpate, percuss, auscultate (I-P-P-A) is the order for other body areas.'),
  ('bowel_sounds', 2, 'A nursing student asks why bowel sounds are auscultated before the abdomen is percussed or palpated. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Palpation must always be the first technique used.\""}, {"id": "b", "text": "\"Touching the abdomen first can alter bowel sounds.\""}, {"id": "c", "text": "\"Bowel sounds can only be heard after palpation.\""}, {"id": "d", "text": "\"Auscultation is the most painful technique to perform.\""}]'::jsonb, '["b"]', 'Touching the abdomen first can alter bowel sounds and cause false findings, so auscultation comes before percussion and palpation. Palpation is done last, not first.'),
  ('bowel_sounds', 3, 'The nurse is performing a physical assessment of a client''s chest. Which sequence of techniques should the nurse use?', '[{"id": "a", "text": "Inspect, auscultate, percuss, palpate"}, {"id": "b", "text": "Auscultate, inspect, percuss, palpate"}, {"id": "c", "text": "Palpate, inspect, percuss, auscultate"}, {"id": "d", "text": "Inspect, palpate, percuss, auscultate"}]'::jsonb, '["d"]', 'Body areas other than the abdomen follow I-P-P-A: inspect, palpate, percuss, auscultate. Inspect, auscultate, percuss, palpate is used only for the abdomen.'),
  ('bowel_sounds', 4, 'The nurse is observing a nursing student perform an abdominal assessment. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"I palpate the abdomen as the last step.\""}, {"id": "b", "text": "\"I listen to bowel sounds before I percuss.\""}, {"id": "c", "text": "\"I palpate the abdomen before I listen to bowel sounds.\""}, {"id": "d", "text": "\"I inspect the abdomen before I touch it.\""}]'::jsonb, '["c"]', 'Bowel sounds are assessed before the abdomen is manipulated, so palpating before auscultating is incorrect. Inspecting first and palpating last are correct.'),
  ('bowel_sounds', 5, 'The nurse begins a client''s physical examination with inspection. What is the reason inspection is always performed first?', '[{"id": "a", "text": "To detect a bruit over the abdominal aorta"}, {"id": "b", "text": "To hear tympany over the air-filled stomach"}, {"id": "c", "text": "To feel for masses and organ enlargement"}, {"id": "d", "text": "To avoid changing signs that touching or tapping could affect"}]'::jsonb, '["d"]', 'Inspection is always done first to avoid changing any signs that could be affected by touching or tapping the body. Detecting a bruit is done by auscultation.'),
  ('bowel_sounds', 6, 'The nurse is inspecting a client''s abdomen. Which activity is part of this step of the examination?', '[{"id": "a", "text": "Noting symmetry, color, and contour"}, {"id": "b", "text": "Tapping to determine organ size"}, {"id": "c", "text": "Listening for gurgling bowel sounds"}, {"id": "d", "text": "Feeling for tenderness and rigidity"}]'::jsonb, '["a"]', 'Inspection involves looking at the body and noting symmetry, color, contour, and movement. Feeling for tenderness and rigidity is palpation.'),
  ('bowel_sounds', 7, 'While percussing over a client''s stomach, the nurse hears a drum-like sound. How should the nurse interpret this finding?', '[{"id": "a", "text": "Tympany over an air-filled structure"}, {"id": "b", "text": "Flatness over muscle or bone"}, {"id": "c", "text": "Dullness over a fluid-filled area"}, {"id": "d", "text": "Resonance over normal lung tissue"}]'::jsonb, '["a"]', 'Tympany is a drum-like sound heard over air-filled structures such as the stomach. Dullness is a thud-like sound over organs, fluid, or masses.'),
  ('bowel_sounds', 8, 'Percussion over an area of a client''s abdomen produces a thud-like sound. How should the nurse interpret this sound?', '[{"id": "a", "text": "Resonance, suggesting lung tissue"}, {"id": "b", "text": "Flatness, suggesting bone"}, {"id": "c", "text": "Dullness, suggesting fluid or a mass"}, {"id": "d", "text": "Tympany, suggesting air"}]'::jsonb, '["c"]', 'Dullness is a thud-like sound heard over organs, fluid, or masses. Tympany is a drum-like sound over air-filled structures.'),
  ('bowel_sounds', 9, 'The nurse suspects a client has abnormal fluid accumulation in the abdomen (ascites). Which examination technique is used to detect it?', '[{"id": "a", "text": "Deep palpation"}, {"id": "b", "text": "Auscultation"}, {"id": "c", "text": "Light palpation"}, {"id": "d", "text": "Percussion"}]'::jsonb, '["d"]', 'Percussion is used to detect abnormal fluid accumulation (ascites) and to find fluid, air, or solid masses. Auscultation is used to listen to sounds such as bowel sounds.'),
  ('bowel_sounds', 10, 'The nurse percusses a client''s lung fields and hears a hollow sound. How should the nurse interpret this finding?', '[{"id": "a", "text": "Tympany, suggesting trapped air"}, {"id": "b", "text": "Flatness, suggesting fluid"}, {"id": "c", "text": "Dullness, suggesting a mass"}, {"id": "d", "text": "Resonance, a normal finding"}]'::jsonb, '["d"]', 'Resonance is a hollow sound that is normal over the lungs. Dullness is a thud-like sound over organs, fluid, or masses.'),
  ('bowel_sounds', 11, 'The nurse percusses over a client''s large thigh muscle. Which percussion sound does the nurse expect?', '[{"id": "a", "text": "Tympany"}, {"id": "b", "text": "Resonance"}, {"id": "c", "text": "Flatness"}, {"id": "d", "text": "Bruit"}]'::jsonb, '["c"]', 'Flatness is a very dull sound heard over muscle and bone. Tympany is heard over air-filled structures, and a bruit is a vascular sound heard on auscultation.'),
  ('bowel_sounds', 12, 'A nursing student asks why palpation is performed last during an abdominal examination. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It can be painful and may influence other results.\""}, {"id": "b", "text": "\"It is needed to find where to place the stethoscope.\""}, {"id": "c", "text": "\"It must follow bowel sounds so they can be counted.\""}, {"id": "d", "text": "\"It is the least accurate of the four techniques.\""}]'::jsonb, '["a"]', 'Palpation is always done last because it can be painful and may influence other exam results if done first. It is not done to locate stethoscope placement.'),
  ('bowel_sounds', 13, 'A client reports tenderness in one area of the abdomen. How should the nurse proceed with palpation?', '[{"id": "a", "text": "Palpate only the tender area"}, {"id": "b", "text": "Palpate the tender area first"}, {"id": "c", "text": "Palpate the tender area last"}, {"id": "d", "text": "Palpate the tender area before percussion"}]'::jsonb, '["c"]', 'Tender areas are always palpated last to get an accurate assessment. Palpating the tender area first could cause pain that changes the remaining findings.'),
  ('bowel_sounds', 14, 'The nurse percusses a client''s abdomen before palpating it. What is the rationale for this order?', '[{"id": "a", "text": "Percussion detects bowel sounds more accurately"}, {"id": "b", "text": "Palpation is used only during chest assessment"}, {"id": "c", "text": "Percussion must follow palpation in every body area"}, {"id": "d", "text": "Palpation may cause pain that changes the findings"}]'::jsonb, '["d"]', 'Percussion is done third for the abdomen, before palpation, to avoid causing pain or tenderness that could change the findings. Bowel sounds are assessed by auscultation, not percussion.'),
  ('bowel_sounds', 15, 'The nurse wants to assess the surface structures of a client''s abdomen. Which technique should the nurse use?', '[{"id": "a", "text": "Auscultation"}, {"id": "b", "text": "Deep palpation"}, {"id": "c", "text": "Light palpation"}, {"id": "d", "text": "Percussion"}]'::jsonb, '["c"]', 'Light palpation uses gentle pressure to assess surface structures. Deep palpation uses deeper pressure to assess organs and masses.'),
  ('bowel_sounds', 16, 'During an abdominal assessment of a client with no suspected aneurysm, the nurse needs to assess the abdominal organs and any masses. Which technique is appropriate?', '[{"id": "a", "text": "Deep palpation"}, {"id": "b", "text": "Light palpation"}, {"id": "c", "text": "Auscultation"}, {"id": "d", "text": "Inspection"}]'::jsonb, '["a"]', 'Deep palpation uses deeper pressure to assess organs and masses. Light palpation uses gentle pressure to assess surface structures only.'),
  ('bowel_sounds', 17, 'The nurse auscultates irregular, intermittent gurgling sounds about every 10 seconds in a client''s abdomen. How should the nurse interpret this finding?', '[{"id": "a", "text": "A bruit over the aorta"}, {"id": "b", "text": "Hyperactive bowel sounds"}, {"id": "c", "text": "Normal peristalsis"}, {"id": "d", "text": "Hypoactive bowel sounds"}]'::jsonb, '["c"]', 'Normal bowel sounds are irregular, intermittent gurgles occurring every 5-15 seconds and indicate normal peristalsis. Hyperactive sounds are loud, frequent, and high-pitched.'),
  ('bowel_sounds', 18, 'The nurse counts 20 bowel sounds per minute during an abdominal assessment. Which action is appropriate?', '[{"id": "a", "text": "Report absent bowel sounds"}, {"id": "b", "text": "Report hyperactive bowel sounds"}, {"id": "c", "text": "Report hypoactive bowel sounds"}, {"id": "d", "text": "Document normal bowel sounds"}]'::jsonb, '["d"]', 'Normal bowel sounds occur at 5-30 sounds per minute, so 20 per minute is a normal finding to document. Hypoactive sounds are rare and very quiet.'),
  ('bowel_sounds', 19, 'Which description of bowel sounds documented by the nurse indicates a normal finding?', '[{"id": "a", "text": "Rare, very quiet sounds"}, {"id": "b", "text": "Loud, frequent, high-pitched sounds"}, {"id": "c", "text": "Irregular, intermittent gurgles"}, {"id": "d", "text": "Swishing sound above the umbilicus"}]'::jsonb, '["c"]', 'Normal bowel sounds are irregular, intermittent gurgling. Loud, frequent, high-pitched sounds are hyperactive, and a swishing sound is a bruit.'),
  ('bowel_sounds', 20, 'A client is admitted with gastroenteritis and diarrhea. Which bowel sound finding does the nurse expect?', '[{"id": "a", "text": "No bowel sounds heard"}, {"id": "b", "text": "Loud, frequent, high-pitched sounds"}, {"id": "c", "text": "A swishing bruit"}, {"id": "d", "text": "Rare, very quiet sounds"}]'::jsonb, '["b"]', 'Hyperactive bowel sounds (loud, frequent, high-pitched) are caused by diarrhea and gastroenteritis. Rare, very quiet sounds are hypoactive, seen with constipation or after surgery.'),
  ('bowel_sounds', 21, 'The nurse hears loud, frequent, high-pitched bowel sounds in a client''s abdomen. What does this finding indicate?', '[{"id": "a", "text": "Fluid accumulation in the abdomen"}, {"id": "b", "text": "Turbulent aortic blood flow"}, {"id": "c", "text": "Increased intestinal activity"}, {"id": "d", "text": "Decreased intestinal activity"}]'::jsonb, '["c"]', 'Hyperactive bowel sounds signify increased intestinal activity. Decreased intestinal activity is the significance of hypoactive sounds.'),
  ('bowel_sounds', 22, 'A client is 1 day after surgery. The nurse hears rare, very quiet bowel sounds. How should the nurse document this finding?', '[{"id": "a", "text": "Hyperactive bowel sounds"}, {"id": "b", "text": "Normal bowel sounds"}, {"id": "c", "text": "Absent bowel sounds"}, {"id": "d", "text": "Hypoactive bowel sounds"}]'::jsonb, '["d"]', 'Rare, very quiet sounds are hypoactive, and post-surgery is a listed cause. Hyperactive sounds are loud, frequent, and high-pitched.'),
  ('bowel_sounds', 23, 'A client reports constipation for several days. Which bowel sound finding is consistent with this condition?', '[{"id": "a", "text": "Frequent gurgles every 5 seconds"}, {"id": "b", "text": "A swishing sound near the umbilicus"}, {"id": "c", "text": "Rare, very quiet sounds"}, {"id": "d", "text": "Loud, high-pitched sounds"}]'::jsonb, '["c"]', 'Constipation is a cause of hypoactive bowel sounds, which are rare and very quiet. Loud, high-pitched sounds are hyperactive and seen with diarrhea.'),
  ('bowel_sounds', 24, 'The nurse documents hypoactive bowel sounds for a client. Which interpretation of this finding is correct?', '[{"id": "a", "text": "Increased intestinal activity"}, {"id": "b", "text": "Turbulent blood flow"}, {"id": "c", "text": "Decreased intestinal activity"}, {"id": "d", "text": "Normal peristalsis"}]'::jsonb, '["c"]', 'Hypoactive bowel sounds signify decreased intestinal activity. Increased intestinal activity is the significance of hyperactive sounds.'),
  ('bowel_sounds', 25, 'After listening for the full required time in all four quadrants, the nurse hears no bowel sounds in a client with a distended abdomen. Which action should the nurse take?', '[{"id": "a", "text": "Palpate deeply to stimulate bowel sounds"}, {"id": "b", "text": "Document the finding and reassess next shift"}, {"id": "c", "text": "Report the finding to the provider immediately"}, {"id": "d", "text": "Encourage a meal and recheck in the morning"}]'::jsonb, '["c"]', 'Absent bowel sounds are a medical emergency that must be reported immediately. Delaying until the next shift or the morning is unsafe.'),
  ('bowel_sounds', 26, 'A client has a complete bowel obstruction. Which auscultation finding does the nurse expect?', '[{"id": "a", "text": "No bowel sounds heard"}, {"id": "b", "text": "Loud, high-pitched sounds"}, {"id": "c", "text": "A bruit above the umbilicus"}, {"id": "d", "text": "Gurgles every 5-15 seconds"}]'::jsonb, '["a"]', 'Absent bowel sounds are associated with complete obstruction or ileus. Loud, high-pitched hyperactive sounds are associated with early obstruction.'),
  ('bowel_sounds', 27, 'A client is admitted with an early bowel obstruction. Which bowel sounds does the nurse expect to hear?', '[{"id": "a", "text": "Rare and very quiet"}, {"id": "b", "text": "Swishing over the aorta"}, {"id": "c", "text": "No sounds at all"}, {"id": "d", "text": "Loud, frequent, high-pitched"}]'::jsonb, '["d"]', 'Hyperactive (loud, frequent, high-pitched) sounds occur with early obstruction or diarrhea. Absent sounds are associated with complete obstruction.'),
  ('bowel_sounds', 28, 'A client with suspected peritonitis has no bowel sounds on auscultation. How should the nurse interpret this finding?', '[{"id": "a", "text": "A medical emergency to report now"}, {"id": "b", "text": "An expected finding needing no action"}, {"id": "c", "text": "Increased intestinal activity"}, {"id": "d", "text": "A normal finding after eating"}]'::jsonb, '["a"]', 'Peritonitis is a cause of absent bowel sounds, which are a medical emergency to report immediately. Increased intestinal activity is the significance of hyperactive sounds.'),
  ('bowel_sounds', 29, 'The nurse is teaching a student how to auscultate bowel sounds. Which instruction is correct?', '[{"id": "a", "text": "Listen only in one quadrant"}, {"id": "b", "text": "Listen in all four quadrants"}, {"id": "c", "text": "Percuss first, then listen"}, {"id": "d", "text": "Palpate first, then listen"}]'::jsonb, '["b"]', 'Bowel sounds are assessed by listening in all 4 quadrants. Palpating or percussing before listening can alter bowel sounds.'),
  ('bowel_sounds', 30, 'While auscultating a client''s abdomen, the nurse hears a swishing sound at the midline above the umbilicus. Which condition should the nurse suspect?', '[{"id": "a", "text": "Hyperactive bowel"}, {"id": "b", "text": "Paralytic ileus"}, {"id": "c", "text": "Abdominal aortic aneurysm"}, {"id": "d", "text": "Constipation"}]'::jsonb, '["c"]', 'A swishing sound, or bruit, over the abdomen may indicate an abdominal aortic aneurysm (AAA). Paralytic ileus is associated with hypoactive or absent bowel sounds.'),
  ('bowel_sounds', 31, 'The nurse auscultates a bruit over a client''s abdominal aorta. Which action should the nurse take?', '[{"id": "a", "text": "Palpate deeply to confirm the finding"}, {"id": "b", "text": "Reassess the client at the next shift"}, {"id": "c", "text": "Document it as an expected finding"}, {"id": "d", "text": "Report it to the provider immediately"}]'::jsonb, '["d"]', 'If a bruit is detected, it must be reported to the provider immediately. Deep palpation is avoided when AAA is suspected because of the risk of rupture.'),
  ('bowel_sounds', 32, 'The nurse is supervising a nursing student assessing a client with a suspected abdominal aortic aneurysm (AAA). Which action by the student requires correction?', '[{"id": "a", "text": "Reporting a bruit to the provider"}, {"id": "b", "text": "Inspecting the abdomen first"}, {"id": "c", "text": "Auscultating over the aorta"}, {"id": "d", "text": "Deeply palpating to feel the mass"}]'::jsonb, '["d"]', 'Deep palpation must be avoided when AAA is suspected because of the risk of rupture. Inspecting, auscultating, and reporting a bruit are appropriate.'),
  ('bowel_sounds', 33, 'A client has a known abdominal aortic aneurysm (AAA). Which finding should alert the nurse to a possible rupture?', '[{"id": "a", "text": "Severe back pain with hypotension"}, {"id": "b", "text": "A hollow sound over the lungs"}, {"id": "c", "text": "Tympany over the stomach"}, {"id": "d", "text": "Gurgling sounds every 10 seconds"}]'::jsonb, '["a"]', 'Signs of AAA rupture include severe back or abdominal pain, hypotension, and shock. Gurgles every 5-15 seconds are normal bowel sounds.'),
  ('bowel_sounds', 34, 'A client asks the nurse what causes the swishing sound heard over an abdominal aortic aneurysm. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is caused by turbulent blood flow in the aneurysm.\""}, {"id": "b", "text": "\"It is caused by fluid collecting in the abdomen.\""}, {"id": "c", "text": "\"It is caused by air trapped in the stomach.\""}, {"id": "d", "text": "\"It is caused by increased intestinal activity.\""}]'::jsonb, '["a"]', 'A bruit over an AAA is caused by turbulent blood flow through the aneurysm. Increased intestinal activity produces hyperactive bowel sounds, not a bruit.'),
  ('bowel_sounds', 35, 'The nurse is assessing a client for a possible abdominal aortic aneurysm (AAA). Where is a bruit typically heard?', '[{"id": "a", "text": "At the midline above the umbilicus"}, {"id": "b", "text": "Under the left lower ribs"}, {"id": "c", "text": "Over the lateral flank"}, {"id": "d", "text": "In the right lower quadrant"}]'::jsonb, '["a"]', 'An AAA bruit is typically heard over the aorta, at the midline above the umbilicus. The other locations are not where the aorta is auscultated.'),
  ('bowel_sounds', 36, 'The nurse places a stethoscope on a client''s chest to assess the heart. Which findings is the nurse evaluating?', '[{"id": "a", "text": "Heart rate, rhythm, and murmurs"}, {"id": "b", "text": "Tenderness and rigidity"}, {"id": "c", "text": "Size and position of the organ"}, {"id": "d", "text": "Skin color and symmetry"}]'::jsonb, '["a"]', 'Auscultation of the heart checks heart rate, rhythm, and murmurs. Tenderness and rigidity are assessed by palpation.'),
  ('bowel_sounds', 37, 'The nurse places the hands on a client''s skin during palpation. Which characteristics can the nurse assess with this technique?', '[{"id": "a", "text": "Breath sounds, crackles, and wheezes"}, {"id": "b", "text": "Temperature, texture, and mobility"}, {"id": "c", "text": "Bowel sound frequency and quality"}, {"id": "d", "text": "Tympany, dullness, and resonance"}]'::jsonb, '["b"]', 'Palpation is used to assess temperature, texture, and mobility. Tympany, dullness, and resonance are percussion sounds.'),
  ('bowel_sounds', 38, 'Before touching the client, the nurse observes the client''s respiratory pattern and effort. Which examination technique is the nurse using?', '[{"id": "a", "text": "Auscultation"}, {"id": "b", "text": "Inspection"}, {"id": "c", "text": "Percussion"}, {"id": "d", "text": "Palpation"}]'::jsonb, '["b"]', 'Inspection is looking at the body and includes observing respiratory pattern and effort. Palpation uses the hands to feel the body.'),
  ('bowel_sounds', 39, 'The nurse has inspected and auscultated a client''s abdomen. Which technique should the nurse perform next?', '[{"id": "a", "text": "Palpate the tender areas"}, {"id": "b", "text": "Percuss the abdomen"}, {"id": "c", "text": "Palpate the abdomen deeply"}, {"id": "d", "text": "Repeat the inspection"}]'::jsonb, '["b"]', 'The abdominal order is inspect, auscultate, percuss, then palpate, so percussion comes next. Palpation, including of tender areas, is done last.'),
  ('bowel_sounds', 40, 'The nurse has completed inspection of a client''s chest. Which technique should the nurse perform next?', '[{"id": "a", "text": "Listening for bruits"}, {"id": "b", "text": "Palpation"}, {"id": "c", "text": "Auscultation"}, {"id": "d", "text": "Percussion"}]'::jsonb, '["b"]', 'Areas other than the abdomen follow I-P-P-A, so palpation follows inspection. Auscultation comes second only for the abdomen.'),
  ('bowel_sounds', 41, 'The nurse taps over a client''s abdomen and listens to the sounds produced. Which examination technique is the nurse performing?', '[{"id": "a", "text": "Percussion"}, {"id": "b", "text": "Inspection"}, {"id": "c", "text": "Palpation"}, {"id": "d", "text": "Auscultation"}]'::jsonb, '["a"]', 'Percussion is tapping on the body to hear different sounds. Auscultation is listening to sounds inside the body with a stethoscope.'),
  ('bowel_sounds', 42, 'The nurse uses the hands to check a client''s abdomen for rigidity. Which examination technique is the nurse using?', '[{"id": "a", "text": "Palpation"}, {"id": "b", "text": "Auscultation"}, {"id": "c", "text": "Percussion"}, {"id": "d", "text": "Inspection"}]'::jsonb, '["a"]', 'Palpation uses the hands to feel the body and detects masses, organ enlargement, or rigidity. Percussion involves tapping to hear sounds.'),
  ('bowel_sounds', 43, 'The nurse auscultates a client''s blood vessels. Which abnormal sound is the nurse listening for?', '[{"id": "a", "text": "Tympany"}, {"id": "b", "text": "Dullness"}, {"id": "c", "text": "Bruit"}, {"id": "d", "text": "Resonance"}]'::jsonb, '["c"]', 'Auscultation of blood vessels listens for bruits, which are abnormal whooshing sounds. Tympany, dullness, and resonance are percussion sounds.'),
  ('bowel_sounds', 44, 'The nurse is assessing four clients. Which client is most likely to have hypoactive bowel sounds?', '[{"id": "a", "text": "A client with gastroenteritis"}, {"id": "b", "text": "A client with early bowel obstruction"}, {"id": "c", "text": "A client with diarrhea"}, {"id": "d", "text": "A client with paralytic ileus"}]'::jsonb, '["d"]', 'Paralytic ileus is a cause of hypoactive bowel sounds. Gastroenteritis, diarrhea, and early bowel obstruction cause hyperactive sounds.'),
  ('bowel_sounds', 45, 'The nurse completes abdominal assessments on four clients. Which finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "Gurgles every 5-15 seconds"}, {"id": "b", "text": "A swishing sound over the aorta"}, {"id": "c", "text": "Resonance over the lungs"}, {"id": "d", "text": "Tympany over the stomach"}]'::jsonb, '["b"]', 'A bruit is treated as an AAA until proven otherwise, and the provider must be notified. Gurgles every 5-15 seconds and tympany over the stomach are normal findings.'),
  ('bowel_sounds', 46, 'The nurse percusses a client''s abdomen. Which information is the nurse gathering with this technique?', '[{"id": "a", "text": "Skin lesions and scars"}, {"id": "b", "text": "Heart rhythm and murmurs"}, {"id": "c", "text": "Presence of fluid, air, or masses"}, {"id": "d", "text": "Frequency of bowel sounds"}]'::jsonb, '["c"]', 'Percussion is used to find out whether there is fluid, air, or solid masses under the skin. Bowel sound frequency is assessed by auscultation.'),
  ('bowel_sounds', 47, 'A client with a suspected abdominal aortic aneurysm suddenly reports severe abdominal pain and becomes hypotensive. Which complication should the nurse suspect?', '[{"id": "a", "text": "Gastroenteritis"}, {"id": "b", "text": "Aneurysm rupture"}, {"id": "c", "text": "Constipation"}, {"id": "d", "text": "Early bowel obstruction"}]'::jsonb, '["b"]', 'Severe back or abdominal pain, hypotension, and shock are signs of AAA rupture. Early bowel obstruction is associated with hyperactive bowel sounds, not hypotension.'),
  ('bowel_sounds', 48, 'The nurse auscultates a client''s lungs. Which findings is the nurse listening for?', '[{"id": "a", "text": "Tenderness and rigidity"}, {"id": "b", "text": "Organ size and position"}, {"id": "c", "text": "Tympany and dullness"}, {"id": "d", "text": "Crackles and wheezes"}]'::jsonb, '["d"]', 'Lung auscultation assesses breath sounds such as clear sounds, crackles, and wheezes. Tympany and dullness are percussion sounds.'),
  ('bowel_sounds', 49, 'The nurse auscultates a client''s bowel sounds. Which characteristics of the sounds should the nurse evaluate?', '[{"id": "a", "text": "Frequency and quality"}, {"id": "b", "text": "Size and firmness"}, {"id": "c", "text": "Color and symmetry"}, {"id": "d", "text": "Dullness and flatness"}]'::jsonb, '["a"]', 'Bowel auscultation listens to gurgling sounds for frequency and quality. Size and firmness are assessed by palpation.'),
  ('bowel_sounds', 50, 'The nurse is assessing the abdomen of a client with a suspected abdominal aortic aneurysm. Which approach is correct?', '[{"id": "a", "text": "Percuss after palpating"}, {"id": "b", "text": "Auscultate and avoid deep palpation"}, {"id": "c", "text": "Deeply palpate to locate the aorta"}, {"id": "d", "text": "Palpate before auscultating"}]'::jsonb, '["b"]', 'Auscultation can detect a bruit, and deep palpation must be avoided when AAA is suspected because of the risk of rupture. Palpating before auscultating or percussing breaks the I-A-P-P order for the abdomen.'),
  ('positioning', 1, 'A client with chronic obstructive pulmonary disease (COPD) reports severe shortness of breath. In which position should the nurse place the client?', '[{"id": "a", "text": "High Fowler''s, head of bed at 60–90°"}, {"id": "b", "text": "Supine, lying flat on the back"}, {"id": "c", "text": "Sims'', left side-lying with right knee bent"}, {"id": "d", "text": "Low Fowler''s, head of bed at 15–30°"}]'::jsonb, '["a"]', 'High Fowler''s (60–90°) is used for severe breathing problems such as COPD. Low Fowler''s is used for resting and easy breathing, not severe distress.'),
  ('positioning', 2, 'The nurse is preparing to insert a nasogastric (NG) tube in an alert client. How should the nurse position the client?', '[{"id": "a", "text": "Sims'', left side-lying with right knee bent"}, {"id": "b", "text": "Trendelenburg, head lower than the feet"}, {"id": "c", "text": "High Fowler''s, sitting upright at 60–90°"}, {"id": "d", "text": "Supine, lying flat on the back"}]'::jsonb, '["c"]', 'High Fowler''s position is used for NG tube insertion. Sims'' position is used for enemas and rectal exams, not NG tube insertion.'),
  ('positioning', 3, 'A client who is at risk for choking is about to receive a meal. Which position best helps prevent aspiration during the feeding?', '[{"id": "a", "text": "Semi-Fowler''s"}, {"id": "b", "text": "Trendelenburg"}, {"id": "c", "text": "Low Fowler''s"}, {"id": "d", "text": "Supine"}]'::jsonb, '["a"]', 'Semi-Fowler''s is the position used during feeding to prevent aspiration (choking). Low Fowler''s is used for resting and easy breathing.'),
  ('positioning', 4, 'The nurse is placing a client in semi-Fowler''s position before a tube feeding. To which head-of-bed elevation should the nurse raise the bed?', '[{"id": "a", "text": "15–30°"}, {"id": "b", "text": "30–45°"}, {"id": "c", "text": "5–10°"}, {"id": "d", "text": "60–90°"}]'::jsonb, '["b"]', 'Semi-Fowler''s is 30–45° and is used for feeding to prevent aspiration. 15–30° is low Fowler''s and 60–90° is high Fowler''s.'),
  ('positioning', 5, 'A client who is breathing easily asks to rest in bed, and the nurse places the client in low Fowler''s position. Which head-of-bed elevation is correct?', '[{"id": "a", "text": "45–60°"}, {"id": "b", "text": "30–45°"}, {"id": "c", "text": "15–30°"}, {"id": "d", "text": "60–90°"}]'::jsonb, '["c"]', 'Low Fowler''s is 15–30° and is used for resting and easy breathing. 30–45° is semi-Fowler''s, used for feeding.'),
  ('positioning', 6, 'A provider orders high Fowler''s position for a client. To which head-of-bed elevation should the nurse raise the bed?', '[{"id": "a", "text": "10–15°"}, {"id": "b", "text": "30–45°"}, {"id": "c", "text": "60–90°"}, {"id": "d", "text": "15–30°"}]'::jsonb, '["c"]', 'High Fowler''s is 60–90°. 30–45° is semi-Fowler''s and 15–30° is low Fowler''s.'),
  ('positioning', 7, 'A client with a severe breathing problem is sitting on the edge of the bed, leaning forward over the overbed table. The nurse recognizes this as which position?', '[{"id": "a", "text": "Sims'' position"}, {"id": "b", "text": "Orthopneic (tripod) position"}, {"id": "c", "text": "Reverse Trendelenburg position"}, {"id": "d", "text": "Semi-Fowler''s position"}]'::jsonb, '["b"]', 'The orthopneic position is sitting up and leaning forward over a table (tripod position) for severe breathing issues. Reverse Trendelenburg tilts the bed so the head is higher than the feet.'),
  ('positioning', 8, 'A client with severe breathing difficulty asks why the nurse suggested leaning forward over a padded overbed table. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Leaning over the table makes it easier for your lungs to expand.\""}, {"id": "b", "text": "\"Leaning over the table helps to prevent pressure ulcers.\""}, {"id": "c", "text": "\"Leaning forward helps to fill the veins in your neck.\""}, {"id": "d", "text": "\"Leaning forward helps to reduce pressure on your brain.\""}]'::jsonb, '["a"]', 'The orthopneic position is used for severe breathing problems because it makes it easier to expand the lungs. Filling the neck veins is the purpose of Trendelenburg for central line insertion.'),
  ('positioning', 9, 'A client with severe lung problems from COVID-19 has poor oxygenation. Which position does the nurse anticipate will be ordered to help the lungs open?', '[{"id": "a", "text": "Sims''"}, {"id": "b", "text": "Prone"}, {"id": "c", "text": "Trendelenburg"}, {"id": "d", "text": "Reverse Trendelenburg"}]'::jsonb, '["b"]', 'The prone (belly-down) position is used for severe COVID-19 lung problems because it helps the lungs open. Trendelenburg is used for central line insertion.'),
  ('positioning', 10, 'The nurse asks an unlicensed assistive personnel (UAP) to help place a client in the prone position. Which description should the nurse give?', '[{"id": "a", "text": "Lying flat on the back"}, {"id": "b", "text": "Lying on the left side, right knee bent"}, {"id": "c", "text": "Lying on the stomach, belly down"}, {"id": "d", "text": "Sitting up, leaning over a table"}]'::jsonb, '["c"]', 'Prone means lying on the stomach (belly down). Lying flat on the back describes the supine position.'),
  ('positioning', 11, 'The nurse is reviewing positioning orders for several postoperative clients. For which client would the nurse expect an order for the prone position?', '[{"id": "a", "text": "A client who is about to receive an enema"}, {"id": "b", "text": "A client recovering after certain spinal surgeries"}, {"id": "c", "text": "A client who is recovering from a seizure"}, {"id": "d", "text": "A client who is having a central line inserted"}]'::jsonb, '["b"]', 'The prone position is used after some spinal surgeries. Clients receiving enemas are placed in Sims'' position, and seizure recovery calls for the lateral position.'),
  ('positioning', 12, 'A client has just finished a seizure and is now drowsy. In which position should the nurse place the client?', '[{"id": "a", "text": "Trendelenburg (head down)"}, {"id": "b", "text": "Prone (belly down)"}, {"id": "c", "text": "Supine (flat on the back)"}, {"id": "d", "text": "Lateral (side-lying)"}]'::jsonb, '["d"]', 'The lateral (side-lying) position is used for seizure recovery because it helps open the airway. Prone is used for severe COVID-19 lung problems and after some spinal surgeries.'),
  ('positioning', 13, 'The nurse turns a client onto the side after a seizure. What is the primary purpose of this position?', '[{"id": "a", "text": "To reduce pressure on the brain"}, {"id": "b", "text": "To fill the veins of the neck"}, {"id": "c", "text": "To improve oxygenation of the lungs"}, {"id": "d", "text": "To help keep the airway open"}]'::jsonb, '["d"]', 'Lateral positioning during seizure recovery helps open the airway. Reducing pressure on the brain after surgery is a use of reverse Trendelenburg.'),
  ('positioning', 14, 'A client confined to bed is at risk for skin breakdown. Which position does the nurse use when turning the client to help prevent pressure ulcers?', '[{"id": "a", "text": "High Fowler''s"}, {"id": "b", "text": "Lateral (side-lying)"}, {"id": "c", "text": "Orthopneic"}, {"id": "d", "text": "Trendelenburg"}]'::jsonb, '["b"]', 'The lateral (side-lying) position is used for preventing pressure ulcers. High Fowler''s and orthopneic positions are used for breathing problems.'),
  ('positioning', 15, 'The nurse is positioning a client in Sims'' position. Which description is correct?', '[{"id": "a", "text": "Left side-lying with the right knee bent"}, {"id": "b", "text": "Right side-lying with the left knee bent"}, {"id": "c", "text": "Lying flat with the head lower than the feet"}, {"id": "d", "text": "Lying on the stomach with the head turned"}]'::jsonb, '["a"]', 'Sims'' position is left side-lying with the right knee bent. Right side-lying with the left knee bent reverses the correct side.'),
  ('positioning', 16, 'The nurse is about to administer a cleansing enema. Which position is most appropriate for the client?', '[{"id": "a", "text": "Reverse Trendelenburg position"}, {"id": "b", "text": "Sims'' position"}, {"id": "c", "text": "High Fowler''s position"}, {"id": "d", "text": "Supine position"}]'::jsonb, '["b"]', 'Sims'' position (left side-lying) is used for enemas and rectal exams. High Fowler''s is used for breathing problems and NG tube insertion.'),
  ('positioning', 17, 'A provider is about to perform a rectal examination. The nurse should assist the client into which position?', '[{"id": "a", "text": "Prone"}, {"id": "b", "text": "Orthopneic"}, {"id": "c", "text": "Semi-Fowler''s"}, {"id": "d", "text": "Sims''"}]'::jsonb, '["d"]', 'Sims'' position (left side) is used for rectal procedures such as rectal exams and enemas. Prone is used for severe COVID-19 lung problems and after some spinal surgeries.'),
  ('positioning', 18, 'The nurse observes a UAP preparing a client for an enema. Which action by the UAP requires correction?', '[{"id": "a", "text": "Turning the client onto the left side"}, {"id": "b", "text": "Placing the client in a side-lying position"}, {"id": "c", "text": "Bending the client''s right knee"}, {"id": "d", "text": "Turning the client onto the right side"}]'::jsonb, '["d"]', 'Enemas are given in Sims'' position, which is left side-lying with the right knee bent. Turning the client onto the right side is the incorrect side.'),
  ('positioning', 19, 'The nurse is assisting with insertion of a central line in the neck. Which position helps fill the neck veins for this procedure?', '[{"id": "a", "text": "High Fowler''s"}, {"id": "b", "text": "Trendelenburg"}, {"id": "c", "text": "Reverse Trendelenburg"}, {"id": "d", "text": "Orthopneic"}]'::jsonb, '["b"]', 'Trendelenburg (head lower than feet) is used for central line insertion because it helps fill the neck veins. Reverse Trendelenburg raises the head above the feet.'),
  ('positioning', 20, 'A nursing student asks what the Trendelenburg position looks like. Which description should the nurse give?', '[{"id": "a", "text": "Bed tilted so the head is lower than the feet"}, {"id": "b", "text": "Sitting up while leaning forward over a table"}, {"id": "c", "text": "Lying on the left side with the right knee bent"}, {"id": "d", "text": "Bed tilted so the head is higher than the feet"}]'::jsonb, '["a"]', 'In the Trendelenburg position the bed is tilted so the head is lower than the feet. A bed tilted with the head higher than the feet is reverse Trendelenburg.'),
  ('positioning', 21, 'A postoperative order reads "reverse Trendelenburg position." How should the nurse position the bed?', '[{"id": "a", "text": "Flat, with the client on the left side"}, {"id": "b", "text": "Flat, with the client lying on the back"}, {"id": "c", "text": "Tilted so the head is higher than the feet"}, {"id": "d", "text": "Tilted so the head is lower than the feet"}]'::jsonb, '["c"]', 'In reverse Trendelenburg the bed is tilted so the head is higher than the feet. Head lower than the feet is the Trendelenburg position.'),
  ('positioning', 22, 'A client is placed in reverse Trendelenburg position after surgery. What is the purpose of this position?', '[{"id": "a", "text": "To help fill the neck veins"}, {"id": "b", "text": "To help the lungs open in severe lung disease"}, {"id": "c", "text": "To reduce pressure on the brain or abdomen"}, {"id": "d", "text": "To allow an enema to be given safely"}]'::jsonb, '["c"]', 'Reverse Trendelenburg is used after some surgeries to reduce pressure on the brain or abdomen. Filling the neck veins is the purpose of Trendelenburg during central line insertion.'),
  ('positioning', 23, 'The nurse documents that a sleeping client is in the supine position. This means the client is:', '[{"id": "a", "text": "Sitting upright in bed"}, {"id": "b", "text": "Lying flat on the back"}, {"id": "c", "text": "Lying on one side"}, {"id": "d", "text": "Lying on the stomach"}]'::jsonb, '["b"]', 'Supine means lying flat on the back. Lying on the stomach is the prone position.'),
  ('positioning', 24, 'A nursing student describes therapeutic positions. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"Orthopneic position is sitting up and leaning over a table.\""}, {"id": "b", "text": "\"Prone position means lying on the stomach, belly down.\""}, {"id": "c", "text": "\"Sims'' position is left side-lying with the right knee bent.\""}, {"id": "d", "text": "\"Reverse Trendelenburg tilts the bed so the head is lower than the feet.\""}]'::jsonb, '["d"]', 'Reverse Trendelenburg tilts the bed so the head is higher than the feet; head lower than the feet is Trendelenburg. The other statements correctly describe Sims'', prone, and orthopneic positions.'),
  ('positioning', 25, 'The nurse reviews Fowler''s positions with a newly hired nurse. Which statement by the newly hired nurse requires correction?', '[{"id": "a", "text": "\"Semi-Fowler''s is 30–45° and is used during feeding.\""}, {"id": "b", "text": "\"Semi-Fowler''s is 60–90° and is used for breathing problems.\""}, {"id": "c", "text": "\"Low Fowler''s is 15–30° and is used for resting.\""}, {"id": "d", "text": "\"High Fowler''s is 60–90° and is used for breathing problems.\""}]'::jsonb, '["b"]', 'Semi-Fowler''s is 30–45° and is used for feeding to prevent aspiration; 60–90° is high Fowler''s, the best position for breathing problems. The other statements are accurate.'),
  ('positioning', 26, 'The nurse is caring for four clients. Which client should be placed in high Fowler''s position?', '[{"id": "a", "text": "A client who is recovering from a seizure"}, {"id": "b", "text": "A client who is about to receive an enema"}, {"id": "c", "text": "A client with severe shortness of breath"}, {"id": "d", "text": "A client who is having a central line inserted"}]'::jsonb, '["c"]', 'High Fowler''s is used for breathing problems. Enemas call for Sims'' position, seizure recovery calls for lateral, and central line insertion calls for Trendelenburg.'),
  ('positioning', 27, 'The nurse is caring for four clients. Which client should be assisted into Sims'' position?', '[{"id": "a", "text": "A client scheduled for a rectal examination"}, {"id": "b", "text": "A client with severe COVID-19 lung problems"}, {"id": "c", "text": "A client who is about to eat a meal"}, {"id": "d", "text": "A client with COPD in respiratory distress"}]'::jsonb, '["a"]', 'Sims'' position (left side-lying) is used for enemas and rectal exams. A client with COPD in respiratory distress needs high Fowler''s, and feeding calls for semi-Fowler''s.'),
  ('positioning', 28, 'Which pairing of a client situation with a therapeutic position is correct?', '[{"id": "a", "text": "COVID-19 ARDS — prone"}, {"id": "b", "text": "Giving an enema — Trendelenburg"}, {"id": "c", "text": "Central line insertion — semi-Fowler''s"}, {"id": "d", "text": "Seizure recovery — Sims''"}]'::jsonb, '["a"]', 'The prone (belly-down) position is used for COVID-19 ARDS. Enemas call for Sims'' position, seizure recovery for lateral, and central line insertion for Trendelenburg.'),
  ('positioning', 29, 'The nurse is caring for four clients. Which client should be placed in the lateral (side-lying) position?', '[{"id": "a", "text": "A client who is receiving a tube feeding"}, {"id": "b", "text": "A client undergoing central line insertion"}, {"id": "c", "text": "A client with COPD who is severely short of breath"}, {"id": "d", "text": "A client who has just had a seizure"}]'::jsonb, '["d"]', 'The lateral position is used for seizure recovery. Feeding calls for semi-Fowler''s, and central line insertion calls for Trendelenburg.'),
  ('positioning', 30, 'A client is eating lunch in bed. Which action by the UAP requires correction by the nurse?', '[{"id": "a", "text": "Raising the head of the bed to 30–45° for the meal"}, {"id": "b", "text": "Lowering the bed flat while the client is still eating"}, {"id": "c", "text": "Keeping the client''s head elevated during the meal"}, {"id": "d", "text": "Placing the client in semi-Fowler''s before the meal"}]'::jsonb, '["b"]', 'Semi-Fowler''s (30–45°) is used during feeding to prevent aspiration, so lowering the bed flat while the client eats is unsafe. The other actions keep the client in semi-Fowler''s for the meal.'),
  ('positioning', 31, 'A client''s family asks why the nurse repositions the client according to specific orders. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Positioning is only for looks and has no other effect.\""}, {"id": "b", "text": "\"Positioning is done mainly to make bed-making easier.\""}, {"id": "c", "text": "\"Positioning matters only right after surgery.\""}, {"id": "d", "text": "\"The right position helps breathing, healing, and comfort.\""}]'::jsonb, '["d"]', 'Client positioning is how the body is placed to help breathing, healing, and comfort and to prevent complications. Positioning is used in many situations, not only after surgery.'),
  ('positioning', 32, 'An order states to place a client in a Fowler''s position. Which general description fits all Fowler''s positions?', '[{"id": "a", "text": "Lying on the stomach"}, {"id": "b", "text": "Left side-lying"}, {"id": "c", "text": "Sitting up in bed"}, {"id": "d", "text": "Head lower than the feet"}]'::jsonb, '["c"]', 'Fowler''s positions (low, semi, and high) all involve sitting up in bed at different angles. Head lower than the feet describes Trendelenburg.'),
  ('positioning', 33, 'A client with a severe breathing problem cannot tolerate leaning back, even in high Fowler''s position. Which alternative position is most appropriate?', '[{"id": "a", "text": "Orthopneic"}, {"id": "b", "text": "Sims''"}, {"id": "c", "text": "Trendelenburg"}, {"id": "d", "text": "Supine"}]'::jsonb, '["a"]', 'For breathing problems the recommended positions are high Fowler''s or orthopneic, which is sitting up and leaning forward over a table. Supine is lying flat on the back.'),
  ('positioning', 34, 'Which statement by a nursing student indicates correct understanding of the Trendelenburg position?', '[{"id": "a", "text": "\"The head is lower than the feet to help fill the neck veins.\""}, {"id": "b", "text": "\"The client sits up in bed and leans over a table.\""}, {"id": "c", "text": "\"The head of the bed is raised higher than the feet.\""}, {"id": "d", "text": "\"The client lies on the left side with the right knee bent.\""}]'::jsonb, '["a"]', 'Trendelenburg tilts the bed so the head is lower than the feet and is used for central line insertion to help fill the neck veins. Head higher than the feet is reverse Trendelenburg.'),
  ('positioning', 35, 'The nurse is reviewing the plan of care for four clients. Which client is most appropriate for the Trendelenburg position?', '[{"id": "a", "text": "A client who is undergoing central line insertion"}, {"id": "b", "text": "A client with COPD in respiratory distress"}, {"id": "c", "text": "A client needing less pressure on the brain after surgery"}, {"id": "d", "text": "A client who is about to receive a tube feeding"}]'::jsonb, '["a"]', 'Trendelenburg is used for central line insertion because it helps fill the neck veins. Reducing pressure on the brain after surgery calls for reverse Trendelenburg.'),
  ('positioning', 36, 'After a surgical procedure, the provider wants to reduce pressure on the client''s abdomen. Which position should the nurse anticipate?', '[{"id": "a", "text": "Prone"}, {"id": "b", "text": "Trendelenburg"}, {"id": "c", "text": "Sims''"}, {"id": "d", "text": "Reverse Trendelenburg"}]'::jsonb, '["d"]', 'Reverse Trendelenburg (head higher than feet) is used after some surgeries to reduce pressure on the brain or abdomen. Trendelenburg places the head lower than the feet.'),
  ('positioning', 37, 'The nurse is caring for four clients. Which client is best suited to the low Fowler''s position?', '[{"id": "a", "text": "A client with COPD in severe respiratory distress"}, {"id": "b", "text": "A client who is about to have an enema"}, {"id": "c", "text": "A client who is resting and breathing easily"}, {"id": "d", "text": "A client who is recovering from a seizure"}]'::jsonb, '["c"]', 'Low Fowler''s (15–30°) is used for resting and easy breathing. Severe respiratory distress calls for high Fowler''s.'),
  ('positioning', 38, 'A client without special positioning orders is getting ready to sleep. Which position is commonly used for sleeping?', '[{"id": "a", "text": "Supine"}, {"id": "b", "text": "Trendelenburg"}, {"id": "c", "text": "Orthopneic"}, {"id": "d", "text": "Sims''"}]'::jsonb, '["a"]', 'The supine position (lying flat on the back) is used for sleeping. Sims'' is used for enemas and rectal exams.'),
  ('positioning', 39, 'A client is told they will be placed in the prone position and asks what that means. Which response by the nurse is correct?', '[{"id": "a", "text": "\"You will lie flat on your back.\""}, {"id": "b", "text": "\"You will lie face down on your belly.\""}, {"id": "c", "text": "\"You will sit up and lean forward.\""}, {"id": "d", "text": "\"You will lie on your left side.\""}]'::jsonb, '["b"]', 'Prone is the face-down, belly-down position. Lying flat on the back is supine.'),
  ('positioning', 40, 'A client with COVID-19 ARDS has been placed in the prone position. Which finding indicates the position is having the intended effect?', '[{"id": "a", "text": "Improved oxygenation"}, {"id": "b", "text": "Reduced pressure on the brain"}, {"id": "c", "text": "Easier enema administration"}, {"id": "d", "text": "Fuller neck veins"}]'::jsonb, '["a"]', 'The prone position helps the lungs open and can improve oxygenation. Fuller neck veins are the goal of Trendelenburg for central line insertion.'),
  ('positioning', 41, 'The nurse teaches a family caregiver how to reposition a client who is confined to bed. Which statement by the caregiver indicates understanding?', '[{"id": "a", "text": "\"I will tilt the head of the bed down to protect the skin.\""}, {"id": "b", "text": "\"I will turn them onto their side to protect the skin.\""}, {"id": "c", "text": "\"I will sit them leaning over a table to protect the skin.\""}, {"id": "d", "text": "\"I will keep them in high Fowler''s to protect the skin.\""}]'::jsonb, '["b"]', 'The lateral (side-lying) position is used to prevent pressure ulcers. Leaning over a table (orthopneic) and high Fowler''s are positions for breathing problems.'),
  ('positioning', 42, 'The nurse places a client in Sims'' position to administer an enema. On which side should the client lie?', '[{"id": "a", "text": "Right side"}, {"id": "b", "text": "Left side"}, {"id": "c", "text": "On the stomach"}, {"id": "d", "text": "On the back"}]'::jsonb, '["b"]', 'Sims'' position is left side-lying with the right knee bent and is used for enemas. Lying on the back is supine and lying on the stomach is prone.'),
  ('positioning', 43, 'The nurse is caring for four clients. Which client requires high Fowler''s position for a procedure?', '[{"id": "a", "text": "A client who is having a central line inserted"}, {"id": "b", "text": "A client who is having a rectal exam"}, {"id": "c", "text": "A client who is receiving an enema"}, {"id": "d", "text": "A client who is having an NG tube inserted"}]'::jsonb, '["d"]', 'High Fowler''s is used for NG tube insertion. Enemas and rectal exams call for Sims'', and central line insertion calls for Trendelenburg.'),
  ('positioning', 44, 'A client returns from spinal surgery with an order for prone positioning. How should the nurse instruct the UAP to position the client?', '[{"id": "a", "text": "Place the client flat on the back"}, {"id": "b", "text": "Tilt the head lower than the feet"}, {"id": "c", "text": "Sit the client up, leaning forward"}, {"id": "d", "text": "Place the client on the stomach"}]'::jsonb, '["d"]', 'Prone means lying on the stomach and is used after some spinal surgeries. Lying flat on the back is the supine position.'),
  ('positioning', 45, 'A client has an order to reduce pressure on the brain after surgery. How should the nurse adjust the bed?', '[{"id": "a", "text": "Tilt it so the head is lower than the feet"}, {"id": "b", "text": "Place the client on the left side, right knee bent"}, {"id": "c", "text": "Tilt it so the head is higher than the feet"}, {"id": "d", "text": "Keep it flat with the client supine"}]'::jsonb, '["c"]', 'Reverse Trendelenburg (head higher than feet) is used after some surgeries to reduce pressure on the brain or abdomen. Head lower than the feet is Trendelenburg.'),
  ('positioning', 46, 'The nurse is preparing to place a client in Trendelenburg position for central line insertion. Which bed adjustment is correct?', '[{"id": "a", "text": "Raise the head of the bed to 30–45°"}, {"id": "b", "text": "Raise the head of the bed to 60–90°"}, {"id": "c", "text": "Tilt the bed so the head is lower than the feet"}, {"id": "d", "text": "Tilt the bed so the head is higher than the feet"}]'::jsonb, '["c"]', 'Trendelenburg tilts the bed so the head is lower than the feet, which helps fill the neck veins for central line insertion. Head higher than the feet is reverse Trendelenburg.'),
  ('positioning', 47, 'A UAP reports placing a client in the supine position for sleep. When checking on the client, the nurse expects to find the client:', '[{"id": "a", "text": "Lying on the left side"}, {"id": "b", "text": "Sitting up at 30–45°"}, {"id": "c", "text": "Lying flat on the back"}, {"id": "d", "text": "Lying on the stomach"}]'::jsonb, '["c"]', 'Supine is lying flat on the back and is used for sleeping. Lying on the stomach is prone.'),
  ('positioning', 48, 'The family of a client confined to bed asks why the nurse regularly turns the client onto one side. Which response by the nurse is best?', '[{"id": "a", "text": "\"Side-lying helps fill the neck veins.\""}, {"id": "b", "text": "\"Side-lying helps prevent pressure ulcers.\""}, {"id": "c", "text": "\"Side-lying is needed before each meal.\""}, {"id": "d", "text": "\"Side-lying reduces pressure on the brain.\""}]'::jsonb, '["b"]', 'The lateral (side-lying) position is used for preventing pressure ulcers. Filling the neck veins is the purpose of Trendelenburg.'),
  ('positioning', 49, 'A client in low Fowler''s position suddenly develops severe difficulty breathing. Which positioning action should the nurse take?', '[{"id": "a", "text": "Raise the head of the bed to high Fowler''s"}, {"id": "b", "text": "Lower the head of the bed until flat"}, {"id": "c", "text": "Turn the client into Sims'' position"}, {"id": "d", "text": "Tilt the bed into Trendelenburg"}]'::jsonb, '["a"]', 'High Fowler''s is the best position for breathing problems. Low Fowler''s is only for resting and easy breathing, and lowering the bed flat would not help breathing.'),
  ('positioning', 50, 'Which pairing of a therapeutic position with its use is correct?', '[{"id": "a", "text": "Trendelenburg — rectal exams"}, {"id": "b", "text": "Prone — central line insertion"}, {"id": "c", "text": "Sims'' — NG tube insertion"}, {"id": "d", "text": "Lateral — seizure recovery"}]'::jsonb, '["d"]', 'The lateral (side-lying) position is used for seizure recovery. NG tube insertion calls for high Fowler''s, central line insertion for Trendelenburg, and rectal exams for Sims''.'),
  ('physical', 1, 'A nurse is about to assess a client''s swollen left forearm. Which technique should the nurse use first?', '[{"id": "a", "text": "Palpation"}, {"id": "b", "text": "Percussion"}, {"id": "c", "text": "Inspection"}, {"id": "d", "text": "Auscultation"}]'::jsonb, '["c"]', 'Inspection is always done first, except in the abdomen, to get baseline information before touching the body. Palpation follows inspection.'),
  ('physical', 2, 'A nursing student asks why inspection is performed before the other assessment techniques. Which response by the nurse is correct?', '[{"id": "a", "text": "It gathers baseline information before touching the body"}, {"id": "b", "text": "It prevents changes in the bowel sounds of the chest"}, {"id": "c", "text": "It is the only technique that needs no equipment"}, {"id": "d", "text": "It replaces the need to palpate or auscultate"}]'::jsonb, '["a"]', 'Inspection is done first to get baseline information before touching or manipulating the body. It does not replace palpation or auscultation.'),
  ('physical', 3, 'A nurse is performing a respiratory assessment. In which order should the nurse use the assessment techniques?', '[{"id": "a", "text": "Auscultation, inspection, palpation, percussion"}, {"id": "b", "text": "Inspection, palpation, percussion, auscultation"}, {"id": "c", "text": "Inspection, auscultation, percussion, palpation"}, {"id": "d", "text": "Palpation, inspection, auscultation, percussion"}]'::jsonb, '["b"]', 'Outside the abdomen, the order is always inspection, palpation, percussion, then auscultation. Inspection, auscultation, percussion, palpation is the abdominal exception.'),
  ('physical', 4, 'A nurse is preparing to assess a client''s abdomen. Which sequence of techniques is correct?', '[{"id": "a", "text": "Inspect, palpate, percuss, auscultate"}, {"id": "b", "text": "Palpate, inspect, auscultate, percuss"}, {"id": "c", "text": "Auscultate, palpate, inspect, percuss"}, {"id": "d", "text": "Inspect, auscultate, percuss, palpate"}]'::jsonb, '["d"]', 'For the abdomen, the nurse inspects, auscultates, percusses, and then palpates to avoid disturbing bowel sounds. Inspect, palpate, percuss, auscultate is the standard order for other areas.'),
  ('physical', 5, 'A nurse observes a student nurse assessing a client''s abdomen. Which action by the student requires correction?', '[{"id": "a", "text": "Looking at the abdomen for distention"}, {"id": "b", "text": "Pressing on the abdomen before listening"}, {"id": "c", "text": "Listening in all 4 quadrants"}, {"id": "d", "text": "Percussing for dullness or tympany"}]'::jsonb, '["b"]', 'For the abdomen, the nurse looks, listens, then feels, so auscultation comes before touching. Inspecting for distention, listening in all 4 quadrants, and percussing are correct.'),
  ('physical', 6, 'A student asks why the abdomen is auscultated before it is palpated or percussed. Which response by the nurse is accurate?', '[{"id": "a", "text": "To avoid disturbing the bowel sounds"}, {"id": "b", "text": "To get baseline data on skin color"}, {"id": "c", "text": "To assess temperature with the dorsum"}, {"id": "d", "text": "To prevent artifact from clothing"}]'::jsonb, '["a"]', 'The abdominal sequence avoids disturbing bowel sounds. Listening over bare skin, not the order of techniques, prevents clothing artifact.'),
  ('physical', 7, 'A nurse wants to assess the skin temperature of a client''s lower legs. Which part of the hand should the nurse use?', '[{"id": "a", "text": "The fingertips"}, {"id": "b", "text": "The palm"}, {"id": "c", "text": "The back of the hand"}, {"id": "d", "text": "The side of the thumb"}]'::jsonb, '["c"]', 'The back of the hand (dorsum) is used to check temperature because it is more sensitive. The fingertips and palm are not the recommended surfaces for temperature.'),
  ('physical', 8, 'A nurse observes a student assessing a client''s skin. Which action by the student requires correction?', '[{"id": "a", "text": "Using the back of the hand to feel skin temperature"}, {"id": "b", "text": "Inspecting the skin for bruises and rashes"}, {"id": "c", "text": "Listening to the heart through the client''s gown"}, {"id": "d", "text": "Comparing the left side with the right side"}]'::jsonb, '["c"]', 'The nurse should always listen over bare skin, not over clothes, because clothing creates artifact sounds. Using the dorsum for temperature and comparing sides are correct.'),
  ('physical', 9, 'A nurse is assessing a client''s skin texture. Which technique is the nurse using when determining whether the skin is rough, smooth, dry, or moist?', '[{"id": "a", "text": "Palpation"}, {"id": "b", "text": "Inspection"}, {"id": "c", "text": "Percussion"}, {"id": "d", "text": "Auscultation"}]'::jsonb, '["a"]', 'Palpation uses the hands to feel skin, muscles, and organs, including texture such as rough, smooth, dry, or moist. Inspection relies on the eyes only.'),
  ('physical', 10, 'Which assessment does the nurse perform using palpation?', '[{"id": "a", "text": "Listening for bruits over a vessel"}, {"id": "b", "text": "Feeling pulses for strength and regularity"}, {"id": "c", "text": "Tapping the chest for resonance"}, {"id": "d", "text": "Observing posture and alignment"}]'::jsonb, '["b"]', 'Palpation includes checking pulses for strength and regularity. Listening for bruits is auscultation, tapping is percussion, and observing posture is inspection.'),
  ('physical', 11, 'A nurse is watching a client walk to the bathroom and noting the client''s body alignment. Which assessment technique is the nurse using?', '[{"id": "a", "text": "Palpation"}, {"id": "b", "text": "Percussion"}, {"id": "c", "text": "Auscultation"}, {"id": "d", "text": "Inspection"}]'::jsonb, '["d"]', 'Inspection involves looking carefully, including watching how the patient moves and observing posture and body alignment. Palpation requires touching the client.'),
  ('physical', 12, 'A nurse percusses over a client''s liver. Which percussion sound should the nurse expect?', '[{"id": "a", "text": "Resonant"}, {"id": "b", "text": "Tympanic"}, {"id": "c", "text": "Dull"}, {"id": "d", "text": "Hyperresonant"}]'::jsonb, '["c"]', 'A dull sound is heard over solid organs or fluid, such as the liver. A resonant sound is heard over air-filled structures such as normal lungs.'),
  ('physical', 13, 'A nurse percusses over the lung fields of a healthy adult. Which sound is expected?', '[{"id": "a", "text": "Resonant"}, {"id": "b", "text": "Dull"}, {"id": "c", "text": "Flat"}, {"id": "d", "text": "Tympanic"}]'::jsonb, '["a"]', 'Resonant sounds are heard over air-filled structures such as normal lungs. Tympanic, drum-like sounds are expected over the stomach and intestines.'),
  ('physical', 14, 'A nurse percusses over a client''s stomach and hears a hollow, drum-like sound. How should the nurse document this sound?', '[{"id": "a", "text": "Flat"}, {"id": "b", "text": "Dull"}, {"id": "c", "text": "Tympanic"}, {"id": "d", "text": "Resonant"}]'::jsonb, '["c"]', 'A tympanic sound is hollow and drum-like and is heard over the stomach and intestines. A dull sound is heard over solid organs or fluid.'),
  ('physical', 15, 'A client involved in a motor vehicle crash has sudden shortness of breath. The nurse percusses the chest and hears hyperresonance on one side. What does this finding suggest?', '[{"id": "a", "text": "A solid organ beneath the area"}, {"id": "b", "text": "Excessive air, as in pneumothorax"}, {"id": "c", "text": "Normal air-filled lung tissue"}, {"id": "d", "text": "Fluid collecting in the chest"}]'::jsonb, '["b"]', 'Hyperresonance indicates excessive air, as seen in pneumothorax. Normal lungs produce a resonant sound, and fluid produces a dull sound.'),
  ('physical', 16, 'A nurse percusses over a client''s thigh muscle. Which sound should the nurse expect?', '[{"id": "a", "text": "Tympanic"}, {"id": "b", "text": "Resonant"}, {"id": "c", "text": "Hyperresonant"}, {"id": "d", "text": "Flat"}]'::jsonb, '["d"]', 'Flatness is a very dull sound heard over muscle or bone. Tympanic sounds are heard over hollow structures such as the stomach.'),
  ('physical', 17, 'A nursing student asks what percussion helps the nurse identify. Which response is accurate?', '[{"id": "a", "text": "Skin temperature and texture"}, {"id": "b", "text": "Heart murmurs and irregular beats"}, {"id": "c", "text": "Fluid, air, or solid masses and organ boundaries"}, {"id": "d", "text": "Pupil size and reaction to light"}]'::jsonb, '["c"]', 'Percussion helps identify fluid, air, or solid masses under the skin and assess organ boundaries. Skin temperature and texture are assessed by palpation, and murmurs by auscultation.'),
  ('physical', 18, 'A nurse places the stethoscope over a client''s carotid artery and hears an abnormal whooshing sound. Which term should the nurse use to document this finding?', '[{"id": "a", "text": "Bruit"}, {"id": "b", "text": "Wheeze"}, {"id": "c", "text": "Crackle"}, {"id": "d", "text": "Murmur of the lung"}]'::jsonb, '["a"]', 'Bruits are abnormal whooshing sounds heard over blood vessels during auscultation. Wheezes and crackles are lung sounds.'),
  ('physical', 19, 'A nurse is auscultating a client''s abdomen for bowel sounds. Which technique is correct?', '[{"id": "a", "text": "Listen in one quadrant only"}, {"id": "b", "text": "Listen in the upper quadrants only"}, {"id": "c", "text": "Listen after palpating the abdomen"}, {"id": "d", "text": "Listen in all 4 quadrants"}]'::jsonb, '["d"]', 'Bowel sounds are gurgles heard by listening in all 4 quadrants of the abdomen. Listening after palpation is incorrect because the abdomen is auscultated before it is touched.'),
  ('physical', 20, 'A nurse auscultates crackles in the lower lobes of a client''s lungs. What do crackles indicate?', '[{"id": "a", "text": "Airway narrowing"}, {"id": "b", "text": "Fluid"}, {"id": "c", "text": "Normal airflow"}, {"id": "d", "text": "Excessive air"}]'::jsonb, '["b"]', 'Crackles indicate fluid in the lungs. Wheezes indicate narrowing of the airways.'),
  ('physical', 21, 'A nurse auscultates a client''s lungs and identifies wheezes. What do wheezes indicate?', '[{"id": "a", "text": "Fluid in the alveoli"}, {"id": "b", "text": "Normal vesicular airflow"}, {"id": "c", "text": "Narrowing of the airways"}, {"id": "d", "text": "A solid organ under the lung"}]'::jsonb, '["c"]', 'Wheezes indicate narrowing. Crackles, not wheezes, indicate fluid.'),
  ('physical', 22, 'A nurse auscultates the lungs of a healthy adult client. Which finding is expected?', '[{"id": "a", "text": "Clear, vesicular sounds"}, {"id": "b", "text": "Crackles in the bases"}, {"id": "c", "text": "Expiratory wheezes"}, {"id": "d", "text": "Diminished sounds on one side"}]'::jsonb, '["a"]', 'Normal lung sounds are clear and vesicular. Crackles, wheezes, and diminished sounds are abnormal.'),
  ('physical', 23, 'A nurse is auscultating a client''s lungs during a head-to-toe assessment. Where should the nurse listen?', '[{"id": "a", "text": "Over the front of the chest only"}, {"id": "b", "text": "Over the back only"}, {"id": "c", "text": "Over one side only"}, {"id": "d", "text": "Over the front and the back"}]'::jsonb, '["d"]', 'The nurse listens to the lungs over the front and back for breath sounds. Listening over only one area can miss abnormal findings.'),
  ('physical', 24, 'A nurse inspects a client''s neck and notes jugular vein distention (JVD). The nurse recognizes this finding as a sign of which type of problem?', '[{"id": "a", "text": "A heart problem"}, {"id": "b", "text": "A bowel problem"}, {"id": "c", "text": "A skin problem"}, {"id": "d", "text": "A hearing problem"}]'::jsonb, '["a"]', 'Jugular vein distention is a sign of a heart problem. It is not associated with bowel, skin, or hearing problems.'),
  ('physical', 25, 'During the neck assessment, a nurse asks the client to turn the head from side to side. What is the nurse assessing?', '[{"id": "a", "text": "Tracheal deviation"}, {"id": "b", "text": "Neck range of motion"}, {"id": "c", "text": "Lymph node swelling"}, {"id": "d", "text": "Jugular vein distention"}]'::jsonb, '["b"]', 'Asking the client to turn the head checks neck range of motion. Lymph nodes are palpated, and tracheal deviation is assessed separately.'),
  ('physical', 26, 'A nurse is assessing the neck of a client. Which additional finding should the nurse assess in the neck?', '[{"id": "a", "text": "Capillary refill"}, {"id": "b", "text": "Grip strength"}, {"id": "c", "text": "Tracheal deviation"}, {"id": "d", "text": "Calf tenderness"}]'::jsonb, '["c"]', 'The neck assessment includes assessing for tracheal deviation. Grip strength and capillary refill are assessed in the arms and hands, and calf tenderness in the legs.'),
  ('physical', 27, 'During the head and face step of a head-to-toe assessment, a nurse examines the client''s ears, nose, and throat. What is the nurse checking for?', '[{"id": "a", "text": "Jugular vein distention"}, {"id": "b", "text": "Tracheal deviation"}, {"id": "c", "text": "Grip strength"}, {"id": "d", "text": "Drainage or signs of infection"}]'::jsonb, '["d"]', 'In the head and face step, the nurse checks the ears, nose, and throat for whether they are clear or show infection or drainage. JVD and tracheal deviation are assessed during the neck step.'),
  ('physical', 28, 'During the head and face assessment, which action is appropriate for the nurse to perform by palpation?', '[{"id": "a", "text": "Checking the skull and facial bones for tenderness"}, {"id": "b", "text": "Checking the pupils for reaction to light"}, {"id": "c", "text": "Checking the ears for drainage by looking"}, {"id": "d", "text": "Checking the scalp and hair for color"}]'::jsonb, '["a"]', 'The nurse palpates the skull and facial bones for tenderness or deformities. The pupils, ear drainage, and scalp color are assessed by inspection.'),
  ('physical', 29, 'A nurse assesses the skin turgor on a client''s forearm. What is the nurse evaluating?', '[{"id": "a", "text": "Circulation to the hand"}, {"id": "b", "text": "Skin temperature"}, {"id": "c", "text": "Sensation in the arm"}, {"id": "d", "text": "Hydration status"}]'::jsonb, '["d"]', 'Turgor reflects skin elasticity and is a hydration test. Skin temperature is assessed with the back of the hand.'),
  ('physical', 30, 'A nurse checks capillary refill on four clients. Which finding should the nurse report?', '[{"id": "a", "text": "Refill in 1 second"}, {"id": "b", "text": "Refill in 3.5 seconds"}, {"id": "c", "text": "Refill in 1.5 seconds"}, {"id": "d", "text": "Refill in under 2 seconds"}]'::jsonb, '["b"]', 'A capillary refill of less than 2 seconds is normal, so 3.5 seconds is abnormal and should be reported. The other times are within the normal limit.'),
  ('physical', 31, 'A nurse is assessing a client''s arms and hands. Which approach is correct?', '[{"id": "a", "text": "Palpate the radial pulse on the dominant arm only"}, {"id": "b", "text": "Check grip strength in one hand only"}, {"id": "c", "text": "Palpate both radial pulses and test both grips"}, {"id": "d", "text": "Skip the arms if the legs are normal"}]'::jsonb, '["c"]', 'The nurse palpates radial pulses in both arms and checks grip strength in both hands, comparing the two sides. Checking only one side misses differences.'),
  ('physical', 32, 'A nurse is assessing the arms of a client who has a peripheral IV. Which finding should the nurse look for during this step?', '[{"id": "a", "text": "Jugular vein distention"}, {"id": "b", "text": "Bowel sounds"}, {"id": "c", "text": "Tracheal deviation"}, {"id": "d", "text": "Swelling at the IV site"}]'::jsonb, '["d"]', 'During the arms and hands step, the nurse looks for swelling, wounds, and IV sites. JVD and tracheal deviation are neck findings, and bowel sounds are abdominal.'),
  ('physical', 33, 'A nurse is assessing pulses in a client''s feet. Which pulses should the nurse palpate?', '[{"id": "a", "text": "Dorsalis pedis and posterior tibial"}, {"id": "b", "text": "Radial and brachial"}, {"id": "c", "text": "Carotid and temporal"}, {"id": "d", "text": "Apical and radial"}]'::jsonb, '["a"]', 'In the legs and feet, the nurse palpates the dorsalis pedis and posterior tibial pulses. Radial pulses are palpated in the arms.'),
  ('physical', 34, 'A client is 2 days post-op after hip surgery. During the leg assessment, the nurse checks the calves for tenderness. What is the purpose of this assessment?', '[{"id": "a", "text": "To assess hydration"}, {"id": "b", "text": "To assess for DVT"}, {"id": "c", "text": "To assess sensation"}, {"id": "d", "text": "To assess grip strength"}]'::jsonb, '["b"]', 'Checking for calf tenderness is a DVT assessment. Hydration is assessed through skin turgor.'),
  ('physical', 35, 'A nurse is assessing a client''s lower extremities. Which finding is abnormal?', '[{"id": "a", "text": "Equal push and pull strength"}, {"id": "b", "text": "Palpable pedal pulses"}, {"id": "c", "text": "Intact skin without wounds"}, {"id": "d", "text": "Swelling of both ankles"}]'::jsonb, '["d"]', 'During the leg assessment, the nurse looks for swelling (edema), wounds, and discoloration as abnormal findings. Equal strength, palpable pulses, and intact skin are expected.'),
  ('physical', 36, 'During a neurological check, a nurse notes the client''s right hand grip is much weaker than the left. Which action should the nurse take?', '[{"id": "a", "text": "Report the finding right away"}, {"id": "b", "text": "Recheck it at the next shift"}, {"id": "c", "text": "Document it as normal variation"}, {"id": "d", "text": "Assess only the stronger side"}]'::jsonb, '["a"]', 'Hand grips and foot pushes should be equal on both sides, and abnormal findings are reported right away. Delaying or labeling it normal ignores an abnormal asymmetry.'),
  ('physical', 37, 'A nurse is performing a quick neurological check on a client. Which question assesses orientation to situation?', '[{"id": "a", "text": "\"What is your full name?\""}, {"id": "b", "text": "\"Where are you right now?\""}, {"id": "c", "text": "\"Why are you in the hospital?\""}, {"id": "d", "text": "\"What is today''s date?\""}]'::jsonb, '["c"]', 'Orientation is assessed to person, place, time, and situation; asking why the client is hospitalized checks situation. Name checks person, location checks place, and date checks time.'),
  ('physical', 38, 'A client with a head injury has a changing level of consciousness. Which tool may the nurse use during the neurological check if needed?', '[{"id": "a", "text": "Snellen chart"}, {"id": "b", "text": "Glasgow Coma Scale"}, {"id": "c", "text": "Pulse grading scale"}, {"id": "d", "text": "Fall risk scale"}]'::jsonb, '["b"]', 'The Glasgow Coma Scale is used during the neurological check if needed. The other tools do not assess level of consciousness.'),
  ('physical', 39, 'A client reports numbness and tingling in the fingers. Which part of the assessment does this finding relate to?', '[{"id": "a", "text": "Sensation in the neurological check"}, {"id": "b", "text": "Percussion of the abdomen"}, {"id": "c", "text": "Inspection of the neck"}, {"id": "d", "text": "Auscultation of the heart"}]'::jsonb, '["a"]', 'The neurological quick check includes sensation, asking about numbness and tingling. The other assessments address different body areas.'),
  ('physical', 40, 'A nurse begins a head-to-toe assessment with a general survey. Which observations are part of the general survey?', '[{"id": "a", "text": "Bowel sounds and abdominal tenderness"}, {"id": "b", "text": "Calf tenderness and pedal pulses"}, {"id": "c", "text": "Level of consciousness, appearance, and behavior"}, {"id": "d", "text": "Tracheal deviation and neck range of motion"}]'::jsonb, '["c"]', 'The general survey is a first quick look at the whole person, including level of consciousness, appearance, behavior, and vital signs. Bowel sounds and calf tenderness are assessed later.'),
  ('physical', 41, 'A new nurse asks in which direction a head-to-toe assessment should proceed. Which response is correct?', '[{"id": "a", "text": "Start at the feet and move up"}, {"id": "b", "text": "Start with the abdomen and move outward"}, {"id": "c", "text": "Assess the most painful area first, then the rest randomly"}, {"id": "d", "text": "Start at the top and move down systematically"}]'::jsonb, '["d"]', 'A head-to-toe assessment always starts at the top and moves down systematically. Starting at the feet reverses the expected direction.'),
  ('physical', 42, 'A nurse completes an abdominal assessment. Which documentation entry best reflects the expected documentation standard?', '[{"id": "a", "text": "\"Abdomen distended and tender to touch in lower quadrants.\""}, {"id": "b", "text": "\"Client seems to be exaggerating abdominal pain.\""}, {"id": "c", "text": "\"Abdomen probably okay, client looks fine.\""}, {"id": "d", "text": "\"Abdomen assessed; client appears comfortable enough.\""}]'::jsonb, '["a"]', 'The nurse documents what is seen, felt, and heard clearly and objectively. Entries based on opinion or vague impressions are not objective.'),
  ('physical', 43, 'A nurse is assessing a client''s gastrointestinal system. Which group of findings should the nurse evaluate?', '[{"id": "a", "text": "Level of consciousness and pupils"}, {"id": "b", "text": "Bowel sounds, firmness, tenderness, and distention"}, {"id": "c", "text": "Muscle strength and joint movement"}, {"id": "d", "text": "Rate, depth, and breath sounds"}]'::jsonb, '["b"]', 'The gastrointestinal assessment includes bowel sounds, whether the abdomen is soft or firm, tenderness, and distention. Rate, depth, and breath sounds are respiratory findings.'),
  ('physical', 44, 'A nurse is assessing the skin of a client on bed rest. Which group of characteristics should the nurse evaluate?', '[{"id": "a", "text": "Heart sounds, blood pressure, and pulses"}, {"id": "b", "text": "Muscle strength and range of motion"}, {"id": "c", "text": "Pupils and level of consciousness"}, {"id": "d", "text": "Color, warmth, moisture, turgor, and wounds"}]'::jsonb, '["d"]', 'The skin assessment includes color, warmth, moisture, turgor (elasticity), wounds, and lesions. Heart sounds, blood pressure, and pulses belong to the cardiac assessment.'),
  ('physical', 45, 'A nurse is performing a cardiac assessment. Which data should the nurse collect?', '[{"id": "a", "text": "Heart sounds, blood pressure, and pulses"}, {"id": "b", "text": "Bowel sounds and distention"}, {"id": "c", "text": "Muscle strength and joint movement"}, {"id": "d", "text": "Skin turgor and lesions"}]'::jsonb, '["a"]', 'The cardiac assessment includes heart sounds, blood pressure, and pulses (rate, rhythm, strength). Bowel sounds belong to the gastrointestinal assessment.'),
  ('physical', 46, 'A nurse is assessing a client''s respiratory system. Which data should the nurse collect?', '[{"id": "a", "text": "Pupil size and reaction"}, {"id": "b", "text": "Joint movement and range of motion"}, {"id": "c", "text": "Rate, depth, and breath sounds"}, {"id": "d", "text": "Bowel sounds and tenderness"}]'::jsonb, '["c"]', 'The respiratory assessment includes rate, depth, and breath sounds such as crackles, wheezes, or clear sounds. Pupil size is a neurological finding.'),
  ('physical', 47, 'A nurse is performing a musculoskeletal assessment on a client with arthritis. Which data should the nurse collect?', '[{"id": "a", "text": "Level of consciousness and pupils"}, {"id": "b", "text": "Muscle strength and range of motion"}, {"id": "c", "text": "Heart sounds and blood pressure"}, {"id": "d", "text": "Breath sounds and depth"}]'::jsonb, '["b"]', 'The musculoskeletal assessment includes muscle strength, joint movement, and range of motion. Level of consciousness and pupils are neurological findings.'),
  ('physical', 48, 'A nurse is assessing a client''s chest. Which observation is made by inspection of breathing?', '[{"id": "a", "text": "Whether breathing is easy or labored"}, {"id": "b", "text": "Whether the lungs sound clear"}, {"id": "c", "text": "Whether the heart has a murmur"}, {"id": "d", "text": "Whether crackles are present"}]'::jsonb, '["a"]', 'The nurse looks at breathing effort to see whether it is easy or labored. Lung sounds, murmurs, and crackles are detected by auscultation.'),
  ('physical', 49, 'A nurse auscultates a client''s heart. Which finding should the nurse report as abnormal?', '[{"id": "a", "text": "A regular lub-dub rhythm"}, {"id": "b", "text": "Irregular beats"}, {"id": "c", "text": "Sounds heard over bare skin"}, {"id": "d", "text": "A steady, regular beat"}]'::jsonb, '["b"]', 'During heart auscultation, the nurse listens for the lub-dub rhythm, murmurs, and irregular beats; irregular beats are abnormal. A regular lub-dub rhythm is expected.'),
  ('physical', 50, 'A nurse is inspecting a client''s skin on admission. Which findings should the nurse look for during inspection?', '[{"id": "a", "text": "Organ size and enlargement"}, {"id": "b", "text": "Bowel sounds in each quadrant"}, {"id": "c", "text": "Swelling, redness, bruises, and rashes"}, {"id": "d", "text": "Pulse strength and regularity"}]'::jsonb, '["c"]', 'Inspection includes looking for swelling, redness, bruises, and rashes. Organ size and pulse strength are assessed by palpation, and bowel sounds by auscultation.'),
  ('maslow', 1, 'The nurse receives report on four clients. Which client should the nurse assess first?', '[{"id": "a", "text": "A client who is upset about the appearance of a new scar"}, {"id": "b", "text": "A client who reports new, severe shortness of breath"}, {"id": "c", "text": "A client who says she misses her family and feels lonely"}, {"id": "d", "text": "A client who wants to talk about returning to college"}]'::jsonb, '["b"]', 'Physiological needs, especially the ABCs, are always prioritized first. Body image, loneliness, and personal growth are psychosocial needs addressed after physical and safety needs.'),
  ('maslow', 2, 'A nurse is caring for four clients. According to Maslow''s hierarchy, which client need is the highest priority?', '[{"id": "a", "text": "A client who feels isolated from friends"}, {"id": "b", "text": "A client who is worried about body image"}, {"id": "c", "text": "A client who reports severe incisional pain"}, {"id": "d", "text": "A client who wants to plan a new career"}]'::jsonb, '["c"]', 'Pain management is a physiological need, not just comfort, so it comes before psychosocial needs. Isolation, body image, and career goals are love/belonging, self-esteem, and self-actualization needs.'),
  ('maslow', 3, 'A confused older client keeps trying to get out of bed without help. Which action by the unlicensed assistive personnel (UAP) requires correction by the nurse?', '[{"id": "a", "text": "Placing the call light within the client''s reach"}, {"id": "b", "text": "Turning on the bed alarm for the client''s bed"}, {"id": "c", "text": "Avoiding a sedative unless it is truly necessary"}, {"id": "d", "text": "Applying wrist restraints to keep the client in bed"}]'::jsonb, '["d"]', 'Ensuring safety without unnecessary restraints or sedation is the priority. Call lights and bed alarms are the least restrictive interventions.'),
  ('maslow', 4, 'A confused client on a medical unit repeatedly tries to climb out of bed without assistance. Which intervention should the nurse implement first?', '[{"id": "a", "text": "Place the call light within reach and use a bed alarm"}, {"id": "b", "text": "Apply wrist restraints to prevent the client from falling"}, {"id": "c", "text": "Administer a prescribed sedative to keep the client calm"}, {"id": "d", "text": "Lower the lights and close the door so the client can rest"}]'::jsonb, '["a"]', 'Bed alarms and call lights are the least restrictive interventions for safety. Restraints and sedation should not be used unnecessarily.'),
  ('maslow', 5, 'A client with a terminal illness whose pain is controlled is crying quietly and says, "I feel so alone." Which nursing action is best?', '[{"id": "a", "text": "Encourage the client to think more positively"}, {"id": "b", "text": "Sit with the client and actively listen"}, {"id": "c", "text": "Suggest the client try to rest for a while"}, {"id": "d", "text": "Remind the client that many people care"}]'::jsonb, '["b"]', 'Providing companionship addresses emotional needs and supports love and belonging; therapeutic presence is key. Encouraging positive thinking does not address the client''s emotional need.'),
  ('maslow', 6, 'A retired client recovering from a minor illness tells the nurse, "I''d love to start mentoring young people in my community." Which response by the nurse is best?', '[{"id": "a", "text": "\"Right now, you should focus only on your recovery.\""}, {"id": "b", "text": "\"You should find something less stressful to do.\""}, {"id": "c", "text": "\"That''s wonderful! How can I support you in this goal?\""}, {"id": "d", "text": "\"Maybe wait until you feel 100% better to consider it.\""}]'::jsonb, '["c"]', 'Self-actualization focuses on personal growth and fulfillment, and supporting the client''s goals promotes holistic care. Discouraging the goal does not support self-actualization.'),
  ('maslow', 7, 'A nursing student asks the nurse to list Maslow''s levels of needs from highest to lowest priority. Which order is correct?', '[{"id": "a", "text": "Safety, physiological, self-esteem, love and belonging, self-actualization"}, {"id": "b", "text": "Physiological, love and belonging, safety, self-actualization, self-esteem"}, {"id": "c", "text": "Physiological, safety, love and belonging, self-esteem, self-actualization"}, {"id": "d", "text": "Physiological, safety, self-esteem, self-actualization, love and belonging"}]'::jsonb, '["c"]', 'Maslow''s hierarchy prioritizes needs from basic physiological needs, then safety and security, love and belonging, self-esteem, and finally self-actualization. Safety never comes before physiological needs.'),
  ('maslow', 8, 'None of the nurse''s four assigned clients has an immediate physiological threat. Which client should the nurse see first?', '[{"id": "a", "text": "A confused client who is climbing out of bed alone"}, {"id": "b", "text": "A client who would like help calling a close friend"}, {"id": "c", "text": "A client who is anxious about how a scar will look"}, {"id": "d", "text": "A client who wants information about a support group"}]'::jsonb, '["a"]', 'Safety is the next priority if no immediate physiological threats exist, and risk for falls is a safety need. The other clients have love/belonging or self-esteem needs.'),
  ('maslow', 9, 'The nurse is planning care for a client recovering from surgery. Which client need would the nurse address last according to Maslow''s hierarchy?', '[{"id": "a", "text": "Elimination"}, {"id": "b", "text": "Infection control"}, {"id": "c", "text": "Family involvement"}, {"id": "d", "text": "Personal growth"}]'::jsonb, '["d"]', 'Self-actualization, which includes personal growth, is the lowest priority. Elimination is physiological, infection control is safety, and family involvement is love and belonging.'),
  ('maslow', 10, 'A nurse is classifying client needs using Maslow''s hierarchy. Which need belongs to the physiological level?', '[{"id": "a", "text": "Infection control"}, {"id": "b", "text": "Elimination"}, {"id": "c", "text": "Social relationships"}, {"id": "d", "text": "Body image concerns"}]'::jsonb, '["b"]', 'Elimination is a physiological need, the most basic and highest priority level. Infection control is a safety need, social relationships fall under love and belonging, and body image falls under self-esteem.'),
  ('maslow', 11, 'The nurse has four clients on a postoperative unit. Which client should the nurse see first?', '[{"id": "a", "text": "A client who is shivering with a new fever"}, {"id": "b", "text": "A client who wants help calling a family member"}, {"id": "c", "text": "A client who is upset about the look of the incision"}, {"id": "d", "text": "A client who asks about returning to a college program"}]'::jsonb, '["a"]', 'Temperature regulation is a physiological need and comes before psychosocial needs. Calling family, body image, and returning to school are love/belonging, self-esteem, and self-actualization needs.'),
  ('maslow', 12, 'Which client should the nurse attend to first?', '[{"id": "a", "text": "A client who wants to talk about feeling lonely"}, {"id": "b", "text": "A client who is worried about losing independence"}, {"id": "c", "text": "A client who has been unable to eat or drink for two days"}, {"id": "d", "text": "A client who wants to discuss long-term personal goals"}]'::jsonb, '["c"]', 'Nutrition and hydration are physiological needs, the highest priority level. Loneliness, independence, and personal goals are psychosocial needs addressed after physical needs.'),
  ('maslow', 13, 'According to Maslow''s hierarchy, which client need belongs to the safety and security level?', '[{"id": "a", "text": "Pain management"}, {"id": "b", "text": "Emotional support"}, {"id": "c", "text": "Promoting confidence"}, {"id": "d", "text": "Infection control"}]'::jsonb, '["d"]', 'Infection control is a safety and security need. Pain management is physiological, emotional support is love and belonging, and promoting confidence is self-esteem.'),
  ('maslow', 14, 'The nurse is about to begin diet teaching with a client when the nurse notices that another client is about to take medication left at the bedside that was meant for someone else. Which action should the nurse take first?', '[{"id": "a", "text": "Finish the diet teaching before addressing the medication"}, {"id": "b", "text": "Stop the other client from taking the wrong medication"}, {"id": "c", "text": "Provide emotional support to the client receiving teaching"}, {"id": "d", "text": "Document the medication concern for the next shift''s nurse"}]'::jsonb, '["b"]', 'Safety concerns such as medication errors always trump teaching or emotional support. Finishing the teaching first would delay addressing a safety threat.'),
  ('maslow', 15, 'None of the nurse''s four clients has an immediate physiological threat. Which client should the nurse see first?', '[{"id": "a", "text": "A client who states a plan to harm herself"}, {"id": "b", "text": "A client who wants more family involvement"}, {"id": "c", "text": "A client who is worried about her appearance"}, {"id": "d", "text": "A client who wants to pursue a new hobby"}]'::jsonb, '["a"]', 'Protection from harm, including self-harm, is a safety need and is the next priority when no physiological threats exist. The other clients have psychosocial needs.'),
  ('maslow', 16, 'A client tells the nurse that a partner has been physically abusing her at home. The nurse recognizes that protecting the client from abuse addresses which level of Maslow''s hierarchy?', '[{"id": "a", "text": "Love and belonging"}, {"id": "b", "text": "Self-esteem"}, {"id": "c", "text": "Safety and security"}, {"id": "d", "text": "Self-actualization"}]'::jsonb, '["c"]', 'Protection from harm, such as abuse, is part of the safety and security level. Love and belonging includes emotional support and social relationships.'),
  ('maslow', 17, 'A client recovering from a long illness has had no visitors. Which nursing intervention addresses the client''s love and belonging needs?', '[{"id": "a", "text": "Using a bed alarm at night"}, {"id": "b", "text": "Encouraging family involvement"}, {"id": "c", "text": "Encouraging independent bathing"}, {"id": "d", "text": "Offering prescribed pain medication"}]'::jsonb, '["b"]', 'Family involvement is part of the love and belonging level. A bed alarm addresses safety, independence addresses self-esteem, and pain medication addresses a physiological need.'),
  ('maslow', 18, 'A client who had a mastectomy says, "I don''t feel like myself when I look in the mirror." Addressing this concern meets which level of Maslow''s hierarchy?', '[{"id": "a", "text": "Self-esteem"}, {"id": "b", "text": "Physiological"}, {"id": "c", "text": "Safety and security"}, {"id": "d", "text": "Self-actualization"}]'::jsonb, '["a"]', 'Supporting body image concerns is part of the self-esteem level. Self-actualization involves personal growth and fulfilling potential.'),
  ('maslow', 19, 'A client recovering from surgery wants to resume self-care. Which nursing action best promotes the client''s self-esteem?', '[{"id": "a", "text": "Performing all hygiene tasks for the client"}, {"id": "b", "text": "Telling the client that self-care is unimportant"}, {"id": "c", "text": "Encouraging the client to do tasks they can manage"}, {"id": "d", "text": "Postponing self-care until the client is discharged"}]'::jsonb, '["c"]', 'Encouraging independence is part of the self-esteem level. Performing all tasks for the client removes the chance for independence.'),
  ('maslow', 20, 'Two clients have no physiological or safety concerns. One client is crying and says, "I have no one." The other wants to talk about learning a new hobby. Which statement explains why the nurse attends to the crying client first?', '[{"id": "a", "text": "Love and belonging needs come before self-actualization"}, {"id": "b", "text": "Self-actualization needs come before love and belonging"}, {"id": "c", "text": "Hobbies are a safety need and can be addressed later"}, {"id": "d", "text": "Crying is a physiological need that comes first"}]'::jsonb, '["a"]', 'Maslow''s hierarchy addresses needs in order of importance, with self-actualization as the lowest priority. Loneliness is a love and belonging need, which ranks above self-actualization.'),
  ('maslow', 21, 'Two clients call for the nurse at the same time. One reports new difficulty breathing, and the other asks for help combing her hair before visitors arrive. Which guiding question best helps the nurse decide whom to see first?', '[{"id": "a", "text": "\"Who called for help first?\""}, {"id": "b", "text": "\"Who will die first if I don''t help?\""}, {"id": "c", "text": "\"Who has visitors arriving soon?\""}, {"id": "d", "text": "\"Who has been waiting the longest?\""}]'::jsonb, '["b"]', 'When two clients need help, the nurse asks who will die first without help. The client with difficulty breathing has a physiological need that comes before a grooming request.'),
  ('maslow', 22, 'The nurse begins discharge teaching for a client, who suddenly becomes short of breath and cannot finish sentences. Which action should the nurse take?', '[{"id": "a", "text": "Continue the teaching but speak more slowly"}, {"id": "b", "text": "Give the client a handout to read later"}, {"id": "c", "text": "Ask a family member to listen to the teaching"}, {"id": "d", "text": "Stop teaching and address the breathing problem"}]'::jsonb, '["d"]', 'A client who can''t breathe can''t be taught; breathing is a physiological need that comes first. Continuing teaching in any form delays care for the breathing problem.'),
  ('maslow', 23, 'A client in rehabilitation is working on self-esteem goals and tries to walk to the bathroom alone despite an unsteady gait. Which need should the nurse address first?', '[{"id": "a", "text": "Promoting the client''s confidence"}, {"id": "b", "text": "Encouraging the client''s independence"}, {"id": "c", "text": "Preventing the client from falling"}, {"id": "d", "text": "Supporting the client''s personal growth"}]'::jsonb, '["c"]', 'Self-esteem cannot be promoted if the client is falling; safety needs come before self-esteem needs. Confidence and independence are self-esteem needs addressed after safety.'),
  ('maslow', 24, 'A nurse is reviewing prioritization with a nursing student. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"Airway problems are addressed before safety needs.\""}, {"id": "b", "text": "\"Pain is a comfort issue that can wait until after safety.\""}, {"id": "c", "text": "\"Safety comes next if there is no physiological threat.\""}, {"id": "d", "text": "\"Psychosocial needs come after physical and safety needs.\""}]'::jsonb, '["b"]', 'Pain management is physiological, not just comfort, so it is not deferred until after safety. The other statements are accurate.'),
  ('maslow', 25, 'A nurse working in triage uses Maslow''s hierarchy to prioritize four clients. Which client should be seen first?', '[{"id": "a", "text": "A client who is choking and unable to speak"}, {"id": "b", "text": "A client who is at risk for falls when walking"}, {"id": "c", "text": "A client who is tearful after a family argument"}, {"id": "d", "text": "A client who is embarrassed about a skin rash"}]'::jsonb, '["a"]', 'Maslow''s hierarchy is used to prioritize clients in triage, and airway is the first of the ABCs. Fall risk is a safety need, and the others are psychosocial.'),
  ('maslow', 26, 'A nurse has four clients. Which client should the nurse see first?', '[{"id": "a", "text": "A client asking for help to call a friend"}, {"id": "b", "text": "A client worried about returning to work"}, {"id": "c", "text": "A client who needs fall-prevention teaching"}, {"id": "d", "text": "A client with active bleeding soaking a dressing"}]'::jsonb, '["d"]', 'Circulation is one of the ABCs, which always come first. Fall-prevention teaching and psychosocial concerns are addressed after physiological threats.'),
  ('maslow', 27, 'A client with shortness of breath is very anxious and keeps asking for a family member. Which need should the nurse address first?', '[{"id": "a", "text": "Reducing the client''s anxiety"}, {"id": "b", "text": "Calling the client''s family member"}, {"id": "c", "text": "Meeting the client''s oxygenation needs"}, {"id": "d", "text": "Teaching the client relaxation techniques"}]'::jsonb, '["c"]', 'Oxygenation is a physiological need and comes before emotional support. Calling family addresses love and belonging, which comes after physical needs.'),
  ('maslow', 28, 'A nurse is creating a care plan for a postoperative client with four identified problems. Which problem should be listed as the highest priority?', '[{"id": "a", "text": "Risk for falls"}, {"id": "b", "text": "Social isolation"}, {"id": "c", "text": "Disturbed body image"}, {"id": "d", "text": "Acute incisional pain"}]'::jsonb, '["d"]', 'The hierarchy is applied when creating care plans, and pain management is a physiological need. Risk for falls is a safety need, which comes after physiological needs.'),
  ('maslow', 29, 'The nurse is assigned four clients on a medical unit. Which client should the nurse attend to first?', '[{"id": "a", "text": "A client who needs teaching about home fall prevention"}, {"id": "b", "text": "A client who is unable to urinate and has bladder discomfort"}, {"id": "c", "text": "A client who wants the nurse to call a friend to visit"}, {"id": "d", "text": "A client who is upset about hair loss from treatment"}]'::jsonb, '["b"]', 'Elimination is a physiological need and takes highest priority. Teaching, social contact, and body image concerns are addressed after physiological needs.'),
  ('maslow', 30, 'A nurse performs hand hygiene before and after caring for each client. Which level of Maslow''s hierarchy does this action support?', '[{"id": "a", "text": "Physiological"}, {"id": "b", "text": "Love and belonging"}, {"id": "c", "text": "Safety and security"}, {"id": "d", "text": "Self-esteem"}]'::jsonb, '["c"]', 'Infection control is part of the safety and security level. Physiological needs include the ABCs, nutrition, elimination, temperature, and pain.'),
  ('maslow', 31, 'Before giving a medication, the nurse double-checks that it is the right drug for the right client. This action addresses which level of Maslow''s hierarchy?', '[{"id": "a", "text": "Safety and security"}, {"id": "b", "text": "Self-esteem"}, {"id": "c", "text": "Love and belonging"}, {"id": "d", "text": "Self-actualization"}]'::jsonb, '["a"]', 'Medication safety is part of the safety and security level. Self-esteem includes independence, confidence, and body image.'),
  ('maslow', 32, 'A nurse is teaching a nursing student about prioritization. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"ABCs are addressed before any other needs.\""}, {"id": "b", "text": "\"Safety comes before emotional support needs.\""}, {"id": "c", "text": "\"Fall risk comes before an airway problem.\""}, {"id": "d", "text": "\"Self-actualization is the lowest priority.\""}]'::jsonb, '["c"]', 'Safety is the next priority only if no immediate physiological threats exist; an airway problem comes first. The other statements are accurate.'),
  ('maslow', 33, 'A client in long-term care has lost contact with friends and wants to reconnect. The nurse helps the client arrange visits. Which level of Maslow''s hierarchy does this address?', '[{"id": "a", "text": "Physiological"}, {"id": "b", "text": "Safety and security"}, {"id": "c", "text": "Self-esteem"}, {"id": "d", "text": "Love and belonging"}]'::jsonb, '["d"]', 'Social relationships are part of the love and belonging level. Self-esteem includes independence, confidence, and body image.'),
  ('maslow', 34, 'A client with a terminal illness says, "I feel so alone." Which response by the nurse requires correction?', '[{"id": "a", "text": "\"Would you like me to sit with you for a while?\""}, {"id": "b", "text": "\"Tell me more about what you are feeling right now.\""}, {"id": "c", "text": "\"I''m here with you. I''ll listen as long as you need.\""}, {"id": "d", "text": "\"Try to think positively; things could be worse.\""}]'::jsonb, '["d"]', 'Sitting with the client and actively listening supports love and belonging; therapeutic presence is key. Encouraging the client to think positively does not address the emotional need.'),
  ('maslow', 35, 'The nurse keeps an older client warm with blankets after the client was found cold and shivering. Which level of Maslow''s hierarchy does this intervention address?', '[{"id": "a", "text": "Physiological"}, {"id": "b", "text": "Safety and security"}, {"id": "c", "text": "Love and belonging"}, {"id": "d", "text": "Self-esteem"}]'::jsonb, '["a"]', 'Temperature regulation is a physiological need. Safety and security includes fall risk, infection control, medication safety, and protection from harm.'),
  ('maslow', 36, 'A client learning to walk with a new prosthesis says, "I don''t think I''ll ever be able to do this." Which nursing action best addresses the client''s self-esteem needs?', '[{"id": "a", "text": "Acknowledging the progress the client has made"}, {"id": "b", "text": "Doing the walking exercises for the client instead"}, {"id": "c", "text": "Telling the client that walking is not important"}, {"id": "d", "text": "Changing the subject to the client''s meal choices"}]'::jsonb, '["a"]', 'Promoting confidence is part of the self-esteem level. Doing the tasks for the client or dismissing the goal does not build confidence.'),
  ('maslow', 37, 'A client has been unable to keep any fluids down since the morning. The client also says, "I hate how I look since my surgery." Which need should the nurse address first?', '[{"id": "a", "text": "Discussing the client''s body image concerns"}, {"id": "b", "text": "Addressing the client''s hydration needs"}, {"id": "c", "text": "Encouraging family members to visit"}, {"id": "d", "text": "Promoting the client''s self-confidence"}]'::jsonb, '["b"]', 'Hydration is a physiological need and comes before self-esteem needs such as body image. Psychosocial needs are addressed after physical needs.'),
  ('maslow', 38, 'A nurse is reviewing priorities with a newly hired nurse. Which statement by the newly hired nurse indicates a need for further teaching?', '[{"id": "a", "text": "\"I address ABCs before a client''s safety needs.\""}, {"id": "b", "text": "\"Fall risk comes before a client''s emotional needs.\""}, {"id": "c", "text": "\"Self-esteem needs come before a client''s safety.\""}, {"id": "d", "text": "\"Pain is a physiological need, not just comfort.\""}]'::jsonb, '["c"]', 'Physiological and safety needs always come before emotional or self-esteem needs. The other statements are accurate.'),
  ('maslow', 39, 'A recovering client says, "When I''m better, I want to volunteer teaching children to read." Which response by the nurse requires correction?', '[{"id": "a", "text": "\"That''s a wonderful goal. How can I help you?\""}, {"id": "b", "text": "\"Tell me more about what you hope to do.\""}, {"id": "c", "text": "\"You should find something less stressful to do.\""}, {"id": "d", "text": "\"What would help you start working toward that?\""}]'::jsonb, '["c"]', 'Supporting the client''s goals promotes holistic care and self-actualization. Telling the client to find something less stressful discourages personal growth.'),
  ('maslow', 40, 'A client in rehabilitation says, "I want to finish my degree so I can reach my full potential." Which level of Maslow''s hierarchy does this statement reflect?', '[{"id": "a", "text": "Self-esteem"}, {"id": "b", "text": "Love and belonging"}, {"id": "c", "text": "Safety and security"}, {"id": "d", "text": "Self-actualization"}]'::jsonb, '["d"]', 'Fulfilling potential is part of self-actualization. Self-esteem involves independence, confidence, and body image.'),
  ('maslow', 41, 'A nursing student asks how psychosocial needs fit into prioritization. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"They are addressed after physical and safety needs are met.\""}, {"id": "b", "text": "\"They are addressed before safety needs in most situations.\""}, {"id": "c", "text": "\"They are addressed only after the client is discharged.\""}, {"id": "d", "text": "\"They are addressed at the same time as airway problems.\""}]'::jsonb, '["a"]', 'Psychosocial needs (love, esteem, and self-actualization) are addressed after physical and safety needs are met. They are not deferred until discharge.'),
  ('maslow', 42, 'Two clients need attention. One was found outdoors in cold weather and cannot stop shivering. The other wants to talk about writing a memoir. When asking which need must be met for survival, which client should the nurse see first?', '[{"id": "a", "text": "The client who wants to write a memoir"}, {"id": "b", "text": "Both clients at the same time"}, {"id": "c", "text": "The client who cannot stop shivering"}, {"id": "d", "text": "Whichever client called first"}]'::jsonb, '["c"]', 'When in doubt, the nurse asks which need must be met for survival; temperature regulation is a physiological need. Writing a memoir is a self-actualization need, the lowest priority.'),
  ('maslow', 43, 'A client''s breathing is stable, pain is controlled, and fall precautions are in place. The client now tells the nurse, "I feel lonely in here." Which action should the nurse take?', '[{"id": "a", "text": "Postpone emotional needs until the client is discharged"}, {"id": "b", "text": "Focus only on the client''s physical recovery for now"}, {"id": "c", "text": "Reassess the client''s fall precautions once again"}, {"id": "d", "text": "Provide emotional support and stay with the client"}]'::jsonb, '["d"]', 'Once basic needs are met, addressing psychosocial needs promotes holistic healing. The client''s physical and safety needs are already met, so emotional support is appropriate now.'),
  ('maslow', 44, 'The nurse is with a client who is crying about a family conflict when the nurse sees a confused client in the next room climbing over the bed rails. Which action should the nurse take first?', '[{"id": "a", "text": "Finish comforting the crying client"}, {"id": "b", "text": "Go to the client climbing over the rails"}, {"id": "c", "text": "Call the crying client''s family members"}, {"id": "d", "text": "Teach the crying client coping strategies"}]'::jsonb, '["b"]', 'Safety concerns such as falls always trump teaching or emotional support. Comforting the crying client addresses a love and belonging need, which comes after safety.'),
  ('maslow', 45, 'A nurse identifies that an older client has a risk for falls. Which level of Maslow''s hierarchy does this problem belong to?', '[{"id": "a", "text": "Physiological"}, {"id": "b", "text": "Safety and security"}, {"id": "c", "text": "Self-esteem"}, {"id": "d", "text": "Love and belonging"}]'::jsonb, '["b"]', 'Risk for falls is part of the safety and security level. Physiological needs include the ABCs, oxygenation, nutrition, elimination, temperature, and pain.'),
  ('maslow', 46, 'A nurse sits with a grieving client and offers comfort and emotional support. Which level of Maslow''s hierarchy does this address?', '[{"id": "a", "text": "Safety and security"}, {"id": "b", "text": "Self-esteem"}, {"id": "c", "text": "Love and belonging"}, {"id": "d", "text": "Self-actualization"}]'::jsonb, '["c"]', 'Emotional support is part of the love and belonging level. Self-esteem includes independence, confidence, and body image.'),
  ('maslow', 47, 'Two clients have no physiological or safety concerns. One client is distressed about body changes after surgery, and the other wants to explore personal growth goals. Which need should the nurse address first?', '[{"id": "a", "text": "Personal growth, because it is the top of the pyramid"}, {"id": "b", "text": "Both needs equally, because they are psychosocial"}, {"id": "c", "text": "Personal growth, because it promotes holistic care"}, {"id": "d", "text": "Body image, because self-esteem ranks higher"}]'::jsonb, '["d"]', 'Body image concerns are self-esteem needs, which rank above self-actualization, the lowest priority. Personal growth is a self-actualization need.'),
  ('maslow', 48, 'A nursing student says, "Self-actualization is the most important need because it is at the top of Maslow''s pyramid." Which response by the nurse is correct?', '[{"id": "a", "text": "\"Yes, it should be addressed before all other needs.\""}, {"id": "b", "text": "\"No, it is the lowest priority when planning care.\""}, {"id": "c", "text": "\"Yes, it ranks just after the client''s airway needs.\""}, {"id": "d", "text": "\"No, it is actually a part of the safety level.\""}]'::jsonb, '["b"]', 'Self-actualization is the lowest priority, and physiological needs are the most basic and highest priority. It is a separate level from safety.'),
  ('maslow', 49, 'The nurse places the call light within reach of a confused client who has tried to get up alone. This intervention addresses which level of Maslow''s hierarchy?', '[{"id": "a", "text": "Physiological"}, {"id": "b", "text": "Self-esteem"}, {"id": "c", "text": "Love and belonging"}, {"id": "d", "text": "Safety and security"}]'::jsonb, '["d"]', 'Placing the call light within reach is a least restrictive intervention that ensures safety. Self-esteem includes independence, confidence, and body image.'),
  ('maslow', 50, 'The nurse enters a room to provide discharge teaching and finds the client trying to stand alone with an unsteady gait. Which action should the nurse take first?', '[{"id": "a", "text": "Help the client back to a safe position"}, {"id": "b", "text": "Start the discharge teaching right away"}, {"id": "c", "text": "Leave the teaching handouts at the bedside"}, {"id": "d", "text": "Ask the client about feelings on going home"}]'::jsonb, '["a"]', 'Safety concerns such as falls always trump teaching or emotional support. Beginning the teaching first would ignore the fall risk.')
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale)
  JOIN _fund_seed_map m USING (source_key)
 CROSS JOIN _fund_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _fund_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Fundamentals seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
